# File names, tables, and map import



# pandas needs unique names here or duplicate channels become impossible to address.
def make_unique_columns(columns):
    seen = {}
    output = []
    for col in columns:
        name = str(col).strip().strip('"')
        if name not in seen:
            seen[name] = 1
            output.append(name)
        else:
            seen[name] += 1
            output.append(f"{name} ({seen[name]})")
    return output



# file names often carry copy numbers or words like “map” that do not belong in the sample name.
def clean_map_name_from_filename(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub("\\s*\\(\\d+\\)\\s*$", "", stem).strip()
    stem = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", stem, flags=re.IGNORECASE).strip()
    stem = re.sub("\\s*matrix(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE)
    stem = re.sub("\\s*map(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE)
    stem = re.sub("\\s*image(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE)
    return stem.strip(" _-")



# tries the likely channel endings before falling back to the whole file name.
def _extract_channel_suffix_from_filename_stem(stem):
    text = str(stem)
    text = re.sub("\\s*\\(\\d+\\)\\s*$", "", text).strip()
    text = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", text, flags=re.IGNORECASE).strip()
    text = re.sub("\\s*matrix(?:\\s*\\(\\d+\\))?\\s*$", "", text, flags=re.IGNORECASE).strip(" _-")
    text = re.sub("\\s*map(?:\\s*\\(\\d+\\))?\\s*$", "", text, flags=re.IGNORECASE).strip(" _-")
    text = re.sub("\\s*image(?:\\s*\\(\\d+\\))?\\s*$", "", text, flags=re.IGNORECASE).strip(" _-")
    text = re.sub("\\s+", " ", text).strip()
    if not text:
        return ""
    pieces = re.split("\\s+", text)
    suffixes = [" ".join(pieces[i:]).strip(" _-") for i in range(len(pieces))]
    suffixes = sorted(set(suffixes), key=len)
    channel_patterns = [
        "^[A-Z][a-z]?(?:\\d+)?(?:Total)?(?:[_\\-][A-Za-z0-9]+)*_ppm$",
        "^[A-Z][a-z]?(?:\\d+)?(?:Total)?(?:[_\\-][A-Za-z0-9]+)+$",
        "^[A-Z][a-z]?(?:\\d+)?[\\-_ ]?(?:ANOM|Anom|anom|anomaly)$",
        "^[A-Z][a-z]?(?:\\d+)?(?:\\s+ppm)$",
        "^[A-Z][a-z]?\\d+(?:[\\s_\\-/]+[A-Z]?[a-z]?\\d+)+.*$",
    ]
    for candidate in suffixes:
        cand = candidate.strip(" _-")
        if not cand:
            continue
        for pat in channel_patterns:
            if re.match(pat, cand, flags=re.IGNORECASE):
                cand = re.sub("\\s+", "_", cand)
                cand = re.sub("_+", "_", cand).strip("_")
                return cand
    last = pieces[-1].strip(" _-")
    if re.match(
        "^[A-Z][a-z]?(?:\\d+)?(?:Total)?(?:[_\\-][A-Za-z0-9]+)*_ppm$", last, flags=re.IGNORECASE
    ):
        return last
    if re.match(
        "^[A-Z][a-z]?(?:\\d+)?[\\-_]?(?:ANOM|anom|Anom|anomaly)$", last, flags=re.IGNORECASE
    ):
        return last
    return ""



# turns the channel part of a matrix file name into the label shown in the program.
def clean_channel_name_from_matrix_filename(path):
    stem = clean_map_name_from_filename(path)
    stem = re.sub("\\s+", " ", stem).strip()
    iso_ratio = re.search(
        "((?:\\d+[A-Z][a-z]?|[A-Z][a-z]?\\d+)(?:\\s*[/_-]\\s*(?:\\d+[A-Z][a-z]?|[A-Z]?[a-z]?\\d+))+.*)$",
        stem,
    )
    if iso_ratio and re.search(
        "(?:age|ratio|date|corrected|corr|err|uncert|discord|concord)", stem, flags=re.IGNORECASE
    ):
        candidate = iso_ratio.group(1)
        candidate = re.sub("\\bmatrix\\b|\\bmap\\b|\\bimage\\b", "", candidate, flags=re.IGNORECASE)
        candidate = re.sub("[\\s/\\\\-]+", "_", candidate.strip())
        candidate = re.sub("_+", "_", candidate).strip("_")
        if candidate:
            return candidate
    age_words = "(?:age|date|dates|discordance|concordance|ratio|corrected|corr|uncert|uncertainty|err|error)"
    if re.search(age_words, stem, flags=re.IGNORECASE):
        ratio_start = re.search(
            "([A-Z][a-z]?\\d+(?:\\s*[/_-]\\s*[A-Z]?[a-z]?\\d+)+.*)$", stem, flags=re.IGNORECASE
        )
        if ratio_start:
            candidate = ratio_start.group(1)
        else:
            isotope_start = re.search("([A-Z][a-z]?\\d+.*)$", stem)
            candidate = isotope_start.group(1) if isotope_start else stem
        candidate = re.sub("\\bmatrix\\b|\\bmap\\b|\\bimage\\b", "", candidate, flags=re.IGNORECASE)
        candidate = re.sub("[\\s/\\\\-]+", "_", candidate.strip())
        candidate = re.sub("_+", "_", candidate).strip("_")
        if candidate:
            return candidate
    ratio = re.search("([A-Z][a-z]?\\d+(?:\\s*[/_-]\\s*[A-Z]?[a-z]?\\d+)+)", stem)
    if ratio:
        candidate = re.sub("[\\s/\\\\-]+", "_", ratio.group(1).strip())
        candidate = re.sub("_+", "_", candidate).strip("_")
        if candidate:
            return candidate
    suffix_candidate = _extract_channel_suffix_from_filename_stem(stem)
    if suffix_candidate:
        return suffix_candidate
    patterns = [
        "([A-Z][a-z]?\\d+(?:_[A-Za-z0-9]+)*_ppm)",
        "([A-Z][a-z]?Total(?:_[A-Za-z0-9]+)*_ppm)",
        "([A-Z][a-z]?\\d+\\s+ppm)",
        "([A-Z][a-z]?Total(?:\\s+[A-Za-z0-9]+)*\\s+ppm)",
        "([A-Z][a-z]?\\d+)",
        "([A-Z][a-z]?Total(?:_[A-Za-z0-9]+)*)",
    ]
    for pat in patterns:
        matches = re.findall(pat, stem)
        if matches:
            candidate = matches[-1]
            candidate = re.sub("\\s+", "_", candidate.strip())
            if not candidate.endswith("_ppm") and re.search("\\bppm\\b", stem, flags=re.IGNORECASE):
                if re.match("^[A-Z][a-z]?\\d+$", candidate) or "Total" in candidate:
                    candidate = candidate + "_ppm"
            return candidate
    bare = re.search(
        "(?:^|[\\s_-])([A-Z][a-z]?)(Total)?(?:[\\s_-]*(ppm|cps|wt|pct|percent))?$", stem
    )
    if bare:
        element = bare.group(1)
        if element in _ELEMENT_SYMBOLS:
            candidate = element + ("Total" if bare.group(2) else "")
            unit = (bare.group(3) or "").lower()
            if unit:
                candidate += "_" + unit
            return candidate
    return stem



# separates the sample name from the channel name during matrix imports.
def clean_sample_prefix_from_matrix_filename(path, channel_name=None):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub("\\s*\\(\\d+\\)\\s*$", "", stem).strip()
    stem = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", stem, flags=re.IGNORECASE).strip()
    stem = re.sub("\\s*matrix(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
    stem = re.sub("\\s*map(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
    stem = re.sub("\\s*image(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
    if channel_name:
        loose = re.escape(str(channel_name)).replace("_", "[\\s_]+")
        prefix = re.sub("[\\s_-]*" + loose + "\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
        if prefix and prefix != stem:
            return prefix
    prefix = re.sub("[\\s_-]+[A-Z][a-z]?\\d+(?:[\\s_]+ppm)?$", "", stem).strip(" _-")
    prefix = re.sub(
        "[\\s_-]+[A-Z][a-z]?Total(?:[\\s_]+[A-Za-z0-9]+)*(?:[\\s_]+ppm)?$", "", prefix
    ).strip(" _-")
    return prefix if prefix else stem



# reduces an isotope or channel label to the element symbol used by REE and plotting tools.
def clean_element_name(name):
    text = str(name)
    text = re.sub("\\.csv$", "", text, flags=re.IGNORECASE)
    text = re.sub("\\.xlsx$", "", text, flags=re.IGNORECASE)
    text = re.sub("\\.xls$", "", text, flags=re.IGNORECASE)
    text = re.sub("\\bmatrix\\b", "", text, flags=re.IGNORECASE)
    text = re.sub("\\bppm\\b", "", text, flags=re.IGNORECASE)
    text = re.sub("\\bcps\\b", "", text, flags=re.IGNORECASE)
    text = re.sub("\\bwt\\b", "", text, flags=re.IGNORECASE)
    element_list = REE_ORDER + [
        "Y",
        "U",
        "Th",
        "Pb",
        "Zr",
        "Hf",
        "Ti",
        "P",
        "Ca",
        "Fe",
        "Mg",
        "Mn",
        "Al",
        "Si",
        "Na",
        "K",
        "Sr",
        "Ba",
        "Rb",
        "Nb",
        "Ta",
        "Sc",
        "V",
        "Cr",
        "Co",
        "Ni",
        "Cu",
        "Zn",
    ]
    for element in sorted(element_list, key=len, reverse=True):
        pattern = f"(?<![A-Za-z]){element}\\d*(?![a-z])"
        if re.search(pattern, text):
            return element
    tokens = re.split("[\\s_\\-()/]+", text)
    for token in tokens:
        match = re.match("^([A-Z][a-z]?)(\\d+)?$", token)
        if match:
            return match.group(1)
    return str(name)



# small guard for text-box values that may be blank or invalid.
def safe_int(value, default):
    try:
        return int(value)
    except Exception:
        return default



# same idea as safe_int, but for decimal values.
def safe_float(value, default):
    try:
        return float(value)
    except Exception:
        return default



# blank and “all” mean no limit; otherwise this keeps only positive whole numbers.
def optional_positive_int(value):
    try:
        raw = str(value).strip()
    except Exception:
        return None
    if raw == "" or raw.lower() in {"all", "none", "no limit", "unlimited"}:
        return None
    try:
        number = int(round(float(raw)))
    except Exception:
        return None
    return number if number > 0 else None



# pandas equations need backticks around column names that contain spaces or symbols.
def backtick_col(col):
    col = str(col).replace("`", "")
    return f"`{col}`"



# keeps IDs, coordinates, and companion uncertainty columns out of the channel menus.
def get_value_columns(df):
    """Return user-facing numeric channels, excluding companion statistics."""
    if df is None:
        return []
    numeric_cols = list(df.select_dtypes(include=[np.number]).columns)
    numeric_names = {str(column) for column in numeric_cols}
    output = []
    statistic_suffix = re.compile(
        r"^(.*?)(?:_(?:sd|std|stdev|standard_deviation|se|sem|standard_error|"
        r"1se|1se_internal|1se_total|2se|2se_internal|2se_total|2sigma|2s|"
        r"n|n_valid|count))$",
        flags=re.IGNORECASE,
    )
    for column in numeric_cols:
        name = str(column)
        if name in METADATA_COLUMNS:
            continue
        match = statistic_suffix.match(name)
        if match and match.group(1) in numeric_names:
            continue
        output.append(column)
    return output



# used for files that should contain one measured channel beside their metadata.
def get_single_value_column(df):
    value_cols = get_value_columns(df)
    if not value_cols:
        raise ValueError("No numeric value column found.")
    if len(value_cols) > 1:
        return value_cols[-1]
    return value_cols[0]



# final filter for the columns a person should actually see in plotting menus.
def user_visible_columns(df):
    """Columns suitable for plot controls and user-facing choices."""
    if not isinstance(df, pd.DataFrame):
        return []
    columns = [str(column) for column in df.columns]
    present = set(columns)
    hidden = {
        "plot_group_id", "plot_summary_mode", "source_kind",
        "coordinate_group_key", "base_grid_layer",
        "_upb_selected_set", "_upb_group", "profile_id",
    }
    for column in columns:
        if column.startswith("__") or column.startswith("_upb_") or column.startswith("_cov"):
            hidden.add(column)
    for alias, direct in [
        ("comparison_dataset", "sample_id"),
        ("map_group", "sample_id"),
        ("dataset_id", "sample_id"),
        ("sample_name", "sample_id"),
        ("mineral_type", "mineral_id"),
        ("mineral_name", "mineral_id"),
        ("mineral_group", "mineral_id"),
        ("run_name", "run_id"),
        ("area_id", "domain"),
        ("source_row_count", "n_pixels"),
    ]:
        if alias in present and direct in present:
            hidden.add(alias)
    if {"sample_id", "mineral_id", "run_id", "grain_id"}.issubset(present):
        hidden.add("grain_uid")
    if any(column in present for column in [
        "sample_id", "mineral_id", "run_id", "domain", "grain_id", "line_id", "spot_id"
    ]):
        hidden.add("plot_group")
    return [column for column in columns if column not in hidden]



# matches mineral-specific columns that represent the same scientific channel.
def _shared_channel_suffix(name, mineral_names=()):
    name = str(name)
    if name in METADATA_COLUMNS or name.startswith("_"):
        return None
    lower = name.lower()
    if lower in {"row_index", "column_index", "row_fractional", "column_fractional"}:
        return None
    for mineral in sorted({str(v) for v in mineral_names if str(v)}, key=len, reverse=True):
        prefix = mineral + "_"
        if name.lower().startswith(prefix.lower()) and len(name) > len(prefix):
            return name[len(prefix):]
    # Common imported form: mineral-channel with a known mineral token before the first underscore.
    if "_" in name:
        first, rest = name.split("_", 1)
        if first.lower() in {str(v).lower() for v in mineral_names} and rest:
            return rest
    return None



# adds a shared channel without deleting the original mineral-specific columns.
def _add_shared_channels(df):
    """Coalesce equivalent mineral-specific columns into shared scientific channels."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df
    out = df.copy()
    minerals = []
    if "mineral_id" in out.columns:
        minerals = [v for v in out["mineral_id"].dropna().astype(str).unique() if v]
    grouped = {}
    for col in list(out.columns):
        suffix = _shared_channel_suffix(col, minerals)
        if suffix:
            grouped.setdefault(suffix, []).append(col)
    for shared, cols in grouped.items():
        if shared in METADATA_COLUMNS or shared in {"x", "y"}:
            continue
        series = pd.Series(np.nan, index=out.index, dtype=float)
        for col in cols:
            values = pd.to_numeric(out[col], errors="coerce")
            if "mineral_id" in out.columns:
                prefix = str(col)[:-len(shared)].rstrip("_")
                mask = out["mineral_id"].astype(str).str.casefold() == prefix.casefold()
                candidate = values.where(mask)
            else:
                candidate = values
            series = series.combine_first(candidate)
        if shared in out.columns:
            series = pd.to_numeric(out[shared], errors="coerce").combine_first(series)
        if series.notna().any():
            out[shared] = series
    return out





COLUMN_DISPLAY_NAMES = {
    "sample_id": "Sample",
    "mineral_id": "Mineral",
    "run_id": "Run",
    "domain": "Domain",
    "area_id": "Domain ID",
    "grain_id": "Grain",
    "line_id": "Line",
    "profile_id": "Profile",
    "spot_id": "Spot",
    "analysis_level": "Analysis level",
    "point_kind": "Point type",
    "ratio_average": "Ratio averaging",
    "n": "Number of rows",
    "n_pixels": "Number of pixels",
}



# keeps readable menu labels tied to the real dataframe column names.
def display_column_choices(columns, include_none=True):
    """Return display-to-column and column-to-display maps."""
    display_to_column = {}
    column_to_display = {}
    if include_none:
        display_to_column["None"] = "None"
        column_to_display["None"] = "None"
    for raw in columns:
        raw = str(raw)
        label = COLUMN_DISPLAY_NAMES.get(raw, raw)
        if label in display_to_column and display_to_column[label] != raw:
            label = f"{label} ({raw})"
        display_to_column[label] = raw
        column_to_display[raw] = label
    return display_to_column, column_to_display



# common reader for CSV, text, and Excel tables.
def read_table_file(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in [".xlsx", ".xls"]:
        df = pd.read_excel(path)
    elif ext in [".csv", ".txt", ".dat"]:
        df = pd.read_csv(path, sep=None, engine="python", comment="#")
    else:
        raise ValueError(f"Unsupported table file type: {ext}")
    df.columns = make_unique_columns(df.columns)
    df = df.dropna(axis=1, how="all")
    return df



# a quick check for tables laid out as X, Y, and one or more measured channels.
def looks_like_wide_xy_table(df):
    if df.shape[1] < 3:
        return False
    cols = [str(c).strip().lower() for c in df.columns]
    has_x = any((c == "x" or "stage_x" in c for c in cols))
    has_y = any((c == "y" or "stage_y" in c for c in cols))
    return has_x and has_y



# estimates the usual pixel spacing while ignoring the occasional large gap.
def estimate_coordinate_step(values):
    arr = np.asarray(values, dtype=float)
    arr = arr[np.isfinite(arr)]
    if arr.size < 2:
        return 1.0
    coord_range = np.nanmax(arr) - np.nanmin(arr)
    tol = max(coord_range * 1e-09, 1e-09)
    unique_vals = np.unique(np.round(arr, 6))
    diffs = np.diff(np.sort(unique_vals))
    diffs = diffs[diffs > tol]
    if diffs.size == 0:
        return 1.0
    upper = np.nanpercentile(diffs, 80)
    small = diffs[diffs <= upper]
    if small.size == 0:
        small = diffs
    rounded = pd.Series(np.round(small, 3))
    if rounded.empty:
        return float(np.nanmedian(diffs))
    return float(rounded.value_counts().idxmax())



# puts scattered X-Y measurements back onto a regular image grid.
def rasterize_sparse_xy_points(df, x_col, y_col, value_cols, path):
    work = df[[x_col, y_col] + value_cols].copy()
    work[x_col] = pd.to_numeric(work[x_col], errors="coerce")
    work[y_col] = pd.to_numeric(work[y_col], errors="coerce")
    work = work.dropna(subset=[x_col, y_col]).reset_index(drop=True)
    if work.empty:
        raise ValueError("No valid X/Y coordinates were found.")
    x_arr = work[x_col].to_numpy(dtype=float)
    y_arr = work[y_col].to_numpy(dtype=float)

    # local spacing estimate that uses repeated scan rows rather than every X difference.
    def robust_step_from_grouped_rows(work_df, x_name, y_name):
        diffs = []
        y_round = np.round(pd.to_numeric(work_df[y_name], errors="coerce").to_numpy(dtype=float), 6)
        for _, sub in work_df.groupby(y_round):
            xs = pd.to_numeric(sub[x_name], errors="coerce").dropna().to_numpy(dtype=float)
            if xs.size < 2:
                continue
            xs = np.sort(xs)
            d = np.diff(xs)
            d = d[np.isfinite(d) & (d > 1e-09)]
            if d.size:
                diffs.extend(d.tolist())
        if not diffs:
            return estimate_coordinate_step(work_df[x_name])
        d = np.asarray(diffs, dtype=float)
        low = np.nanpercentile(d, 1)
        near = d[d <= max(np.nanpercentile(d, 20), low * 3)]
        if near.size == 0:
            near = d[d <= np.nanpercentile(d, 50)]
        if near.size == 0:
            near = d
        return float(np.nanmedian(near))

    x_step = robust_step_from_grouped_rows(work, x_col, y_col)
    y_step = estimate_coordinate_step(work[y_col])
    if not np.isfinite(x_step) or x_step <= 0:
        x_step = estimate_coordinate_step(work[x_col])
    if not np.isfinite(y_step) or y_step <= 0:
        y_step = estimate_coordinate_step(work[y_col])
    if not np.isfinite(x_step) or x_step <= 0:
        x_step = 1.0
    if not np.isfinite(y_step) or y_step <= 0:
        y_step = 1.0
    x_min = float(np.nanmin(x_arr))
    y_min = float(np.nanmin(y_arr))
    cols = np.rint((x_arr - x_min) / x_step).astype(int)
    rows = np.rint((y_arr - y_min) / y_step).astype(int)
    rows = rows - rows.min()
    cols = cols - cols.min()
    n_rows = int(rows.max()) + 1
    n_cols = int(cols.max()) + 1
    if n_rows <= 0 or n_cols <= 0:
        raise ValueError("Could not infer a valid image grid from X/Y coordinates.")
    if n_rows * n_cols > max(len(work) * 50, 25000000):
        raise ValueError(
            f"The inferred X/Y pixel grid is too large. Check X/Y coordinate columns or pixel spacing. Inferred grid: {n_rows} x {n_cols}."
        )
    values = {}
    flat_index = rows * n_cols + cols
    for col in value_cols:
        vals = pd.to_numeric(work[col], errors="coerce").to_numpy(dtype=float)
        valid = np.isfinite(vals)
        z_sum = np.zeros(n_rows * n_cols, dtype=float)
        z_count = np.zeros(n_rows * n_cols, dtype=float)
        np.add.at(z_sum, flat_index[valid], vals[valid])
        np.add.at(z_count, flat_index[valid], 1.0)
        z = np.full(n_rows * n_cols, np.nan, dtype=float)
        ok = z_count > 0
        z[ok] = z_sum[ok] / z_count[ok]
        values[str(col)] = z.reshape((n_rows, n_cols))
    x_grid = x_min + np.arange(n_cols, dtype=float) * x_step
    y_grid = y_min + np.arange(n_rows, dtype=float) * y_step
    meta = {
        "kind": "xy_point_pixel_coordinate_raster",
        "x": x_grid,
        "y": y_grid,
        "x_name": str(x_col),
        "y_name": str(y_col),
        "path": path,
        "x_step": float(x_step),
        "y_step": float(y_step),
        "source_rows": int(len(work)),
        "raster_rows": int(n_rows),
        "raster_columns": int(n_cols),
    }
    return (values, meta)



# converts a wide X-Y table into one raster per measured channel.
def read_wide_xy_table(path):
    df = read_table_file(path)
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors="coerce")
    numeric_cols = list(df.select_dtypes(include=[np.number]).columns)
    if len(numeric_cols) < 3:
        raise ValueError("Need at least X, Y, and one value column.")
    lower = {col: str(col).lower().strip() for col in numeric_cols}
    x_candidates = [
        col for col, low in lower.items() if low == "x" or "stage_x" in low or low == "_stage_x"
    ]
    y_candidates = [
        col for col, low in lower.items() if low == "y" or "stage_y" in low or low == "_stage_y"
    ]
    if not x_candidates or not y_candidates:
        raise ValueError("Could not find X and Y columns.")
    x_col = x_candidates[0]
    y_col = y_candidates[0]
    value_cols = []
    for col in numeric_cols:
        if col in [x_col, y_col]:
            continue
        if str(col).lower().startswith("unnamed") and df[col].isna().all():
            continue
        if df[col].notna().sum() == 0:
            continue
        value_cols.append(col)
    if not value_cols:
        raise ValueError("No numeric value columns found after X/Y columns.")
    valid_xy = df[[x_col, y_col]].dropna()
    if valid_xy.empty:
        raise ValueError("No valid X/Y rows were found.")
    x_unique_count = valid_xy[x_col].nunique(dropna=True)
    y_unique_count = valid_xy[y_col].nunique(dropna=True)
    n_points = len(valid_xy)
    pivot_cell_count = x_unique_count * y_unique_count
    rows_per_y = valid_xy.groupby(y_col).size()
    median_rows_per_y = float(rows_per_y.median()) if len(rows_per_y) else 0.0
    sparse_mask_table = (
        y_unique_count >= 3 and median_rows_per_y >= 2 and (x_unique_count > median_rows_per_y * 3)
    )
    sparse_exact_grid = (
        pivot_cell_count > max(n_points * 4, 1000000)
        or x_unique_count > n_points * 0.5
        or y_unique_count > n_points * 0.5
        or sparse_mask_table
    )
    if sparse_exact_grid:
        return rasterize_sparse_xy_points(df, x_col, y_col, value_cols, path)
    x_unique = np.sort(valid_xy[x_col].dropna().unique())
    y_unique = np.sort(valid_xy[y_col].dropna().unique())
    values = {}
    for col in value_cols:
        pivot = df.pivot_table(index=y_col, columns=x_col, values=col, aggfunc="mean")
        pivot = pivot.reindex(index=y_unique, columns=x_unique)
        values[str(col)] = pivot.to_numpy(dtype=float)
    meta = {
        "kind": "wide_xy_table",
        "x": x_unique.astype(float),
        "y": y_unique.astype(float),
        "x_name": str(x_col),
        "y_name": str(y_col),
        "path": path,
    }
    return (values, meta)



# reader for Probe image DAT files
def read_probe_dat(path):
    with open(path, "r", encoding="latin1") as f:
        first_line = f.readline().strip()
    parts = first_line.split()
    if len(parts) < 4:
        raise ValueError("This does not look like a Probe image .DAT file.")
    try:
        nx_pixels = int(parts[0])
        ny_pixels = int(parts[1])
        total_pixels = int(parts[2])
        n_columns = int(parts[3])
    except Exception:
        raise ValueError("Could not read Probe image dimensions from the first line.")
    df = pd.read_csv(path, sep="\t", skiprows=[0], engine="python")
    df.columns = make_unique_columns(df.columns)
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors="coerce")
    required = {"X", "Y", "NX", "NY"}
    missing = required - set(df.columns)
    if missing:
        raise ValueError(f"Missing expected Probe columns: {missing}")
    nx_index = df["NX"].astype(int).to_numpy() - 1
    ny_index = df["NY"].astype(int).to_numpy() - 1
    x_by_col = df.groupby("NX")["X"].mean().sort_index().to_numpy(dtype=float)
    y_by_row = df.groupby("NY")["Y"].mean().sort_index().to_numpy(dtype=float)
    excluded = {"NK", "X", "Y", "NX", "NY", "NXY"}
    value_columns = [
        col for col in df.columns if col not in excluded and pd.api.types.is_numeric_dtype(df[col])
    ]
    if not value_columns:
        raise ValueError("No concentration/value columns were found in the DAT file.")
    values = {}
    for col in value_columns:
        z = np.full((ny_pixels, nx_pixels), np.nan, dtype=float)
        z[ny_index, nx_index] = df[col].to_numpy(dtype=float)
        values[str(col)] = z
    meta = {
        "kind": "probe_dat",
        "x": x_by_col,
        "y": y_by_row,
        "x_name": "X",
        "y_name": "Y",
        "path": path,
        "nx_pixels": nx_pixels,
        "ny_pixels": ny_pixels,
        "n_columns": n_columns,
    }
    if len(df) != total_pixels:
        print(f"Warning: expected {total_pixels} pixels but found {len(df)} rows.")
    return (values, meta)



# reader for Surfer 7 binary grids
def read_surfer7_grid(path):
    with open(path, "rb") as f:
        blob = f.read()
    if blob[:4] != b"DSRB":
        raise ValueError("This does not look like a Surfer 7 binary .grd file.")
    grid_pos = blob.find(b"GRID")
    data_pos = blob.find(b"DATA")
    if grid_pos < 0 or data_pos < 0:
        raise ValueError("Could not find GRID and DATA sections in this .grd file.")
    grid_size = struct.unpack("<I", blob[grid_pos + 4 : grid_pos + 8])[0]
    grid_start = grid_pos + 8
    grid = blob[grid_start : grid_start + grid_size]
    n_rows, n_cols = struct.unpack("<II", grid[:8])
    x_min, y_min, x_step, y_step, z_min, z_max, rotation, blank_value = struct.unpack(
        "<8d", grid[8:72]
    )
    data_size = struct.unpack("<I", blob[data_pos + 4 : data_pos + 8])[0]
    data_start = data_pos + 8
    data = np.frombuffer(blob[data_start : data_start + data_size], dtype="<f8")
    expected = n_rows * n_cols
    if data.size != expected:
        raise ValueError(f"Grid size mismatch. Expected {expected} values, found {data.size}.")
    z = data.reshape((n_rows, n_cols)).astype(float)
    z[z >= blank_value * 0.5] = np.nan
    x = x_min + np.arange(n_cols) * x_step
    y = y_min + np.arange(n_rows) * y_step
    name = clean_map_name_from_filename(path)
    values = {name: z}
    meta = {"kind": "grd", "x": x, "y": y, "x_name": "X", "y_name": "Y", "path": path}
    return (values, meta)



# recognizes separate X and Y coordinate-matrix files from their names.
def coordinate_axis_from_filename(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub("\\s*\\(\\d+\\)\\s*$", "", stem).strip()
    stem = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", stem, flags=re.IGNORECASE).strip()
    stem = re.sub("\\s*matrix(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
    full = stem.lower()
    if re.search(
        "(^|[\\s_-])x\\s*(?:\\[?\\s*(?:um|µm|micron|microns)\\s*\\]?)?$", full, flags=re.IGNORECASE
    ):
        return "x"
    if re.search(
        "(^|[\\s_-])y\\s*(?:\\[?\\s*(?:um|µm|micron|microns)\\s*\\]?)?$", full, flags=re.IGNORECASE
    ):
        return "y"
    if re.search(
        "(^|[\\s_-])(?:stage[\\s_-]*)?x(?:[\\s_-]*(?:coord|coordinate|stage|um|µm))?$",
        full,
        flags=re.IGNORECASE,
    ):
        return "x"
    if re.search(
        "(^|[\\s_-])(?:stage[\\s_-]*)?y(?:[\\s_-]*(?:coord|coordinate|stage|um|µm))?$",
        full,
        flags=re.IGNORECASE,
    ):
        return "y"
    return None



# removes the X or Y ending so matching coordinate matrices can be paired.
def _coordinate_axis_group_name(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub("\\s*\\(\\d+\\)\\s*$", "", stem).strip()
    stem = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", stem, flags=re.IGNORECASE).strip()
    stem = re.sub("\\s*matrix(?:\\s*\\(\\d+\\))?\\s*$", "", stem, flags=re.IGNORECASE).strip(" _-")
    stem = re.sub(
        "[\\s_-]+[xy]\\s*(?:\\[?\\s*(?:um|µm|micron|microns)\\s*\\]?)?$",
        "",
        stem,
        flags=re.IGNORECASE,
    ).strip(" _-")
    stem = re.sub(
        "[\\s_-]+(?:stage[\\s_-]*)?[xy](?:[\\s_-]*(?:coord|coordinate|stage|um|µm))?$",
        "",
        stem,
        flags=re.IGNORECASE,
    ).strip(" _-")
    return stem or clean_map_name_from_filename(path)



# loads one coordinate matrix without treating its first row as a header.
def read_coordinate_axis_matrix(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in [".xlsx", ".xls"]:
        raw = pd.read_excel(path, header=None)
    elif ext in [".csv", ".txt"]:
        raw = pd.read_csv(path, header=None)
    else:
        raise ValueError(f"Unsupported coordinate matrix file type: {ext}")
    raw = raw.apply(pd.to_numeric, errors="coerce")
    arr = raw.to_numpy(dtype=float)
    if arr.size == 0 or not np.isfinite(arr).any():
        raise ValueError("Coordinate matrix has no finite coordinate values.")
    return arr



# bundles a matching X/Y matrix pair into the reference used by the map importer.
def _make_coordinate_reference(x_path, y_path, group_key=None):
    x_grid = read_coordinate_axis_matrix(x_path)
    y_grid = read_coordinate_axis_matrix(y_path)
    if x_grid.shape != y_grid.shape:
        raise ValueError(
            f"X and Y coordinate matrices have different shapes: {x_grid.shape} vs {y_grid.shape}"
        )
    if group_key is None:
        group_key = clean_coordinate_axis_group_name_from_filename(x_path)
    return {
        "kind": "coordinate_matrix_pair",
        "path": x_path,
        "source_file": f"{os.path.basename(x_path)} + {os.path.basename(y_path)}",
        "group_key": str(group_key),
        "x_col": "X",
        "y_col": "Y",
        "x_grid": x_grid,
        "y_grid": y_grid,
        "matrix_shape": tuple(x_grid.shape),
        "n_points": int((np.isfinite(x_grid) & np.isfinite(y_grid)).sum()),
    }



# makes a short group name for a coordinate-reference file.
def clean_coordinate_group_name_from_filename(path):
    stem = os.path.splitext(os.path.basename(path))[0]
    stem = re.sub("\\s*\\(\\d+\\)\\s*$", "", stem).strip()
    stem = re.sub("\\s+copy(?:\\s+\\d+)?\\s*$", "", stem, flags=re.IGNORECASE).strip()
    stem = re.sub(
        "[\\s_-]*(?:xy|x_y|coords?|coordinates?|stagecoords?|stage_coordinates?|pixelcoords?|pixel_coordinates?|reference|ref)[\\s_-]*$",
        "",
        stem,
        flags=re.IGNORECASE,
    ).strip(" _-")
    try:
        channel = clean_channel_name_from_matrix_filename(stem + ".csv")
        prefix = clean_sample_prefix_from_matrix_filename(stem + ".csv", channel)
        if prefix and prefix != channel:
            stem = prefix
    except Exception:
        pass
    return stem.strip(" _-") or clean_map_name_from_filename(path)



# reads a coordinate table and identifies its X, Y, row, and column fields.
def read_coordinate_reference_file(path):
    ext = os.path.splitext(path)[1].lower()
    if ext not in [".csv", ".txt", ".xlsx", ".xls"]:
        raise ValueError("Coordinate reference must be a table file.")
    df = read_table_file(path)
    if df is None or df.empty:
        raise ValueError("Coordinate reference table is empty.")
    cols = list(df.columns)
    lower = {c: str(c).strip().lower() for c in cols}
    x_candidates = [
        c
        for c in cols
        if lower[c] in ["x", "stage_x", "_stage_x", "x_stage", "pixel_x"] or lower[c].endswith("_x")
    ]
    y_candidates = [
        c
        for c in cols
        if lower[c] in ["y", "stage_y", "_stage_y", "y_stage", "pixel_y"] or lower[c].endswith("_y")
    ]
    if not x_candidates or not y_candidates:
        raise ValueError("No X/Y coordinate columns found.")
    x_col = x_candidates[0]
    y_col = y_candidates[0]
    row_candidates = [
        c for c in cols if lower[c] in ["row", "rows", "pixel_row", "row_index", "ny", "iy", "j"]
    ]
    col_candidates = [
        c
        for c in cols
        if lower[c] in ["col", "column", "columns", "pixel_col", "column_index", "nx", "ix", "i"]
    ]
    allowed = {x_col, y_col}
    if row_candidates:
        allowed.add(row_candidates[0])
    if col_candidates:
        allowed.add(col_candidates[0])
    numeric_cols = []
    for c in cols:
        vals = pd.to_numeric(df[c], errors="coerce")
        if vals.notna().sum() > 0:
            numeric_cols.append(c)
    extra_numeric = [c for c in numeric_cols if c not in allowed]
    name_says_coordinates = (
        re.search(
            "(?:^|[\\s_-])(xy|x_y|coord|coords|coordinate|coordinates|stage|pixel)(?:[\\s_-]|$)",
            os.path.splitext(os.path.basename(path))[0],
            flags=re.IGNORECASE,
        )
        is not None
    )
    if extra_numeric and (not name_says_coordinates):
        raise ValueError("This looks like an X/Y value table, not a coordinate reference.")
    x = pd.to_numeric(df[x_col], errors="coerce").to_numpy(dtype=float)
    y = pd.to_numeric(df[y_col], errors="coerce").to_numpy(dtype=float)
    valid = np.isfinite(x) & np.isfinite(y)
    if not np.any(valid):
        raise ValueError("Coordinate reference has no valid X/Y rows.")
    ref = {
        "kind": "coordinate_reference",
        "path": path,
        "source_file": os.path.basename(path),
        "group_key": clean_coordinate_group_name_from_filename(path),
        "x_col": str(x_col),
        "y_col": str(y_col),
        "x": x[valid],
        "y": y[valid],
        "n_points": int(np.sum(valid)),
    }
    if row_candidates and col_candidates:
        r = pd.to_numeric(df[row_candidates[0]], errors="coerce").to_numpy(dtype=float)
        c = pd.to_numeric(df[col_candidates[0]], errors="coerce").to_numpy(dtype=float)
        ref["row"] = r[valid]
        ref["col"] = c[valid]
        ref["row_col_present"] = True
    else:
        ref["row_col_present"] = False
    return ref



# chooses the right map reader from the file type and table layout.
def load_probe_file(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == ".grd":
        return read_surfer7_grid(path)
    if ext == ".dat":
        try:
            return read_probe_dat(path)
        except Exception:
            return read_wide_xy_table(path)
    if ext in [".csv", ".txt", ".xlsx", ".xls"]:
        try:
            df = read_table_file(path)
            if looks_like_wide_xy_table(df):
                return read_wide_xy_table(path)
            return read_matrix_file(path)
        except Exception as original_error:
            try:
                return read_matrix_file(path)
            except Exception:
                raise original_error
    raise ValueError("Unsupported file type.")



# joins separate profile-channel files by line and point number.
def load_and_merge_profile_csvs(paths):
    merged = None
    loaded_info = []
    merge_keys = ["line_id", "point_id"]
    preferred_metadata = [
        "line_id",
        "point_id",
        "n_points_in_line",
        "line_total_length",
        "distance",
        "distance_normalized",
        "x",
        "y",
        "row_fractional",
        "column_fractional",
    ]
    for path in paths:
        df = pd.read_csv(path)
        if "distance_normalized" not in df.columns:
            raise ValueError(f"{os.path.basename(path)} does not have distance_normalized.")
        if "line_id" not in df.columns:
            df["line_id"] = 1
        if "point_id" not in df.columns:
            df["point_id"] = df.groupby("line_id").cumcount() + 1
        df["line_id"] = pd.to_numeric(df["line_id"], errors="coerce").astype("Int64")
        df["point_id"] = pd.to_numeric(df["point_id"], errors="coerce").astype("Int64")
        df["distance_normalized"] = pd.to_numeric(df["distance_normalized"], errors="coerce")
        value_col = get_single_value_column(df)
        new_name = str(value_col).strip()
        if new_name.lower() in ["value", "concentration", "intensity", "ppm"]:
            new_name = os.path.splitext(os.path.basename(path))[0]
        if merged is not None and new_name in merged.columns:
            base = new_name
            i = 2
            while new_name in merged.columns:
                new_name = f"{base} ({i})"
                i += 1
        keep_cols = [c for c in preferred_metadata if c in df.columns]
        keep_cols = list(dict.fromkeys(keep_cols + [value_col]))
        small = df[keep_cols].copy()
        small = small.rename(columns={value_col: new_name})
        if merged is None:
            merged = small
        else:
            merged = pd.merge(merged, small[merge_keys + [new_name]], on=merge_keys, how="outer")
        loaded_info.append((os.path.basename(path), new_name))
    if merged is None:
        raise ValueError("No CSVs loaded.")
    merged = merged.sort_values(["line_id", "point_id"]).reset_index(drop=True)
    return (merged, loaded_info)



# used when a profile passes between pixel centers.
def bilinear_sample(z, row_f, col_f):
    row_f = np.asarray(row_f, dtype=float)
    col_f = np.asarray(col_f, dtype=float)
    n_rows, n_cols = z.shape
    valid = (row_f >= 0) & (row_f <= n_rows - 1) & (col_f >= 0) & (col_f <= n_cols - 1)
    out = np.full(row_f.shape, np.nan, dtype=float)
    if not np.any(valid):
        return out
    r = row_f[valid]
    c = col_f[valid]
    r0 = np.floor(r).astype(int)
    c0 = np.floor(c).astype(int)
    r1 = np.clip(r0 + 1, 0, n_rows - 1)
    c1 = np.clip(c0 + 1, 0, n_cols - 1)
    dr = r - r0
    dc = c - c0
    z00 = z[r0, c0]
    z01 = z[r0, c1]
    z10 = z[r1, c0]
    z11 = z[r1, c1]
    out[valid] = (
        z00 * (1 - dr) * (1 - dc) + z01 * (1 - dr) * dc + z10 * dr * (1 - dc) + z11 * dr * dc
    )
    return out



# used when the closest map pixel is preferable to interpolation.
def nearest_sample(z, row_f, col_f):
    n_rows, n_cols = z.shape
    row_i = int(round(row_f))
    col_i = int(round(col_f))
    if row_i < 0 or row_i >= n_rows:
        return np.nan
    if col_i < 0 or col_i >= n_cols:
        return np.nan
    return z[row_i, col_i]





