# evaluates one calculated-channel equation against the active table
def _calculate_column_values(self, df, definition):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        raise ValueError("No analysis table is available for the calculation.")
    work = df.copy(deep=False)
    try:
        work = _normalize_multimineral_table(self, work)
    except Exception:
        pass
    upb_operands = [name for name in _upb_definition_operands(definition) if name]
    if upb_operands:
        missing = [name for name in upb_operands if name not in work.columns]
        if missing:
            raise ValueError("Missing U-Pb source column(s): " + ", ".join(missing))
        arrays = {
            name: pd.to_numeric(work[name], errors="coerce").to_numpy(dtype=float)
            for name in upb_operands
        }
        result = pd.Series(_upb_apply_definition(definition, arrays), index=df.index)
        return pd.to_numeric(result, errors="coerce").replace([np.inf, -np.inf], np.nan)
    if definition.get("kind") == "simple":
        col_a = str(definition["col_a"])
        col_b = str(definition["col_b"])
        op = str(definition["op"])
        if col_a not in work.columns:
            raise ValueError(f"Column A is not available: {col_a}")
        if col_b not in work.columns:
            raise ValueError(f"Column B is not available: {col_b}")
        a = pd.to_numeric(work[col_a], errors="coerce")
        b = pd.to_numeric(work[col_b], errors="coerce")
        with np.errstate(divide="ignore", invalid="ignore"):
            if op == "+":
                result = a + b
            elif op == "-":
                result = a - b
            elif op == "*":
                result = a * b
            elif op == "/":
                result = a / b
            elif op == "**":
                result = a**b
            else:
                raise ValueError(f"Unknown operation: {op}")
    else:
        equation = str(definition.get("equation", "")).strip()
        if not equation:
            raise ValueError("Equation cannot be blank.")
        local_dict = {
            "np": np,
            "log": np.log,
            "log10": np.log10,
            "sqrt": np.sqrt,
            "abs": np.abs,
            "sin": np.sin,
            "cos": np.cos,
            "tan": np.tan,
            "exp": np.exp,
        }
        with np.errstate(divide="ignore", invalid="ignore"):
            result = work.eval(equation, engine="python", local_dict=local_dict)
    result = pd.to_numeric(result, errors="coerce").replace([np.inf, -np.inf], np.nan)
    if len(result) != len(df):
        raise ValueError("Equation result length does not match the source dataset.")
    result.index = df.index
    return result



# calculate definition on map context
def _compute_definition_on_map_context(self, definition, colmap):
    operands = self._calculation_operand_names(definition, self._get_full_calculation_table())
    if not operands:
        raise ValueError("Could not identify map-channel inputs in the equation.")
    missing = [name for name in operands if name not in colmap]
    if missing:
        raise KeyError(", ".join(missing))
    arrays = {name: np.asarray(self.values[colmap[name]], dtype=float) for name in operands}
    shapes = {arr.shape for arr in arrays.values()}
    if len(shapes) != 1:
        raise ValueError("Source map channels do not share the same pixel-grid shape.")
    shape = next(iter(shapes))
    if _upb_definition_operands(definition):
        z = _upb_apply_definition(definition, arrays)
    elif definition.get("kind") == "simple":
        a = arrays[str(definition["col_a"])]
        b = arrays[str(definition["col_b"])]
        op = str(definition["op"])
        with np.errstate(divide="ignore", invalid="ignore"):
            if op == "+":
                z = a + b
            elif op == "-":
                z = a - b
            elif op == "*":
                z = a * b
            elif op == "/":
                z = a / b
            elif op == "**":
                z = a**b
            else:
                raise ValueError(f"Unknown operation: {op}")
    else:
        equation = str(definition.get("equation", "")).strip()
        flat = pd.DataFrame({name: arr.ravel() for name, arr in arrays.items()})
        local_dict = {
            "np": np,
            "log": np.log,
            "log10": np.log10,
            "sqrt": np.sqrt,
            "abs": np.abs,
            "sin": np.sin,
            "cos": np.cos,
            "tan": np.tan,
            "exp": np.exp,
        }
        with np.errstate(divide="ignore", invalid="ignore"):
            result = flat.eval(equation, engine="python", local_dict=local_dict)
        z = pd.to_numeric(result, errors="coerce").to_numpy(dtype=float).reshape(shape)
    z = np.asarray(z, dtype=float)
    z[~np.isfinite(z)] = np.nan
    return (z, operands)



# finds a calculated map layer that already has the requested channel name.
def _find_existing_calculated_layer(self, new_col, context_key):
    for layer, meta in getattr(self, "metas", {}).items():
        if not isinstance(meta, dict):
            continue
        if str(meta.get("calculated_channel_name", "")) != str(new_col):
            continue
        if str(meta.get("calculation_context_key", "")) == str(context_key):
            if layer in getattr(self, "values", {}):
                return layer
    return None



# calculated map layers associated with one channel
def _derived_layers_for_channel(self, channel):
    out = []
    for layer, meta in getattr(self, "metas", {}).items():
        if layer not in getattr(self, "values", {}):
            continue
        if isinstance(meta, dict) and str(meta.get("calculated_channel_name", "")) == str(channel):
            out.append(layer)
    return out



# copies a calculated sample channel into its analysis table.
def _sample_persistent_channel_to_df(self, df, channel, definition):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    out = df.copy()
    layers = _derived_layers_for_channel(self, channel)
    combined = np.full(len(out), np.nan, dtype=float)
    mineral_values = None
    if "mineral_type" in out.columns:
        mineral_values = out["mineral_type"].astype(str).to_numpy()
    map_values = None
    if "map_group" in out.columns:
        map_values = out["map_group"].astype(str).to_numpy()
    comparison_values = None
    if "comparison_dataset" in out.columns:
        comparison_values = out["comparison_dataset"].astype(str).to_numpy()
    mineral_group_values = None
    if "mineral_group" in out.columns:
        mineral_group_values = out["mineral_group"].astype(str).to_numpy()
    plot_group_values = None
    if "plot_group" in out.columns:
        plot_group_values = out["plot_group"].astype(str).to_numpy()
    grain_set_values = None
    if "grain_set" in out.columns:
        grain_set_values = out["grain_set"].astype(str).to_numpy()
    group_values = None
    if "coordinate_group_key" in out.columns:
        group_values = out["coordinate_group_key"].astype(str).to_numpy()

    # convert restrict to layer identity
    def _restrict_to_layer_identity(use, meta):
        use = np.asarray(use, dtype=bool).copy()
        mineral = str(meta.get("mineral_type", "") or "")
        if mineral_values is not None and mineral:
            use &= mineral_values == mineral
        map_group = str(meta.get("map_group", "") or meta.get("comparison_dataset", "") or "")
        if map_group:
            if map_values is not None:
                use &= map_values == map_group
            elif comparison_values is not None:
                use &= comparison_values == map_group
        mineral_group = str(meta.get("mineral_group", "") or "")
        if mineral_group:
            if mineral_group_values is not None:
                use &= mineral_group_values == mineral_group
            elif plot_group_values is not None:
                use &= plot_group_values == mineral_group
            elif grain_set_values is not None:
                use &= grain_set_values == mineral_group
        group_key = str(
            meta.get("coordinate_group_key", "")
            or meta.get("matrix_group_key", "")
            or meta.get("group_key", "")
        )
        if group_values is not None and group_key:
            use &= group_values == group_key
        return use

    if layers and "row_index" in out.columns and ("column_index" in out.columns):
        rr = pd.to_numeric(out["row_index"], errors="coerce").to_numpy(dtype=float)
        cc = pd.to_numeric(out["column_index"], errors="coerce").to_numpy(dtype=float)
        for layer in layers:
            try:
                z = np.asarray(self.values[layer], dtype=float)
            except Exception:
                continue
            meta = getattr(self, "metas", {}).get(layer, {}) or {}
            use = np.isfinite(rr) & np.isfinite(cc) & ~np.isfinite(combined)
            use = _restrict_to_layer_identity(use, meta)
            if not np.any(use):
                continue
            ri = np.zeros(len(out), dtype=int)
            ci = np.zeros(len(out), dtype=int)
            ri[use] = np.rint(rr[use]).astype(int)
            ci[use] = np.rint(cc[use]).astype(int)
            good = use & (ri >= 0) & (ri < z.shape[0]) & (ci >= 0) & (ci < z.shape[1])
            combined[good] = z[ri[good], ci[good]]
    remaining = ~np.isfinite(combined)
    if layers and np.any(remaining) and ("x" in out.columns) and ("y" in out.columns):
        xs = pd.to_numeric(out["x"], errors="coerce").to_numpy(dtype=float)
        ys = pd.to_numeric(out["y"], errors="coerce").to_numpy(dtype=float)
        for layer in layers:
            meta = getattr(self, "metas", {}).get(layer, {}) or {}
            use = remaining & np.isfinite(xs) & np.isfinite(ys)
            use = _restrict_to_layer_identity(use, meta)
            if not np.any(use):
                continue
            try:
                method = (
                    "bilinear"
                    if "line_id" in out.columns and "row_index" not in out.columns
                    else "nearest"
                )
                vals = self._sample_layer_line_or_point(layer, xs[use], ys[use], method=method)
                combined[use] = np.asarray(vals, dtype=float)
                remaining = ~np.isfinite(combined)
            except Exception:
                pass
    if np.isfinite(combined).any():
        out[channel] = combined
        if np.isfinite(combined).all():
            return out
    try:
        evaluated = pd.to_numeric(
            _calculate_column_values(self, out, definition), errors="coerce"
        )
        if channel not in out.columns:
            out[channel] = evaluated
        else:
            current = pd.to_numeric(out[channel], errors="coerce")
            out[channel] = current.where(current.notna(), evaluated)
    except Exception:
        pass
    return out



# finishes a calculated map channel and refreshes the dependent menus.
def _finish_persistent_calculation(self, definition, table_result):
    new_col = str(definition["new_col"])
    made, skipped = self._materialize_calculated_channel(definition)
    full = self._get_full_calculation_table()
    main_id = None
    if isinstance(full, pd.DataFrame) and len(table_result) == len(full):
        full[new_col] = pd.to_numeric(table_result, errors="coerce").to_numpy(dtype=float)
        main_id = id(full)
        self.analysis_df = full
        self.active_analysis_df = full
        self.comparison_df = full.copy(deep=False)
        self._full_analysis_df_for_plotting = full
        self._full_analysis_source_name = str(
            getattr(self, "analysis_source_name", "analysis table")
        )
    self._propagate_persistent_channel(
        new_col,
        definition,
        skip_ids={main_id} if main_id is not None else None,
    )
    if new_col in getattr(self, "excluded_columns", set()):
        self.excluded_columns.remove(new_col)
    try:
        self._set_active_everywhere(
            self.active_analysis_df, getattr(self, "analysis_source_name", "analysis table")
        )
    except Exception:
        try:
            self.refresh_analysis_columns()
        except Exception:
            pass
    if made:
        try:
            self.column_var.set(new_col)
            self.update_map()
        except Exception:
            pass
    return made, skipped



# IQR multiplier currently used by the outlier filter
def _iqr_multiplier(self):
    self._ensure_iqr_settings()
    value = safe_float(self.plot_iqr_multiplier_var.get(), 1.5)
    if not np.isfinite(value) or value < 0:
        raise ValueError("IQR multiplier must be zero or greater.")
    return float(value)



# stores a temporary IQR setting for one plot
def _set_iqr_override(self, df):
    self._iqr_plot_override_df = df.copy() if isinstance(df, pd.DataFrame) else None



# removes the temporary IQR setting
def _clear_iqr_override(self):
    self._iqr_plot_override_df = None



# unfiltered analysis table behind the current plots
def _raw_analysis_table(self):
    override = getattr(self, "_iqr_plot_override_df", None)
    if isinstance(override, pd.DataFrame):
        return override.copy()
    return _raw_analysis_source_table(self)



# plot figure for X-Y plots
def _plot_xy_figure(self):
    x_col = str(self.xy_x_col_var.get()) if hasattr(self, "xy_x_col_var") else ""
    y_col = str(self.xy_y_col_var.get()) if hasattr(self, "xy_y_col_var") else ""
    raw = _raw_analysis_source_table(self)
    filtered, info = self._apply_iqr_filter(raw, [x_col, y_col])
    _set_iqr_override(self, filtered)
    try:
        out = _plot_xy(self)
    finally:
        _clear_iqr_override(self)
    self._append_iqr_note(info, context="X-Y")
    return out



# removes labeled frames whose titles match the supplied names.
def _destroy_named_labelframes(root, names):
    try:
        children = list(root.winfo_children())
    except Exception:
        return
    for child in children:
        try:
            if isinstance(child, ttk.LabelFrame) and str(child.cget("text")) in names:
                child.destroy()
                continue
        except Exception:
            pass
        _destroy_named_labelframes(child, names)



# pixel positions and distances along a drawn polyline
def _polyline_pixel_distance_table(self, pixel_df, points):
    rows = pd.to_numeric(pixel_df["row_index"], errors="coerce").to_numpy(dtype=float)
    cols = pd.to_numeric(pixel_df["column_index"], errors="coerce").to_numpy(dtype=float)
    best_perp = np.full(len(pixel_df), np.inf, dtype=float)
    best_along = np.full(len(pixel_df), np.nan, dtype=float)
    cumulative_length = 0.0
    for i in range(len(points) - 1):
        x0, y0 = points[i]
        x1, y1 = points[i + 1]
        row0, col0 = self.data_xy_to_fractional_indices(x0, y0)
        row1, col1 = self.data_xy_to_fractional_indices(x1, y1)
        t, perp = self._segment_projection_and_distance_pixels(rows, cols, row0, col0, row1, col1)
        segment_length = float(np.hypot(x1 - x0, y1 - y0))
        update = np.isfinite(perp) & (perp < best_perp)
        best_perp[update] = perp[update]
        best_along[update] = cumulative_length + t[update] * segment_length
        cumulative_length += segment_length
    out = pixel_df.copy()
    out["perpendicular_distance_pixels"] = best_perp
    out["distance"] = best_along
    out["line_total_length"] = float(cumulative_length)
    if cumulative_length > 0:
        out["distance_normalized"] = best_along / float(cumulative_length)
    else:
        out["distance_normalized"] = 0.0
    return out



# plot summary for radial profiles
def _plot_radial_summary(self):
    if getattr(self, "last_grain_df", None) is None or self.last_grain_df.empty:
        messagebox.showinfo("No grains", "Detect grains first.")
        return
    try:
        ax, canvas = self._visible_map_ax_canvas()
    except Exception:
        ax, canvas = (None, None)
    if ax is None:
        ax = getattr(self, "grain_ax", None) or getattr(self, "ax", None)
    if canvas is None:
        try:
            canvas = self._grain_canvas()
        except Exception:
            canvas = getattr(self, "grain_canvas", None) or getattr(self, "canvas", None)
    if ax is None or canvas is None:
        messagebox.showerror("No plot", "Could not find the visible map plot.")
        return
    try:
        limits = self._current_visible_axis_limits()
    except Exception:
        limits = None
    for artist in getattr(self, "_grain_radial_line_artists", []):
        try:
            artist.remove()
        except Exception:
            pass
    self._grain_radial_line_artists = []
    try:
        n_lines = int(float(self.grain_radial_line_count_var.get()))
    except Exception:
        n_lines = 8
    n_lines = max(1, min(n_lines, 180))
    for _, grain_row in self.last_grain_df.iterrows():
        try:
            cx, cy, major, minor, angle_deg, _ = self._grain_current_ellipse_params(grain_row)
        except Exception:
            continue
        if not all((np.isfinite(v) for v in [cx, cy, major, minor, angle_deg])):
            continue
        if major <= 0 or minor <= 0:
            continue
        spokes = self._grain_radial_ordered_spokes(cx, cy, major, minor, angle_deg, n_lines)
        for spoke in spokes:
            xedge = spoke["xedge"]
            yedge = spoke["yedge"]
            number = spoke["profile_number"]
            (halo,) = ax.plot(
                [cx, xedge],
                [cy, yedge],
                color="white",
                linewidth=3.4,
                alpha=0.95,
                zorder=90000,
                solid_capstyle="round",
            )
            (line,) = ax.plot(
                [cx, xedge],
                [cy, yedge],
                color="magenta",
                linewidth=1.5,
                alpha=0.98,
                zorder=90001,
                solid_capstyle="round",
            )
            label = ax.text(
                xedge,
                yedge,
                str(number),
                ha="center",
                va="center",
                fontsize=7,
                zorder=90003,
                bbox=dict(facecolor="white", edgecolor="none", alpha=0.8, pad=0.8),
            )
            self._grain_radial_line_artists.extend([halo, line, label])
        center_halo = ax.scatter(
            [cx], [cy], s=95, c="white", marker="+", linewidths=3.0, zorder=90004
        )
        center_mark = ax.scatter(
            [cx], [cy], s=65, c="magenta", marker="+", linewidths=2.0, zorder=90005
        )
        self._grain_radial_line_artists.extend([center_halo, center_mark])
    try:
        self._restore_visible_axis_limits(limits)
    except Exception:
        pass
    try:
        canvas.draw_idle()
    except Exception:
        pass
    try:
        self.status_var.set(
            f"Showing {n_lines} numbered radial profiles per grain. Profile 1 starts at the long-axis tip and numbering runs clockwise."
        )
    except Exception:
        pass



# normalizes X-Y group labels before colors and legends are assigned.
def _normalize_xy_group_labels(raw_text):
    raw_text = str(raw_text or "").strip()
    if not raw_text:
        return []
    labels = []
    pieces = [piece.strip() for piece in re.split("[|;]+", raw_text) if piece.strip()]
    for index, piece in enumerate(pieces, start=1):
        label = f"Group {index}"
        if ":" in piece:
            maybe_label, _ = piece.split(":", 1)
            if maybe_label.strip():
                label = maybe_label.strip()
        labels.append(label)
    return labels



# normalizes custom X-Y colors into matplotlib values
def _normalize_xy_group_colors(self):
    try:
        labels = _normalize_xy_group_labels(self.custom_color_groups_var.get())
    except Exception:
        labels = []
    try:
        raw_colors = self.custom_color_group_colors_var.get()
    except Exception:
        raw_colors = "red, blue, green, purple, orange, cyan"
    colors = [value.strip() for value in str(raw_colors).split(",") if value.strip()]
    valid_colors = [value for value in colors if mcolors.is_color_like(value)]
    if not valid_colors:
        valid_colors = ["C0", "C1", "C2", "C3", "C4", "C5"]
    color_map = {
        str(label): valid_colors[index % len(valid_colors)] for index, label in enumerate(labels)
    }
    self.custom_color_group_color_map = color_map
    return color_map



# category-to-color lookup for X-Y plots
def _xy_category_color_map(self, values):
    categories = [str(value) for value in pd.Series(values).fillna("NA").astype(str).unique()]
    manual = _normalize_xy_group_colors(self)
    cmap = plt.get_cmap("tab20")
    output = {}
    fallback_index = 0
    for category in categories:
        if category in manual:
            output[category] = manual[category]
        else:
            output[category] = cmap(fallback_index % 20)
            fallback_index += 1
    return output



# identifies categorical grouping fields in X-Y plots
def _xy_is_categorical_group_column(pair, column):
    if column not in pair.columns:
        return False
    name = str(column).strip().lower()
    categorical_names = {
        "grain_id",
        "line_id",
        "area_id",
        "spot_id",
        "profile_number",
        "domain",
        "mineral",
        "mineral_type",
        "mineral_group",
        "grain_set",
        "custom_color_group",
        "map_group",
    }
    if name in categorical_names or name.endswith("_id"):
        return True
    series = pair[column]
    if not pd.api.types.is_numeric_dtype(series):
        return True
    try:
        return int(series.nunique(dropna=True)) <= 50
    except Exception:
        return False



# grouping column used for separate X-Y regressions
def _xy_regression_group_column(self, pair):
    try:
        selected = str(self.xy_regression_group_var.get()).strip()
    except Exception:
        selected = "Auto"
    if selected and selected != "Auto" and (selected in pair.columns):
        return selected
    try:
        color_by = str(self.xy_color_by_var.get()).strip()
    except Exception:
        color_by = "None"
    if color_by and color_by != "None" and _xy_is_categorical_group_column(pair, color_by):
        return color_by
    if "custom_color_group" in pair.columns:
        return "custom_color_group"
    return _xy_group_column_for_lines(pair)



# short internal key for the selected X-Y regression mode.
def _xy_regression_mode_key(self):
    try:
        raw = str(self.xy_regression_mode_var.get()).strip().lower()
    except Exception:
        raw = "none"
    compact = re.sub("\\s+", " ", raw)
    if compact in {"per group", "one fit per group", "group", "grouped"}:
        return "per_group"
    if compact in {"all data", "one fit for all data", "all", "overall"}:
        return "all_data"
    return "none"



# keeps the X-Y regression controls mutually consistent
def _xy_sync_regression_mode(self):
    mode = _xy_regression_mode_key(self)
    try:
        self.xy_fit_line_var.set(mode != "none")
        self.xy_fit_each_group_var.set(mode == "per_group")
    except Exception:
        pass



# draw scatter for X-Y plots
def _draw_xy_scatter(self, pair, x_col, y_col):
    color_by = self.xy_color_by_var.get() if hasattr(self, "xy_color_by_var") else "None"
    symbol_by = self.xy_symbol_by_var.get() if hasattr(self, "xy_symbol_by_var") else "None"
    x = pair[x_col].to_numpy(dtype=float)
    y = pair[y_col].to_numpy(dtype=float)
    markers = ["o", "s", "^", "D", "v", "P", "X", "*"]
    if symbol_by and symbol_by != "None" and (symbol_by in pair.columns):
        symbol_values = pd.Series(pair[symbol_by]).fillna("NA").astype(str)
        symbol_categories = list(pd.unique(symbol_values))
    else:
        symbol_values = pd.Series(["all"] * len(pair), index=pair.index)
        symbol_categories = ["all"]
    marker_map = {
        category: markers[index % len(markers)] for index, category in enumerate(symbol_categories)
    }
    if color_by and color_by != "None" and (color_by in pair.columns):
        color_values = pair[color_by]
        numeric = pd.to_numeric(color_values, errors="coerce")
        continuous = numeric.notna().sum() == len(color_values) and (
            not _xy_is_categorical_group_column(pair, color_by)
        )
        if continuous:
            artist = None
            for symbol_category in symbol_categories:
                mask = symbol_values.to_numpy() == symbol_category
                if not np.any(mask):
                    continue
                artist = self.xy_ax.scatter(
                    x[mask],
                    y[mask],
                    c=numeric.to_numpy(dtype=float)[mask],
                    s=18,
                    alpha=0.78,
                    marker=marker_map[symbol_category],
                    cmap="viridis",
                    label=str(symbol_category) if symbol_category != "all" else None,
                )
            if artist is not None:
                _add_xy_colorbar(self, artist, color_by)
            if len(symbol_categories) > 1:
                self.xy_ax.legend(title=symbol_by, fontsize=7, loc="best", frameon=True)
            return
        categories = pd.Series(color_values).fillna("NA").astype(str)
        color_map = _xy_category_color_map(self, categories)
        for category in pd.unique(categories):
            category_mask = categories.to_numpy() == category
            for symbol_category in symbol_categories:
                symbol_mask = symbol_values.to_numpy() == symbol_category
                mask = category_mask & symbol_mask
                if not np.any(mask):
                    continue
                label = str(category)
                if len(symbol_categories) > 1:
                    label = f"{category} / {symbol_category}"
                self.xy_ax.scatter(
                    x[mask],
                    y[mask],
                    s=18,
                    alpha=0.78,
                    color=color_map.get(str(category)),
                    marker=marker_map[symbol_category],
                    label=label,
                )
        try:
            handles, labels = self.xy_ax.get_legend_handles_labels()
            if handles and len(handles) <= 30:
                self.xy_ax.legend(title=color_by, fontsize=7, loc="best", frameon=True)
        except Exception:
            pass
        return
    for symbol_category in symbol_categories:
        mask = symbol_values.to_numpy() == symbol_category
        self.xy_ax.scatter(
            x[mask],
            y[mask],
            s=18,
            alpha=0.78,
            marker=marker_map[symbol_category],
            label=str(symbol_category) if symbol_category != "all" else None,
        )
    if len(symbol_categories) > 1:
        self.xy_ax.legend(title=symbol_by, fontsize=7, loc="best", frameon=True)



# connects X-Y points in their saved line or profile order.
def _plot_xy_lines(self, pair_plot, x_col, y_col, include_points=False):
    group_col = _xy_group_column_for_lines(pair_plot)
    try:
        connect_in_path_order = bool(self.xy_connect_in_path_order_var.get())
    except Exception:
        connect_in_path_order = True
    order_cols = _xy_order_columns(pair_plot) if connect_in_path_order else []
    try:
        connect_by_group = bool(self.xy_connect_by_group_var.get())
    except Exception:
        connect_by_group = True
    try:
        color_by = str(self.xy_color_by_var.get()).strip()
    except Exception:
        color_by = "None"
    use_category_color = (
        color_by
        and color_by != "None"
        and (color_by in pair_plot.columns)
        and _xy_is_categorical_group_column(pair_plot, color_by)
    )
    color_map = _xy_category_color_map(self, pair_plot[color_by]) if use_category_color else {}
    if include_points:
        _draw_xy_scatter(self, pair_plot, x_col, y_col)
    if group_col is not None and connect_by_group:
        category_labeled = set()
        for group_value, sub in pair_plot.groupby(group_col, dropna=False):
            sub = sub.copy()
            if order_cols:
                for column in order_cols:
                    sub[column] = pd.to_numeric(sub[column], errors="coerce")
                sub = sub.sort_values(order_cols)
            else:
                sub = sub.sort_values(x_col)
            if len(sub) < 2:
                continue
            kwargs = {"linewidth": 1.4, "alpha": 0.85}
            label = str(group_value)
            if use_category_color:
                category_values = pd.Series(sub[color_by]).fillna("NA").astype(str)
                category = category_values.mode().iloc[0] if not category_values.empty else "NA"
                kwargs["color"] = color_map.get(category)
                if category in category_labeled:
                    label = "_nolegend_"
                else:
                    label = category
                    category_labeled.add(category)
            self.xy_ax.plot(sub[x_col], sub[y_col], label=label, **kwargs)
        try:
            handles, labels = self.xy_ax.get_legend_handles_labels()
            if handles and len(handles) <= 30:
                self.xy_ax.legend(
                    title=color_by if use_category_color else group_col,
                    fontsize=7,
                    loc="best",
                    frameon=True,
                )
        except Exception:
            pass
        return
    sub = pair_plot.copy()
    if order_cols:
        for column in order_cols:
            sub[column] = pd.to_numeric(sub[column], errors="coerce")
        sub = sub.sort_values(order_cols)
    else:
        sub = sub.sort_values(x_col)
    if len(sub) >= 2:
        self.xy_ax.plot(sub[x_col], sub[y_col], linewidth=1.6, alpha=0.85)



# fits and draws the requested X-Y regression lines
def _add_xy_regression_lines(self, pair_plot, x_col, y_col):
    if pair_plot is None or pair_plot.empty:
        return pd.DataFrame()
    mode = _xy_regression_mode_key(self)
    if mode == "none":
        return pd.DataFrame()
    group_col = _xy_regression_group_column(self, pair_plot) if mode == "per_group" else None
    if mode == "per_group" and group_col is None:
        messagebox.showwarning(
            "Regression groups",
            "Choose Group by or a categorical Color by column.",
        )
        return pd.DataFrame()
    groups = (
        [("all", pair_plot)]
        if group_col is None
        else list(pair_plot.groupby(group_col, dropna=False))
    )
    color_map = (
        _xy_category_color_map(self, [group_value for group_value, _ in groups])
        if group_col
        else {}
    )
    rows = []
    for group_value, sub in groups:
        x = pd.to_numeric(sub[x_col], errors="coerce").to_numpy(dtype=float)
        y = pd.to_numeric(sub[y_col], errors="coerce").to_numpy(dtype=float)
        valid = np.isfinite(x) & np.isfinite(y)
        x = x[valid]
        y = y[valid]
        if len(x) < 2 or float(np.nanmax(x)) == float(np.nanmin(x)):
            continue
        slope, intercept = np.polyfit(x, y, 1)
        y_pred = slope * x + intercept
        ss_res = float(np.sum((y - y_pred) ** 2))
        ss_tot = float(np.sum((y - np.mean(y)) ** 2))
        r_squared = np.nan if ss_tot <= 0 else 1.0 - ss_res / ss_tot
        x_line = np.linspace(float(np.nanmin(x)), float(np.nanmax(x)), 100)
        y_line = slope * x_line + intercept
        if group_col is None:
            label = f"linear fit: y={slope:.3g}x+{intercept:.3g}, R²={r_squared:.3f}"
            color = None
        else:
            label = f"{group_value}: y={slope:.3g}x+{intercept:.3g}, R²={r_squared:.3f}"
            color = color_map.get(str(group_value))
        self.xy_ax.plot(
            x_line, y_line, linestyle="--", linewidth=2.0, alpha=0.95, color=color, label=label
        )
        rows.append(
            {
                "group_column": group_col or "all_data",
                "group": str(group_value),
                "x_column": x_col,
                "y_column": y_col,
                "slope": float(slope),
                "intercept": float(intercept),
                "r_squared": float(r_squared) if np.isfinite(r_squared) else np.nan,
                "n": int(len(x)),
            }
        )
    try:
        handles, labels = self.xy_ax.get_legend_handles_labels()
        if handles and len(handles) <= 30:
            self.xy_ax.legend(fontsize=7, loc="best", frameon=True)
    except Exception:
        pass
    return pd.DataFrame(rows)



# applies the legend on/off setting to the X-Y figure.
def _xy_apply_legend_visibility(self):
    ax = getattr(self, "xy_ax", None)
    if ax is None:
        return
    try:
        show_legend = bool(self.xy_show_legend_var.get())
    except Exception:
        show_legend = True
    try:
        existing = ax.get_legend()
        if existing is not None:
            existing.remove()
    except Exception:
        pass
    if not show_legend:
        return
    try:
        handles, labels = ax.get_legend_handles_labels()
    except Exception:
        return
    unique = []
    seen = set()
    for handle, label in zip(handles, labels):
        label = str(label)
        if not label or label.startswith("_") or label in seen:
            continue
        seen.add(label)
        unique.append((handle, label))
    if not unique:
        return
    total = len(unique)
    try:
        limit = optional_positive_int(self.xy_legend_max_entries_var.get())
    except Exception:
        limit = 30
    if limit is not None and total > limit:
        unique = unique[:limit]
    shown = len(unique)
    legend_handles = [item[0] for item in unique]
    legend_labels = [item[1] for item in unique]
    title = None
    try:
        color_by = str(self.xy_color_by_var.get()).strip()
        symbol_by = str(self.xy_symbol_by_var.get()).strip()
        if color_by and color_by != "None":
            title = color_by
        elif symbol_by and symbol_by != "None":
            title = symbol_by
    except Exception:
        pass
    if total > shown:
        suffix = f"first {shown} of {total}"
        title = f"{title} ({suffix})" if title else suffix
    ncol = 1 if shown <= 12 else min(3, int(np.ceil(shown / 12.0)))
    try:
        ax.legend(
            legend_handles,
            legend_labels,
            title=title,
            fontsize=7,
            title_fontsize=7,
            loc="best",
            frameon=True,
            ncol=ncol,
        )
    except Exception:
        pass



# grouping fields available for X-Y regressions
def _xy_regression_group_choices(self):
    choices = ["Auto"]
    df = self.get_active_analysis_table()
    if isinstance(df, pd.DataFrame):
        priority = [
            "custom_color_group",
            "profile_color_group",
            "plot_group_id",
            "plot_group",
            "line_id",
            "profile_id",
            "grain_id",
            "domain",
            "area_id",
            "spot_id",
            "mineral_type",
            "comparison_dataset",
        ]
        for column in priority:
            if column in df.columns and column not in choices:
                choices.append(column)
        for column in df.columns:
            if column not in choices and _xy_is_categorical_group_column(df, column):
                choices.append(str(column))
    return choices



# small UI wrapper for a control section that can be opened or closed.
def _collapsible_section(parent, title, var, initially_open=False):
    if not hasattr(var, "get"):
        var = tk.BooleanVar(value=bool(initially_open))
    header = ttk.Checkbutton(parent, text=title, variable=var)
    header.pack(anchor="w", pady=(4, 1))
    body = ttk.Frame(parent)

    # refresh
    def refresh(*_args):
        try:
            open_now = bool(var.get())
        except Exception:
            open_now = False
        if open_now:
            if not body.winfo_manager():
                body.pack(fill=tk.X, padx=(12, 0), pady=(0, 3), after=header)
        else:
            try:
                body.pack_forget()
            except Exception:
                pass

    try:
        var.trace_add("write", refresh)
    except Exception:
        pass
    refresh()
    return body



