# complete grain table before display-only columns are trimmed
def _full_grain_dataframe(self):
    for attr in ["last_grain_df_full", "last_grain_table_full", "last_grain_df"]:
        df = getattr(self, attr, None)
        if isinstance(df, pd.DataFrame) and (not df.empty) and ("grain_id" in df.columns):
            return df
    return None



# runs grain analysis and stores the result under its sample/mineral key.
def _run_grain_analysis_and_store(self, *args, **kwargs):
    mode = str(
        getattr(self, "grain_display_mode_var", tk.StringVar(value="Element map + outlines")).get()
    )
    debug_map = {
        "Raw mask": "raw_mask",
        "Cleaned mask": "cleaned_mask",
        "Split seeds": "split_seeds",
    }
    try:
        self.grain_debug_view_var.set(debug_map.get(mode, "final_grains"))
    except Exception:
        pass
    out = _run_grain_analysis(self, *args, **kwargs) if _run_grain_analysis is not None else None
    if mode == "Element map + outlines":
        try:
            self.show_grains_on_selected_element_map()
        except Exception:
            pass
    elif mode == "Colored grain labels":
        try:
            self.show_grain_labels_without_offset()
        except Exception:
            pass
    return out



# starts grain analysis from the controls beside the map.
def _run_grain_analysis_from_map_view_ui(self, *args, **kwargs):
    return _run_grain_analysis_and_store(self, *args, **kwargs)



# leave split line mode
def stop_split_line_mode(self, disconnect_only=False):
    try:
        stop_manual_split_line_tool(self, disconnect_only=disconnect_only)
    except Exception:
        try:
            disconnect_split_line_events(self)
        except Exception:
            pass
        self.split_line_mode_active = False
        self.drawing_split_line = False
        self.manual_grain_split_active = False
        self.current_split_line_start = None
        self.manual_grain_split_start = None



# disconnect center move events
def _disconnect_center_move_events(self):
    for canvas, cid in list(getattr(self, "_grain_center_event_ids", []) or []):
        try:
            canvas.mpl_disconnect(cid)
        except Exception:
            pass
    self._grain_center_event_ids = []
    for canvas in _grain_interaction_all_canvases(self):
        for attr in [
            "_move_grain_center_press_cid",
            "_move_grain_center_motion_cid",
            "_move_grain_center_release_cid",
            "_move_grain_center_cid",
        ]:
            cid = getattr(self, attr, None)
            if cid:
                try:
                    canvas.mpl_disconnect(cid)
                except Exception:
                    pass
    for attr in [
        "_move_grain_center_press_cid",
        "_move_grain_center_motion_cid",
        "_move_grain_center_release_cid",
        "_move_grain_center_cid",
    ]:
        setattr(self, attr, None)



# leave move grain center mode
def _stop_move_grain_center_mode(self):
    _disconnect_center_move_events(self)
    self._move_grain_center_active = False
    self._dragging_grain_center = False
    self._drag_grain_center_gid = None
    self._last_grain_drag_xy = None
    try:
        self._clear_drag_center_preview()
    except Exception:
        pass
    try:
        self.status_var.set("Stopped moving grain centers.")
    except Exception:
        pass



# map X-Y coordinates from a grain-center mouse event
def _center_event_data_xy(self, event):
    if event is None:
        return None
    if event.xdata is not None and event.ydata is not None:
        return (float(event.xdata), float(event.ydata))
    ax = getattr(self, "_grain_center_axis", None)
    if ax is None:
        return None
    try:
        x, y = ax.transData.inverted().transform((float(event.x), float(event.y)))
        if np.isfinite(x) and np.isfinite(y):
            return (float(x), float(y))
    except Exception:
        pass
    return None



# hides repeated labels left by older versions of the layout.
def _hide_duplicate_text_widgets(tab, class_name, text_value, keep=1):
    found = [
        w
        for w in _walk_widgets(tab)
        if w.winfo_class() == class_name and _widget_text(w) == text_value
    ]
    for widget in found[keep:]:
        try:
            widget.pack_forget()
        except Exception:
            try:
                widget.grid_remove()
            except Exception:
                pass



# collapses one labeled control frame
def _collapse_label_frame(
    self, tab, frame_text, attr_name, toggle_text="Show advanced display options"
):
    frames = [
        w
        for w in _walk_widgets(tab)
        if w.winfo_class() == "TLabelframe" and _widget_text(w) == frame_text
    ]
    if not frames:
        return
    frame = frames[0]
    if getattr(frame, "_collapse_binding_added", False):
        return
    parent = frame.master
    try:
        info = frame.pack_info().copy()
    except Exception:
        return
    frame._collapse_binding_added = True
    for key in ["in", "before", "after"]:
        info.pop(key, None)
    var = getattr(self, attr_name, None)
    if not hasattr(var, "get"):
        var = tk.BooleanVar(value=False)
        setattr(self, attr_name, var)
    toggle = ttk.Checkbutton(parent, text=toggle_text, variable=var)
    try:
        toggle.pack(before=frame, fill=tk.X, pady=(2, 2))
    except Exception:
        toggle.pack(fill=tk.X, pady=(2, 2))

    # refresh
    def refresh(*_args):
        if bool(var.get()):
            if not frame.winfo_manager():
                try:
                    frame.pack(after=toggle, **info)
                except Exception:
                    frame.pack(fill=tk.X, pady=4, after=toggle)
        else:
            try:
                frame.pack_forget()
            except Exception:
                pass

    try:
        var.trace_add("write", refresh)
    except Exception:
        pass
    refresh()



# finds a run of packed widgets between two known labels.
def _packed_range_by_text(tab, start_text, end_text=None):
    start_widget = None
    for widget in _walk_widgets(tab):
        if _widget_text(widget) == start_text and widget.winfo_manager() == "pack":
            start_widget = widget
            break
    if start_widget is None:
        return (None, [])
    parent = start_widget.master
    children = list(parent.pack_slaves())
    try:
        start_idx = children.index(start_widget)
    except ValueError:
        return (parent, [])
    end_idx = len(children)
    if end_text is not None:
        for i in range(start_idx + 1, len(children)):
            if _widget_text(children[i]) == end_text:
                end_idx = i
                break
    return (parent, children[start_idx:end_idx])



# collapses a known range of packed widgets
def _collapse_widget_range(self, tab, start_text, end_text, attr_name, toggle_text):
    parent, targets = _packed_range_by_text(tab, start_text, end_text)
    if parent is None or not targets:
        return
    first = targets[0]
    if getattr(first, "_range_collapse_binding_added", False):
        return
    first._range_collapse_binding_added = True
    infos = []
    for target in targets:
        try:
            info = target.pack_info().copy()
            for key in ["in", "before", "after"]:
                info.pop(key, None)
        except Exception:
            info = {"fill": tk.X}
        infos.append((target, info))
    var = getattr(self, attr_name, None)
    if not hasattr(var, "get"):
        var = tk.BooleanVar(value=False)
        setattr(self, attr_name, var)
    toggle = ttk.Checkbutton(parent, text=toggle_text, variable=var)
    try:
        toggle.pack(before=first, fill=tk.X, pady=(3, 2))
    except Exception:
        toggle.pack(fill=tk.X, pady=(3, 2))

    # refresh
    def refresh(*_args):
        if bool(var.get()):
            prev = toggle
            for target, info in infos:
                if not target.winfo_manager():
                    try:
                        target.pack(after=prev, **info)
                    except Exception:
                        target.pack(after=prev, fill=tk.X)
                prev = target
        else:
            for target, _info in infos:
                try:
                    target.pack_forget()
                except Exception:
                    pass

    try:
        var.trace_add("write", refresh)
    except Exception:
        pass
    refresh()



# finds a widget range from nearby labels at runtime.
def _dynamic_widget_range(self, tab, start_text, end_text, variable, show_value):
    parent, targets = _packed_range_by_text(tab, start_text, end_text)
    if parent is None or not targets or (not hasattr(variable, "get")):
        return
    first = targets[0]
    if getattr(first, "_range_visibility_binding_added", False):
        return
    first._range_visibility_binding_added = True
    infos = []
    for target in targets:
        try:
            info = target.pack_info().copy()
            for key in ["in", "before", "after"]:
                info.pop(key, None)
        except Exception:
            info = {"fill": tk.X}
        infos.append((target, info))
    anchor = ttk.Frame(parent, height=1)
    try:
        anchor.pack(before=first, fill=tk.X)
    except Exception:
        anchor.pack(fill=tk.X)

    # refresh
    def refresh(*_args):
        show = str(variable.get()) == str(show_value)
        if show:
            prev = anchor
            for target, info in infos:
                if not target.winfo_manager():
                    try:
                        target.pack(after=prev, **info)
                    except Exception:
                        target.pack(after=prev, fill=tk.X)
                prev = target
        else:
            for target, _info in infos:
                try:
                    target.pack_forget()
                except Exception:
                    pass

    try:
        variable.trace_add("write", refresh)
    except Exception:
        pass
    refresh()



# hides the repeated controls at the bottom of the map panel.
def _hide_map_bottom_duplicates(self):
    tab = getattr(self, "map_tab", None)
    if tab is None:
        return
    _hide_duplicate_text_widgets(tab, "TButton", "Use grain means", keep=0)
    _hide_duplicate_text_widgets(tab, "TButton", "Use grain pixels", keep=0)

    orientation_labels = [
        widget
        for widget in _walk_widgets(tab)
        if widget.winfo_class() == "TLabel" and _widget_text(widget) == "Map orientation:"
    ]
    for widget in orientation_labels[1:]:
        parent = widget.master
        children = list(parent.winfo_children())
        try:
            idx = children.index(widget)
        except ValueError:
            continue
        for target in children[idx : idx + 3]:
            try:
                target.pack_forget()
            except Exception:
                pass



# first numeric grain field available for a default plot choice.
def _first_numeric_grain_column(df, candidates):
    for column in candidates:
        if column not in df.columns:
            continue
        values = pd.to_numeric(df[column], errors="coerce")
        if values.notna().any():
            return values
    return pd.Series(np.nan, index=df.index, dtype=float)



# builds the radial-profile results table
def _build_radial_table(self):
    if getattr(self, "last_grain_df", None) is None or self.last_grain_df.empty:
        raise ValueError("Detect grains first.")
    if not hasattr(self, "last_grain_label_mask"):
        raise ValueError("No grain labels are available. Detect grains again.")
    full_grains = _full_grain_dataframe(self)
    grain_table = self.ensure_grain_shape_metrics(
        full_grains if full_grains is not None else self.last_grain_df
    )
    n_lines = max(1, min(self._grain_radial_get_int("grain_radial_line_count_var", 8), 180))
    buffer_px = self.get_profile_buffer_pixels()
    n_bins = max(2, self._grain_radial_get_int("grain_radial_bins_var", 25))
    x_axis = np.asarray(self.last_grain_x, dtype=float)
    y_axis = np.asarray(self.last_grain_y, dtype=float)
    profile_parts = []
    for _, grain_row in grain_table.iterrows():
        grain_id = int(grain_row["grain_id"])
        candidates = self._radial_profile_candidate_pixels(grain_id, grain_row)
        if candidates.empty:
            continue
        try:
            cx, cy, major, minor, angle_deg, _method = self._grain_current_ellipse_params(grain_row)
        except Exception:
            continue
        if not all(np.isfinite(value) for value in [cx, cy, major, minor, angle_deg]) or major <= 0 or minor <= 0:
            continue
        rows = candidates["row_index"].to_numpy(dtype=float)
        cols = candidates["column_index"].to_numpy(dtype=float)
        center_r, center_c = self._xy_to_fractional_indices_on_axes([cx], [cy], x_axis, y_axis)
        if not np.isfinite(center_r[0]) or not np.isfinite(center_c[0]):
            continue
        spokes = self._grain_radial_ordered_spokes(cx, cy, major, minor, angle_deg, n_lines)
        for spoke in spokes:
            edge_r, edge_c = self._xy_to_fractional_indices_on_axes(
                [spoke["xedge"]], [spoke["yedge"]], x_axis, y_axis
            )
            if not np.isfinite(edge_r[0]) or not np.isfinite(edge_c[0]):
                continue
            dr = float(edge_r[0] - center_r[0])
            dc = float(edge_c[0] - center_c[0])
            length_squared = dr * dr + dc * dc
            if not np.isfinite(length_squared) or length_squared <= 0:
                continue
            t_raw = ((rows - center_r[0]) * dr + (cols - center_c[0]) * dc) / length_squared
            projected_r = center_r[0] + t_raw * dr
            projected_c = center_c[0] + t_raw * dc
            perpendicular = np.sqrt((rows - projected_r) ** 2 + (cols - projected_c) ** 2)
            take = (
                np.isfinite(t_raw)
                & np.isfinite(perpendicular)
                & (t_raw >= 0.0)
                & (t_raw <= 1.0)
                & (perpendicular <= float(buffer_px))
            )
            if not np.any(take):
                continue
            chosen = candidates.iloc[np.where(take)[0]].copy()
            profile_number = int(spoke["profile_number"])
            profile_degrees = float(spoke["profile_clockwise_angle_deg"])
            physical_length = float(
                np.hypot(float(spoke["xedge"]) - float(cx), float(spoke["yedge"]) - float(cy))
            )
            chosen["profile_number"] = profile_number
            chosen["profile_degrees"] = profile_degrees
            chosen["distance_normalized"] = t_raw[take]
            chosen["distance"] = t_raw[take] * physical_length
            chosen["profile_id"] = f"grain_{grain_id}_profile_{profile_number:02d}"
            chosen["distance_bin"] = np.minimum(
                np.floor(chosen["distance_normalized"].to_numpy(dtype=float) * n_bins).astype(int),
                n_bins - 1,
            )
            profile_parts.append(chosen)
    if not profile_parts:
        raise ValueError(
            "No grain pixels fall inside the radial profile swaths. Increase the pixel buffer or check the grain fits."
        )
    full_pixels = pd.concat(profile_parts, ignore_index=True)
    full_pixels = full_pixels.sort_values(
        ["grain_id", "profile_number", "distance_normalized"], kind="mergesort"
    ).reset_index(drop=True)
    value_columns = self._grain_value_columns_for_profiles(full_pixels)
    identifier_columns = [
        column
        for column in ["sample_id", "mineral_id", "run_id", "grain_id", "profile_number", "profile_degrees", "distance", "distance_normalized"]
        if column in full_pixels.columns
    ]
    chemistry_columns = [
        column
        for column in value_columns
        if column not in identifier_columns
        and column not in {
            "x", "y", "row_index", "column_index", "pixel_id", "profile_id",
            "distance_bin", "profile_number", "profile_degrees", "distance", "distance_normalized"
        }
    ]
    user_pixels = full_pixels[identifier_columns + chemistry_columns].copy()
    group_columns = [
        column
        for column in ["sample_id", "mineral_id", "run_id", "grain_id", "profile_number", "profile_degrees", "distance_bin"]
        if column in full_pixels.columns
    ]
    aggregation = {column: "mean" for column in chemistry_columns if column in full_pixels.columns}
    aggregation["distance"] = "mean"
    aggregation["distance_normalized"] = "mean"
    binned = full_pixels.groupby(group_columns, dropna=False).agg(aggregation).reset_index()
    if "distance_bin" in binned.columns:
        binned = binned.drop(columns=["distance_bin"])
    self.last_grain_radial_profile_pixels_full_df = full_pixels.copy()
    self.last_grain_radial_profile_bins_full_df = binned.copy()
    self.last_grain_radial_profile_pixels_df = user_pixels.copy()
    self.last_grain_radial_profile_bins_df = binned.copy()
    return user_pixels, binned



# finds a labeled frame by the title shown in the UI.
def _find_labelframe_with_title(root, title):
    try:
        children = root.winfo_children()
    except Exception:
        return None
    for child in children:
        try:
            if isinstance(child, ttk.LabelFrame) and str(child.cget("text")) == title:
                return child
        except Exception:
            pass
        found = _find_labelframe_with_title(child, title)
        if found is not None:
            return found
    return None



# build controls for grain analysis
def _build_grain_controls(self, *args, **kwargs):
    out = _build_mineral_grain_controls(self, *args, **kwargs)
    radial_box = _find_labelframe_with_title(self, "Radial profiles")
    if radial_box is None:
        return out
    for child in radial_box.winfo_children():
        try:
            child.destroy()
        except Exception:
            pass
    ttk.Label(
        radial_box, text="One row per radial-profile pixel.", wraplength=320
    ).pack(anchor="w", padx=4, pady=(4, 3))
    self.grain_radial_use_full_ellipse_var = getattr(
        self, "grain_radial_use_full_ellipse_var", tk.BooleanVar(value=True)
    )
    self.grain_radial_line_count_var = getattr(
        self, "grain_radial_line_count_var", tk.StringVar(value="8")
    )
    row = ttk.Frame(radial_box)
    row.pack(fill=tk.X, padx=4, pady=2)
    ttk.Label(row, text="Profiles per grain:").pack(side=tk.LEFT)
    ttk.Entry(row, textvariable=self.grain_radial_line_count_var, width=8).pack(side=tk.RIGHT)
    row = ttk.Frame(radial_box)
    row.pack(fill=tk.X, padx=4, pady=2)
    ttk.Label(row, text="Buffer (pixels):").pack(side=tk.LEFT)
    ttk.Entry(row, textvariable=self.profile_buffer_pixels_var, width=8).pack(side=tk.RIGHT)
    row = ttk.Frame(radial_box)
    row.pack(fill=tk.X, padx=4, pady=2)
    ttk.Button(row, text="Show spokes", command=self.plot_grain_radial_profile_summary).pack(
        side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 2)
    )
    ttk.Button(row, text="Clear spokes", command=self.clear_grain_radial_profile_lines).pack(
        side=tk.LEFT, fill=tk.X, expand=True, padx=(2, 0)
    )
    ttk.Button(
        radial_box,
        text="Use radial pixels",
        command=self.use_grain_radial_pixels_for_analysis,
    ).pack(fill=tk.X, padx=4, pady=(3, 2))
    ttk.Button(
        radial_box, text="Export radial pixels", command=self.export_grain_radial_profile_pixels
    ).pack(fill=tk.X, padx=4, pady=(0, 4))
    return out



# keeps only grain-shape fields in the shape-only output
def simplify_grain_output_columns_shape_only(self, df, keep_radial=True):
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    data = self.ensure_grain_shape_metrics(df)
    keep_metadata = {
        "grain_id",
        "mineral_type",
        "phase",
        "comparison_dataset",
        "grain_category",
        "mask_selection",
        "value_selection",
        "domain",
        "x",
        "y",
        "row_index",
        "column_index",
        "pixel_id",
        "profile_pixel_id",
        "profile_id",
        "line_id",
        "profile_number",
        "profiles_per_grain",
        "profile_buffer_pixels",
        "perpendicular_distance_pixels",
        "distance_normalized",
        "distance_percent",
        "distance_bin",
        "distance_bin_center",
        "pixel_index_in_profile",
        "n_pixels_in_profile",
        "analysis_level",
        "analysis_type",
        "profile_kind",
    }
    shape_columns = {
        "grain_area",
        "grain_area_um2",
        "grain_area_coordinate_units2",
        "grain_area_pixels",
        "pixel_size_x_um",
        "pixel_size_y_um",
        "pixel_area_um2",
        "grain_length",
        "grain_width",
        "grain_aspect_ratio",
        "grain_roundness",
    }
    hidden_shape_tokens = (
        "ellipse_",
        "bbox",
        "axial_ratio",
        "aspect_ratio_x",
        "aspect_ratio_y",
        "equivalent_circle",
        "boundary_pixel",
        "centroid",
        "orientation",
        "perimeter",
        "circularity",
        "feret",
        "solidity",
        "eccentricity",
    )
    kept = []
    for column in data.columns:
        name = str(column)
        low = name.lower()
        if name in keep_metadata or name in shape_columns:
            kept.append(column)
            continue
        if name.startswith("grain_") or any((token in low for token in hidden_shape_tokens)):
            continue
        try:
            numeric = pd.to_numeric(data[column], errors="coerce").notna().any()
        except Exception:
            numeric = False
        chemistry_like = (
            bool(re.match("^[A-Z][a-z]?\\d+", name))
            or name.endswith("_ppm")
            or name.endswith("_ppb")
            or name.endswith("_cps")
            or name.startswith("calc_")
            or name.startswith("ratio_")
            or ("/" in name)
        )
        if chemistry_like or (not numeric and name not in kept):
            kept.append(column)
    ordered = []
    for column in list(keep_metadata) + list(shape_columns) + kept:
        if column in data.columns and column not in ordered:
            ordered.append(column)
    return data[ordered].copy()



# grain table used by the comparison tab
def _grain_comparison_table(self):
    for attr in (
        "last_compare_grain_df",
        "last_grain_means_df",
        "last_grain_df",
        "analysis_df",
        "comparison_df",
    ):
        table = getattr(self, attr, None)
        if isinstance(table, pd.DataFrame) and (not table.empty) and ("grain_id" in table.columns):
            return self.ensure_grain_shape_metrics(table)
    return None



# grouping columns available in grain comparisons
def _compare_group_columns(df):
    preferred = [
        "sample_id", "mineral_id", "run_id", "domain",
        "grain_category", "phase", "mask_selection",
        "value_selection", "custom_color_group",
    ]
    visible = user_visible_columns(df)
    columns = [column for column in preferred if column in visible]
    for column in visible:
        if column in columns or column in _GRAIN_METRIC_COLUMNS.values() or column == "grain_id":
            continue
        if pd.api.types.is_numeric_dtype(df[column]):
            continue
        if 1 < df[column].nunique(dropna=False) <= 40:
            columns.append(column)
    return columns



# runs grain detection and stores the result under its dataset key.
def _run_and_store_grain_detection(self, *args, **kwargs):
    result = _run_grain_detection(self, *args, **kwargs)
    full = _full_grain_dataframe(self)
    if isinstance(full, pd.DataFrame) and (not full.empty):
        full = self.ensure_grain_shape_metrics(full)
        self.last_grain_df_full = full.copy()
        self.last_grain_df = simplify_grain_output_columns_shape_only(self, full, keep_radial=False)
        try:
            self.refresh_compare_grain_controls()
        except Exception:
            pass
    return result



# recursively visits every widget below a parent frame
def _walk_widgets(root):
    widgets = []
    try:
        children = root.winfo_children()
    except Exception:
        return widgets
    for child in children:
        widgets.append(child)
        widgets.extend(_walk_widgets(child))
    return widgets



# visible text attached to a Tkinter widget
def _widget_text(widget):
    try:
        return str(widget.cget("text"))
    except Exception:
        return ""



# title of the nearest enclosing label frame
def _ancestor_labelframe_title(widget):
    parent = getattr(widget, "master", None)
    while parent is not None:
        try:
            if isinstance(parent, ttk.LabelFrame):
                return str(parent.cget("text"))
        except Exception:
            pass
        parent = getattr(parent, "master", None)
    return ""



# removes a label and the input widget paired with it.
def _destroy_widget_and_next_input(widget):
    parent = getattr(widget, "master", None)
    if parent is None:
        return
    try:
        siblings = list(parent.winfo_children())
        index = siblings.index(widget)
    except Exception:
        siblings = []
        index = -1
    try:
        widget.destroy()
    except Exception:
        pass
    if index >= 0 and index + 1 < len(siblings):
        nxt = siblings[index + 1]
        try:
            if isinstance(nxt, (ttk.Entry, ttk.Combobox)):
                nxt.destroy()
        except Exception:
            pass



# safe copy used while saving or restoring project state.
def _project_copy(value):
    try:
        return copy.deepcopy(value)
    except Exception:
        try:
            return pickle.loads(pickle.dumps(value, protocol=pickle.HIGHEST_PROTOCOL))
        except Exception:
            return value



# storage key for the next grain result
def _grain_run_target_key(self):
    selected = ""
    try:
        selected = str(self.grain_mask_var.get()).strip()
    except Exception:
        pass
    if selected and selected not in {"None", ""}:
        if selected in getattr(self, "mineral_presence_groups", {}):
            return selected
        layer = selected
        if layer not in getattr(self, "values", {}):
            for candidate in getattr(self, "values", {}):
                if str(candidate).split(" :: ", 1)[-1] == selected:
                    layer = candidate
                    break
        try:
            mineral = self.metas.get(layer, {}).get("mineral_type") or self.layer_mineral_type.get(
                layer
            )
            if mineral:
                return str(mineral)
        except Exception:
            pass
        return selected
    try:
        mineral = getattr(self, "last_grain_mineral_type", None)
        if mineral not in (None, "", "None"):
            return str(mineral)
    except Exception:
        pass
    try:
        layer = str(self.column_var.get()).strip()
        mineral = self.metas.get(layer, {}).get("mineral_type") or self.layer_mineral_type.get(
            layer
        )
        if mineral:
            return str(mineral)
        if layer:
            return layer
    except Exception:
        pass
    return "Grains"



# storage key for the currently active grain result
def _grain_run_current_key(self):
    key = getattr(self, "active_grain_analysis_key", None)
    if key not in (None, ""):
        return str(key)
    mineral = getattr(self, "last_grain_mineral_type", None)
    if mineral not in (None, "", "None"):
        return str(mineral)
    return _grain_run_target_key(self)



# separates a map-group label into sample, mineral, and run parts.
def _split_map_group_label(label, fallback_mineral=None):
    text = str(label or "").strip()
    if " :: " in text:
        left, right = text.split(" :: ", 1)
        return (left.strip() or "Map", right.strip() or str(fallback_mineral or text), text)
    mineral = str(fallback_mineral or text or "Mineral").strip()
    map_group = text or mineral or "Map"
    return (map_group, mineral, text or mineral)



# adds sample, mineral, and run IDs to a grain result.
def _add_grain_set_identity(df, key, mineral):
    if not isinstance(df, pd.DataFrame):
        return df
    out = df.copy()
    map_group, mineral_name, mineral_group = _split_map_group_label(key, fallback_mineral=mineral)
    out["grain_set"] = str(key)
    out["mineral_group"] = str(mineral_group)
    out["map_group"] = str(map_group)
    out["comparison_dataset"] = str(map_group)
    out["mineral_type"] = str(mineral_name)
    if "grain_id" in out.columns:
        ids = pd.to_numeric(out["grain_id"], errors="coerce")
        out["grain_uid"] = [
            f"{key}:{int(v)}" if np.isfinite(v) else f"{key}:NA" for v in ids.to_numpy(dtype=float)
        ]
    return out



# apply analysis run for grain analysis
def _apply_grain_analysis_run(self, key, redraw=True):
    runs = getattr(self, "grain_analysis_runs", {})
    if key not in runs:
        raise KeyError(f"Unknown grain set: {key}")
    snapshot = runs[key]
    for method_name in ["stop_move_grain_center_mode", "stop_grain_split_lines"]:
        try:
            getattr(self, method_name)()
        except Exception:
            pass
    for attr, value in snapshot.get("attrs", {}).items():
        try:
            setattr(self, attr, _project_copy(value))
        except Exception:
            pass
    self.manual_grain_split_lines = _project_copy(snapshot.get("manual_grain_split_lines", []))
    self.manual_grain_centers = _project_copy(snapshot.get("manual_grain_centers", {}))
    self.manual_grain_merge_groups = _project_copy(snapshot.get("manual_grain_merge_groups", []))
    self.active_grain_analysis_key = str(key)
    for var_name, state_name in [
        ("grain_mask_var", "grain_mask_value"),
        ("grain_value_var", "grain_value_value"),
        ("grain_display_mode_var", "grain_display_mode"),
    ]:
        value = snapshot.get(state_name)
        if value is not None:
            try:
                getattr(self, var_name).set(value)
            except Exception:
                pass
    try:
        labels = getattr(self, "last_grain_label_mask", None)
        if labels is not None:
            self._remember_grain_labels(
                labels,
                source_layer=getattr(self, "last_grain_layer_name", None),
                mineral_type=getattr(
                    self, "last_grain_mineral_type", snapshot.get("mineral_type", key)
                ),
            )
    except Exception:
        pass
    self._grain_radial_lines_visible = bool(snapshot.get("radial_lines_visible", False))
    try:
        self.last_compare_grain_df = combined_grain_shape_table(self)
        self.refresh_compare_grain_controls()
    except Exception:
        pass
    try:
        self.refresh_grain_analysis_set_controls()
    except Exception:
        pass
    if redraw:
        try:
            self.refresh_grain_view()
        except Exception:
            try:
                self.update_map()
            except Exception:
                pass
        try:
            self.draw_manual_grain_split_lines()
        except Exception:
            pass
        if self._grain_radial_lines_visible:
            try:
                self.draw_grain_radial_profile_lines()
            except Exception:
                pass
        try:
            self._draw_extraction_overlays_on_visible_map()
        except Exception:
            pass
        try:
            self.status_var.set(f"Showing detected grain set: {key}")
        except Exception:
            pass
    return snapshot



# grain-pixel table recovered from a saved grain run
def _grain_pixels_from_saved_run(self, key, run):
    attrs = run.get("attrs", {})
    labels = attrs.get("last_grain_label_mask")
    if labels is None:
        labels = attrs.get("last_grain_labels")
    if labels is None:
        return pd.DataFrame()
    labels = np.asarray(labels, dtype=int)
    if labels.ndim != 2 or not np.any(labels > 0):
        return pd.DataFrame()
    source_layer = (
        attrs.get("last_grain_layer_name")
        or attrs.get("last_grain_source_layer")
        or attrs.get("last_grain_mask_layer")
    )
    mineral = str(run.get("mineral_type") or key)
    try:
        map_group, mineral_name, mineral_group = _split_map_group_label(
            key, fallback_mineral=mineral
        )
    except Exception:
        map_group, mineral_name, mineral_group = ("Map", mineral, str(key))
    rows, cols = np.where(labels > 0)
    grain_ids = labels[rows, cols].astype(int)
    meta = self.metas.get(source_layer, {}) if source_layer in getattr(self, "metas", {}) else {}
    try:
        xg, yg = self._layer_pixel_centers(meta, z_shape=labels.shape)
    except Exception:
        xg = yg = None
    if (
        xg is not None
        and yg is not None
        and (np.shape(xg) == labels.shape)
        and (np.shape(yg) == labels.shape)
    ):
        x_values = np.asarray(xg, dtype=float)[rows, cols]
        y_values = np.asarray(yg, dtype=float)[rows, cols]
    else:
        x_values = cols.astype(float)
        y_values = rows.astype(float)
    base = pd.DataFrame(
        {
            "grain_set": str(key),
            "map_group": str(map_group),
            "comparison_dataset": str(map_group),
            "mineral_type": str(mineral_name),
            "mineral_group": str(mineral_group),
            "grain_id": grain_ids,
            "grain_uid": [f"{key}:{int(gid)}" for gid in grain_ids],
            "row_index": rows.astype(int),
            "column_index": cols.astype(int),
            "x": x_values,
            "y": y_values,
            "source_layer": str(source_layer),
            "source_kind": "grain_pixels",
        }
    )
    try:
        self.rebuild_mineral_column_index()
    except Exception:
        pass
    layer_map = dict(getattr(self, "mineral_column_index", {}).get(str(key), {}))
    if not layer_map:
        layer_map = dict(getattr(self, "mineral_column_index", {}).get(mineral, {}))
    if not layer_map:
        for layer, layer_meta in getattr(self, "metas", {}).items():
            layer_mineral = layer_meta.get("mineral_type") or getattr(
                self, "layer_mineral_type", {}
            ).get(layer)
            layer_group = (
                self._mineral_group_key_from_meta(layer, layer_meta)
                if hasattr(self, "_mineral_group_key_from_meta")
                else str(layer_mineral)
            )
            if str(layer_group) == str(key) or str(layer_mineral) == mineral:
                clean = (
                    self.canonical_element_column_name(layer)
                    if hasattr(self, "canonical_element_column_name")
                    else str(layer).split(" :: ", 1)[-1]
                )
                layer_map.setdefault(clean, layer)
    for clean, layer in layer_map.items():
        try:
            arr = np.asarray(self.values[layer], dtype=float)
            if arr.shape == labels.shape:
                sampled = arr[rows, cols]
            else:
                sampled = self._sample_layer_at_xy_for_radial(
                    layer, base["x"].to_numpy(dtype=float), base["y"].to_numpy(dtype=float)
                )
            base[str(clean)] = sampled
        except Exception:
            pass
    grain_table = attrs.get("last_grain_df_full")
    if not isinstance(grain_table, pd.DataFrame) or grain_table.empty:
        grain_table = attrs.get("last_grain_df")
    if (
        isinstance(grain_table, pd.DataFrame)
        and (not grain_table.empty)
        and ("grain_id" in grain_table.columns)
    ):
        try:
            shapes = self.ensure_grain_shape_metrics(grain_table)
        except Exception:
            shapes = grain_table.copy()
        keep = [
            col
            for col in [
                "grain_id",
                "grain_area",
                "grain_area_um2",
                "grain_area_coordinate_units2",
                "grain_area_pixels",
                "pixel_size_x_um",
                "pixel_size_y_um",
                "pixel_area_um2",
                "grain_length",
                "grain_width",
                "grain_aspect_ratio",
                "grain_roundness",
                "grain_center_x",
                "grain_center_y",
            ]
            if col in shapes.columns
        ]
        if keep:
            shape_small = shapes[keep].drop_duplicates(subset=["grain_id"])
            base = base.merge(shape_small, on="grain_id", how="left")
    return base



# grain pixels combined across saved runs
def combined_grain_pixel_table(self):
    _sample_save_active_workspace(self)
    parts = []
    for sample_id in getattr(self, "sample_registry", {}):
        df = _sample_grain_pixels_from_sample_state(self, sample_id)
        if not df.empty:
            parts.append(df)
    if parts:
        return pd.concat(parts, ignore_index=True, sort=False)
    return _collect_grain_pixel_tables(self)



# per-grain means combined across saved runs
def combined_grain_mean_table(self):
    pixels = _sample_combined_grain_pixel_table(self)
    if pixels.empty:
        return pixels
    group_cols = [
        c
        for c in [
            "sample_id",
            "mineral_id",
            "run_id",
            "grain_set",
            "map_group",
            "mineral_type",
            "mineral_group",
            "grain_uid",
            "grain_id",
        ]
        if c in pixels.columns
    ]
    numeric_cols = []
    excluded = {"grain_id", "row_index", "column_index", "x", "y", "pixel_id"}
    for col in pixels.columns:
        if col in excluded or col in group_cols:
            continue
        vals = pd.to_numeric(pixels[col], errors="coerce")
        if vals.notna().any():
            numeric_cols.append(col)
    if not numeric_cols:
        return pixels[group_cols].drop_duplicates().reset_index(drop=True)
    out = pixels.groupby(group_cols, dropna=False, sort=False)[numeric_cols].mean().reset_index()
    out["source_kind"] = "grain_means"
    return out



# grain-shape measurements combined across saved runs
def combined_grain_shape_table(self):
    _sample_save_active_workspace(self)
    parts = []
    for sample_id, rec in getattr(self, "sample_registry", {}).items():
        state = rec.get("state", {})
        runs = state.get("grain_analysis_runs", {})
        if not isinstance(runs, dict):
            continue
        for key, run in runs.items():
            attrs = run.get("attrs", {}) if isinstance(run, dict) else {}
            table = attrs.get("last_grain_df_full")
            if not isinstance(table, pd.DataFrame) or table.empty:
                table = attrs.get("last_grain_df")
            if not isinstance(table, pd.DataFrame) or table.empty:
                continue
            try:
                table = self.ensure_grain_shape_metrics(table)
            except Exception:
                table = table.copy()
            table = _add_grain_set_identity(table, key, run.get("mineral_type", key))
            table["sample_id"] = sample_id
            if "mineral_id" not in table.columns:
                table["mineral_id"] = table.get("mineral_type", str(run.get("mineral_type", key)))
            if "run_id" not in table.columns:
                table["run_id"] = str(run.get("run_id", key))
            table["grain_uid"] = [
                f"{sample_id}:{key}:{int(g)}"
                for g in pd.to_numeric(
                    table.get("grain_id", np.arange(len(table)) + 1), errors="coerce"
                ).fillna(0)
            ]
            parts.append(table)
    if parts:
        return pd.concat(parts, ignore_index=True, sort=False)
    return _collect_grain_shape_tables(self)



# runs grain detection for one selected sample/mineral/run set
def _run_single_grain_detection(self, *args, **kwargs):
    target = _grain_run_target_key(self)
    active = getattr(self, "active_grain_analysis_key", None)
    if active and active != target:
        try:
            self.store_current_grain_analysis_run(refresh=False)
        except Exception:
            pass
        self.manual_grain_split_lines = []
        self.manual_grain_centers = {}
        self._grain_radial_lines_visible = False
    self.active_grain_analysis_key = str(target)
    result = _run_grain_analysis_and_store(self, *args, **kwargs)
    try:
        self.store_current_grain_analysis_run(refresh=True)
    except Exception:
        pass
    return result



# comparison table assembled from all saved grain runs
def _combined_grain_comparison_table(self):
    combined = combined_grain_shape_table(self)
    if isinstance(combined, pd.DataFrame) and (not combined.empty):
        return self.ensure_grain_shape_metrics(combined)
    return _grain_comparison_table(self)



# coordinate-set ID inferred from an imported file name
def coordinate_set_id_from_filename(path):
    stem = os.path.splitext(os.path.basename(str(path)))[0]
    match = re.search("\\((\\d+)\\)\\s*$", stem)
    if match:
        return match.group(1)
    match = re.search("\\bcopy(?:\\s+(\\d+))?\\s*$", stem, flags=re.IGNORECASE)
    if match:
        return match.group(1) or "copy"
    return ""



# common group name shared by matching X and Y coordinate files.
def clean_coordinate_axis_group_name_from_filename(path):
    base = _coordinate_axis_group_name(path)
    set_id = coordinate_set_id_from_filename(path)
    return f"{base}::__set_{set_id}" if set_id else str(base)



# builds a coordinate reference from separate X and Y matrices.
def make_coordinate_reference_from_axis_matrices(x_path, y_path, group_key=None):
    ref = _make_coordinate_reference(x_path, y_path, group_key=group_key)
    set_id = coordinate_set_id_from_filename(x_path) or coordinate_set_id_from_filename(y_path)
    key = str(group_key or ref.get("group_key", ""))
    base_key = re.sub("::__set_[^:]+$", "", key)
    ref["group_key"] = key
    ref["base_group_key"] = base_key
    ref["coordinate_set_id"] = str(set_id)
    ref["coordinate_pair_x_file"] = os.path.basename(str(x_path))
    ref["coordinate_pair_y_file"] = os.path.basename(str(y_path))
    return ref



# read matrix file
def read_matrix_file(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in [".xlsx", ".xls"]:
        raw = pd.read_excel(path, header=None)
    elif ext in [".csv", ".txt"]:
        raw = pd.read_csv(path, header=None)
    else:
        raise ValueError(f"Unsupported matrix file type: {ext}")
    raw = raw.apply(pd.to_numeric, errors="coerce")
    z = raw.to_numpy(dtype=float)
    if z.size == 0 or not np.isfinite(z).any():
        raise ValueError("Matrix file has no numeric values.")
    n_rows, n_cols = z.shape
    values = {clean_channel_name_from_matrix_filename(path): z}
    meta = {
        "kind": "matrix_file",
        "x": np.arange(n_cols, dtype=float),
        "y": np.arange(n_rows, dtype=float),
        "x_name": "Pixel column",
        "y_name": "Pixel row",
        "path": path,
        "matrix_original_shape": tuple(z.shape),
        "matrix_trimmed_shape": tuple(z.shape),
        "matrix_kept_row_indices": np.arange(n_rows, dtype=int),
        "matrix_kept_col_indices": np.arange(n_cols, dtype=int),
        "matrix_only_blank_borders_removed": False,
        "matrix_grid_preserved": True,
        "coordinate_set_id": coordinate_set_id_from_filename(path),
    }
    return (values, meta)



# one-dimensional axis inferred from a sparse coordinate grid
def _axis_from_sparse_coordinate_grid(grid, axis):
    arr = np.asarray(grid, dtype=float)
    if arr.ndim != 2:
        raise ValueError("Coordinate grid must be two-dimensional.")
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=RuntimeWarning)
        with np.errstate(all="ignore"):
            centers = np.nanmedian(arr, axis=0 if axis == "x" else 1)
    index = np.arange(centers.size, dtype=float)
    good = np.isfinite(centers)
    if good.sum() < 2:
        raise ValueError(
            f"Not enough finite {axis.upper()} coordinate values to recover the map axis."
        )
    gi = index[good]
    gv = centers[good]
    slope, intercept = np.polyfit(gi, gv, 1)
    if not np.isfinite(slope) or abs(slope) <= 1e-12:
        diffs_i = np.diff(gi)
        diffs_v = np.diff(gv)
        slopes = diffs_v / diffs_i
        slopes = slopes[np.isfinite(slopes) & (np.abs(slopes) > 1e-12)]
        if slopes.size == 0:
            raise ValueError(f"Could not determine {axis.upper()} coordinate spacing.")
        slope = float(np.nanmedian(slopes))
        intercept = float(np.nanmedian(gv - slope * gi))
    recovered = intercept + slope * index
    if slope > 0 and np.any(np.diff(recovered) <= 0):
        recovered = recovered[0] + abs(slope) * index
    elif slope < 0 and np.any(np.diff(recovered) >= 0):
        recovered = recovered[0] - abs(slope) * index
    return recovered.astype(float)



# apply coordinate reference to meta
def apply_coordinate_reference_to_meta(meta, z_shape, coord_ref):
    new_meta = dict(meta)
    x_grid = np.asarray(coord_ref.get("x_grid"), dtype=float)
    y_grid = np.asarray(coord_ref.get("y_grid"), dtype=float)
    if x_grid.shape != y_grid.shape:
        raise ValueError(f"X/Y coordinate grid shape mismatch: {x_grid.shape} vs {y_grid.shape}")
    z_shape = tuple(z_shape)
    if tuple(x_grid.shape) != z_shape:
        original_shape = tuple(meta.get("matrix_original_shape", ()))
        row_idx = np.asarray(meta.get("matrix_kept_row_indices", []), dtype=int)
        col_idx = np.asarray(meta.get("matrix_kept_col_indices", []), dtype=int)
        if (
            original_shape
            and tuple(x_grid.shape) == original_shape
            and (row_idx.size == z_shape[0])
            and (col_idx.size == z_shape[1])
        ):
            x_grid = x_grid[np.ix_(row_idx, col_idx)]
            y_grid = y_grid[np.ix_(row_idx, col_idx)]
        else:
            raise ValueError(
                f"Coordinate matrix shape {x_grid.shape} does not match map shape {z_shape}."
            )
    x_axis = _axis_from_sparse_coordinate_grid(x_grid, "x")
    y_axis = _axis_from_sparse_coordinate_grid(y_grid, "y")
    new_meta["x"] = x_axis
    new_meta["y"] = y_axis
    new_meta["x_grid"] = x_grid
    new_meta["y_grid"] = y_grid
    new_meta["x_name"] = "X (µm)"
    new_meta["y_name"] = "Y (µm)"
    new_meta["kind"] = str(meta.get("kind", "matrix_file")) + "_with_xy_reference"
    new_meta["coordinate_reference_file"] = coord_ref.get("source_file", "")
    new_meta["coordinate_reference_group_key"] = coord_ref.get("group_key", "")
    new_meta["coordinate_import_mode"] = "exact_xy_matrix_pair"
    new_meta["physical_coordinate_units"] = "µm"
    new_meta["coordinate_set_id"] = str(coord_ref.get("coordinate_set_id", ""))
    new_meta["coordinate_pair_x_file"] = coord_ref.get("coordinate_pair_x_file", "")
    new_meta["coordinate_pair_y_file"] = coord_ref.get("coordinate_pair_y_file", "")
    new_meta["coordinate_grid_preserved"] = True
    return new_meta



# whether a layer uses stage coordinates rather than pixel indices.
def _layer_uses_physical_coordinates(meta, z_shape=None):
    if not isinstance(meta, dict):
        return False
    if meta.get("coordinate_import_mode") in {"exact_xy_matrix_pair", "exact_xy_matrix_or_table"}:
        return True
    try:
        xg = np.asarray(meta.get("x_grid"), dtype=float)
        yg = np.asarray(meta.get("y_grid"), dtype=float)
        if z_shape is None:
            return (
                xg.ndim == 2
                and yg.shape == xg.shape
                and np.isfinite(xg).any()
                and np.isfinite(yg).any()
            )
        return (
            xg.shape == yg.shape == tuple(z_shape)
            and np.isfinite(xg).any()
            and np.isfinite(yg).any()
        )
    except Exception:
        return False



# simple coordinate transform fitted from a grid

# true when map coordinates are explicitly stored in micrometres.
def _metadata_uses_micron_coordinates(meta, z_shape=None):
    if not isinstance(meta, dict):
        return False
    units = str(meta.get("physical_coordinate_units", "")).strip().lower()
    units = units.replace("μ", "µ")
    if units in {"µm", "um", "micron", "microns", "micrometre", "micrometres", "micrometer", "micrometers"}:
        return True
    labels = " ".join(
        str(meta.get(key, "")) for key in ("x_name", "y_name", "coordinate_reference_file")
    ).lower().replace("μ", "µ")
    if ("µm" in labels or "[um]" in labels or "(um)" in labels) and _layer_uses_physical_coordinates(meta, z_shape):
        return True
    return False


# add unambiguous physical-area aliases to one grain record.
def _add_grain_area_unit_aliases(record, meta, z_shape=None):
    rec = dict(record)
    area = safe_float(rec.get("area_units2", rec.get("grain_area_coordinate_units2", np.nan)), np.nan)
    dx = safe_float(rec.get("pixel_size_x_coordinate_units", np.nan), np.nan)
    dy = safe_float(rec.get("pixel_size_y_coordinate_units", np.nan), np.nan)
    pixel_area = safe_float(rec.get("pixel_area_coordinate_units2", np.nan), np.nan)
    rec["grain_area_coordinate_units2"] = area
    # Older saved projects used this name. Keep it as an alias, but do not use it as a unit label.
    rec["grain_area_coordinate_units"] = area
    rec["grain_area_units2"] = area
    if _metadata_uses_micron_coordinates(meta, z_shape=z_shape):
        rec["grain_area_um2"] = area
        rec["grain_area"] = area
        rec["pixel_size_x_um"] = dx
        rec["pixel_size_y_um"] = dy
        rec["pixel_area_um2"] = pixel_area
        rec["grain_area_units"] = "µm²"
    else:
        # Never silently call a raw pixel count an area in µm².
        rec["grain_area_um2"] = np.nan
        rec["grain_area"] = np.nan
        rec["pixel_size_x_um"] = np.nan
        rec["pixel_size_y_um"] = np.nan
        rec["pixel_area_um2"] = np.nan
        rec["grain_area_units"] = "coordinate units²" if np.isfinite(area) else "pixels"
    return rec


# compare two coordinate references before choosing between equally good matches.
def _coordinate_references_equivalent(ref_a, ref_b, z_shape):
    try:
        xa = _axis_from_sparse_coordinate_grid(np.asarray(ref_a.get("x_grid"), dtype=float), "x")
        ya = _axis_from_sparse_coordinate_grid(np.asarray(ref_a.get("y_grid"), dtype=float), "y")
        xb = _axis_from_sparse_coordinate_grid(np.asarray(ref_b.get("x_grid"), dtype=float), "x")
        yb = _axis_from_sparse_coordinate_grid(np.asarray(ref_b.get("y_grid"), dtype=float), "y")
        if xa.size != int(z_shape[1]) or xb.size != int(z_shape[1]):
            return False
        if ya.size != int(z_shape[0]) or yb.size != int(z_shape[0]):
            return False
        return bool(
            np.allclose(xa, xb, rtol=1e-7, atol=1e-6, equal_nan=True)
            and np.allclose(ya, yb, rtol=1e-7, atol=1e-6, equal_nan=True)
        )
    except Exception:
        return False


def _coordinate_fit_from_grid(grid, axis):
    arr = np.asarray(grid, dtype=float)
    rr, cc = np.where(np.isfinite(arr))
    if rr.size < 2:
        raise ValueError("Not enough coordinate pixels for registration.")
    index = cc.astype(float) if axis == "x" else rr.astype(float)
    values = arr[rr, cc].astype(float)
    slope, intercept = np.polyfit(index, values, 1)
    return (float(slope), float(intercept))



# grain KDE evaluated on a shared X grid for comparison.
def _grain_kde_on_common_grid(values, grid, bandwidth_multiplier=1.0):
    values = np.asarray(values, dtype=float)
    values = values[np.isfinite(values)]
    if values.size < 3:
        raise ValueError("Need at least 3 grains for a KDE curve.")
    std = float(np.std(values, ddof=1))
    if not np.isfinite(std) or std <= 0:
        raise ValueError("Grain values have no spread.")
    bandwidth = 1.06 * std * values.size ** (-1.0 / 5.0) * float(bandwidth_multiplier)
    if not np.isfinite(bandwidth) or bandwidth <= 0:
        raise ValueError("KDE bandwidth is not valid.")
    density = np.zeros_like(grid, dtype=float)
    norm = 1.0 / (np.sqrt(2.0 * np.pi) * bandwidth * values.size)
    for start in range(0, values.size, 1000):
        sample = values[start : start + 1000]
        u = (grid[:, None] - sample[None, :]) / bandwidth
        density += np.exp(-0.5 * u**2).sum(axis=1)
    density *= norm
    return (density, bandwidth)



# whether a layer carries usable physical X-Y coordinates
def _layer_uses_physical_xy(meta, z_shape=None):
    if isinstance(meta, dict) and bool(meta.get("shared_coordinate_registration", False)):
        try:
            x = np.asarray(meta.get("registered_x_axis", []), dtype=float)
            y = np.asarray(meta.get("registered_y_axis", []), dtype=float)
            if z_shape is None:
                if x.size >= 2 and y.size >= 2 and np.isfinite(x).all() and np.isfinite(y).all():
                    return True
            elif (
                x.size == int(z_shape[1])
                and y.size == int(z_shape[0])
                and np.isfinite(x).all()
                and np.isfinite(y).all()
            ):
                return True
        except Exception:
            pass
    return _layer_uses_physical_coordinates(meta, z_shape=z_shape)





