# safe copy of one sample workspace
def _sample_copy(value):
    try:
        return _project_copy(value)
    except Exception:
        try:
            return copy.deepcopy(value)
        except Exception:
            return value



# file-safe ID used for sample-workspace keys
def _sample_safe_id(text, fallback):
    value = re.sub("\\s+", " ", str(text or "")).strip()
    return value if value else fallback



# stable sample/layer identity used when maps are combined
def _sample_layer_identity(meta, layer_name=""):
    meta = meta if isinstance(meta, dict) else {}
    sample = _sample_safe_id(
        meta.get("sample_id") or meta.get("map_group") or meta.get("comparison_dataset"), "Sample"
    )
    mineral = _sample_safe_id(meta.get("mineral_id") or meta.get("mineral_type"), "Mineral")
    run = _sample_safe_id(meta.get("run_id"), "Run 1")
    channel_value = meta.get("canonical_column") or meta.get("source_layer_name") or layer_name
    channel_text = str(channel_value or "").strip()
    if " :: " in channel_text:
        channel_text = channel_text.split(" :: ")[-1].strip()
    channel = _sample_safe_id(channel_text, "Channel")
    return (sample, mineral, run, channel)



# sample IDs recovered from imported metadata
def _sample_sample_ids_from_metadata(self):
    ids = []
    for layer, meta in (getattr(self, "metas", {}) or {}).items():
        if layer not in (getattr(self, "values", {}) or {}):
            continue
        sample, _mineral, _run, _channel = _sample_layer_identity(meta, layer)
        if sample not in ids:
            ids.append(sample)
    return ids



# saves the current sample workspace before switching tabs
def _sample_save_active_workspace(self):
    sample_id = getattr(self, "active_sample_id", None)
    if not sample_id or sample_id == "__EMPTY__":
        return
    registry = getattr(self, "sample_registry", {})
    if sample_id not in registry:
        return
    state = registry[sample_id].setdefault("state", _sample_empty_workspace_state())
    for attr in _MS_STATE_ATTRS:
        if hasattr(self, attr):
            try:
                state[attr] = _sample_copy(getattr(self, attr))
            except Exception:
                pass
    try:
        state["column_name"] = str(self.column_var.get())
    except Exception:
        pass
    try:
        state["map_mode"] = str(self.map_view_render_mode_var.get())
    except Exception:
        pass
    try:
        state["vmin"] = str(self.vmin_var.get())
        state["vmax"] = str(self.vmax_var.get())
        state["invert_x"] = bool(self.map_invert_x_var.get())
        state["invert_y"] = bool(self.map_invert_y_var.get())
    except Exception:
        pass



# restores a sample’s maps, selections, and analysis state
def _sample_restore_workspace(self, sample_id):
    registry = getattr(self, "sample_registry", {})
    state = registry.get(sample_id, {}).get("state")
    if not isinstance(state, dict):
        state = _sample_empty_workspace_state()
        registry.setdefault(sample_id, {})["state"] = state
    for attr in _MS_STATE_ATTRS:
        if attr in state:
            try:
                setattr(self, attr, _sample_copy(state[attr]))
            except Exception:
                pass
    self.line_artists = []
    self.spot_artists = []
    self.area_artists = []
    self.lasso_preview_artists = []
    try:
        self.column_var.set(str(state.get("column_name", "")))
    except Exception:
        pass
    try:
        self.map_view_render_mode_var.set(str(state.get("map_mode", "single_element")))
    except Exception:
        pass
    try:
        self.vmin_var.set(str(state.get("vmin", "")))
        self.vmax_var.set(str(state.get("vmax", "")))
        self.map_invert_x_var.set(bool(state.get("invert_x", False)))
        self.map_invert_y_var.set(bool(state.get("invert_y", False)))
    except Exception:
        pass



# walks all widgets inside a sample tab
def _sample_recursive_widgets(root):
    out = []
    try:
        children = root.winfo_children()
    except Exception:
        return out
    for child in children:
        out.append(child)
        out.extend(_sample_recursive_widgets(child))
    return out



# creates the map canvas for a sample tab
def _sample_make_sample_canvas(self, sample_id, label=None):
    notebook = self.sample_map_notebook
    frame = ttk.Frame(notebook)
    fig = plt.Figure(figsize=(8, 6), constrained_layout=False)
    ax = fig.add_subplot(111)
    ax.set_title("No map loaded" if sample_id == "__EMPTY__" else str(sample_id))
    ax.set_xlabel("X")
    ax.set_ylabel("Y")
    canvas = FigureCanvasTkAgg(fig, master=frame)
    canvas.draw()
    canvas.get_tk_widget().pack(side=tk.TOP, fill=tk.BOTH, expand=True)
    toolbar = self.make_navigation_toolbar(canvas, frame)
    canvas.mpl_connect("button_press_event", self.on_map_click)
    notebook.add(frame, text=label or str(sample_id))
    self.sample_map_views[sample_id] = {
        "frame": frame,
        "fig": fig,
        "ax": ax,
        "canvas": canvas,
        "toolbar": toolbar,
    }
    return self.sample_map_views[sample_id]



# points the shared toolbar at the active sample canvas.
def _sample_assign_active_canvas(self, sample_id):
    view = self.sample_map_views.get(sample_id)
    if not view:
        return False
    self.map_fig = view["fig"]
    self.map_ax = view["ax"]
    self.map_canvas = view["canvas"]
    self.map_toolbar = view["toolbar"]
    self.fig = view["fig"]
    self.ax = view["ax"]
    self.canvas = view["canvas"]
    return True



# removes the placeholder tab once a real sample is loaded.
def _sample_remove_empty_tab(self):
    view = getattr(self, "sample_map_views", {}).pop("__EMPTY__", None)
    if not view:
        return
    try:
        self.sample_map_notebook.forget(view["frame"])
    except Exception:
        pass
    try:
        view["frame"].destroy()
    except Exception:
        pass



# refreshes sample choices in the plotting filters
def _sample_refresh_plot_sample_list(self, select_new=None):
    lb = getattr(self, "plot_sample_listbox", None)
    if lb is None:
        return
    old = set()
    try:
        old = {str(lb.get(i)) for i in lb.curselection()}
    except Exception:
        pass
    if select_new:
        old.add(str(select_new))
    ids = list(getattr(self, "sample_registry", {}).keys())
    lb.delete(0, tk.END)
    for sid in ids:
        lb.insert(tk.END, sid)
    if not old and ids:
        old = set(ids)
    for i, sid in enumerate(ids):
        if sid in old:
            lb.selection_set(i)
    try:
        active = getattr(self, "active_sample_id", None)
        self.active_sample_info_var.set(
            f"Active map viewer: {active}"
            if active and active != "__EMPTY__"
            else "No sample loaded"
        )
    except Exception:
        pass



# sample IDs currently selected in the plotting filters
def _sample_selected_sample_ids(self):
    lb = getattr(self, "plot_sample_listbox", None)
    selected = []
    if lb is not None:
        try:
            selected = [str(lb.get(i)) for i in lb.curselection()]
        except Exception:
            selected = []
    if not selected:
        active = getattr(self, "active_sample_id", None)
        if active and active != "__EMPTY__":
            selected = [active]
    return selected



# switches the active workspace to one sample
def _sample_activate_sample(self, sample_id, redraw=True, select_tab=False):
    if sample_id not in getattr(self, "sample_map_views", {}):
        return False
    old = getattr(self, "active_sample_id", None)
    if old and old != sample_id and (old != "__EMPTY__"):
        _sample_save_active_workspace(self)
    self.active_sample_id = sample_id
    _sample_assign_active_canvas(self, sample_id)
    if sample_id != "__EMPTY__":
        _sample_restore_workspace(self, sample_id)
        try:
            self.map_group_filter_var.set(sample_id)
        except Exception:
            pass
    if select_tab:
        try:
            self.sample_map_notebook.select(self.sample_map_views[sample_id]["frame"])
        except Exception:
            pass
    try:
        self.refresh_map_column_combo(preserve=True)
    except Exception:
        pass
    try:
        available = list(self.get_canonical_map_columns())
        current = self.canonical_layer_display_name(self.column_var.get())
        if current not in available and available:
            self.column_var.set(available[0])
            self.sample_registry[sample_id]["state"]["column_name"] = available[0]
    except Exception:
        pass
    try:
        self.refresh_map_view_mineral_list()
        self.refresh_grain_analysis_set_controls()
    except Exception:
        pass
    _sample_refresh_plot_sample_list(self)
    if redraw and sample_id != "__EMPTY__":
        self.update_map()
    return True



# adds the sample-tab controls around a map canvas
def _sample_install_sample_workspace_ui(self):
    if getattr(self, "_multi_sample_workspace_ui_installed", False):
        return
    self._multi_sample_workspace_ui_installed = True
    try:
        plot_area = self.map_canvas.get_tk_widget().master
    except Exception:
        return
    for child in list(plot_area.winfo_children()):
        try:
            child.destroy()
        except Exception:
            pass
    bar = ttk.LabelFrame(plot_area, text="Samples")
    bar.pack(side=tk.TOP, fill=tk.X, padx=3, pady=3)
    self.active_sample_info_var = tk.StringVar(value="No sample loaded")
    ttk.Label(bar, textvariable=self.active_sample_info_var).grid(
        row=0, column=0, columnspan=4, sticky="w", padx=4, pady=(3, 1)
    )
    ttk.Label(bar, text="Samples to plot:").grid(row=1, column=0, sticky="nw", padx=4, pady=2)
    self.plot_sample_listbox = tk.Listbox(
        bar, selectmode=tk.MULTIPLE, exportselection=False, height=3, width=30
    )
    self.plot_sample_listbox.grid(row=1, column=1, rowspan=3, sticky="nsew", padx=4, pady=2)
    ttk.Button(
        bar, text="Use pixels from selected samples", command=self.use_selected_sample_pixels_for_analysis
    ).grid(row=1, column=2, sticky="ew", padx=4, pady=2)
    ttk.Button(
        bar, text="Use domain pixels from selected samples", command=self.use_selected_sample_area_pixels_for_analysis
    ).grid(row=2, column=2, sticky="ew", padx=4, pady=2)
    ttk.Button(
        bar,
        text="Use grain pixels from selected samples",
        command=self.use_selected_sample_grain_pixels_for_analysis,
    ).grid(row=3, column=2, sticky="ew", padx=4, pady=2)
    ttk.Button(
        bar, text="Select all", command=lambda: self.plot_sample_listbox.selection_set(0, tk.END)
    ).grid(row=1, column=3, sticky="ew", padx=4, pady=2)
    ttk.Button(
        bar, text="Active sample only", command=self.select_only_active_sample_for_plots
    ).grid(row=2, column=3, sticky="ew", padx=4, pady=2)
    ttk.Label(
        bar,
        text="Channels with the same name plot together.",
        wraplength=640,
        justify=tk.LEFT,
    ).grid(row=3, column=3, sticky="w", padx=4, pady=2)
    bar.columnconfigure(1, weight=0)
    bar.columnconfigure(2, weight=1)
    bar.columnconfigure(3, weight=1)
    self.sample_map_notebook = ttk.Notebook(plot_area)
    self.sample_map_notebook.pack(side=tk.TOP, fill=tk.BOTH, expand=True)
    self.sample_map_notebook.bind("<<NotebookTabChanged>>", self._on_sample_tab_changed)
    self.sample_map_views = {}
    _sample_make_sample_canvas(self, "__EMPTY__", "No samples")
    self.active_sample_id = "__EMPTY__"
    _sample_assign_active_canvas(self, "__EMPTY__")
    for widget in _sample_recursive_widgets(self):
        try:
            text = str(widget.cget("text"))
        except Exception:
            continue
        if text == "New project":
            try:
                widget.configure(text="New project")
            except Exception:
                pass
        elif text == "Import maps":
            try:
                widget.configure(text="Import maps")
            except Exception:
                pass



# best sample-name guess from the imported file metadata
def _sample_infer_sample_default(paths):
    for path in paths:
        try:
            if coordinate_axis_from_filename(path) in {"x", "y"}:
                continue
            channel = clean_channel_name_from_matrix_filename(path)
            prefix = clean_sample_prefix_from_matrix_filename(path, channel)
            if prefix and prefix != channel:
                return prefix
        except Exception:
            pass
    return "Sample 1"



# estimates the physical spacing between neighboring pixel centers in an X/Y coordinate pair.
def _estimate_pixel_size_from_xy_grids(x_grid, y_grid):
    xg = np.asarray(x_grid, dtype=float)
    yg = np.asarray(y_grid, dtype=float)
    if xg.shape != yg.shape or xg.ndim != 2:
        return (np.nan, np.nan)

    def _step(axis):
        if xg.shape[axis] < 2:
            return np.nan
        dx = np.diff(xg, axis=axis)
        dy = np.diff(yg, axis=axis)
        distance = np.hypot(dx, dy)
        distance = distance[np.isfinite(distance) & (distance > 1e-12)]
        if distance.size == 0:
            return np.nan
        # Large gaps can occur across blank parts of sparse mineral masks. Keep the
        # normal nearest-neighbour spacing rather than letting those gaps control it.
        upper = np.nanpercentile(distance, 80)
        usual = distance[distance <= upper]
        if usual.size == 0:
            usual = distance
        return float(np.nanmedian(usual))

    # Adjacent columns are the X pixel dimension; adjacent rows are the Y dimension.
    return (_step(1), _step(0))


# reads the selected import files and makes a best estimate of X/Y pixel size in microns.
def _sample_estimate_import_pixel_size(paths, sample_hint=""):
    axis_groups = {}
    estimates = []
    for path in paths:
        try:
            axis = coordinate_axis_from_filename(path)
        except Exception:
            axis = None
        if axis in {"x", "y"}:
            key = clean_coordinate_axis_group_name_from_filename(path)
            axis_groups.setdefault(key, {})[axis] = path

    for key, pair in axis_groups.items():
        if "x" not in pair or "y" not in pair:
            continue
        try:
            xg = read_coordinate_axis_matrix(pair["x"])
            yg = read_coordinate_axis_matrix(pair["y"])
            dx, dy = _estimate_pixel_size_from_xy_grids(xg, yg)
            if np.isfinite(dx) and dx > 0 and np.isfinite(dy) and dy > 0:
                estimates.append((str(key), float(dx), float(dy)))
        except Exception:
            pass

    if not estimates:
        return (np.nan, np.nan, "")
    if len(estimates) == 1:
        key, dx, dy = estimates[0]
        return (dx, dy, key)

    hint = re.sub("[^a-z0-9]+", "", str(sample_hint).lower())
    if hint:
        scored = []
        for key, dx, dy in estimates:
            base = re.sub("::__set_[^:]+$", "", key)
            norm = re.sub("[^a-z0-9]+", "", base.lower())
            score = 1 if hint == norm else (0.5 if hint in norm or norm in hint else 0)
            scored.append((score, key, dx, dy))
        scored.sort(key=lambda item: item[0], reverse=True)
        if scored and scored[0][0] > 0 and (len(scored) == 1 or scored[0][0] > scored[1][0]):
            _, key, dx, dy = scored[0]
            return (dx, dy, key)

    dxs = np.asarray([item[1] for item in estimates], dtype=float)
    dys = np.asarray([item[2] for item in estimates], dtype=float)
    dx_med = float(np.nanmedian(dxs))
    dy_med = float(np.nanmedian(dys))
    close_x = np.all(np.abs(dxs - dx_med) <= max(abs(dx_med) * 0.02, 1e-9))
    close_y = np.all(np.abs(dys - dy_med) <= max(abs(dy_med) * 0.02, 1e-9))
    if close_x and close_y:
        return (dx_med, dy_med, "selected X/Y files")
    return (np.nan, np.nan, "")


# dialog for assigning imported files to sample, mineral, run, and pixel size.
def _sample_prompt_import_assignment(self, paths, force_new=False):
    result = {"value": None}
    existing = list(getattr(self, "sample_registry", {}).keys())
    default_sample = _sample_infer_sample_default(paths)

    win = tk.Toplevel(self)
    win.title("Assign imported maps")
    win.transient(self)
    win.grab_set()

    mode_var = tk.StringVar(value="new" if force_new or not existing else "existing")
    existing_var = tk.StringVar(
        value=(
            getattr(self, "active_sample_id", None)
            if getattr(self, "active_sample_id", None) in existing
            else existing[0] if existing else ""
        )
    )
    sample_var = tk.StringVar(value=default_sample)
    mineral_var = tk.StringVar(value="Mineral 1")
    run_var = tk.StringVar(value="Run 1")

    auto_dx, auto_dy, pixel_size_source = _sample_estimate_import_pixel_size(
        paths, sample_hint=default_sample
    )
    pixel_x_var = tk.StringVar(value=f"{auto_dx:.6g}" if np.isfinite(auto_dx) else "")
    pixel_y_var = tk.StringVar(value=f"{auto_dy:.6g}" if np.isfinite(auto_dy) else "")

    ttk.Label(win, text="Assign these maps.").grid(
        row=0, column=0, columnspan=3, sticky="w", padx=10, pady=(10, 6)
    )
    rb_new = ttk.Radiobutton(
        win, text="New sample", variable=mode_var, value="new"
    )
    rb_new.grid(row=1, column=0, columnspan=3, sticky="w", padx=10, pady=2)
    rb_existing = ttk.Radiobutton(
        win, text="Add to existing sample", variable=mode_var, value="existing"
    )
    rb_existing.grid(row=2, column=0, columnspan=3, sticky="w", padx=10, pady=2)
    if force_new or not existing:
        rb_existing.state(["disabled"])
        mode_var.set("new")

    ttk.Label(win, text="Existing sample:").grid(row=3, column=0, sticky="e", padx=6, pady=4)
    existing_combo = ttk.Combobox(
        win, textvariable=existing_var, values=existing, state="readonly", width=34
    )
    existing_combo.grid(row=3, column=1, columnspan=2, sticky="ew", padx=6, pady=4)

    ttk.Label(win, text="New sample ID:").grid(row=4, column=0, sticky="e", padx=6, pady=4)
    sample_entry = ttk.Entry(win, textvariable=sample_var, width=36)
    sample_entry.grid(row=4, column=1, columnspan=2, sticky="ew", padx=6, pady=4)

    ttk.Label(win, text="Mineral ID:").grid(row=5, column=0, sticky="e", padx=6, pady=4)
    mineral_combo = ttk.Combobox(win, textvariable=mineral_var, width=34, state="normal")
    mineral_combo.grid(row=5, column=1, columnspan=2, sticky="ew", padx=6, pady=4)

    ttk.Label(win, text="Run ID:").grid(row=6, column=0, sticky="e", padx=6, pady=4)
    run_combo = ttk.Combobox(win, textvariable=run_var, width=34, state="normal")
    run_combo.grid(row=6, column=1, columnspan=2, sticky="ew", padx=6, pady=4)

    ttk.Label(win, text="Pixel size (µm):").grid(row=7, column=0, sticky="e", padx=6, pady=4)
    pixel_row = ttk.Frame(win)
    pixel_row.grid(row=7, column=1, columnspan=2, sticky="w", padx=6, pady=4)
    ttk.Label(pixel_row, text="X").pack(side=tk.LEFT)
    ttk.Entry(pixel_row, textvariable=pixel_x_var, width=10).pack(side=tk.LEFT, padx=(4, 12))
    ttk.Label(pixel_row, text="Y").pack(side=tk.LEFT)
    ttk.Entry(pixel_row, textvariable=pixel_y_var, width=10).pack(side=tk.LEFT, padx=(4, 0))

    pixel_hint = "Estimated from X/Y files; edit if needed." if np.isfinite(auto_dx) and np.isfinite(auto_dy) else "Enter X and Y only if the files do not contain a usable scale."
    ttk.Label(win, text=pixel_hint).grid(
        row=8, column=1, columnspan=2, sticky="w", padx=6, pady=(0, 6)
    )

    # options used for sample
    def options_for_sample(sample_id):
        minerals = []
        runs_by_mineral = {}
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if layer not in (getattr(self, "values", {}) or {}):
                continue
            sample, mineral, run, _channel = _sample_layer_identity(meta, layer)
            if sample != sample_id:
                continue
            if mineral not in minerals:
                minerals.append(mineral)
            runs_by_mineral.setdefault(mineral, [])
            if run not in runs_by_mineral[mineral]:
                runs_by_mineral[mineral].append(run)

        record = (getattr(self, "sample_registry", {}) or {}).get(sample_id, {})
        for mineral in record.get("mineral_ids", []) if isinstance(record, dict) else []:
            mineral = str(mineral).strip()
            if mineral and mineral not in minerals:
                minerals.append(mineral)
        return minerals, runs_by_mineral

    # refresh run choices
    def refresh_run_choices(*_):
        if mode_var.get() != "existing":
            run_combo.configure(values=[])
            return
        sample_id = existing_var.get().strip()
        mineral = mineral_var.get().strip()
        _minerals, runs_by_mineral = options_for_sample(sample_id)
        runs = runs_by_mineral.get(mineral, [])
        run_combo.configure(values=runs)
        current = run_var.get().strip()
        if runs and current not in runs:
            run_var.set(runs[0])
        elif not runs and (not current or current in {"Run 1", "Run 2"}):
            run_var.set("Run 1")

    # refresh existing choices
    def refresh_existing_choices(*_):
        if mode_var.get() == "existing":
            existing_combo.configure(state="readonly")
            sample_entry.configure(state="disabled")
            sample_id = existing_var.get().strip()
            minerals, _runs = options_for_sample(sample_id)
            mineral_combo.configure(values=minerals)
            current = mineral_var.get().strip()
            if minerals and current not in minerals:
                mineral_var.set(minerals[0])
            elif not minerals and not current:
                mineral_var.set("Mineral 1")
            refresh_run_choices()
        else:
            existing_combo.configure(state="disabled")
            sample_entry.configure(state="normal")
            mineral_combo.configure(values=[])
            run_combo.configure(values=[])
            if not mineral_var.get().strip():
                mineral_var.set("Mineral 1")
            if not run_var.get().strip():
                run_var.set("Run 1")

    mode_var.trace_add("write", refresh_existing_choices)
    existing_var.trace_add("write", refresh_existing_choices)
    mineral_var.trace_add("write", refresh_run_choices)
    refresh_existing_choices()

    buttons = ttk.Frame(win)
    buttons.grid(row=9, column=0, columnspan=3, sticky="ew", padx=10, pady=(2, 10))

    # check the import assignment and close the dialog
    def accept():
        mode = mode_var.get()
        if mode == "existing":
            sample_id = existing_var.get().strip()
            if sample_id not in existing:
                messagebox.showerror("Import assignment", "Choose an existing sample.", parent=win)
                return
            new_sample = False
        else:
            sample_id = sample_var.get().strip()
            if not sample_id:
                messagebox.showerror("Import assignment", "Enter a sample ID.", parent=win)
                return
            if sample_id in existing:
                messagebox.showerror(
                    "Import assignment",
                    "That sample already exists. Use the existing-sample option instead.",
                    parent=win,
                )
                return
            new_sample = True

        mineral_id = mineral_var.get().strip()
        run_id = run_var.get().strip()
        if not mineral_id:
            messagebox.showerror("Import assignment", "Enter a mineral ID.", parent=win)
            return
        if not run_id:
            messagebox.showerror("Import assignment", "Enter a run ID.", parent=win)
            return

        px_text = pixel_x_var.get().strip()
        py_text = pixel_y_var.get().strip()
        if bool(px_text) != bool(py_text):
            messagebox.showerror("Import assignment", "Enter both X and Y pixel sizes, or leave both blank.", parent=win)
            return
        pixel_x = pixel_y = np.nan
        if px_text and py_text:
            try:
                pixel_x = float(px_text)
                pixel_y = float(py_text)
            except Exception:
                messagebox.showerror("Import assignment", "Pixel sizes must be numbers in microns.", parent=win)
                return
            if (not np.isfinite(pixel_x)) or (not np.isfinite(pixel_y)) or pixel_x <= 0 or pixel_y <= 0:
                messagebox.showerror("Import assignment", "Pixel sizes must be positive numbers.", parent=win)
                return

        result["value"] = {
            "sample_id": sample_id,
            "mineral_id": mineral_id,
            "run_id": run_id,
            "new_sample": new_sample,
            "pixel_size_x_um": pixel_x,
            "pixel_size_y_um": pixel_y,
            "auto_pixel_size_x_um": auto_dx,
            "auto_pixel_size_y_um": auto_dy,
        }
        win.destroy()

    import_button = ttk.Button(buttons, text="Import", command=accept)
    import_button.pack(side=tk.RIGHT, padx=4)
    ttk.Button(buttons, text="Cancel", command=win.destroy).pack(side=tk.RIGHT, padx=4)

    win.columnconfigure(1, weight=1)
    win.columnconfigure(2, weight=1)
    win.update_idletasks()
    width = max(470, win.winfo_reqwidth() + 20)
    height = max(380, win.winfo_reqheight() + 20)
    try:
        x = max(0, self.winfo_rootx() + (self.winfo_width() - width) // 2)
        y = max(0, self.winfo_rooty() + (self.winfo_height() - height) // 2)
        win.geometry(f"{width}x{height}+{x}+{y}")
    except Exception:
        win.geometry(f"{width}x{height}")
    win.minsize(width, height)
    win.resizable(True, True)
    win.bind("<Return>", lambda _event: accept())
    win.bind("<Escape>", lambda _event: win.destroy())
    win.protocol("WM_DELETE_WINDOW", win.destroy)

    try:
        win.wait_visibility()
        win.lift()
        import_button.focus_set()
    except Exception:
        pass
    self.wait_window(win)
    return result["value"]



# chooses the coordinate reference that matches an imported layer.
def _sample_choose_coordinate_reference(path, z_shape, refs):
    compatible = []
    set_id = coordinate_set_id_from_filename(path)
    channel = clean_channel_name_from_matrix_filename(path)
    prefix = clean_sample_prefix_from_matrix_filename(path, channel)
    prefix_norm = re.sub("[^a-z0-9]+", "", str(prefix).lower())
    for ref in refs:
        try:
            xg = np.asarray(ref.get("x_grid"), dtype=float)
            yg = np.asarray(ref.get("y_grid"), dtype=float)
            if xg.shape != yg.shape:
                continue
            if tuple(xg.shape) != tuple(z_shape):
                continue
        except Exception:
            continue
        score = 0
        ref_set = str(ref.get("coordinate_set_id", ""))
        if set_id and ref_set == str(set_id):
            score += 100
        ref_base = str(ref.get("base_group_key") or ref.get("group_key") or "")
        ref_norm = re.sub("[^a-z0-9]+", "", re.sub("::__set_[^:]+$", "", ref_base).lower())
        if (
            prefix_norm
            and ref_norm
            and (prefix_norm == ref_norm or prefix_norm in ref_norm or ref_norm in prefix_norm)
        ):
            score += 50
        compatible.append((score, ref))
    if not compatible:
        return None
    compatible.sort(key=lambda x: x[0], reverse=True)
    best_score = compatible[0][0]
    best = [ref for score, ref in compatible if score == best_score]
    if len(best) == 1:
        return best[0] if best_score > 0 or len(compatible) == 1 else None
    if best_score <= 0:
        return None
    if all(_coordinate_references_equivalent(best[0], ref, z_shape) for ref in best[1:]):
        return best[0]
    names = [str(ref.get("source_file") or ref.get("group_key") or "X/Y reference") for ref in best]
    raise ValueError(
        "More than one different X/Y coordinate set matches this map: " + "; ".join(names)
        + ". Give the map and its X/Y pair the same copy/set suffix, or enter the correct pixel size in the import window."
    )



# avoids internal layer-name collisions within one sample
def _sample_unique_internal_layer_name(self, sample_id, mineral_id, run_id, channel):
    base = f"{sample_id} :: {mineral_id} :: {run_id} :: {channel}"
    if base not in self.values:
        return base
    i = 2
    while f"{base} ({i})" in self.values:
        i += 1
    return f"{base} ({i})"



# finds an existing layer from the same dataset and channel.
def _sample_find_same_dataset_channel(self, sample_id, mineral_id, run_id, channel):
    for layer, meta in (getattr(self, "metas", {}) or {}).items():
        if layer not in self.values:
            continue
        s, m, r, c = _sample_layer_identity(meta, layer)
        if (s, m, r, c) == (sample_id, mineral_id, run_id, channel):
            return layer
    return None



# creates or updates a sample record from imported metadata.
def _sample_register_sample_from_metadata(self, sample_id):
    rec = self.sample_registry.setdefault(
        sample_id,
        {
            "sample_id": sample_id,
            "layer_keys": [],
            "mineral_ids": [],
            "run_ids": [],
            "state": _sample_empty_workspace_state(),
        },
    )
    rec["layer_keys"] = []
    rec["mineral_ids"] = []
    rec["run_ids"] = []
    for layer, meta in (getattr(self, "metas", {}) or {}).items():
        if layer not in self.values:
            continue
        sample, mineral, run, _channel = _sample_layer_identity(meta, layer)
        if sample != sample_id:
            continue
        rec["layer_keys"].append(layer)
        if mineral not in rec["mineral_ids"]:
            rec["mineral_ids"].append(mineral)
        if run not in rec["run_ids"]:
            rec["run_ids"].append(run)
    return rec



# imports a batch of map paths into one sample workspace.
def _sample_import_paths(
    self, paths, sample_id, mineral_id, run_id, new_sample=False,
    pixel_size_x_um=np.nan, pixel_size_y_um=np.nan,
    auto_pixel_size_x_um=np.nan, auto_pixel_size_y_um=np.nan,
):
    paths = list(paths)
    errors = []
    warnings_list = []
    data_items = []
    refs = []
    axis_groups = {}

    chosen_dx = safe_float(pixel_size_x_um, np.nan)
    chosen_dy = safe_float(pixel_size_y_um, np.nan)
    auto_dx = safe_float(auto_pixel_size_x_um, np.nan)
    auto_dy = safe_float(auto_pixel_size_y_um, np.nan)
    chosen_pixel_size_valid = (
        np.isfinite(chosen_dx) and chosen_dx > 0 and np.isfinite(chosen_dy) and chosen_dy > 0
    )
    auto_pixel_size_valid = (
        np.isfinite(auto_dx) and auto_dx > 0 and np.isfinite(auto_dy) and auto_dy > 0
    )
    pixel_size_was_edited = False
    if chosen_pixel_size_valid:
        if not auto_pixel_size_valid:
            pixel_size_was_edited = True
        else:
            x_changed = abs(chosen_dx - auto_dx) > max(abs(auto_dx) * 1e-6, 1e-9)
            y_changed = abs(chosen_dy - auto_dy) > max(abs(auto_dy) * 1e-6, 1e-9)
            pixel_size_was_edited = bool(x_changed or y_changed)

    for path in paths:
        try:
            axis = coordinate_axis_from_filename(path)
            if axis in {"x", "y"}:
                key = clean_coordinate_axis_group_name_from_filename(path)
                axis_groups.setdefault(key, {})[axis] = path
                continue
            coord_ref = self.maybe_read_coordinate_reference(path)
            if coord_ref is not None:
                refs.append(coord_ref)
                continue
            file_values, file_meta = load_probe_file(path)
            data_items.append((path, file_values, file_meta))
        except Exception as exc:
            errors.append(f"{os.path.basename(path)}: {exc}")
    for key, pair in axis_groups.items():
        if "x" in pair and "y" in pair:
            try:
                refs.append(
                    make_coordinate_reference_from_axis_matrices(
                        pair["x"], pair["y"], group_key=key
                    )
                )
            except Exception as exc:
                warnings_list.append(f"{key}: coordinate pair could not be read ({exc})")
        else:
            warnings_list.append(
                f"{key}: matching X and Y coordinate matrices were not both selected"
            )
    if not data_items:
        messagebox.showerror(
            "Import failed", "No map data files were found.\n\n" + "\n".join(errors)
        )
        return 0
    if new_sample and sample_id not in self.sample_registry:
        _sample_remove_empty_tab(self)
        self.sample_registry[sample_id] = {
            "sample_id": sample_id,
            "layer_keys": [],
            "mineral_ids": [],
            "run_ids": [],
            "state": _sample_empty_workspace_state(),
        }
        _sample_make_sample_canvas(self, sample_id)
    elif sample_id not in self.sample_registry:
        _sample_remove_empty_tab(self)
        self.sample_registry[sample_id] = {
            "sample_id": sample_id,
            "layer_keys": [],
            "mineral_ids": [],
            "run_ids": [],
            "state": _sample_empty_workspace_state(),
        }
        _sample_make_sample_canvas(self, sample_id)
    loaded_layers = 0
    first_channel = None
    for path, file_values, file_meta in data_items:
        for raw_name, z in file_values.items():
            try:
                channel = str(raw_name).strip()
                if str(file_meta.get("kind", "")).startswith("matrix_file"):
                    channel = clean_channel_name_from_matrix_filename(path)
                channel = (
                    self.raw_canonical_element_column_name(channel)
                    if hasattr(self, "raw_canonical_element_column_name")
                    else channel
                )
                channel = _sample_safe_id(channel, "Channel")
                if first_channel is None:
                    first_channel = channel
                arr = np.asarray(z, dtype=float)
                meta = dict(file_meta)
                meta.update(
                    {
                        "sample_id": sample_id,
                        "sample_name": sample_id,
                        "map_group": sample_id,
                        "comparison_dataset": sample_id,
                        "mineral_id": mineral_id,
                        "mineral_name": mineral_id,
                        "mineral_type": mineral_id,
                        "run_id": run_id,
                        "run_name": run_id,
                        "canonical_column": channel,
                        "source_layer_name": channel,
                        "source_file": os.path.basename(path),
                        "import_group_key": f"{sample_id}::{mineral_id}::{run_id}",
                        "coordinate_group_key": sample_id,
                        "display_prefix": "",
                    }
                )
                coordinate_reference_ambiguous = False
                try:
                    ref = _sample_choose_coordinate_reference(path, arr.shape, refs)
                except ValueError as exc:
                    ref = None
                    coordinate_reference_ambiguous = True
                    warnings_list.append(f"{os.path.basename(path)}: {exc}")
                if ref is not None and str(meta.get("kind", "")).startswith("matrix_file"):
                    try:
                        meta = apply_coordinate_reference_to_meta(meta, arr.shape, ref)
                        meta["sample_id"] = sample_id
                        meta["map_group"] = sample_id
                        meta["comparison_dataset"] = sample_id
                        meta["mineral_id"] = mineral_id
                        meta["mineral_type"] = mineral_id
                        meta["run_id"] = run_id
                        meta["canonical_column"] = channel
                        meta["coordinate_group_key"] = sample_id
                        meta["coordinate_reference_group_key"] = sample_id
                    except Exception as exc:
                        warnings_list.append(
                            f"{os.path.basename(path)}: X/Y reference was not applied ({exc})"
                        )
                if (not coordinate_reference_ambiguous) and (not _layer_uses_physical_coordinates(meta, arr.shape)):
                    for existing_layer, existing_meta in (getattr(self, "metas", {}) or {}).items():
                        if existing_layer not in getattr(self, "values", {}):
                            continue
                        es, _em, _er, _ec = _sample_layer_identity(existing_meta, existing_layer)
                        if es != sample_id:
                            continue
                        existing_arr = np.asarray(self.values[existing_layer])
                        if existing_arr.shape != arr.shape:
                            continue
                        coordinate_keys = [
                            "x",
                            "y",
                            "x_grid",
                            "y_grid",
                            "x_name",
                            "y_name",
                            "registered_x_axis",
                            "registered_y_axis",
                            "physical_coordinate_units",
                            "coordinate_grid_preserved",
                        ]
                        inherited = False
                        for key in coordinate_keys:
                            if key in existing_meta:
                                meta[key] = _sample_copy(existing_meta[key])
                                inherited = True
                        if inherited:
                            meta["coordinate_import_mode"] = "inherited_from_existing_sample"
                            meta["coordinate_reference_group_key"] = sample_id
                            meta["coordinate_group_key"] = sample_id
                            meta["shared_coordinate_registration"] = True
                            meta["shared_coordinate_registration_group"] = sample_id
                            break
                # The import dialog shows the file-derived pixel size. If the user changes it,
                # use that value while keeping the first imported coordinate as the map origin.
                if chosen_pixel_size_valid and pixel_size_was_edited:
                    try:
                        x_axis = np.asarray(meta.get("x", []), dtype=float)
                        y_axis = np.asarray(meta.get("y", []), dtype=float)
                        finite_x = x_axis[np.isfinite(x_axis)]
                        finite_y = y_axis[np.isfinite(y_axis)]
                        x0 = float(finite_x[0]) if finite_x.size else 0.0
                        y0 = float(finite_y[0]) if finite_y.size else 0.0
                        meta = self._apply_manual_pixel_scale_to_meta(
                            meta, arr.shape, chosen_dx, chosen_dy, x0, y0
                        )
                        meta["pixel_size_set_at_import"] = True
                    except Exception as exc:
                        warnings_list.append(
                            f"{os.path.basename(path)}: edited pixel size could not be applied ({exc})"
                        )

                existing = _sample_find_same_dataset_channel(
                    self, sample_id, mineral_id, run_id, channel
                )
                if existing is not None:
                    old = np.asarray(self.values[existing], dtype=float)
                    if old.shape == arr.shape:
                        merged = old.copy()
                        fill = ~np.isfinite(merged) & np.isfinite(arr)
                        merged[fill] = arr[fill]
                        self.values[existing] = merged
                        if _layer_uses_physical_coordinates(meta, arr.shape) and (
                            not _layer_uses_physical_coordinates(
                                self.metas.get(existing, {}), old.shape
                            )
                        ):
                            self.metas[existing] = meta
                        continue
                    warnings_list.append(
                        f"{channel}: same sample/mineral/run already has this channel with a different shape; kept as a separate stored layer"
                    )
                internal = _sample_unique_internal_layer_name(
                    self, sample_id, mineral_id, run_id, channel
                )
                self.values[internal] = arr
                self.metas[internal] = meta
                self.layer_mineral_type[internal] = mineral_id
                loaded_layers += 1
            except Exception as exc:
                errors.append(f"{os.path.basename(path)} / {raw_name}: {exc}")
    _sample_register_sample_from_metadata(self, sample_id)
    try:
        self.rebuild_mineral_presence_groups_from_metadata()
        self.rebuild_mineral_column_index()
    except Exception:
        pass
    try:
        self.register_shared_physical_axes()
    except Exception:
        pass
    _sample_refresh_plot_sample_list(self, select_new=sample_id)
    _sample_activate_sample(self, sample_id, redraw=False, select_tab=True)
    if first_channel:
        try:
            self.column_var.set(first_channel)
            self.sample_registry[sample_id]["state"]["column_name"] = first_channel
        except Exception:
            pass
    try:
        self.refresh_map_column_combo(preserve=True)
        self.refresh_map_view_mineral_list()
        self.refresh_mineral_overlay_list()
        self.refresh_mineral_stats_controls()
        self.refresh_grain_controls()
        self.refresh_compare_grain_controls()
        self.refresh_analysis_columns()
        self.update_map()
    except Exception:
        pass
    message = f"Imported {loaded_layers} channel layer(s) into sample {sample_id}, mineral {mineral_id}, run {run_id}."
    if warnings_list:
        message += f" {len(warnings_list)} warning(s)."
    try:
        self.status_var.set(message)
    except Exception:
        pass
    if errors or warnings_list:
        notes = []
        if warnings_list:
            notes.append("Warnings:\n" + "\n".join(warnings_list[:15]))
        if errors:
            notes.append("Files/layers not loaded:\n" + "\n".join(errors[:15]))
        messagebox.showwarning("Import notes", "\n\n".join(notes))
    return loaded_layers



# file dialog and basic checks for sample map imports.
def _sample_choose_import_files(self, title):
    return filedialog.askopenfilenames(
        title=title,
        filetypes=[
            (
                "Map/data files",
                "*.dat *.DAT *.grd *.GRD *.csv *.CSV *.txt *.TXT *.xlsx *.XLSX *.xls *.XLS",
            ),
            ("All files", "*.*"),
        ],
    )



# groups compatible layers before building the combined pixel table.
def _sample_group_layers_for_pixels(self, sample_ids):
    groups = {}
    for layer, meta in (getattr(self, "metas", {}) or {}).items():
        if layer not in (getattr(self, "values", {}) or {}):
            continue
        sample, mineral, run, channel = _sample_layer_identity(meta, layer)
        if sample not in sample_ids:
            continue
        z = np.asarray(self.values[layer])
        key = (sample, mineral, run, tuple(z.shape))
        groups.setdefault(key, []).append((layer, channel))
    return groups



# physical or index coordinates for one sample layer
def _sample_pixel_coordinates_for_layer(self, layer):
    arr = np.asarray(self.values[layer], dtype=float)
    meta = self.metas.get(layer, {})
    xg, yg = self._layer_pixel_centers(meta, z_shape=arr.shape)
    if (
        xg is None
        or yg is None
        or tuple(np.shape(xg)) != tuple(arr.shape)
        or (tuple(np.shape(yg)) != tuple(arr.shape))
    ):
        rows, cols = np.indices(arr.shape)
        return (cols.astype(float), rows.astype(float))
    return (np.asarray(xg, dtype=float), np.asarray(yg, dtype=float))



# combines compatible sample layers into one pixel table
def _sample_build_combined_pixel_table(self, sample_ids):
    sample_ids = [str(s) for s in sample_ids if str(s) in getattr(self, "sample_registry", {})]
    if not sample_ids:
        raise ValueError("Select at least one sample.")

    parts = []
    groups = _sample_group_layers_for_pixels(self, sample_ids)
    for (sample, mineral, run, shape), layers in groups.items():
        if not layers:
            continue

        channel_arrays = []
        for layer, channel in layers:
            arr = np.asarray(self.values[layer], dtype=float)
            if tuple(arr.shape) == tuple(shape):
                channel_arrays.append((channel, arr))
        if not channel_arrays:
            continue

        valid = np.zeros(shape, dtype=bool)
        for _channel, arr in channel_arrays:
            valid |= np.isfinite(arr)
        flat_index = np.flatnonzero(valid.ravel())
        if flat_index.size == 0:
            continue

        n_rows, n_cols = shape
        row_index = flat_index // n_cols
        column_index = flat_index % n_cols
        base_layer = layers[0][0]
        x_grid, y_grid = _sample_pixel_coordinates_for_layer(self, base_layer)
        dataset_id = f"{sample} :: {mineral} :: {run}"
        n = flat_index.size

        # one repeated categorical value without building a full object array.
        def repeated_category(value):
            return pd.Categorical.from_codes(np.zeros(n, dtype=np.int8), categories=[str(value)])

        out = pd.DataFrame(
            {
                "sample_id": repeated_category(sample),
                "mineral_id": repeated_category(mineral),
                "run_id": repeated_category(run),
                "dataset_id": repeated_category(dataset_id),
                "map_group": repeated_category(sample),
                "comparison_dataset": repeated_category(sample),
                "mineral_type": repeated_category(mineral),
                "plot_group": repeated_category(sample),
                "row_index": row_index.astype(np.int32, copy=False),
                "column_index": column_index.astype(np.int32, copy=False),
                "x": np.asarray(x_grid, dtype=float).ravel()[flat_index],
                "y": np.asarray(y_grid, dtype=float).ravel()[flat_index],
                "pixel_id": np.arange(1, n + 1, dtype=np.int32),
            }
        )

        for channel, arr in channel_arrays:
            values = arr.ravel()[flat_index]
            if channel not in out.columns:
                out[channel] = values
            else:
                current = pd.to_numeric(out[channel], errors="coerce").to_numpy(dtype=float)
                fill = ~np.isfinite(current) & np.isfinite(values)
                current[fill] = values[fill]
                out[channel] = current
        parts.append(out)

    if not parts:
        raise ValueError("No pixel rows were available for the selected samples.")
    return pd.concat(parts, ignore_index=True, sort=False)



# normalizes sample, mineral, and run columns after import
def _sample_canonicalize_dataframe_columns(self, df):
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df.copy() if isinstance(df, pd.DataFrame) else pd.DataFrame()
    out = pd.DataFrame(index=df.index)
    for col in df.columns:
        name = str(col)
        if name in (getattr(self, "metas", {}) or {}):
            target = _sample_layer_identity(self.metas.get(name, {}), name)[3]
        else:
            target = name
            if " :: " in name:
                try:
                    target = self.canonical_layer_display_name(name)
                except Exception:
                    target = name.split(" :: ")[-1]
        if target not in out.columns:
            out[target] = df[col]
        else:
            current = out[target]
            incoming = df[col]
            out[target] = current.where(current.notna(), incoming)
    return out



# analysis table stored for one sample workspace
def _sample_state_dataframe(self, sample_id, attr):
    if sample_id == getattr(self, "active_sample_id", None):
        _sample_save_active_workspace(self)
    state = getattr(self, "sample_registry", {}).get(sample_id, {}).get("state", {})
    df = state.get(attr)
    if not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()
    out = _sample_canonicalize_dataframe_columns(self, df)
    if "sample_id" not in out.columns:
        out["sample_id"] = sample_id
    if "map_group" not in out.columns:
        out["map_group"] = sample_id
    if "comparison_dataset" not in out.columns:
        out["comparison_dataset"] = sample_id
    if "mineral_id" not in out.columns:
        if "mineral_type" in out.columns:
            out["mineral_id"] = out["mineral_type"]
        else:
            out["mineral_id"] = "Selection"
    if "run_id" not in out.columns:
        out["run_id"] = "Selection"
    if "plot_group" not in out.columns:
        out["plot_group"] = sample_id
    return out



# grain pixels recovered from a saved sample state
def _sample_grain_pixels_from_sample_state(self, sample_id):
    if sample_id == getattr(self, "active_sample_id", None):
        _sample_save_active_workspace(self)
    state = getattr(self, "sample_registry", {}).get(sample_id, {}).get("state", {})
    parts = []
    runs = state.get("grain_analysis_runs", {})
    if isinstance(runs, dict):
        for key, run in runs.items():
            try:
                df = _grain_pixels_from_saved_run(self, key, run)
            except Exception:
                df = pd.DataFrame()
            if isinstance(df, pd.DataFrame) and (not df.empty):
                df = _sample_canonicalize_dataframe_columns(self, df)
                df["sample_id"] = sample_id
                if "mineral_id" not in df.columns:
                    df["mineral_id"] = df.get("mineral_type", str(run.get("mineral_type", key)))
                if "run_id" not in df.columns:
                    df["run_id"] = str(run.get("run_id", key))
                parts.append(df)
    if not parts:
        df = state.get("last_grain_pixel_df")
        if isinstance(df, pd.DataFrame) and (not df.empty):
            df = _sample_canonicalize_dataframe_columns(self, df)
            df["sample_id"] = sample_id
            parts.append(df)
    return pd.concat(parts, ignore_index=True, sort=False) if parts else pd.DataFrame()



# adds the sample/mineral/run rename controls
