# guesses which ID field the user is trying to rename.
def _sample_suggest_rename_target(self, event=None):
    layer = getattr(self, "_channel_rename_sources", {}).get(self.simple_rename_source_var.get())
    if layer in (getattr(self, "metas", {}) or {}):
        _s, _m, _r, channel = _sample_layer_identity(self.metas[layer], layer)
        self.simple_rename_target_var.set(channel)



# merges repeated imports that belong to the same dataset.
def _sample_merge_same_dataset_layers(self, keep_layer, remove_layer):
    a = np.asarray(self.values[keep_layer], dtype=float)
    b = np.asarray(self.values[remove_layer], dtype=float)
    if a.shape != b.shape:
        return False
    merged = a.copy()
    fill = ~np.isfinite(merged) & np.isfinite(b)
    merged[fill] = b[fill]
    self.values[keep_layer] = merged
    self.values.pop(remove_layer, None)
    self.metas.pop(remove_layer, None)
    self.layer_mineral_type.pop(remove_layer, None)
    for rec in getattr(self, "sample_registry", {}).values():
        rec["layer_keys"] = [k for k in rec.get("layer_keys", []) if k != remove_layer]
    return True



# applies a sample/mineral/run rename to matching table rows
def _sample_contextual_rename_df(
    df, sample_id, mineral_id, run_id, old_name, new_name, old_still_exists
):
    if not isinstance(df, pd.DataFrame) or df.empty or old_name not in df.columns:
        return df
    out = df.copy()
    mask = np.ones(len(out), dtype=bool)
    for col, value in [("sample_id", sample_id), ("mineral_id", mineral_id), ("run_id", run_id)]:
        if col in out.columns:
            mask &= out[col].astype(str).to_numpy() == str(value)
    if new_name not in out.columns:
        out[new_name] = np.nan
    source_vals = out.loc[mask, old_name]
    current_vals = out.loc[mask, new_name]
    out.loc[mask, new_name] = current_vals.where(current_vals.notna(), source_vals)
    if old_still_exists:
        out.loc[mask, old_name] = np.nan
    else:
        out = out.drop(columns=[old_name])
    return out



# recreates sample tabs when a project is opened
def _sample_rebuild_sample_tabs_from_state(self, state):
    for sid, view in list(getattr(self, "sample_map_views", {}).items()):
        try:
            self.sample_map_notebook.forget(view["frame"])
            view["frame"].destroy()
        except Exception:
            pass
    self.sample_map_views = {}
    saved_registry = state.get("sample_registry") if isinstance(state, dict) else None
    if isinstance(saved_registry, dict) and saved_registry:
        self.sample_registry = _sample_copy(saved_registry)
    else:
        self.sample_registry = {}
        ids = _sample_sample_ids_from_metadata(self)
        if not ids and self.values:
            ids = ["Sample 1"]
            for layer, meta in self.metas.items():
                if not isinstance(meta, dict):
                    meta = {}
                    self.metas[layer] = meta
                meta.setdefault("sample_id", "Sample 1")
                meta.setdefault("map_group", "Sample 1")
                meta.setdefault("comparison_dataset", "Sample 1")
                meta.setdefault("mineral_id", meta.get("mineral_type", "Mineral 1"))
                meta.setdefault("mineral_type", meta.get("mineral_id", "Mineral 1"))
                meta.setdefault("run_id", "Run 1")
            ids = ["Sample 1"]
        for sid in ids:
            self.sample_registry[sid] = {
                "sample_id": sid,
                "layer_keys": [],
                "mineral_ids": [],
                "run_ids": [],
                "state": _sample_empty_workspace_state(),
            }
            _sample_register_sample_from_metadata(self, sid)
    if not self.sample_registry:
        _sample_make_sample_canvas(self, "__EMPTY__", "No samples")
        self.active_sample_id = "__EMPTY__"
        _sample_assign_active_canvas(self, "__EMPTY__")
        _sample_refresh_plot_sample_list(self)
        return
    for sid in self.sample_registry:
        _sample_make_sample_canvas(self, sid)
    active = state.get("active_sample_id") if isinstance(state, dict) else None
    if active not in self.sample_registry:
        active = next(iter(self.sample_registry))
    _sample_activate_sample(self, active, redraw=True, select_tab=True)
    selected = set(state.get("selected_plot_sample_ids", [])) if isinstance(state, dict) else set()
    _sample_refresh_plot_sample_list(self)
    if selected:
        self.plot_sample_listbox.selection_clear(0, tk.END)
        for i in range(self.plot_sample_listbox.size()):
            if str(self.plot_sample_listbox.get(i)) in selected:
                self.plot_sample_listbox.selection_set(i)



# grain pixels combined across all loaded sample workspaces
def _sample_combined_grain_pixel_table(self):
    return combined_grain_pixel_table(self)



# builds the main interface after the project state has been initialized.
def _build_interface(self, *args, **kwargs):
    """Build the interface once, then add the optional analysis controls."""
    result = _build_base_interface(self, *args, **kwargs)

    # Add controls that extend the base tabs.
    for setup in (
        self.add_xy_profile_tools_xy_controls,
        self.add_xy_profile_tools_profile_controls,
        self._add_profile_color_group_controls,
        self._add_custom_color_group_controls,
    ):
        try:
            setup()
        except (AttributeError, tk.TclError):
            pass

    # Profiles are handled in the X-Y tab.
    try:
        self.notebook.forget(self.profile_tab)
    except (AttributeError, tk.TclError):
        pass
    try:
        _destroy_named_labelframes(self, {"Profile drawing"})
    except (AttributeError, tk.TclError):
        pass

    self._ensure_iqr_settings()
    try:
        _remove_profile_group_panel(self, self)
    except (AttributeError, tk.TclError):
        pass
    try:
        _rename_radial_handoff_buttons(self, self)
    except (AttributeError, tk.TclError):
        pass
    try:
        self._build_xy_control_panel()
    except (AttributeError, tk.TclError):
        pass

    self.grain_analysis_runs = getattr(self, "grain_analysis_runs", {})
    try:
        self._install_grain_set_controls()
        self._configure_multi_mineral_grain_button()
    except (AttributeError, tk.TclError):
        pass

    # Layout-sensitive controls are added after Tk has calculated widget sizes.

    # finish layout
    def finish_layout():
        for task in (
            self._simplify_tab_layouts,
            self._tidy_interface,
            self.refresh_plot_filters,
            self._place_iqr_controls,
            self.retarget_plot_current_map_buttons,
        ):
            try:
                task()
            except (AttributeError, tk.TclError):
                pass
        try:
            _rename_radial_handoff_buttons(self, self)
        except (AttributeError, tk.TclError):
            pass

    try:
        self.after_idle(finish_layout)
        self.after(500, finish_layout)
    except tk.TclError:
        pass
    self.title("Geochemical Map Analysis")
    return result



# map group currently selected in the shared controls
def _selected_map_group(self):
    try:
        value = str(self.map_group_filter_var.get()).strip()
    except Exception:
        value = "All maps"
    if not value or value == "All maps":
        return None
    return value



# turns a displayed layer label back into its internal layer name.
def _resolve_display_layer(self, display_col, mineral=None):
    clean = self.canonical_layer_display_name(display_col)
    if mineral not in (None, "", "None"):
        try:
            layer = self._layer_for_mineral_value_column(str(mineral), clean)
            if layer in getattr(self, "values", {}):
                return layer
        except Exception:
            pass
    try:
        for layer, meta in getattr(self, "metas", {}).items():
            meta_clean = meta.get("canonical_column") if isinstance(meta, dict) else None
            meta_clean = self.canonical_layer_display_name(meta_clean if meta_clean else layer)
            if meta_clean == clean and layer in self.values:
                return layer
    except Exception:
        pass
    try:
        for layer in getattr(self, "values", {}).keys():
            if self.canonical_layer_display_name(layer) == clean:
                return layer
    except Exception:
        pass
    return None



# refreshes alias choices after a map import or rename.
def _refresh_alias_controls(self):
    mapping = self._column_source_choices()
    self._channel_source_map = mapping
    sources = list(mapping.keys())
    targets = self._canonical_target_name_choices()
    try:
        self.alias_source_combo.configure(values=sources)
        self.alias_target_combo.configure(values=targets)
    except Exception:
        pass
    try:
        current = self.alias_source_col_var.get()
        if sources and current not in sources:
            self.alias_source_col_var.set(sources[0])
            current = sources[0]
        if current:
            self._suggest_column_target()
    except Exception:
        pass



# collect state for project files
def _collect_project_state(self):
    try:
        self.store_current_grain_analysis_run(refresh=False)
    except Exception:
        pass
    simple_attrs = ['values', 'metas', 'mineral_layers', 'mineral_colors', 'mineral_presence_groups', 'mineral_column_index', 'coord_refs', 'line_profile_df', 'spot_df', 'area_df', 'area_pixel_df', 'analysis_df', 'active_analysis_df', 'comparison_df', 'last_boundary_buffer_chemistry_df', 'last_boundary_buffer_delta_df', 'last_boundary_buffer_ratio_df', 'last_boundary_buffer_ratio_pairs_df', 'last_boundary_buffer_skipped', 'last_boundary_buffer_ratio_skipped', 'last_nn_summary_df', 'last_nn_pairwise_df', 'last_grain_table_df', 'last_grain_pixel_df', 'last_grain_summary_df', 'last_grain_label_mask', 'last_grain_labels', 'last_grain_x', 'last_grain_y', 'last_grain_source_layer', 'last_kde_ks_df', 'shared_coordinate_pixel_df', 'current_column', 'current_layer', 'current_map_layer', 'active_map_layer', 'current_map_name']
    var_attrs = ['column_var', 'vmin_var', 'vmax_var', 'map_invert_x_var', 'map_invert_y_var', 'profile_mode_var', 'profile_logy_var', 'profile_separate_y_var', 'profile_buffer_pixels_var', 'xy_connect_in_path_order_var', 'profile_number_filter_var', 'profile_color_by_number_var', 'profile_color_groups_var', 'custom_color_group_source_var', 'spider_iqr_reject_var', 'spider_iqr_multiplier_var', 'mineral_stats_value_var', 'mineral_stats_rule_var', 'mineral_stats_threshold_var', 'mineral_stats_pie_mode_var', 'mineral_stats_colors_var', 'mineral_stats_source_var', 'boundary_buffer_pixels_var', 'show_mineral_boundary_buffer_var', 'kde_summary_var', 'kde_group_var', 'kde_mean_unit_var', 'kde_max_points_var', 'kde_grid_points_var', 'kde_bandwidth_var', 'kde_log_data_var', 'kde_fill_var', 'kde_positive_only_var']
    state = {'format': 'GeochemicalMapAnalysis_project', 'version': 1, 'simple_attrs': {}, 'var_values': {}}
    for attr in simple_attrs:
        value = self._safe_project_get(attr, None)
        if value is not None:
            state['simple_attrs'][attr] = value
    for attr in var_attrs:
        value = self._safe_project_var_value(attr, None)
        if value is not None:
            state['var_values'][attr] = value
    try:
        state['area_masks'] = getattr(self, 'area_masks', {})
    except Exception:
        pass
