    # keeps the filter menu in step with the channels loaded for the active sample.
    def _refresh_pixel_filter_channels(self):
        combo = getattr(self, "pixel_filter_channel_combo", None)
        var = getattr(self, "pixel_filter_channel_var", None)
        if combo is None or var is None:
            return
        choices = ["Current map"] + list(self.get_canonical_map_columns())
        combo.configure(values=choices)
        if str(var.get()) not in choices:
            var.set("Current map")


    # finds the real map layer represented by the pixel-filter channel menu.
    def _resolve_pixel_filter_layer(self):
        selected = str(self.pixel_filter_channel_var.get()).strip()
        if selected in {"", "Current map"}:
            self._force_displayed_map_into_tool_state()
            for name in ("current_column", "current_layer", "current_map_layer"):
                layer = getattr(self, name, None)
                if layer in getattr(self, "values", {}):
                    return layer
            try:
                selected = str(self.column_var.get()).strip()
            except Exception:
                selected = ""
        layer = self.resolve_display_column_to_layer(selected)
        if layer not in getattr(self, "values", {}):
            raise ValueError("Choose a map channel that is loaded for the active sample.")
        return layer


    # turns the rule entries into a Boolean mask on the chosen channel.
    def _pixel_filter_condition(self, values):
        arr = np.asarray(values, dtype=float)
        operator = str(self.pixel_filter_operator_var.get()).strip()
        finite = np.isfinite(arr)
        if operator == "not finite":
            return ~finite

        try:
            value1 = float(str(self.pixel_filter_value1_var.get()).strip())
        except Exception:
            raise ValueError("Enter a numeric filter value.")

        if operator in {"between", "outside"}:
            try:
                value2 = float(str(self.pixel_filter_value2_var.get()).strip())
            except Exception:
                raise ValueError("Between and outside rules need two numeric values.")
            low, high = sorted((value1, value2))
            if operator == "between":
                return finite & (arr >= low) & (arr <= high)
            return finite & ((arr < low) | (arr > high))
        if operator == "<":
            return finite & (arr < value1)
        if operator == "<=":
            return finite & (arr <= value1)
        if operator == ">":
            return finite & (arr > value1)
        if operator == ">=":
            return finite & (arr >= value1)
        if operator == "==":
            return finite & np.isclose(arr, value1, rtol=1e-12, atol=0.0)
        raise ValueError("Choose a valid pixel-filter rule.")


    # identifies layers that share the same pixels as the channel used for the rule.
    def _pixel_filter_target_layers(self, source_layer, scope=None):
        if scope is None:
            scope = str(self.pixel_filter_scope_var.get()).strip()
        else:
            scope = str(scope).strip()
        if scope == "Selected channel only":
            return [source_layer]

        source_values = np.asarray(self.values[source_layer])
        source_meta = self.metas.get(source_layer, {}) or {}
        source_sample, source_mineral, source_run, _source_channel = _sample_layer_identity(
            source_meta, source_layer
        )
        source_group = str(
            source_meta.get("coordinate_group_key")
            or source_meta.get("base_grid_layer")
            or ""
        )
        targets = []
        mask_names = {"presence", "present", "mask", "mineral_presence", "mineral type"}
        for layer, values in getattr(self, "values", {}).items():
            try:
                arr = np.asarray(values)
                if arr.ndim != 2 or arr.shape != source_values.shape:
                    continue
            except Exception:
                continue
            meta = self.metas.get(layer, {}) or {}
            sample, mineral, run, channel = _sample_layer_identity(meta, layer)
            if (sample, mineral, run) != (source_sample, source_mineral, source_run):
                continue
            target_group = str(
                meta.get("coordinate_group_key") or meta.get("base_grid_layer") or ""
            )
            if source_group and target_group and source_group != target_group:
                continue
            if scope == "All aligned data channels" and str(channel).strip().lower() in mask_names:
                continue
            targets.append(layer)
        if not targets:
            targets = [source_layer]
        return targets


    # reapplies every saved rule from the untouched copies of the map arrays.
    def _rebuild_pixel_exclusions(self):
        values = getattr(self, "values", {})
        originals = getattr(self, "pixel_exclusion_original_values", {})
        for layer, original in list(originals.items()):
            if layer in values:
                values[layer] = np.asarray(original, dtype=float).copy()

        combined = {}
        for rule in getattr(self, "pixel_exclusion_rules", []):
            mask = np.asarray(rule.get("mask"), dtype=bool)
            source_layer = rule.get("source_layer")
            try:
                targets = self._pixel_filter_target_layers(
                    source_layer, scope=rule.get("scope")
                )
            except Exception:
                targets = list(rule.get("target_layers", []))
            rule["target_layers"] = list(targets)
            for layer in targets:
                if layer not in values:
                    continue
                if layer not in originals:
                    originals[layer] = np.asarray(values[layer], dtype=float).copy()
                if np.shape(originals[layer]) != np.shape(mask):
                    continue
                if layer not in combined:
                    combined[layer] = mask.copy()
                else:
                    combined[layer] |= mask

        for layer, mask in combined.items():
            original = np.asarray(originals[layer], dtype=float)
            values[layer] = np.where(mask, np.nan, original)
        self.pixel_exclusion_masks = combined
        self._update_pixel_filter_status()


    # updates the small count shown under the pixel-filter buttons.
    def _update_pixel_filter_status(self):
        rules = list(getattr(self, "pixel_exclusion_rules", []))
        masks = getattr(self, "pixel_exclusion_masks", {})
        if not rules:
            text = "No pixels are excluded."
        else:
            positions = set()
            for mask in masks.values():
                flat = np.flatnonzero(np.asarray(mask, dtype=bool).ravel())
                positions.update(flat.tolist())
            text = (
                f"{len(rules)} rule(s); {len(positions):,} pixel position(s) excluded "
                f"across {len(masks)} channel(s)."
            )
        var = getattr(self, "pixel_filter_status_var", None)
        if hasattr(var, "set"):
            var.set(text)


    # applies the current rule and keeps an untouched copy so it can be reversed.
    def apply_pixel_exclusion(self):
        try:
            source_layer = self._resolve_pixel_filter_layer()
            source_values = self.pixel_exclusion_original_values.get(
                source_layer, np.asarray(self.values[source_layer], dtype=float)
            )
            mask = self._pixel_filter_condition(source_values)
            if not np.any(mask):
                messagebox.showinfo("Pixel exclusion", "No pixels matched that rule.")
                return
            targets = self._pixel_filter_target_layers(source_layer)
            for layer in targets:
                if layer not in self.pixel_exclusion_original_values:
                    self.pixel_exclusion_original_values[layer] = np.asarray(
                        self.values[layer], dtype=float
                    ).copy()
            self.pixel_exclusion_rules.append(
                {
                    "source_layer": source_layer,
                    "operator": str(self.pixel_filter_operator_var.get()),
                    "value1": str(self.pixel_filter_value1_var.get()),
                    "value2": str(self.pixel_filter_value2_var.get()),
                    "scope": str(self.pixel_filter_scope_var.get()),
                    "mask": np.asarray(mask, dtype=bool).copy(),
                    "target_layers": list(targets),
                }
            )
            self._rebuild_pixel_exclusions()
            self.update_map()
            self.status_var.set(
                f"Excluded {int(np.count_nonzero(mask)):,} pixel positions. "
                "New selections and calculations will ignore them; rerun existing grain results."
            )
        except Exception as exc:
            messagebox.showerror("Could not exclude pixels", str(exc))


    # removes only the most recently applied pixel rule.
    def undo_pixel_exclusion(self):
        if not getattr(self, "pixel_exclusion_rules", []):
            return
        self.pixel_exclusion_rules.pop()
        self._rebuild_pixel_exclusions()
        try:
            self.update_map()
        except Exception:
            pass
        self.status_var.set("Removed the last pixel-exclusion rule.")


    # restores every map array to its values from before filtering.
    def clear_pixel_exclusions(self):
        for layer, original in getattr(self, "pixel_exclusion_original_values", {}).items():
            if layer in getattr(self, "values", {}):
                self.values[layer] = np.asarray(original, dtype=float).copy()
        self.pixel_exclusion_rules = []
        self.pixel_exclusion_masks = {}
        self.pixel_exclusion_original_values = {}
        self._update_pixel_filter_status()
        try:
            self.update_map()
        except Exception:
            pass
        self.status_var.set("Cleared all pixel exclusions.")


    # removes excluded rows from pixel tables before they reach plots or exports.
    def _filter_excluded_pixel_rows(self, df):
        if not isinstance(df, pd.DataFrame) or df.empty:
            return df.copy() if isinstance(df, pd.DataFrame) else df
        masks = getattr(self, "pixel_exclusion_masks", {})
        if not masks:
            return df.copy()

        work = df.copy()
        if "row_index" in work.columns and "column_index" in work.columns:
            rows = pd.to_numeric(work["row_index"], errors="coerce").to_numpy(dtype=float)
            cols = pd.to_numeric(work["column_index"], errors="coerce").to_numpy(dtype=float)
        elif "row_fractional" in work.columns and "column_fractional" in work.columns:
            rows = pd.to_numeric(work["row_fractional"], errors="coerce").to_numpy(dtype=float)
            cols = pd.to_numeric(work["column_fractional"], errors="coerce").to_numpy(dtype=float)
        elif "x" in work.columns and "y" in work.columns and len(work) <= 10000:
            rows = np.full(len(work), np.nan, dtype=float)
            cols = np.full(len(work), np.nan, dtype=float)
            for index, (x, y) in enumerate(zip(work["x"], work["y"])):
                try:
                    rows[index], cols[index] = self.data_xy_to_fractional_indices(float(x), float(y))
                except Exception:
                    pass
        else:
            return work

        valid_coordinates = np.isfinite(rows) & np.isfinite(cols)
        row_index = np.zeros(len(work), dtype=np.int64)
        col_index = np.zeros(len(work), dtype=np.int64)
        row_index[valid_coordinates] = np.rint(rows[valid_coordinates]).astype(np.int64)
        col_index[valid_coordinates] = np.rint(cols[valid_coordinates]).astype(np.int64)
        remove = np.zeros(len(work), dtype=bool)

        has_identity = all(name in work.columns for name in ("sample_id", "mineral_id", "run_id"))
        active_layer = None
        if not has_identity:
            try:
                active_layer = self._resolve_pixel_filter_layer()
            except Exception:
                for name in ("current_column", "current_layer"):
                    candidate = getattr(self, name, None)
                    if candidate in masks:
                        active_layer = candidate
                        break

        for layer, mask in masks.items():
            mask = np.asarray(mask, dtype=bool)
            use = valid_coordinates.copy()
            if has_identity:
                sample, mineral, run, _channel = _sample_layer_identity(
                    self.metas.get(layer, {}), layer
                )
                use &= work["sample_id"].astype(str).to_numpy() == str(sample)
                use &= work["mineral_id"].astype(str).to_numpy() == str(mineral)
                use &= work["run_id"].astype(str).to_numpy() == str(run)
            elif active_layer is not None:
                active_meta = self.metas.get(active_layer, {}) or {}
                layer_meta = self.metas.get(layer, {}) or {}
                if _sample_layer_identity(active_meta, active_layer)[:3] != _sample_layer_identity(
                    layer_meta, layer
                )[:3]:
                    continue
            inside = (
                use
                & (row_index >= 0)
                & (row_index < mask.shape[0])
                & (col_index >= 0)
                & (col_index < mask.shape[1])
            )
            if np.any(inside):
                idx = np.flatnonzero(inside)
                remove[idx] |= mask[row_index[idx], col_index[idx]]
        return work.loc[~remove].reset_index(drop=True)


