    # Mineral Analysis tab layout
    def build_mineral_stats_tab(self):
        left_outer = ttk.Frame(self.mineral_stats_tab, width=330)
        left_outer.pack(side=tk.LEFT, fill=tk.Y, padx=8, pady=8)
        left_outer.pack_propagate(False)
        self.mineral_stats_left_canvas = tk.Canvas(left_outer, width=320, highlightthickness=0)
        mineral_stats_scroll = ttk.Scrollbar(
            left_outer, orient=tk.VERTICAL, command=self.mineral_stats_left_canvas.yview
        )
        self.mineral_stats_left_canvas.configure(yscrollcommand=mineral_stats_scroll.set)
        mineral_stats_scroll.pack(side=tk.RIGHT, fill=tk.Y)
        self.mineral_stats_left_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
        left = ttk.Frame(self.mineral_stats_left_canvas)
        left_window = self.mineral_stats_left_canvas.create_window((0, 0), window=left, anchor="nw")

        # update the Mineral Analysis scroll region after a resize
        def _minstats_on_frame_configure(event):
            self.mineral_stats_left_canvas.configure(
                scrollregion=self.mineral_stats_left_canvas.bbox("all")
            )

        # match the Mineral Analysis inner frame to its canvas width.
        def _minstats_on_canvas_configure(event):
            self.mineral_stats_left_canvas.itemconfigure(left_window, width=event.width)

        # scroll the Mineral Analysis controls with the mouse wheel
        def _minstats_mousewheel(event):
            try:
                self.mineral_stats_left_canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            except Exception:
                pass

        left.bind("<Configure>", _minstats_on_frame_configure)
        self.mineral_stats_left_canvas.bind("<Configure>", _minstats_on_canvas_configure)
        self.mineral_stats_left_canvas.bind(
            "<Enter>",
            lambda event: self.mineral_stats_left_canvas.bind_all(
                "<MouseWheel>", _minstats_mousewheel
            ),
        )
        self.mineral_stats_left_canvas.bind(
            "<Leave>", lambda event: self.mineral_stats_left_canvas.unbind_all("<MouseWheel>")
        )
        right = self.make_scrollable_graph_frame(self.mineral_stats_tab, side=tk.RIGHT)
        try:
            self._add_log_axis_controls(left)
        except Exception:
            pass
