    # shared analysis table builders
    # These methods turn maps, minerals, boundaries, and grains into tidy tables.


    # build the boundary-buffer chemistry results table
    def build_boundary_buffer_chemistry_table(self):
        value_col = (
            self.mineral_stats_value_var.get() if hasattr(self, "mineral_stats_value_var") else ""
        )
        value_col = (
            self.canonical_layer_display_name(value_col)
            if hasattr(self, "canonical_layer_display_name")
            else str(value_col)
        )
        if not value_col:
            raise ValueError("Choose an element/value column first.")
        try:
            rule = self.mineral_stats_rule_var.get()
        except Exception:
            rule = "finite"
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        buffer_px = self.get_boundary_buffer_pixel_width()
        pairs = self.get_selected_nn_or_mineral_pairs(respect_pair_dropdown=True)
        if not pairs:
            raise ValueError("Select at least two mineral/domain groups or run an NN test first.")
        try:
            from scipy.spatial import cKDTree
        except Exception as exc:
            raise ValueError(f"Boundary-buffer chemistry requires scipy.spatial.cKDTree.\n\n{exc}")
        rows = []
        skipped = []
        for a_raw, b_raw in pairs:
            a = (
                self._resolve_mineral_group_name(a_raw)
                if hasattr(self, "_resolve_mineral_group_name")
                else str(a_raw)
            )
            b = (
                self._resolve_mineral_group_name(b_raw)
                if hasattr(self, "_resolve_mineral_group_name")
                else str(b_raw)
            )
            if not a or not b or a == b:
                skipped.append(f"{a_raw} ↔ {b_raw}: could not resolve pair")
                continue
            try:
                pa = self._phase_value_points_for_boundary(
                    a, value_col, rule=rule, threshold=threshold
                )
                pb = self._phase_value_points_for_boundary(
                    b, value_col, rule=rule, threshold=threshold
                )
            except Exception as exc:
                skipped.append(f"{a} ↔ {b}: {exc}")
                continue
            if pa["coords"].size == 0 or pb["coords"].size == 0:
                skipped.append(f"{a} ↔ {b}: one phase has no coordinate points")
                continue
            spacing = float(np.nanmax([pa.get("spacing", 1.0), pb.get("spacing", 1.0)]))
            if not np.isfinite(spacing) or spacing <= 0:
                spacing = 1.0
            buffer_distance = float(buffer_px * spacing)
            tree_b = cKDTree(pb["coords"])
            dist_a_to_b, _ = tree_b.query(pa["coords"], k=1)
            near_a_to_b = dist_a_to_b <= buffer_distance
            interior_a_vs_b = ~near_a_to_b
            tree_a = cKDTree(pa["coords"])
            dist_b_to_a, _ = tree_a.query(pb["coords"], k=1)
            near_b_to_a = dist_b_to_a <= buffer_distance
            interior_b_vs_a = ~near_b_to_a
            for phase_points, phase, other, near_mask, interior_mask, dists_to_other in [
                (pa, a, b, near_a_to_b, interior_a_vs_b, dist_a_to_b),
                (pb, b, a, near_b_to_a, interior_b_vs_a, dist_b_to_a),
            ]:
                vals = np.asarray(phase_points["values"], dtype=float)
                near_vals = vals[near_mask]
                interior_vals = vals[interior_mask]
                near_stats = self._boundary_stats_from_values(near_vals)
                int_stats = self._boundary_stats_from_values(interior_vals)
                for zone_name, stats in [("near_boundary", near_stats), ("interior", int_stats)]:
                    rows.append(
                        {
                            "pair": f"{a} ↔ {b}",
                            "phase": phase,
                            "other_phase": other,
                            "zone": zone_name,
                            "buffer_pixels": buffer_px,
                            "buffer_coordinate_distance": buffer_distance,
                            "estimated_pixel_spacing": spacing,
                            "value_col": value_col,
                            "value_layer": phase_points.get("layer", ""),
                            **{f"{k}_value": v for k, v in stats.items()},
                        }
                    )
                ratio = np.nan
                diff = np.nan
                percent_diff = np.nan
                if np.isfinite(near_stats["mean"]) and np.isfinite(int_stats["mean"]):
                    diff = near_stats["mean"] - int_stats["mean"]
                    if int_stats["mean"] != 0:
                        ratio = near_stats["mean"] / int_stats["mean"]
                        percent_diff = 100.0 * (ratio - 1.0)
                rows.append(
                    {
                        "pair": f"{a} ↔ {b}",
                        "phase": phase,
                        "other_phase": other,
                        "zone": "near_vs_interior",
                        "buffer_pixels": buffer_px,
                        "buffer_coordinate_distance": buffer_distance,
                        "estimated_pixel_spacing": spacing,
                        "value_col": value_col,
                        "value_layer": phase_points.get("layer", ""),
                        "n_pixels_value": near_stats["n_pixels"],
                        "mean_value": near_stats["mean"],
                        "interior_n_pixels_value": int_stats["n_pixels"],
                        "interior_mean_value": int_stats["mean"],
                        "near_minus_interior_mean": diff,
                        "near_div_interior_mean": ratio,
                        "near_percent_difference_from_interior": percent_diff,
                        "median_value": near_stats["median"],
                        "interior_median_value": int_stats["median"],
                        "sd_value": near_stats["sd"],
                        "interior_sd_value": int_stats["sd"],
                        "cv_percent_value": near_stats["cv_percent"],
                        "interior_cv_percent_value": int_stats["cv_percent"],
                        "sum_value": near_stats["sum"],
                        "interior_sum_value": int_stats["sum"],
                        "p05_value": near_stats["p05"],
                        "p25_value": near_stats["p25"],
                        "p75_value": near_stats["p75"],
                        "p95_value": near_stats["p95"],
                        "mean_distance_to_other_phase": (
                            float(np.nanmean(dists_to_other)) if np.size(dists_to_other) else np.nan
                        ),
                        "median_distance_to_other_phase": (
                            float(np.nanmedian(dists_to_other))
                            if np.size(dists_to_other)
                            else np.nan
                        ),
                    }
                )
        if not rows:
            msg = "No boundary-buffer chemistry rows could be calculated.\n\nThis usually means either:\n1) the selected pair name did not match loaded mineral groups,\n2) the chosen element/calculated column is not present in both phases, or\n3) one phase has no valid pixels after the mask rule.\n\nThis version no longer requires the two phases to be on the same array grid.\n\n"
            if skipped:
                msg += "Skipped:\n" + "\n".join(skipped[:12])
            raise ValueError(msg)
        self.last_boundary_buffer_skipped = skipped
        return pd.DataFrame(rows)


    # build the shared coordinate pixel table
    def build_shared_coordinate_pixel_table(self):
        if not getattr(self, "values", None):
            raise ValueError("No maps are loaded.")
        layers = list(self.values.keys())
        if len(layers) < 2:
            raise ValueError("Need at least two loaded layers for shared X/Y comparison.")
        groups = {}
        for layer in layers:
            try:
                meta = self.metas.get(layer, {})
                coord_key = str(
                    meta.get("coordinate_group_key", "")
                    or self._normalize_coord_group_key_for_shared_plane(
                        meta.get("import_group_key", layer)
                    )
                )
                if not coord_key:
                    coord_key = "shared_area"
                groups.setdefault(coord_key, []).append(layer)
            except Exception:
                groups.setdefault("shared_area", []).append(layer)
        base_key, base_layers = max(groups.items(), key=lambda kv: len(kv[1]))
        extents = {}
        for layer in layers:
            try:
                extents[layer] = self._shared_layer_extent(layer)
            except Exception:
                pass
        base_candidates = [l for l in base_layers if l in extents]
        if not base_candidates:
            base_candidates = [l for l in layers if l in extents]
        if not base_candidates:
            raise ValueError("Could not find valid X/Y axes for any loaded layer.")
        base_layer = max(base_candidates, key=lambda l: np.asarray(self.values[l]).size)
        base_extent = extents[base_layer]
        selected_layers = []
        skipped_layers = []
        for layer in layers:
            try:
                if layer not in extents:
                    skipped_layers.append((layer, "no valid extent"))
                    continue
                same_key = layer in base_layers
                overlaps = self._shared_extents_overlap(
                    base_extent, extents[layer], min_fraction=0.05
                )
                if same_key or overlaps:
                    selected_layers.append(layer)
                else:
                    skipped_layers.append((layer, "different/non-overlapping X/Y area"))
            except Exception as exc:
                skipped_layers.append((layer, str(exc)))
        if len(selected_layers) < 2:
            raise ValueError(
                "Only one compatible layer was found. The loaded maps may not share/overlap the same X/Y area."
            )
        base_x, base_y = self._layer_xy_axes_for_shared_sampling(base_layer)
        nr = base_y.size
        nc = base_x.size
        rr, cc = np.indices((nr, nc))
        out = pd.DataFrame(
            {
                "row_index": rr.ravel().astype(int),
                "column_index": cc.ravel().astype(int),
                "x": base_x[cc.ravel()],
                "y": base_y[rr.ravel()],
                "coordinate_group_key": base_key,
                "base_grid_layer": str(base_layer),
            }
        )
        used = set(out.columns)
        sampled_summary = []
        for layer in selected_layers:
            try:
                meta = self.metas.get(layer, {})
                mineral = str(meta.get("mineral_type", "Map")).strip() or "Map"
                chan = str(
                    meta.get("canonical_column", meta.get("source_layer_name", layer))
                ).strip() or str(layer)
                col = f"{mineral}_{chan}"
                base_col = col
                i = 2
                while col in used:
                    col = f"{base_col}_{i}"
                    i += 1
                used.add(col)
                sampled = self._sample_layer_to_reference_grid(layer, base_x, base_y)
                out[col] = sampled
                valid_n = int(np.isfinite(sampled).sum())
                sampled_summary.append(
                    {
                        "layer": layer,
                        "output_column": col,
                        "mineral_type": mineral,
                        "channel": chan,
                        "source_shape": str(np.asarray(self.values[layer]).shape),
                        "base_shape": str((nr, nc)),
                        "finite_pixels_after_sampling": valid_n,
                        "fraction_finite_after_sampling": valid_n / max(len(sampled), 1),
                        "sampling_mode": (
                            "direct"
                            if np.asarray(self.values[layer]).shape == (nr, nc)
                            else "nearest_xy"
                        ),
                    }
                )
            except Exception as exc:
                skipped_layers.append((layer, f"sampling failed: {exc}"))
        data_cols = [
            c
            for c in out.columns
            if c
            not in [
                "row_index",
                "column_index",
                "x",
                "y",
                "coordinate_group_key",
                "base_grid_layer",
            ]
        ]
        if data_cols:
            all_nan = out[data_cols].isna().all(axis=1)
            out = out.loc[~all_nan].reset_index(drop=True)
        self.shared_coordinate_pixel_df = out.copy()
        self.shared_coordinate_sampling_summary_df = pd.DataFrame(sampled_summary)
        self.shared_coordinate_skipped_layers = skipped_layers
        self.analysis_df = out.copy()
        self.current_analysis_df = out.copy()
        self.active_analysis_df = out.copy()
        self.selected_pixels_df = out.copy()
        self.last_analysis_df = out.copy()
        self.analysis_source_label = f"Aligned map pixels: {base_key}"
        try:
            self.activate_analysis_table(out, self.analysis_source_label, mirror_to_comparison=True)
        except Exception:
            pass
        for name in [
            "refresh_analysis_columns",
            "refresh_xy_columns",
            "refresh_kde_controls",
            "refresh_kde_columns",
            "refresh_ternary_columns",
            "refresh_ternary_controls",
            "refresh_pca_columns",
            "refresh_correlation_columns",
            "refresh_compare_grain_controls",
        ]:
            try:
                if hasattr(self, name):
                    getattr(self, name)()
            except Exception:
                pass
        try:
            msg = f"Using shared/overlapping X/Y pixel table: {len(out):,} pixels, {len(data_cols)} data columns from {len(selected_layers)} layers. Base grid: {base_layer}."
            if skipped_layers:
                msg += f" Skipped {len(skipped_layers)} non-overlapping/failed layers."
            self.status_var.set(msg)
        except Exception:
            pass
        try:
            self._activate_shared_xy_as_drawable_map(out)
        except Exception:
            pass
        return out


    # build the boundary-buffer ratio results table
    def build_boundary_buffer_ratio_table(self):
        value_col = (
            self.mineral_stats_value_var.get() if hasattr(self, "mineral_stats_value_var") else ""
        )
        value_col = (
            self.canonical_layer_display_name(value_col)
            if hasattr(self, "canonical_layer_display_name")
            else str(value_col)
        )
        if not value_col:
            raise ValueError("Choose an element/value column first.")
        try:
            rule = self.mineral_stats_rule_var.get()
        except Exception:
            rule = "finite"
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        buffer_px = self.get_boundary_buffer_pixel_width()
        pairs = self.get_selected_nn_or_mineral_pairs(respect_pair_dropdown=True)
        if not pairs:
            raise ValueError("Select at least two mineral/domain groups or run an NN test first.")
        try:
            from scipy.spatial import cKDTree
        except Exception as exc:
            raise ValueError(f"Buffer ratio analysis requires scipy.spatial.cKDTree.\n\n{exc}")
        summary_rows = []
        pair_rows = []
        skipped = []

        # rows where the required U-Pb ratios are all present
        def _matched_ratio_rows(
            p_num, p_den, num_name, den_name, pair_label, buffer_distance, spacing
        ):
            coords_num = np.asarray(p_num["coords"], dtype=float)
            vals_num = np.asarray(p_num["values"], dtype=float)
            coords_den = np.asarray(p_den["coords"], dtype=float)
            vals_den = np.asarray(p_den["values"], dtype=float)
            ok_num = np.isfinite(coords_num).all(axis=1) & np.isfinite(vals_num)
            ok_den = np.isfinite(coords_den).all(axis=1) & np.isfinite(vals_den)
            coords_num = coords_num[ok_num]
            vals_num = vals_num[ok_num]
            coords_den = coords_den[ok_den]
            vals_den = vals_den[ok_den]
            if len(coords_num) == 0 or len(coords_den) == 0:
                return ([], None)
            tree_den = cKDTree(coords_den)
            dists, idx = tree_den.query(coords_num, k=1)
            dists = np.asarray(dists, dtype=float)
            idx = np.asarray(idx, dtype=int)
            near = np.isfinite(dists) & (dists <= buffer_distance)
            if not np.any(near):
                return (
                    [],
                    {
                        "pair": pair_label,
                        "ratio_direction": f"{num_name} / {den_name}",
                        "numerator_phase": num_name,
                        "denominator_phase": den_name,
                        "value_col": value_col,
                        "buffer_pixels": buffer_px,
                        "buffer_coordinate_distance": buffer_distance,
                        "estimated_pixel_spacing": spacing,
                        "n_ratio_pairs": 0,
                        "mean_ratio": np.nan,
                        "median_ratio": np.nan,
                        "sd_ratio": np.nan,
                        "se_ratio": np.nan,
                        "p05_ratio": np.nan,
                        "p25_ratio": np.nan,
                        "p75_ratio": np.nan,
                        "p95_ratio": np.nan,
                        "mean_log10_ratio": np.nan,
                        "median_log10_ratio": np.nan,
                    },
                )
            near_idx_num = np.where(near)[0]
            nearest_den_idx = idx[near_idx_num]
            numerator = vals_num[near_idx_num]
            denominator = vals_den[nearest_den_idx]
            dist_vals = dists[near_idx_num]
            valid_ratio = np.isfinite(numerator) & np.isfinite(denominator) & (denominator != 0)
            near_idx_num = near_idx_num[valid_ratio]
            nearest_den_idx = nearest_den_idx[valid_ratio]
            numerator = numerator[valid_ratio]
            denominator = denominator[valid_ratio]
            dist_vals = dist_vals[valid_ratio]
            ratios = numerator / denominator
            good = np.isfinite(ratios)
            near_idx_num = near_idx_num[good]
            nearest_den_idx = nearest_den_idx[good]
            numerator = numerator[good]
            denominator = denominator[good]
            dist_vals = dist_vals[good]
            ratios = ratios[good]
            rows = []
            for i, j, nv, dv, rv, dd in zip(
                near_idx_num, nearest_den_idx, numerator, denominator, ratios, dist_vals
            ):
                rows.append(
                    {
                        "pair": pair_label,
                        "ratio_direction": f"{num_name} / {den_name}",
                        "numerator_phase": num_name,
                        "denominator_phase": den_name,
                        "value_col": value_col,
                        "buffer_pixels": buffer_px,
                        "buffer_coordinate_distance": buffer_distance,
                        "estimated_pixel_spacing": spacing,
                        "numerator_x": float(coords_num[i, 0]),
                        "numerator_y": float(coords_num[i, 1]),
                        "denominator_x": float(coords_den[j, 0]),
                        "denominator_y": float(coords_den[j, 1]),
                        "nearest_distance": float(dd),
                        "numerator_value": float(nv),
                        "denominator_value": float(dv),
                        "ratio": float(rv),
                        "log10_ratio": (
                            float(np.log10(rv)) if rv > 0 and np.isfinite(rv) else np.nan
                        ),
                    }
                )
            r = np.asarray(ratios, dtype=float)
            r = r[np.isfinite(r)]
            log_r = np.log10(r[(r > 0) & np.isfinite(r)])
            if r.size == 0:
                summary = {
                    "pair": pair_label,
                    "ratio_direction": f"{num_name} / {den_name}",
                    "numerator_phase": num_name,
                    "denominator_phase": den_name,
                    "value_col": value_col,
                    "buffer_pixels": buffer_px,
                    "buffer_coordinate_distance": buffer_distance,
                    "estimated_pixel_spacing": spacing,
                    "n_ratio_pairs": 0,
                    "mean_ratio": np.nan,
                    "median_ratio": np.nan,
                    "sd_ratio": np.nan,
                    "se_ratio": np.nan,
                    "p05_ratio": np.nan,
                    "p25_ratio": np.nan,
                    "p75_ratio": np.nan,
                    "p95_ratio": np.nan,
                    "mean_log10_ratio": np.nan,
                    "median_log10_ratio": np.nan,
                }
            else:
                sd = float(np.nanstd(r, ddof=1)) if r.size > 1 else np.nan
                summary = {
                    "pair": pair_label,
                    "ratio_direction": f"{num_name} / {den_name}",
                    "numerator_phase": num_name,
                    "denominator_phase": den_name,
                    "value_col": value_col,
                    "buffer_pixels": buffer_px,
                    "buffer_coordinate_distance": buffer_distance,
                    "estimated_pixel_spacing": spacing,
                    "n_ratio_pairs": int(r.size),
                    "mean_ratio": float(np.nanmean(r)),
                    "median_ratio": float(np.nanmedian(r)),
                    "sd_ratio": sd,
                    "se_ratio": (
                        float(sd / np.sqrt(r.size)) if r.size > 1 and np.isfinite(sd) else np.nan
                    ),
                    "p05_ratio": float(np.nanpercentile(r, 5)),
                    "p25_ratio": float(np.nanpercentile(r, 25)),
                    "p75_ratio": float(np.nanpercentile(r, 75)),
                    "p95_ratio": float(np.nanpercentile(r, 95)),
                    "mean_log10_ratio": float(np.nanmean(log_r)) if log_r.size else np.nan,
                    "median_log10_ratio": float(np.nanmedian(log_r)) if log_r.size else np.nan,
                }
            return (rows, summary)

        for a_raw, b_raw in pairs:
            a = (
                self._resolve_mineral_group_name(a_raw)
                if hasattr(self, "_resolve_mineral_group_name")
                else str(a_raw)
            )
            b = (
                self._resolve_mineral_group_name(b_raw)
                if hasattr(self, "_resolve_mineral_group_name")
                else str(b_raw)
            )
            if not a or not b or a == b:
                skipped.append(f"{a_raw} ↔ {b_raw}: could not resolve pair")
                continue
            pair_label = f"{a} ↔ {b}"
            try:
                pa = self._phase_value_points_for_boundary(
                    a, value_col, rule=rule, threshold=threshold
                )
                pb = self._phase_value_points_for_boundary(
                    b, value_col, rule=rule, threshold=threshold
                )
            except Exception as exc:
                skipped.append(f"{pair_label}: {exc}")
                continue
            spacing = float(np.nanmax([pa.get("spacing", 1.0), pb.get("spacing", 1.0)]))
            if not np.isfinite(spacing) or spacing <= 0:
                spacing = 1.0
            buffer_distance = float(buffer_px * spacing)
            for p_num, p_den, num_name, den_name in [(pa, pb, a, b), (pb, pa, b, a)]:
                try:
                    rows, summary = _matched_ratio_rows(
                        p_num, p_den, num_name, den_name, pair_label, buffer_distance, spacing
                    )
                    pair_rows.extend(rows)
                    if summary is not None:
                        summary_rows.append(summary)
                except Exception as exc:
                    skipped.append(f"{num_name} / {den_name}: {exc}")
        if not summary_rows:
            msg = "No buffer concentration ratios could be calculated.\n\nThis usually means the selected element is not present in both phases, the selected pair has no pixels within the buffer distance, or denominator values are zero/non-finite."
            if skipped:
                msg += "\n\nSkipped:\n" + "\n".join(skipped[:12])
            raise ValueError(msg)
        summary_df = pd.DataFrame(summary_rows)
        pair_df = pd.DataFrame(pair_rows)
        try:
            if not summary_df.empty:
                summary_df["mean_Kd"] = summary_df["mean_ratio"]
                summary_df["median_Kd"] = summary_df["median_ratio"]
                summary_df["sd_Kd"] = summary_df["sd_ratio"]
                summary_df["se_Kd"] = summary_df["se_ratio"]
            if not pair_df.empty:
                pair_df["Kd"] = pair_df["ratio"]
                pair_df["log10_Kd"] = pair_df["log10_ratio"]
        except Exception:
            pass
        self.last_boundary_buffer_ratio_df = summary_df.copy()
        self.last_boundary_buffer_ratio_pairs_df = pair_df.copy()
        self.last_boundary_buffer_ratio_skipped = skipped
        return (summary_df, pair_df)


    # build comparison table from loaded mineral maps if needed
    def build_comparison_df_from_loaded_mineral_maps_if_needed(self):
        if getattr(self, "comparison_df", None) is not None and (not self.comparison_df.empty):
            return
        if hasattr(self, "mineral_comparison_dataframe_from_loaded_maps"):
            try:
                self.comparison_df = self.mineral_comparison_dataframe_from_loaded_maps()
            except Exception:
                return


    # rebuild column index for mineral analysis
    def rebuild_mineral_column_index(self):
        try:
            self.rebuild_mineral_presence_groups_from_metadata()
        except Exception:
            pass
        index = {}
        for group_key, rec in (getattr(self, "mineral_presence_groups", {}) or {}).items():
            index.setdefault(str(group_key), {})
            for layer in rec.get("layers", []):
                if layer not in getattr(self, "values", {}):
                    continue
                meta_canon = self.metas.get(layer, {}).get("canonical_column")
                clean = self.canonical_element_column_name(meta_canon if meta_canon else layer)
                if clean not in index[str(group_key)]:
                    index[str(group_key)][clean] = layer
        self.mineral_column_index = index
        return index


    # build canonical mineral comparison dataframe
    def build_canonical_mineral_comparison_dataframe(self):
        index = self.rebuild_mineral_column_index()
        rows = []
        hidden = getattr(self, "hidden_mineral_groups", set())
        for group_key, col_map in index.items():
            if str(group_key) in hidden:
                continue
            rec = getattr(self, "mineral_presence_groups", {}).get(group_key, {})
            map_group = str(rec.get("map_group") or "Map")
            mineral_name = str(rec.get("mineral_type") or group_key)
            if not col_map:
                continue
            base_layer = rec.get("representative_layer") or next(iter(col_map.values()), None)
            if base_layer not in getattr(self, "values", {}):
                base_layer = next(iter(col_map.values()), None)
            if base_layer not in getattr(self, "values", {}):
                continue
            extent, x, y, zbase = self._layer_extent_from_meta(base_layer)
            zbase = np.asarray(zbase, dtype=float)
            xx, yy = np.meshgrid(np.asarray(x, dtype=float), np.asarray(y, dtype=float))
            row_grid, col_grid = np.indices(zbase.shape)
            data = {
                "map_group": np.repeat(map_group, zbase.size),
                "comparison_dataset": np.repeat(map_group, zbase.size),
                "mineral_type": np.repeat(mineral_name, zbase.size),
                "mineral_group": np.repeat(group_key, zbase.size),
                "plot_group": np.repeat(group_key, zbase.size),
                "row_index": row_grid.ravel().astype(int),
                "column_index": col_grid.ravel().astype(int),
                "x": xx.ravel(),
                "y": yy.ravel(),
            }
            any_valid = np.zeros(zbase.shape, dtype=bool)
            for canon_col, layer in col_map.items():
                try:
                    _, x2, y2, z = self._layer_extent_from_meta(layer)
                    z = np.asarray(z, dtype=float)
                    if z.shape != zbase.shape:
                        continue
                    data[canon_col] = z.ravel()
                    any_valid |= np.isfinite(z)
                except Exception:
                    continue
            df = pd.DataFrame(data)
            df = df.loc[any_valid.ravel()].copy()
            if not df.empty:
                df["present"] = 1
                rows.append(df)
        if not rows:
            raise ValueError("Could not build canonical mineral comparison table.")
        return pd.concat(rows, ignore_index=True, sort=False)


    # build the stacked mineral fraction table
    def build_stacked_mineral_fraction_table(self):
        variables = self._selected_mineral_fraction_variables()
        if not variables:
            raise ValueError("Choose at least one variable/element for stacked fraction bars.")
        selected_groups = (
            self._selected_mineral_stat_groups()
            if hasattr(self, "_selected_mineral_stat_groups")
            else []
        )
        if not selected_groups:
            raise ValueError("Select at least one mineral/domain group.")
        try:
            pie_mode = self.mineral_stats_pie_mode_var.get()
        except Exception:
            pie_mode = "sum"
        rows = []
        skipped = []
        for variable in variables:
            try:
                records = self._records_for_one_fraction_variable(variable)
            except Exception as exc:
                skipped.append(f"{variable}: {exc}")
                continue
            rec_by_group = {r["group"]: r for r in records}
            ordered_records = [rec_by_group[g] for g in selected_groups if g in rec_by_group]
            if not ordered_records:
                skipped.append(f"{variable}: no selected groups contain valid values")
                continue
            vals = []
            for r in ordered_records:
                if "area" in str(pie_mode).lower():
                    v = r.get("n_pixels", np.nan)
                    value_type = "finite_pixel_area"
                elif "mean" in str(pie_mode).lower():
                    v = r.get("mean_value", np.nan)
                    value_type = "mean_value"
                else:
                    v = r.get("sum_value", np.nan)
                    value_type = "selected_column_sum"
                try:
                    vals.append(float(v))
                except Exception:
                    vals.append(np.nan)
            vals = np.asarray(vals, dtype=float)
            good = np.isfinite(vals) & (vals > 0)
            total = float(np.nansum(vals[good]))
            if total <= 0:
                skipped.append(f"{variable}: total is zero/invalid")
                continue
            for r, v, ok in zip(ordered_records, vals, good):
                raw = float(v) if ok else 0.0
                rows.append(
                    {
                        "variable": variable,
                        "mineral_type": r["group"],
                        "value_type": value_type,
                        "raw_value": raw,
                        "total_selected_value": total,
                        "fraction": raw / total if total else np.nan,
                        "percent": 100.0 * raw / total if total else np.nan,
                        "n_pixels": r.get("n_pixels", np.nan),
                        "sum_value": r.get("sum_value", np.nan),
                        "mean_value": r.get("mean_value", np.nan),
                        "median_value": r.get("median_value", np.nan),
                        "sd_value": r.get("sd_value", np.nan),
                    }
                )
        if not rows:
            msg = "No stacked fraction rows were made."
            if skipped:
                msg += "\n\nSkipped:\n" + "\n".join(skipped[:15])
            raise ValueError(msg)
        long_df = pd.DataFrame(rows)
        wide = long_df.pivot_table(
            index="variable",
            columns="mineral_type",
            values="percent",
            aggfunc="sum",
            fill_value=0.0,
        ).reset_index()
        self.last_stacked_mineral_fraction_long_df = long_df.copy()
        self.last_stacked_mineral_fraction_wide_df = wide.copy()
        self.last_stacked_mineral_fraction_skipped = skipped
        return (long_df, wide)


    # build the summary analysis table
    def build_grain_summary_analysis_table(self):
        label_mask = self._grain_label_mask_safe()
        base_df = self._grain_metric_frame().copy()
        stat_columns = {}
        grain_ids = pd.to_numeric(base_df["grain_id"], errors="coerce").astype("Int64")
        for layer in self._compatible_layers_for_grain_tables(label_mask):
            arr = np.asarray(self.values[layer], dtype=float)
            base = str(layer).split(" :: ", 1)[-1]
            mean_col = f"{base}_mean"
            std_col = f"{base}_std"
            twosd_col = f"{base}_2sd"
            n_col = f"{base}_n"
            if mean_col in base_df.columns or mean_col in stat_columns:
                base = str(layer)
                mean_col = f"{base}_mean"
                std_col = f"{base}_std"
                twosd_col = f"{base}_2sd"
                n_col = f"{base}_n"
            means, stds, twosds, ns = ([], [], [], [])
            for gid in grain_ids:
                if pd.isna(gid):
                    vals = np.array([], dtype=float)
                else:
                    vals = arr[label_mask == int(gid)]
                    vals = vals[np.isfinite(vals)]
                n = int(vals.size)
                if n:
                    mean = float(np.nanmean(vals))
                    std = float(np.nanstd(vals, ddof=1)) if n > 1 else np.nan
                    twosd = float(2.0 * std) if np.isfinite(std) else np.nan
                else:
                    mean = std = twosd = np.nan
                means.append(mean)
                stds.append(std)
                twosds.append(twosd)
                ns.append(n)
            stat_columns[mean_col] = means
            stat_columns[std_col] = stds
            stat_columns[twosd_col] = twosds
            stat_columns[n_col] = ns
        meta_columns = {
            "analysis_level": ["grain_mean"] * len(base_df),
            "source_kind": ["grain_means"] * len(base_df),
            "grain_rows_source": ["unique_label_mask_ids"] * len(base_df),
        }
        add_df = pd.DataFrame({**stat_columns, **meta_columns}, index=base_df.index)
        out = pd.concat([base_df, add_df], axis=1).copy()
        return self._dedupe_cols_keep_first(out)


    # build the pixel analysis table
    def build_grain_pixel_analysis_table(self):
        label_mask = self._grain_label_mask_safe()
        rr, cc = np.where(label_mask > 0)
        if rr.size == 0:
            raise ValueError("No labeled grain pixels are available.")
        x_axis, y_axis = self._grain_xy_axes_safe(label_mask)
        total = self._grain_total_count()
        mineral = self._grain_run_mineral_name()
        base_df = pd.DataFrame(
            {
                "grain_id": label_mask[rr, cc].astype(int),
                "mineral_type": mineral,
                "map_group": mineral,
                "total_grains_identified": total,
                "row_index": rr.astype(int),
                "column_index": cc.astype(int),
                "x": x_axis[cc],
                "y": y_axis[rr],
                "analysis_level": "grain_pixel",
                "source_kind": "grain_pixels",
                "grain_rows_source": "unique_label_mask_ids",
            }
        )
        used = set(base_df.columns)
        element_columns = {}
        for layer in self._compatible_layers_for_grain_tables(label_mask):
            arr = np.asarray(self.values[layer], dtype=float)
            col = self._table_column_name(layer, used)
            element_columns[col] = arr[rr, cc]
        if element_columns:
            out = pd.concat(
                [base_df, pd.DataFrame(element_columns, index=base_df.index)], axis=1
            ).copy()
        else:
            out = base_df.copy()
        try:
            metrics = self._grain_metric_frame().drop_duplicates("grain_id")
            out = out.merge(
                metrics,
                on=["grain_id", "mineral_type", "map_group", "total_grains_identified"],
                how="left",
                suffixes=("", "_grain"),
            ).copy()
        except Exception:
            pass
        return self._dedupe_cols_keep_first(out)


