    # score used to choose the best mineral-presence layer
    def _presence_layer_score(self, layer_name, meta=None):
        name = str(layer_name).split(" :: ", 1)[-1]
        clean = (
            self.canonical_element_column_name(name)
            if hasattr(self, "canonical_element_column_name")
            else name
        )
        low = clean.lower()
        score = 0.0
        bad_terms = [
            "anom",
            "age",
            "ratio",
            "discord",
            "concord",
            "err",
            "error",
            "uncert",
            "unc",
            "sigma",
            "rse",
            "rsd",
        ]
        if any((term in low for term in bad_terms)):
            score -= 1000.0
        if "total" in low:
            score += 300.0
        if "nomb" in low or low.endswith("_ppm") or low.endswith(" ppm"):
            score += 120.0
        preferred_exact = [
            "PbTotal_ppm",
            "Zr90_ppm",
            "Zr91_ppm",
            "Zr92_ppm",
            "Hf178_ppm",
            "Hf179_ppm",
            "Ce140_ppm",
            "GdTotal_nomb_ppm",
            "Ca44_ppm",
            "P31",
            "P31_ppm",
        ]
        if clean in preferred_exact:
            score += 500.0
        try:
            arr = np.asarray(self.values[layer_name], dtype=float)
            finite = int(np.isfinite(arr).sum())
            positive = int((np.isfinite(arr) & (arr > 0)).sum())
            score += min(finite / 1000.0, 250.0)
            score += min(positive / 1000.0, 250.0)
        except Exception:
            pass
        return score


    # rebuild presence groups from metadata for mineral analysis
    def rebuild_mineral_presence_groups_from_metadata(self):
        try:
            self._refresh_matrix_group_names()
        except Exception:
            pass
        groups = {}
        for layer_name, meta in getattr(self, "metas", {}).items():
            if layer_name not in getattr(self, "values", {}):
                continue
            if not isinstance(meta, dict):
                meta = {}
            mineral = str(
                meta.get("mineral_type")
                or getattr(self, "layer_mineral_type", {}).get(layer_name)
                or ""
            ).strip()
            if not mineral:
                continue
            map_group = str(meta.get("map_group") or meta.get("comparison_dataset") or "").strip()
            if not map_group:
                map_group = self._map_group_from_import_record(
                    meta.get("import_group_key", ""),
                    meta.get("path", ""),
                    meta.get("source_layer_name", ""),
                )
                try:
                    meta["map_group"] = map_group
                    meta["comparison_dataset"] = map_group
                except Exception:
                    pass
            group_key = self._mineral_group_key_from_meta(layer_name, meta)
            rec = groups.setdefault(
                group_key,
                {
                    "layers": [],
                    "representative_layer": layer_name,
                    "map_group": map_group,
                    "mineral_type": mineral,
                    "mineral_group": group_key,
                    "display_name": group_key,
                },
            )
            rec["layers"].append(layer_name)
        for group_key, rec in groups.items():
            layers = rec.get("layers", [])
            if not layers:
                continue
            scored = sorted(
                layers,
                key=lambda lyr: self._presence_layer_score(lyr, self.metas.get(lyr, {})),
                reverse=True,
            )
            rec["representative_layer"] = scored[0]
            rec["representative_score"] = float(
                self._presence_layer_score(scored[0], self.metas.get(scored[0], {}))
            )
        self.mineral_presence_groups = groups
        try:
            self.refresh_map_group_filter_choices()
        except Exception:
            pass
        return groups


    # build the presence pixel table
    def build_mineral_presence_pixel_table(self, selected_minerals=None, value_columns=None):
        index = self.rebuild_mineral_column_index()
        if not index:
            raise ValueError("No mineral/map groups are available. Load map files first.")
        if selected_minerals is None:
            selected_minerals = self.get_available_mineral_names_for_map_view()
        hidden = getattr(self, "hidden_mineral_groups", set())
        selected_minerals = [m for m in selected_minerals if m in index and str(m) not in hidden]
        if value_columns is None:
            value_columns = self.get_all_canonical_mineral_columns(
                require_shared=False, selected_groups=selected_minerals
            )
        value_columns = [
            self.canonical_element_column_name(c) for c in value_columns if str(c) != "presence"
        ]
        rows = []
        rule = "finite"
        threshold = 0.0
        try:
            rule = getattr(self, "mineral_overlay_rule_var", tk.StringVar(value="finite")).get()
            threshold = float(
                getattr(self, "mineral_overlay_threshold_var", tk.StringVar(value="0")).get()
            )
        except Exception:
            pass
        for group_key in selected_minerals:
            rec = getattr(self, "mineral_presence_groups", {}).get(group_key, {})
            map_group = str(rec.get("map_group") or "Map")
            mineral_name = str(rec.get("mineral_type") or group_key)
            col_map = index.get(group_key, {})
            if not col_map:
                continue
            rep_layer = rec.get("representative_layer") or next(iter(col_map.values()), None)
            if rep_layer not in getattr(self, "values", {}):
                rep_layer = next(iter(col_map.values()), None)
            if rep_layer not in getattr(self, "values", {}):
                continue
            extent, x, y, zrep = self._layer_extent_from_meta(rep_layer)
            zrep = np.asarray(zrep, dtype=float)
            mask = np.isfinite(zrep)
            if rule == ">0":
                mask &= zrep > 0
            elif rule == ">custom":
                mask &= zrep > threshold
            if not np.any(mask):
                continue
            xx, yy = np.meshgrid(np.asarray(x, dtype=float), np.asarray(y, dtype=float))
            row_grid, col_grid = np.indices(zrep.shape)
            n = int(np.count_nonzero(mask))
            data = {
                "map_group": np.repeat(map_group, n),
                "comparison_dataset": np.repeat(map_group, n),
                "mineral_type": np.repeat(mineral_name, n),
                "mineral_group": np.repeat(group_key, n),
                "plot_group": np.repeat(group_key, n),
                "row_index": row_grid[mask].ravel().astype(int),
                "column_index": col_grid[mask].ravel().astype(int),
                "x": xx[mask].ravel(),
                "y": yy[mask].ravel(),
                "present": np.repeat(True, n),
            }
            for col in value_columns:
                layer = col_map.get(col)
                if layer not in getattr(self, "values", {}):
                    continue
                z = np.asarray(self.values[layer], dtype=float)
                if z.shape != zrep.shape:
                    continue
                data[col] = z[mask].ravel()
            rows.append(pd.DataFrame(data))
        if not rows:
            raise ValueError(
                "No mineral pixels were available under the current map/mineral selection and mask rule."
            )
        return pd.concat(rows, ignore_index=True, sort=False)


    # build the presence mean table
    def build_mineral_presence_mean_table(self, selected_minerals=None, value_columns=None):
        pix = self.build_mineral_presence_pixel_table(
            selected_minerals=selected_minerals, value_columns=value_columns
        )
        rows = []
        numeric_cols = [
            c
            for c in pix.columns
            if c not in ("x", "y", "present") and pd.api.types.is_numeric_dtype(pix[c])
        ]
        group_cols = [c for c in ["map_group", "mineral_type", "mineral_group"] if c in pix.columns]
        if not group_cols:
            group_cols = ["mineral_type"]
        for keys, sub in pix.groupby(group_cols, dropna=False):
            if not isinstance(keys, tuple):
                keys = (keys,)
            rec = {col: val for col, val in zip(group_cols, keys)}
            if "map_group" not in rec:
                rec["map_group"] = rec.get("comparison_dataset", "Map")
            if "comparison_dataset" not in rec:
                rec["comparison_dataset"] = rec.get("map_group", "Map")
            rec["analysis_type"] = "mineral_mean"
            rec["n_pixels"] = int(len(sub))
            if "x" in sub:
                rec["x_mean"] = float(pd.to_numeric(sub["x"], errors="coerce").mean())
            if "y" in sub:
                rec["y_mean"] = float(pd.to_numeric(sub["y"], errors="coerce").mean())
            for col in numeric_cols:
                vals = pd.to_numeric(sub[col], errors="coerce").dropna().to_numpy(dtype=float)
                if vals.size == 0:
                    continue
                rec[col] = float(np.nanmean(vals))
                rec[f"{col}__sd"] = float(np.nanstd(vals, ddof=1)) if vals.size > 1 else np.nan
                rec[f"{col}__se"] = (
                    float(np.nanstd(vals, ddof=1) / np.sqrt(vals.size)) if vals.size > 1 else np.nan
                )
                rec[f"{col}__cv"] = (
                    float(np.nanstd(vals, ddof=1) / np.nanmean(vals))
                    if vals.size > 1 and np.nanmean(vals) != 0
                    else np.nan
                )
                rec[f"{col}__sum"] = float(np.nansum(vals))
                rec[f"{col}__n"] = int(vals.size)
            rows.append(rec)
        return pd.DataFrame(rows)


