    # build pixel table from mask for radial profiles
    def _build_radial_pixel_table_from_mask(self):
        if getattr(self, "last_grain_df", None) is None or self.last_grain_df.empty:
            raise ValueError("Detect grains first.")
        if not hasattr(self, "last_grain_label_mask"):
            raise ValueError("No grain label mask is available. Re-run Detect grains.")
        label_mask = np.asarray(self.last_grain_label_mask, dtype=int)
        x = np.asarray(self.last_grain_x, dtype=float)
        y = np.asarray(self.last_grain_y, dtype=float)
        layers = []
        try:
            layers = self._compatible_layers_for_grain_mask()
        except Exception:
            layers = list(getattr(self, "values", {}).keys())
        rows = []
        for _, grow in self.last_grain_df.iterrows():
            try:
                gid = int(grow.get("grain_id"))
            except Exception:
                continue
            rr, cc = np.where(label_mask == gid)
            if rr.size == 0:
                continue
            xv = x[cc]
            yv = y[rr]
            try:
                cx, cy, major, minor, angle, method = self._grain_current_ellipse_params(grow)
            except Exception:
                cx = np.nanmean(xv)
                cy = np.nanmean(yv)
                major = np.nan
                minor = np.nan
                angle = 0.0
                method = "detected_pixels"
            if not (np.isfinite(cx) and np.isfinite(cy)):
                cx = np.nanmean(xv)
                cy = np.nanmean(yv)
            rn = None
            if np.isfinite(major) and np.isfinite(minor) and (major > 0) and (minor > 0):
                try:
                    rn, xp, yp = self._grain_radial_norm_for_points(xv, yv, cx, cy, major, minor, angle)
                except Exception:
                    rn = None
            if rn is None or not np.isfinite(rn).any():
                dist = np.sqrt((xv - cx) ** 2 + (yv - cy) ** 2)
                max_dist = np.nanmax(dist) if dist.size else np.nan
                if not np.isfinite(max_dist) or max_dist <= 0:
                    max_dist = 1.0
                rn = dist / max_dist
                xp = xv - cx
                yp = yv - cy
                method = str(method) + "+detected_pixel_radius"
            radial_bin, radial_zone, radial_percent = self._grain_radial_bin_labels(rn)
            base = pd.DataFrame(
                {
                    "grain_id": gid,
                    "row_index": rr,
                    "column_index": cc,
                    "x": xv,
                    "y": yv,
                    "grain_center_x": cx,
                    "grain_center_y": cy,
                    "grain_ellipse_major_axis": major,
                    "grain_ellipse_minor_axis": minor,
                    "grain_ellipse_angle_deg": angle,
                    "grain_ellipse_method": method,
                    "grain_radial_norm": rn,
                    "grain_radial_percent": radial_percent,
                    "grain_radial_bin": radial_bin,
                    "grain_radial_zone": radial_zone,
                    "grain_ellipse_xprime": xp,
                    "grain_ellipse_yprime": yp,
                    "grain_pixel_in_detected_mask": True,
                    "grain_pixel_in_fitted_ellipse": np.isfinite(rn) & (rn <= 1.0),
                    "analysis_level": "grain_radial_pixel",
                }
            )
            for layer in layers:
                try:
                    arr = np.asarray(self.values[layer], dtype=float)
                except Exception:
                    continue
                if arr.shape != label_mask.shape:
                    continue
                clean = (
                    self._grain_channel_name(layer)
                    if hasattr(self, "_grain_channel_name")
                    else str(layer).split(" :: ")[-1]
                )
                if clean in base.columns:
                    clean = clean + "_map_value"
                try:
                    base[clean] = arr[rr, cc]
                except Exception:
                    pass
            for col in ["grain_area_pixels", "aspect_ratio_x_over_y", "x_y_aspect_ratio"]:
                if col in grow.index and col not in base.columns:
                    base[col] = grow[col]
            rows.append(base)
        if not rows:
            raise ValueError("No radial grain pixels were generated from the detected grain mask.")
        out = pd.concat(rows, ignore_index=True)
        try:
            out = self.add_radial_zone_labels(out)
        except Exception:
            pass
        self.last_grain_radial_pixel_df = out.copy()
        return out


    # build the radial pixel table
    def build_grain_radial_pixel_table(self, use_full_ellipse=None):
        if _build_grain_radial_pixel_table is not None:
            try:
                out = _build_grain_radial_pixel_table(self, use_full_ellipse=use_full_ellipse)
                if out is not None and (not out.empty):
                    return out
            except Exception as exc:
                self._last_radial_profile_error = str(exc)
        return self._build_radial_pixel_table_from_mask()



