    # refresh plot filters
    def refresh_plot_filters(self):
        """Rebuild the row-filter panel once in each plotting tab."""
        _refresh_plot_filter_panels(self)
        try:
            self._build_xy_control_panel()
        except (AttributeError, tk.TclError):
            pass


    # remove duplicate controls after all tabs have been built
    def _simplify_tab_layouts(self):
        _hide_map_bottom_duplicates(self)
        for tab_name in [
            "xy_tab",
            "spider_tab",
            "ternary_tab",
            "compare_grain_tab",
            "corr_tab",
            "pca_tab",
        ]:
            tab = getattr(self, tab_name, None)
            if tab is not None:
                _hide_duplicate_text_widgets(
                    tab, "TLabelframe", "Filter rows", keep=1
                )
        for tab_name, attr in [
            ("ternary_tab", "ternary_show_advanced_display_var"),
            ("mineral_stats_tab", "mineral_stats_show_advanced_display_var"),
            ("pca_tab", "pca_show_advanced_display_var"),
        ]:
            tab = getattr(self, tab_name, None)
            if tab is not None:
                _collapse_label_frame(self, tab, "Axis scale", attr)
        spider_tab = getattr(self, "spider_tab", None)
        if spider_tab is not None:
            _collapse_widget_range(
                self,
                spider_tab,
                "Envelope around mean:",
                "Normalize to:",
                "spider_show_variation_options_var",
                "Show variation and outlier options",
            )
            try:
                _dynamic_widget_range(
                    self,
                    spider_tab,
                    "Number of distance zones:",
                    "Log y-axis",
                    self.spider_mode_var,
                    "Distance zones",
                )
            except Exception:
                pass
        mineral_tab = getattr(self, "mineral_stats_tab", None)
        if mineral_tab is not None:
            _collapse_widget_range(
                self,
                mineral_tab,
                "Nearest neighbors",
                "Boundary chemistry",
                "mineral_stats_show_nn_tools_var",
                "Show nearest-neighbor tools",
            )
            _collapse_widget_range(
                self,
                mineral_tab,
                "Boundary chemistry",
                "Load mineral maps first.",
                "mineral_stats_show_boundary_tools_var",
                "Boundary tools",
            )
        for tab_name in ["ternary_tab", "corr_tab", "pca_tab"]:
            tab = getattr(self, tab_name, None)
            if tab is None:
                continue
            for widget in _walk_widgets(tab):
                text = _widget_text(widget)
                if text.startswith("Uses only the variables selected for the current plot"):
                    try:
                        widget.configure(
                            text="Filters only the variables used here.", wraplength=300
                        )
                    except Exception:
                        pass
        xy_tab = getattr(self, "xy_tab", None)
        if xy_tab is not None:
            frames = {
                _widget_text(w): w for w in _walk_widgets(xy_tab) if w.winfo_class() == "TLabelframe"
            }
            kde_frame = frames.get("KDE")
            bins_frame = frames.get("Distance bins")
            if kde_frame is not None and (not getattr(kde_frame, "_visibility_binding_added", False)):
                kde_frame._visibility_binding_added = True
                try:
                    kde_info = kde_frame.pack_info().copy()
                    for k in ["in", "before", "after"]:
                        kde_info.pop(k, None)
                except Exception:
                    kde_info = {"fill": tk.X, "pady": 4}

                # refresh KDE
                def refresh_kde(*_args):
                    mode = str(self.xy_plot_type_var.get())
                    if mode in ["KDE", "Scatter + KDE"]:
                        if not kde_frame.winfo_manager():
                            try:
                                kde_frame.pack(**kde_info)
                            except Exception:
                                kde_frame.pack(fill=tk.X, pady=4)
                    else:
                        try:
                            kde_frame.pack_forget()
                        except Exception:
                            pass

                try:
                    self.xy_plot_type_var.trace_add("write", refresh_kde)
                except Exception:
                    pass
                refresh_kde()
            if bins_frame is not None and (not getattr(bins_frame, "_visibility_binding_added", False)):
                bins_frame._visibility_binding_added = True
                try:
                    bins_info = bins_frame.pack_info().copy()
                    for k in ["in", "before", "after"]:
                        bins_info.pop(k, None)
                except Exception:
                    bins_info = {"fill": tk.X, "pady": 4}

                # refresh bins
                def refresh_bins(*_args):
                    mode = str(self.xy_data_mode_var.get())
                    if mode == "binned_means":
                        if not bins_frame.winfo_manager():
                            try:
                                bins_frame.pack(**bins_info)
                            except Exception:
                                bins_frame.pack(fill=tk.X, pady=4)
                    else:
                        try:
                            bins_frame.pack_forget()
                        except Exception:
                            pass

                try:
                    self.xy_data_mode_var.trace_add("write", refresh_bins)
                except Exception:
                    pass
                refresh_bins()


    # build the radial distance profile table
    def build_grain_radial_distance_profile_table(self):
        old_value = None
        try:
            old_value = self.profile_buffer_pixels_var.get()
            self.profile_buffer_pixels_var.set(str(self.get_radial_profile_buffer_pixels()))
            pixels, binned = _build_radial_table(self)
        finally:
            if old_value is not None:
                try:
                    self.profile_buffer_pixels_var.set(old_value)
                except Exception:
                    pass
        key = (
            getattr(self, "active_grain_analysis_key", None)
            or getattr(self, "last_grain_mineral_type", None)
            or getattr(self, "last_grain_source_mineral", None)
        )
        mineral_type = None
        if key:
            try:
                _map_group, mineral_type, _group = _split_map_group_label(
                    key, fallback_mineral=getattr(self, "last_grain_mineral_type", key)
                )
                mineral_type = re.sub(r"\s*\[[^\]]*\]\s*$", "", str(mineral_type)).strip()
            except Exception:
                mineral_type = str(key)
        if mineral_type:
            pixels.insert(0, "mineral_type", mineral_type)
            binned.insert(0, "mineral_type", mineral_type)
        preferred = [
            "mineral_type",
            "grain_id",
            "profile_number",
            "profile_degrees",
            "distance",
            "distance_normalized",
        ]
        pixel_order = [column for column in preferred if column in pixels.columns]
        pixel_order += [column for column in pixels.columns if column not in pixel_order]
        bin_order = [column for column in preferred if column in binned.columns]
        bin_order += [column for column in binned.columns if column not in bin_order]
        pixels = pixels[pixel_order].copy()
        binned = binned[bin_order].copy()
        self.last_grain_radial_profile_pixels_df = pixels.copy()
        self.last_grain_radial_profile_bins_df = binned.copy()
        return pixels, binned


    # build integrated mineral grain controls
    def build_integrated_mineral_grain_controls(self, *args, **kwargs):
        out = _build_grain_controls(self, *args, **kwargs)
        self.radial_profile_buffer_pixels_var = getattr(
            self,
            "radial_profile_buffer_pixels_var",
            tk.StringVar(value=str(self.get_profile_buffer_pixels())),
        )
        radial_box = _find_labelframe_with_title(self, "Radial profiles")
        if radial_box is None:
            return out
        for child in radial_box.winfo_children():
            try:
                child.destroy()
            except Exception:
                pass
        ttk.Label(
            radial_box, text="Each buffered grain pixel stays as one row.", wraplength=300
        ).pack(anchor="w", padx=4, pady=(4, 4))
        self.grain_radial_line_count_var = getattr(
            self, "grain_radial_line_count_var", tk.StringVar(value="8")
        )
        row = ttk.Frame(radial_box)
        row.pack(fill=tk.X, padx=4, pady=2)
        ttk.Label(row, text="Profiles per grain:").pack(side=tk.LEFT)
        ttk.Entry(row, textvariable=self.grain_radial_line_count_var, width=8).pack(side=tk.RIGHT)
        row = ttk.Frame(radial_box)
        row.pack(fill=tk.X, padx=4, pady=2)
        ttk.Label(row, text="Radial buffer (pixels):").pack(side=tk.LEFT)
        ttk.Entry(row, textvariable=self.radial_profile_buffer_pixels_var, width=8).pack(
            side=tk.RIGHT
        )
        row = ttk.Frame(radial_box)
        row.pack(fill=tk.X, padx=4, pady=2)
        ttk.Button(row, text="Show spokes", command=self.plot_grain_radial_profile_summary).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 2)
        )
        ttk.Button(row, text="Clear spokes", command=self.clear_grain_radial_profile_lines).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(2, 0)
        )
        ttk.Button(
            radial_box,
            text="Use radial pixels as data",
            command=self.use_grain_radial_pixels_for_analysis,
        ).pack(fill=tk.X, padx=4, pady=(3, 2))
        ttk.Button(
            radial_box,
            text="Export radial pixels",
            command=self.export_grain_radial_profile_pixels,
        ).pack(fill=tk.X, padx=4, pady=(0, 4))
        return out


    # tidy interface helper
    def _tidy_interface(self):
        tab_names = {
            "Map + selections": "Map + selections",
            "Data": "Data",
            "Calculated channels": "Calculated channels",
            "X-Y": "X-Y",
            "Ternary": "Ternary",
            "Mineral analysis": "Mineral analysis",
            "Grain comparison": "Grain comparison",
            "Results": "Results",
        }
        try:
            for tab_id in self.notebook.tabs():
                current = str(self.notebook.tab(tab_id, "text"))
                if current in tab_names:
                    self.notebook.tab(tab_id, text=tab_names[current])
        except Exception:
            pass
        replacements = {
            "Draw on the current map.": "Select map pixels; exports keep matching channels.",
            "Map orientation:": "Map orientation:",
            "Profile buffer (pixels):": "Pixels on each side of line:",
            "Use lines for analysis": "Use line pixels as data",
            "Use spots for analysis": "Use spots as data",
            "Use domain means": "Use domain means as data",
            "Use domain pixels": "Use domain pixels",
            "Use all pixels": "Use all pixels",
            "Use matched X/Y pixels": "Use matched X/Y pixels",
            "Use active rows": "Use selected rows",
            "Binned profile means": "Distance-binned means",
            "Keep separate line/grain/domain traces": "Keep traces separate",
            "One fit for all data": "One fit",
            "Group column:": "Group values by:",
            "Group colors:": "Colors, same order:",
            "Apply groups and colors": "Apply groups",
            "Filter plot variables by IQR": "Filter outliers by IQR",
            "Filter outliers for this plot/statistic": "Filter outliers by IQR",
            "Removes IQR outliers from this plot.": "Uses only the columns in this plot.",
            "Compare grain shapes": "Compare grain shape",
            "Bin width (blank = auto):": "Bin width (blank = auto):",
            "Group colors, in the order above (optional):": "Colors, same order (optional):",
            "Plot grain comparison": "Plot comparison",
            "Export grain comparison CSV": "Export comparison CSV",
            "Advanced mineral-map options": "More mineral options",
            "Advanced grain detection": "More grain options",
            "Advanced center options": "More center options",
            "When moving a center:": "When moving a center:",
            "refit_from_center stretches the ellipse to the detected grain from the new center.": "Refit stretches the ellipse from the moved center.",
        }
        for widget in _walk_widgets(self):
            text = _widget_text(widget)
            if text in replacements:
                try:
                    widget.configure(text=replacements[text])
                except Exception:
                    pass
        try:
            frames = [
                widget
                for widget in _walk_widgets(self.xy_tab)
                if isinstance(widget, ttk.LabelFrame)
                and _widget_text(widget) == "Filter rows"
            ]
            if len(frames) > 1:

                # widget nesting depth, used to keep the outermost duplicate panel.
                def depth(widget):
                    count = 0
                    parent = getattr(widget, "master", None)
                    while parent is not None:
                        count += 1
                        parent = getattr(parent, "master", None)
                    return count

                keep = max(frames, key=depth)
                for frame in frames:
                    if frame is not keep:
                        frame.destroy()
        except Exception:
            pass
        unwanted_frames = {"X-Y plot shape", "Lines and regression"}
        for widget in list(_walk_widgets(self.xy_tab)):
            try:
                if isinstance(widget, ttk.LabelFrame) and _widget_text(widget) in unwanted_frames:
                    widget.destroy()
            except Exception:
                pass
        try:
            for widget in list(_walk_widgets(self.map_tab)):
                text = _widget_text(widget)
                if text in {"Use grain means", "Use grain pixels"}:
                    if _ancestor_labelframe_title(widget) != "Grains":
                        widget.destroy()
        except Exception:
            pass
        try:
            orientation_labels = [
                widget
                for widget in _walk_widgets(self.map_tab)
                if _widget_text(widget) == "Map orientation:"
            ]
            for widget in orientation_labels[1:]:
                parent = widget.master
                siblings = list(parent.winfo_children())
                index = siblings.index(widget)
                widget.destroy()
                for sibling in siblings[index + 1 : index + 3]:
                    if _widget_text(sibling) in {"Invert X axis", "Invert Y axis"}:
                        sibling.destroy()
        except Exception:
            pass
        core_rim_labels = {"Core-to-rim bins:", "Core cutoff:", "Rim cutoff:", "Element for core/rim:"}
        core_rim_checks = {"Use element map to help label core/rim", "High value means rim"}
        for widget in list(_walk_widgets(self.map_tab)):
            text = _widget_text(widget)
            if text in core_rim_labels:
                _destroy_widget_and_next_input(widget)
            elif text in core_rim_checks:
                try:
                    widget.destroy()
                except Exception:
                    pass
        try:
            self.add_compare_grain_iqr_controls()
        except Exception:
            pass
        for widget in list(_walk_widgets(self.xy_tab)):
            text = _widget_text(widget)
            if text == "Named groups also work: Axial:1,4,7 | Oblique:2,3,6":
                try:
                    widget.configure(text="Example: Axial:1,4,7 | Oblique:2,3,6")
                except Exception:
                    pass
            elif text == "Groups: 1,4,7 | 2,3,6 | 5":
                try:
                    widget.destroy()
                except Exception:
                    pass


    # install grain set controls helper for grain analysis
    def _install_grain_set_controls(self):
        if getattr(self, "_grain_set_controls_complete_built", False):
            self.refresh_grain_analysis_set_controls()
            return
        grain_box = _find_labelframe_with_title(self, "Grains")
        if grain_box is None:
            return
        before_widget = None
        for widget in grain_box.winfo_children():
            if _widget_text(widget) == "Grain view:":
                before_widget = widget
                break
        frame = ttk.Frame(grain_box)
        pack_kwargs = dict(fill=tk.X, padx=4, pady=(3, 3))
        if before_widget is not None:
            pack_kwargs["before"] = before_widget
        frame.pack(**pack_kwargs)
        ttk.Label(frame, text="Grain set:").pack(anchor="w")
        self.grain_analysis_set_var = getattr(self, "grain_analysis_set_var", tk.StringVar(value=""))
        self.grain_analysis_set_combo = ttk.Combobox(
            frame, textvariable=self.grain_analysis_set_var, state="readonly", width=30
        )
        self.grain_analysis_set_combo.pack(fill=tk.X, pady=(1, 2))
        self.grain_analysis_set_combo.bind(
            "<<ComboboxSelected>>", lambda _event: self.show_selected_grain_analysis_set()
        )
        row = ttk.Frame(frame)
        row.pack(fill=tk.X)
        ttk.Button(row, text="Show set", command=self.show_selected_grain_analysis_set).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 2)
        )
        ttk.Button(row, text="All means", command=self.use_all_detected_grain_means).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=2
        )
        ttk.Button(row, text="All pixels", command=self.use_all_detected_grain_pixels).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(2, 0)
        )
        self._grain_set_controls_complete_built = True
        self.refresh_grain_analysis_set_controls()


