    # keeps regression choices valid for the selected concordia style.
    def _geochron_update_fit_choices(self):
        if not hasattr(self, "geochron_fit_combo"):
            return
        if self.geochron_plot_type_var.get() == "Tera-Wasserburg":
            choices = [
                "Concordia date + common-Pb regression",
                "Common-Pb regression",
                "Concordia date",
                "None",
            ]
        else:
            choices = [
                "Concordia date + discordia",
                "Discordia (two intercepts)",
                "Concordia date",
                "None",
            ]
        self.geochron_fit_combo.configure(values=choices)
        if self.geochron_fit_var.get() not in choices:
            self.geochron_fit_var.set(choices[0])
        if hasattr(self, "geochron_common_pb_entry"):
            state = "normal" if self.geochron_plot_type_var.get() == "Tera-Wasserburg" else "disabled"
            self.geochron_common_pb_entry.configure(state=state)


    # reads the optional fixed Terra–Wasserburg common-Pb value
    def _geochron_fixed_common_pb_intercept(self):
        text = str(self.geochron_common_pb_var.get()).strip()
        if not text:
            return None
        value = float(text)
        if not np.isfinite(value):
            raise ValueError("The common-Pb 207Pb/206Pb intercept must be a finite number.")
        return value


    # uses the current lasso or picked points as the active U-Pb subset.
    def _geochron_apply_selection(self):
        self.refresh_geochron_controls()
        if getattr(self, "geochron_last_plot_kind", "concordia") == "dates":
            self.plot_geochron_dates()
        else:
            self.plot_geochron_concordia()


    # returns the geochronology plots to all available points.
    def _geochron_clear_selection(self):
        self.analysis_filter_mode_var.set("All rows")
        self.analysis_filter_value_var.set("")
        self.geochron_filter_col_var.set("None")
        self.geochron_keep_var.set("")
        self.geochron_omit_var.set("")
        self.geochron_date_min_var.set("")
        self.geochron_date_max_var.set("")
        self.refresh_geochron_controls()


    # decay constants and the present-day 238U/235U value used by the U-Pb math.
    def _geochron_constants(self):
        lambda238 = float(self.geochron_lambda238_var.get())
        lambda235 = float(self.geochron_lambda235_var.get())
        u_ratio = float(self.geochron_u_ratio_var.get())
        if lambda238 <= 0.0 or lambda235 <= 0.0 or u_ratio <= 0.0:
            raise ValueError("U-Pb constants must be positive.")
        return lambda238, lambda235, u_ratio


    # collects compatible U-Pb rows from the active project workspace.
    def _geochron_collect_workspace_table(self, attr, fallback_attr=None):
        try:
            _sample_save_active_workspace(self)
        except Exception:
            pass
        parts = []
        registry = getattr(self, "sample_registry", {}) or {}
        if registry:
            for sample_id in registry:
                table = _sample_state_dataframe(self, sample_id, attr)
                if table.empty and fallback_attr:
                    table = _sample_state_dataframe(self, sample_id, fallback_attr)
                if not table.empty:
                    parts.append(table)
        else:
            table = getattr(self, attr, None)
            if (not isinstance(table, pd.DataFrame) or table.empty) and fallback_attr:
                table = getattr(self, fallback_attr, None)
            if isinstance(table, pd.DataFrame) and not table.empty:
                parts.append(table.copy())
        return pd.concat(parts, ignore_index=True, sort=False) if parts else pd.DataFrame()


    # chooses the table that currently feeds the geochronology tab.
    def _geochron_source_table(self):
        source = str(self.geochron_source_var.get())
        self._geochron_auto_group_hint = None
        if source == "Active data":
            table = _raw_analysis_source_table(self)
            if not isinstance(table, pd.DataFrame) or table.empty:
                table = self.get_active_analysis_table()
            if isinstance(table, pd.DataFrame) and not table.empty:
                mean_kind = ""
                if "source_kind" in table.columns:
                    values = table["source_kind"].dropna().astype(str).str.casefold()
                    mean_kind = values.iloc[0] if not values.empty else ""
                domain_key = "domain" if "domain" in table.columns else (
                    "area_id" if "area_id" in table.columns else None
                )
                grain_key = "grain_id" if "grain_id" in table.columns else None
                looks_like_domain_means = domain_key is not None and (
                    "mean" in mean_kind
                    or "n_pixels" in table.columns
                    or "source_row_count" in table.columns
                ) and not table[domain_key].duplicated().any()
                looks_like_grain_means = grain_key is not None and (
                    "mean" in mean_kind
                    or "grain_area_pixels" in table.columns
                    or "n_pixels" in table.columns
                ) and not table[grain_key].duplicated().any()
                looks_like_map_mean = "map_mean" in mean_kind
                if looks_like_map_mean:
                    sample_ids = []
                    if "sample_id" in table.columns:
                        sample_ids = [
                            value for value in table["sample_id"].dropna().astype(str).unique()
                            if value and value != "__EMPTY__"
                        ]
                    if not sample_ids:
                        active_sample = getattr(self, "active_sample_id", None)
                        if active_sample and active_sample != "__EMPTY__":
                            sample_ids = [str(active_sample)]
                    if sample_ids:
                        pixels = _sample_build_combined_pixel_table(self, sample_ids)
                        if not pixels.empty:
                            pixels = pixels.copy()
                            pixels["_upb_map_mean"] = "Map mean"
                            table = pixels
                            self._geochron_auto_group_hint = "_upb_map_mean"
                elif looks_like_domain_means:
                    pixels = self._geochron_collect_workspace_table("area_pixel_df")
                    if pixels.empty:
                        try:
                            pixels = self._build_domain_pixel_table()
                        except Exception:
                            pixels = pd.DataFrame()
                    if not pixels.empty and domain_key in pixels.columns:
                        wanted = set(table[domain_key].dropna().astype(str))
                        pixels = pixels[pixels[domain_key].astype(str).isin(wanted)].copy()
                        if not pixels.empty:
                            table = pixels
                            self._geochron_auto_group_hint = domain_key
                elif looks_like_grain_means:
                    try:
                        pixels = combined_grain_pixel_table(self)
                    except Exception:
                        pixels = self._geochron_collect_workspace_table("last_grain_pixel_df")
                    if not pixels.empty and grain_key in pixels.columns:
                        wanted = set(table[grain_key].dropna().astype(str))
                        pixels = pixels[pixels[grain_key].astype(str).isin(wanted)].copy()
                        if not pixels.empty:
                            table = pixels
                            self._geochron_auto_group_hint = grain_key
        elif source == "Selected sample pixels":
            table = _sample_build_combined_pixel_table(self, _sample_selected_sample_ids(self))
        elif source == "Line pixels":
            table = self._geochron_collect_workspace_table("line_profile_df")
        elif source in {"Domain pixels", "Domain means"}:
            table = self._geochron_collect_workspace_table("area_pixel_df")
            if table.empty:
                try:
                    table = self._build_domain_pixel_table()
                except Exception:
                    table = pd.DataFrame()
            if table.empty and source == "Domain means":
                table = self._geochron_collect_workspace_table("area_df")
            if source == "Domain means":
                if "domain" in table.columns:
                    self._geochron_auto_group_hint = "domain"
                elif "area_id" in table.columns:
                    self._geochron_auto_group_hint = "area_id"
        elif source == "Grain pixels":
            try:
                table = combined_grain_pixel_table(self)
            except Exception:
                table = self._geochron_collect_workspace_table("last_grain_pixel_df")
        elif source == "Grain means":
            try:
                table = combined_grain_pixel_table(self)
            except Exception:
                table = self._geochron_collect_workspace_table("last_grain_pixel_df")
            if table.empty:
                table = self._geochron_collect_workspace_table(
                    "last_grain_table_df", "last_grain_summary_df"
                )
            if "grain_id" in table.columns:
                self._geochron_auto_group_hint = "grain_id"
        elif source == "Spot data":
            table = self._geochron_collect_workspace_table("spot_df")
        else:
            table = pd.DataFrame()
        if not isinstance(table, pd.DataFrame) or table.empty:
            raise ValueError(f"No rows are available for {source.lower()}.")
        try:
            needs_normalizing = any(
                " :: " in str(column) or re.search(r"\s+\(\d+\)$", str(column))
                for column in table.columns
            )
            if needs_normalizing:
                table = self.normalize_multimineral_analysis_columns(table)
        except Exception:
            pass
        for channel, definition in (getattr(self, "calculated_channel_definitions", {}) or {}).items():
            if str(channel) in table.columns:
                continue
            try:
                table = _sample_persistent_channel_to_df(self, table, channel, definition)
            except Exception:
                pass
        return table


    # finds likely ratio, age, and uncertainty columns in the source table.
    def _geochron_candidate_columns(self):
        columns = []
        try:
            columns.extend(self.get_canonical_map_columns())
        except Exception:
            pass
        try:
            table = self._geochron_source_table()
            columns.extend([str(c) for c in table.columns if pd.api.types.is_numeric_dtype(table[c])])
        except Exception:
            pass
        return list(dict.fromkeys([str(c) for c in columns if str(c).strip()]))


    # picks the best matching U-Pb column when the user has not chosen one.
    def _geochron_pick_column(self, columns, current, tokens):
        if current in columns:
            return current
        lowered = [(c, re.sub(r"[^a-z0-9]", "", c.lower())) for c in columns]
        for c, clean in lowered:
            if all(token in clean for token in tokens):
                return c
        return current if current else (columns[0] if columns else "")


    # finds a useful grouping or label column for geochronology plots.
    def _geochron_metadata_column(self, value_or_variable):
        if hasattr(value_or_variable, "get"):
            value = str(value_or_variable.get())
        else:
            value = str(value_or_variable)
        return getattr(self, "_geochron_display_to_column", {}).get(value, value)


    # refreshes the geochronology menus after a new table or calculated channel appears.
    def refresh_geochron_controls(self):
        if not hasattr(self, "geochron_r68_combo"):
            return
        columns = self._geochron_candidate_columns()
        for combo in [self.geochron_r68_combo, self.geochron_r76_combo, self.geochron_r75_combo]:
            combo.configure(values=columns)
        self.geochron_r68_var.set(self._geochron_pick_column(
            columns, self.geochron_r68_var.get(), ["206", "238"]
        ))
        self.geochron_r76_var.set(self._geochron_pick_column(
            columns, self.geochron_r76_var.get(), ["207", "206"]
        ))
        if "Pb207_U235_calc" in columns:
            self.geochron_r75_var.set("Pb207_U235_calc")
        else:
            self.geochron_r75_var.set(self._geochron_pick_column(
                columns, self.geochron_r75_var.get(), ["207", "235"]
            ))
        try:
            table = self._geochron_source_table()
            metadata = user_visible_columns(table)
        except Exception:
            table = pd.DataFrame()
            metadata = []
        preferred = [
            column for column in [
                "sample_id", "mineral_id", "run_id", "grain_id",
                "line_id", "domain", "area_id", "spot_id",
            ] if column in metadata
        ]
        raw_columns = list(dict.fromkeys(preferred + metadata))
        categorical = [
            column for column in raw_columns
            if column in preferred
            or (column in table.columns and not pd.api.types.is_numeric_dtype(table[column]))
        ]
        raw_group_columns = list(dict.fromkeys(preferred + categorical))
        old_map = getattr(self, "_geochron_display_to_column", {})
        current_raw = {}
        for name, variable in [
            ("group", self.geochron_group_var),
            ("color", self.geochron_color_var),
            ("summary", self.geochron_summary_group_var),
            ("filter", self.geochron_filter_col_var),
        ]:
            value = str(variable.get())
            current_raw[name] = old_map.get(value, value)

        display_map, reverse_map = display_column_choices(raw_columns, include_none=True)
        self._geochron_display_to_column = display_map
        self._geochron_column_to_display = reverse_map
        all_display_values = list(display_map.keys())
        group_display_values = ["None"] + [
            reverse_map[column] for column in raw_group_columns if column in reverse_map
        ]
        self.geochron_group_combo.configure(values=group_display_values)
        self.geochron_summary_group_combo.configure(values=group_display_values)
        self.geochron_color_combo.configure(values=all_display_values)
        self.geochron_filter_col_combo.configure(values=all_display_values)
        for name, variable in [
            ("group", self.geochron_group_var),
            ("summary", self.geochron_summary_group_var),
        ]:
            raw_value = current_raw[name]
            variable.set(reverse_map.get(raw_value, "None") if raw_value in raw_group_columns else "None")
        for name, variable in [
            ("color", self.geochron_color_var),
            ("filter", self.geochron_filter_col_var),
        ]:
            variable.set(reverse_map.get(current_raw[name], "None"))

        source = self.geochron_source_var.get()
        automatic = getattr(self, "_geochron_auto_group_hint", None) or {
            "Line pixels": "line_id",
            "Domain pixels": "domain",
            "Domain means": "domain",
            "Grain pixels": "grain_id",
            "Grain means": "grain_id",
            "Spot data": "spot_id",
        }.get(source)
        if automatic not in raw_group_columns and automatic == "domain" and "area_id" in raw_group_columns:
            automatic = "area_id"
        if automatic in raw_group_columns:
            automatic_display = reverse_map.get(automatic, automatic)
            if source in {"Domain means", "Grain means"} or getattr(
                self, "_geochron_auto_group_hint", None
            ):
                self.geochron_mode_var.set("Group means")
                self.geochron_group_var.set(automatic_display)
            elif self._geochron_metadata_column(self.geochron_group_var) == "None" and self.geochron_mode_var.get() == "Group means":
                self.geochron_group_var.set(automatic_display)


    # checks whether the selected 206Pb/238U field already contains dates rather than ratios.
    def _geochron_r68_is_date(self, table, column):
        mode = str(self.geochron_r68_input_var.get()).strip()
        if mode == "Date (Ma)":
            return True
        if mode == "Ratio":
            return False
        name = str(column).casefold()
        if "date" in name or "age" in name:
            return True
        values = pd.to_numeric(table[column], errors="coerce")
        finite = values[np.isfinite(values)]
        if finite.empty:
            return False
        sample = finite.iloc[: min(len(finite), 10000)]
        return float(sample.median()) > 2.0


    # returns 206Pb/238U as ratios even when the source column stores dates.
    def _geochron_r68_values(self, table, column, lambda238):
        values = pd.to_numeric(table[column], errors="coerce").to_numpy(dtype=float)
        if not self._geochron_r68_is_date(table, column):
            return values
        with np.errstate(over="ignore", invalid="ignore"):
            ratio = np.expm1(lambda238 * values * 1.0e6)
        ratio[(~np.isfinite(ratio)) | (values < 0.0) | (values > 4600.0)] = np.nan
        return ratio


    # creates the standard U-Pb ratios, dates, uncertainties, and rho columns from selected inputs.
    def create_upb_channels(self):
        try:
            table = self._geochron_source_table()
            r68_input = str(self.geochron_r68_var.get()).strip()
            r76 = str(self.geochron_r76_var.get()).strip()
            if not r68_input or not r76:
                raise ValueError("Choose the 206Pb/238U and 207Pb/206Pb columns.")
            if r68_input not in table.columns or r76 not in table.columns:
                raise ValueError("The selected U-Pb columns are not in the current data.")

            lambda238, lambda235, u_ratio = self._geochron_constants()
            r68_is_date = self._geochron_r68_is_date(table, r68_input)
            r68_ratio = r68_input
            definitions = []
            if r68_is_date:
                r68_ratio = "Pb206_U238_calc"
                definitions.append(
                    {
                        "kind": "geochron_ratio68_from_date",
                        "new_col": r68_ratio,
                        "date_col": r68_input,
                        "u238_u235": u_ratio,
                        "lambda238": lambda238,
                        "lambda235": lambda235,
                    }
                )
            definitions.extend(
                [
                    {
                        "kind": "geochron_ratio75",
                        "new_col": "Pb207_U235_calc",
                        "r76_col": r76,
                        "r68_col": r68_ratio,
                        "u238_u235": u_ratio,
                        "lambda238": lambda238,
                        "lambda235": lambda235,
                    },
                    {
                        "kind": "geochron_date68",
                        "new_col": "Date_206Pb_238U_Ma",
                        "ratio_col": r68_ratio,
                        "u238_u235": u_ratio,
                        "lambda238": lambda238,
                        "lambda235": lambda235,
                    },
                    {
                        "kind": "geochron_date75",
                        "new_col": "Date_207Pb_235U_Ma",
                        "ratio_col": "Pb207_U235_calc",
                        "u238_u235": u_ratio,
                        "lambda238": lambda238,
                        "lambda235": lambda235,
                    },
                    {
                        "kind": "geochron_date76",
                        "new_col": "Date_207Pb_206Pb_Ma",
                        "ratio_col": r76,
                        "u238_u235": u_ratio,
                        "lambda238": lambda238,
                        "lambda235": lambda235,
                    },
                ]
            )

            self.analysis_df = table
            self.active_analysis_df = table
            self._full_analysis_df_for_plotting = table
            made_total = 0
            made_by_channel = {}
            for definition in definitions:
                result = self._evaluate_definition_on_dataframe(table, definition)
                new_col = str(definition["new_col"])
                table[new_col] = pd.to_numeric(result, errors="coerce").to_numpy(dtype=float)
                made, _skipped = self._materialize_calculated_channel(definition)
                made_total += len(made)
                made_by_channel[new_col] = made
                self.calculated_channel_definitions[new_col] = dict(definition)

            self.analysis_df = table
            self.active_analysis_df = table
            self.comparison_df = table.copy(deep=False)
            self._full_analysis_df_for_plotting = table
            main_id = id(table)
            for definition in definitions:
                self._propagate_persistent_channel(
                    str(definition["new_col"]),
                    definition,
                    skip_ids={main_id},
                )
            self._set_active_everywhere(
                table, f"Geochron source: {self.geochron_source_var.get()}"
            )

            self.geochron_r75_var.set("Pb207_U235_calc")
            self.refresh_geochron_controls()
            names = [definition["new_col"] for definition in definitions]
            self._geochron_write(
                "Created channels:\n" + "\n".join(names) + f"\n\nMap layers updated: {made_total}"
            )
            if names:
                self.column_var.set(names[-1])
                self.update_map()
            messagebox.showinfo("U-Pb channels", "Created the U-Pb ratio and date channels.")
        except Exception as exc:
            messagebox.showerror("U-Pb channels", str(exc))


    # applies the current geochronology filters without altering the source table.
    def _geochron_filter_values(self, series, text):
        tokens = [part.strip() for part in str(text or "").replace(";", ",").split(",") if part.strip()]
        if not tokens:
            return np.ones(len(series), dtype=bool)
        numeric = pd.to_numeric(series, errors="coerce")
        use = np.zeros(len(series), dtype=bool)
        for token in tokens:
            if "-" in token and not token.startswith("-"):
                left, right = token.split("-", 1)
                try:
                    lower, upper = sorted((float(left), float(right)))
                    use |= numeric.between(lower, upper, inclusive="both").to_numpy()
                    continue
                except Exception:
                    pass
            try:
                value = float(token)
                use |= np.isclose(numeric.to_numpy(dtype=float), value, equal_nan=False)
            except Exception:
                use |= series.astype(str).str.casefold().eq(token.casefold()).to_numpy()
        return use


    # looks for the uncertainty or count column paired with a selected U-Pb field.
    def _geochron_companion_column(self, table, base_column, suffixes):

        # clean
        def clean(value):
            return re.sub(r"[^a-z0-9]", "", str(value).casefold())
        target_base = clean(base_column)
        lookup = {clean(column): column for column in table.columns}
        for suffix in suffixes:
            candidate = lookup.get(target_base + clean(suffix))
            if candidate is not None:
                return candidate
        return None


    # reads a usable 1-sigma uncertainty from the available companion columns.
    def _geochron_existing_1se(self, table, value_column, values, values_are_dates=False,
                                lambda_value=None):
        one_se_column = self._geochron_companion_column(
            table, value_column, ["_1se_internal", "_1se", "_se", "_sem", "_standard_error"]
        )
        two_se_column = self._geochron_companion_column(
            table, value_column, ["_2se_internal", "_2se", "_2sigma", "_2s"]
        )
        sd_column = self._geochron_companion_column(
            table, value_column, ["_std", "_sd", "_stdev", "_standard_deviation"]
        )
        count_column = self._geochron_companion_column(
            table, value_column, ["_n_valid", "_n", "_count"]
        )
        if count_column is None:
            for candidate in ["source_row_count", "n_pixels", "n"]:
                if candidate in table.columns:
                    count_column = candidate
                    break
        if one_se_column is not None:
            one_se = pd.to_numeric(table[one_se_column], errors="coerce").to_numpy(dtype=float)
        elif two_se_column is not None:
            one_se = pd.to_numeric(table[two_se_column], errors="coerce").to_numpy(dtype=float) / 2.0
        elif sd_column is not None and count_column is not None:
            sd = pd.to_numeric(table[sd_column], errors="coerce").to_numpy(dtype=float)
            count = pd.to_numeric(table[count_column], errors="coerce").to_numpy(dtype=float)
            one_se = np.divide(sd, np.sqrt(count), out=np.full_like(sd, np.nan), where=count > 0.0)
        else:
            one_se = np.full(len(table), np.nan, dtype=float)
        if values_are_dates and lambda_value is not None:
            date_ma = pd.to_numeric(table[value_column], errors="coerce").to_numpy(dtype=float)
            derivative = lambda_value * 1.0e6 * np.exp(lambda_value * date_ma * 1.0e6)
            one_se = np.abs(derivative) * one_se
        one_se[(~np.isfinite(one_se)) | (one_se <= 0.0)] = np.nan
        return one_se


    # decides which metadata fields define separate geochronology groups.
    def _geochron_group_columns(self, table, selected):
        identity = [column for column in ["sample_id", "mineral_id", "run_id"] if column in table.columns]
        if selected == "sample_id" and "sample_id" in table.columns:
            return ["sample_id"]
        if selected == "mineral_id" and "mineral_id" in table.columns:
            return [column for column in ["sample_id", "mineral_id"] if column in table.columns]
        if selected == "run_id" and "run_id" in table.columns:
            return identity
        columns = identity.copy()
        if selected not in {None, "", "None"} and selected in table.columns and selected not in columns:
            columns.append(selected)
        return columns


    # builds the ratio, covariance, age, and grouping arrays used by every U-Pb plot.
    def _geochron_prepare_points(self):
        table = self._geochron_source_table()
        r68_column = str(self.geochron_r68_var.get())
        r76_column = str(self.geochron_r76_var.get())
        r75_column = str(self.geochron_r75_var.get())
        if r68_column not in table.columns or r76_column not in table.columns:
            raise ValueError("Choose valid 206Pb/238U and 207Pb/206Pb columns.")

        lambda238, lambda235, u_ratio = self._geochron_constants()
        work = table.copy(deep=False)
        r68_is_date = self._geochron_r68_is_date(table, r68_column)
        work["upb_r68"] = self._geochron_r68_values(table, r68_column, lambda238)
        work["upb_r76"] = pd.to_numeric(work[r76_column], errors="coerce")
        calculated_r75 = work["upb_r76"] * work["upb_r68"] * u_ratio
        if r75_column in work.columns:
            measured_r75 = pd.to_numeric(work[r75_column], errors="coerce")
            work["upb_r75"] = measured_r75.where(np.isfinite(measured_r75), calculated_r75)
        else:
            work["upb_r75"] = calculated_r75
        work["_upb_r75_pixel_calc"] = calculated_r75

        valid = (
            np.isfinite(work["upb_r68"]) & np.isfinite(work["upb_r75"])
            & np.isfinite(work["upb_r76"]) & (work["upb_r68"] > 0.0)
            & (work["upb_r75"] > 0.0) & (work["upb_r76"] > 0.0)
        )
        work = work.loc[valid].copy()
        if work.empty:
            raise ValueError("No positive, finite U-Pb ratio rows are available.")

        work = _filter_table(self, work)
        if work.empty:
            raise ValueError("The selected-row filter removed every row.")
        filter_column = self._geochron_metadata_column(self.geochron_filter_col_var)
        if filter_column != "None" and filter_column in work.columns:
            keep_text = self.geochron_keep_var.get().strip()
            omit_text = self.geochron_omit_var.get().strip()
            if keep_text:
                work = work.loc[self._geochron_filter_values(work[filter_column], keep_text)].copy()
            if omit_text and not work.empty:
                work = work.loc[~self._geochron_filter_values(work[filter_column], omit_text)].copy()
        if work.empty:
            raise ValueError("The value filter removed every row.")

        source = str(self.geochron_source_var.get())
        requested_mode = str(self.geochron_mode_var.get())
        filter_group = None
        auto_group = getattr(self, "_geochron_auto_group_hint", None)
        force_group = source in {"Domain means", "Grain means"} or auto_group is not None
        group_selected = filter_group if filter_group is not None else (
            auto_group if auto_group is not None else self._geochron_metadata_column(self.geochron_group_var)
        )
        if source == "Domain means" and group_selected in {None, "", "None"}:
            group_selected = "domain" if "domain" in work.columns else "area_id"
        if source == "Grain means" and group_selected in {None, "", "None"}:
            group_selected = "grain_id"

        existing_r68_se = self._geochron_existing_1se(
            work, r68_column, work["upb_r68"].to_numpy(dtype=float), r68_is_date, lambda238
        )
        existing_r76_se = self._geochron_existing_1se(
            work, r76_column, work["upb_r76"].to_numpy(dtype=float)
        )
        if r75_column in work.columns:
            existing_r75_se = self._geochron_existing_1se(
                work, r75_column, work["upb_r75"].to_numpy(dtype=float)
            )
        else:
            existing_r75_se = np.full(len(work), np.nan, dtype=float)
        prepared_means = (
            np.isfinite(existing_r68_se).any()
            and np.isfinite(existing_r76_se).any()
            and np.isfinite(existing_r75_se).any()
        )

        make_groups = force_group or filter_group is not None or requested_mode in {"Group means", "One mean of all active pixels"}
        if requested_mode == "Individual rows" and not force_group and filter_group is None:
            make_groups = False
        if requested_mode == "Auto" and prepared_means and not force_group and filter_group is None:
            make_groups = False

        if make_groups:
            if filter_group == "_upb_selected_set":
                work = work.copy()
                work["_upb_selected_set"] = "Selected set"
            group_columns = self._geochron_group_columns(work, group_selected)
            if not group_columns:
                work = work.copy()
                work["_upb_group"] = "All data"
                group_columns = ["_upb_group"]

            # Grain numbers repeat between samples and runs. The identity columns above
            # keep grain_id unambiguous without exposing a second grain identifier.
            grouped = work.groupby(group_columns, dropna=False, sort=False, observed=True)
            count = grouped["upb_r68"].count().reset_index(name="n")
            points = grouped[["upb_r68", "upb_r76"]].mean().reset_index()
            points = points.merge(count, on=group_columns, how="left")

            for ratio in ["r68", "r76"]:
                column = f"upb_{ratio}"
                sd = grouped[column].std(ddof=1).reset_index(name=f"{column}_sd")
                points = points.merge(sd, on=group_columns, how="left")
                points[f"{column}_1se_internal"] = points[f"{column}_sd"] / np.sqrt(points["n"])

            ratio_method = self.geochron_ratio_method_var.get()
            if ratio_method == "Mean of pixel ratios":
                r75_stats = grouped["_upb_r75_pixel_calc"].agg(["mean", "std"]).reset_index()
                r75_stats = r75_stats.rename(columns={"mean": "upb_r75", "std": "upb_r75_sd"})
                points = points.merge(r75_stats, on=group_columns, how="left")
                points["upb_r75_1se_internal"] = points["upb_r75_sd"] / np.sqrt(points["n"])
            else:
                work = work.copy()
                work["_upb_cross_68_76"] = work["upb_r68"] * work["upb_r76"]
                grouped = work.groupby(group_columns, dropna=False, sort=False, observed=True)
                cross_sum = grouped["_upb_cross_68_76"].sum().reset_index(name="_upb_cross_sum")
                points = points.merge(cross_sum, on=group_columns, how="left")
                covariance_sample = np.divide(
                    points["_upb_cross_sum"] - points["n"] * points["upb_r68"] * points["upb_r76"],
                    points["n"] - 1.0,
                    out=np.full(len(points), np.nan, dtype=float),
                    where=points["n"].to_numpy(dtype=float) > 1.0,
                )
                covariance_mean = covariance_sample / points["n"]
                points["upb_r75"] = points["upb_r68"] * points["upb_r76"] * u_ratio
                variance_68 = points["upb_r68_1se_internal"] ** 2
                variance_76 = points["upb_r76_1se_internal"] ** 2
                variance_75 = (u_ratio ** 2) * (
                    (points["upb_r76"] ** 2) * variance_68
                    + (points["upb_r68"] ** 2) * variance_76
                    + 2.0 * points["upb_r68"] * points["upb_r76"] * covariance_mean
                )
                variance_75 = np.where(variance_75 >= 0.0, variance_75, np.nan)
                points["upb_r75_1se_internal"] = np.sqrt(variance_75)
                points["upb_r75_sd"] = points["upb_r75_1se_internal"] * np.sqrt(points["n"])

            # Direct sample covariances are used when possible. They make rho
            # consistent with whichever averaging choice was selected.
            covariance_rows = []
            for keys, group in grouped:
                if not isinstance(keys, tuple):
                    keys = (keys,)
                rec = {column: value for column, value in zip(group_columns, keys)}
                n = int(group["upb_r68"].count())
                if n > 1:
                    r75_values = (
                        group["_upb_r75_pixel_calc"]
                        if ratio_method == "Mean of pixel ratios"
                        else group["upb_r68"] * group["upb_r76"] * u_ratio
                    )
                    rec["_cov75_68_mean"] = float(np.cov(r75_values, group["upb_r68"], ddof=1)[0, 1] / n)
                    with np.errstate(divide="ignore", invalid="ignore"):
                        r86_values = 1.0 / group["upb_r68"].to_numpy(dtype=float)
                    rec["_cov86_76_mean"] = float(np.cov(r86_values, group["upb_r76"], ddof=1)[0, 1] / n)
                else:
                    rec["_cov75_68_mean"] = np.nan
                    rec["_cov86_76_mean"] = np.nan
                covariance_rows.append(rec)
            if covariance_rows:
                points = points.merge(pd.DataFrame(covariance_rows), on=group_columns, how="left")

            metadata_columns = [
                column for column in work.columns
                if column not in {"upb_r68", "upb_r75", "upb_r76", "_upb_r75_pixel_calc"}
                and column not in group_columns
                and not pd.api.types.is_numeric_dtype(work[column])
                and column != "grain_uid"
            ]
            for column in metadata_columns:
                first = grouped[column].first().reset_index(name=column)
                points = points.merge(first, on=group_columns, how="left")
            points["group_label"] = points[group_columns].astype(str).agg(" | ".join, axis=1)
            points["point_kind"] = "group_mean"
            points["ratio_average"] = ratio_method
        else:
            points = work.reset_index(drop=True).copy()
            if "source_row_count" in points.columns:
                count_values = pd.to_numeric(points["source_row_count"], errors="coerce")
            elif "n_pixels" in points.columns:
                count_values = pd.to_numeric(points["n_pixels"], errors="coerce")
            elif "n" in points.columns:
                count_values = pd.to_numeric(points["n"], errors="coerce")
            else:
                count_values = pd.Series(1.0, index=points.index, dtype=float)
            points["n"] = count_values.fillna(1.0).clip(lower=1.0)
            points["upb_r68_1se_internal"] = existing_r68_se
            points["upb_r75_1se_internal"] = existing_r75_se
            points["upb_r76_1se_internal"] = existing_r76_se
            points["point_kind"] = np.where(
                np.isfinite(existing_r68_se) & np.isfinite(existing_r75_se) & np.isfinite(existing_r76_se),
                "prepared_mean", "row"
            )
            points["ratio_average"] = "row"
            if "group_label" not in points.columns:
                label_columns = [
                    column for column in ["sample_id", "mineral_id", "run_id", "domain", "grain_id", "line_id", "spot_id"]
                    if column in points.columns
                ]
                if label_columns:
                    points["group_label"] = points[label_columns].astype(str).agg(" | ".join, axis=1)
                else:
                    points["group_label"] = np.arange(1, len(points) + 1).astype(str)

        with np.errstate(divide="ignore", invalid="ignore"):
            points["upb_r86"] = 1.0 / points["upb_r68"]
            points["upb_r87"] = u_ratio / points["upb_r75"]
        points["upb_r86_1se_internal"] = (
            points["upb_r68_1se_internal"] / (points["upb_r68"] * points["upb_r68"])
        )
        points["upb_r87_1se_internal"] = (
            u_ratio * points["upb_r75_1se_internal"] / (points["upb_r75"] * points["upb_r75"])
        )

        # Internal correlation coefficients. Direct covariance is preferred for
        # grouped data; the Schmitz-Schoene relative-uncertainty identity is the fallback.
        rel75 = points["upb_r75_1se_internal"] / points["upb_r75"]
        rel68 = points["upb_r68_1se_internal"] / points["upb_r68"]
        rel76 = points["upb_r76_1se_internal"] / points["upb_r76"]
        rel86 = points["upb_r86_1se_internal"] / points["upb_r86"]
        rel87 = points["upb_r87_1se_internal"] / points["upb_r87"]
        rho_w = _upb_rho(rel75, rel68, rel76)
        rho_tw = _upb_rho(rel86, rel76, rel87)
        if "_cov75_68_mean" in points.columns:
            direct = points["_cov75_68_mean"] / (
                points["upb_r75_1se_internal"] * points["upb_r68_1se_internal"]
            )
            direct = direct.where(np.abs(direct) <= 1.000001)
            rho_w = direct.where(np.isfinite(direct), rho_w)
        if "_cov86_76_mean" in points.columns:
            direct = points["_cov86_76_mean"] / (
                points["upb_r86_1se_internal"] * points["upb_r76_1se_internal"]
            )
            direct = direct.where(np.abs(direct) <= 1.000001)
            rho_tw = direct.where(np.isfinite(direct), rho_tw)
        points["rho_wetherill_internal"] = np.clip(rho_w, -1.0, 1.0)
        points["rho_tw_internal"] = np.clip(rho_tw, -1.0, 1.0)

        external_2s = max(0.0, float(self.geochron_external_var.get() or 0.0)) / 100.0
        external_1s = external_2s / 2.0
        for ratio in ["r68", "r75", "r76", "r86", "r87"]:
            column = f"upb_{ratio}"
            internal = pd.to_numeric(points[f"{column}_1se_internal"], errors="coerce")
            systematic = np.abs(pd.to_numeric(points[column], errors="coerce")) * external_1s
            # External uncertainty can draw total-uncertainty ellipses for rows that
            # do not carry an internal uncertainty. It is not used as independent
            # analytical precision for weighted means or population concordia fits.
            internal_for_total = internal.fillna(0.0) if external_1s > 0.0 else internal
            points[f"{column}_1se_total"] = np.sqrt(
                internal_for_total * internal_for_total + systematic * systematic
            )

        # External terms are added in quadrature to each axis. The internal covariance
        # is retained, so total ellipses widen instead of silently keeping the same size.
        internal_cov_w = (
            points["rho_wetherill_internal"]
            * points["upb_r75_1se_internal"] * points["upb_r68_1se_internal"]
        )
        internal_cov_tw = (
            points["rho_tw_internal"]
            * points["upb_r86_1se_internal"] * points["upb_r76_1se_internal"]
        )
        denom_w = points["upb_r75_1se_total"] * points["upb_r68_1se_total"]
        denom_tw = points["upb_r86_1se_total"] * points["upb_r76_1se_total"]
        points["rho_wetherill_total"] = internal_cov_w.fillna(0.0) / denom_w
        points["rho_tw_total"] = internal_cov_tw.fillna(0.0) / denom_tw
        points["rho_wetherill_total"] = points["rho_wetherill_total"].clip(-1.0, 1.0)
        points["rho_tw_total"] = points["rho_tw_total"].clip(-1.0, 1.0)

        points["date_68_ma"] = _upb_date_from_ratio(
            points["upb_r68"].to_numpy(dtype=float), "68", lambda238, lambda235, u_ratio
        )
        points["date_75_ma"] = _upb_date_from_ratio(
            points["upb_r75"].to_numpy(dtype=float), "75", lambda238, lambda235, u_ratio
        )
        points["date_76_ma"] = _upb_date_from_ratio(
            points["upb_r76"].to_numpy(dtype=float), "76", lambda238, lambda235, u_ratio
        )

        for system, ratio in [("68", "r68"), ("75", "r75"), ("76", "r76")]:
            for level in ["internal", "total"]:
                sigma = points[f"upb_{ratio}_1se_{level}"].to_numpy(dtype=float)
                points[f"date_{system}_1se_{level}"] = _upb_date_sigma_ma(
                    points[f"upb_{ratio}"].to_numpy(dtype=float), sigma, system,
                    lambda238, lambda235, u_ratio,
                )
                points[f"date_{system}_2se_{level}"] = 2.0 * points[f"date_{system}_1se_{level}"]

        points["concordia_date_ma"] = np.nan
        points["concordia_date_1se_internal"] = np.nan
        points["concordia_date_2se_internal"] = np.nan
        points["concordia_date_1se_total"] = np.nan
        points["concordia_date_2se_total"] = np.nan
        points["concordance_chi2"] = np.nan
        points["concordance_mswd"] = np.nan
        points["concordance_p_value"] = np.nan
        for index, row in points.iterrows():
            has_internal = (
                np.isfinite(row["upb_r75_1se_internal"])
                and np.isfinite(row["upb_r68_1se_internal"])
                and np.isfinite(row["rho_wetherill_internal"])
            )
            if has_internal:
                date, sigma, chi2_value = _upb_concordia_date(
                    row["upb_r75"], row["upb_r68"], row["upb_r75_1se_internal"],
                    row["upb_r68_1se_internal"], row["rho_wetherill_internal"],
                    lambda238, lambda235,
                )
            else:
                date, sigma, chi2_value = _upb_concordia_date(
                    row["upb_r75"], row["upb_r68"], row["upb_r75_1se_total"],
                    row["upb_r68_1se_total"], row["rho_wetherill_total"],
                    lambda238, lambda235,
                )
            if np.isfinite(date):
                points.at[index, "concordia_date_ma"] = date
                if has_internal:
                    points.at[index, "concordia_date_1se_internal"] = sigma
                    points.at[index, "concordia_date_2se_internal"] = 2.0 * sigma
                points.at[index, "concordance_chi2"] = chi2_value
                points.at[index, "concordance_mswd"] = chi2_value
                points.at[index, "concordance_p_value"] = _upb_chi2_pvalue(chi2_value, 1)
                _date_total, sigma_total, _chi2_total = _upb_concordia_date(
                    row["upb_r75"], row["upb_r68"], row["upb_r75_1se_total"],
                    row["upb_r68_1se_total"], row["rho_wetherill_total"],
                    lambda238, lambda235,
                )
                points.at[index, "concordia_date_1se_total"] = sigma_total
                points.at[index, "concordia_date_2se_total"] = 2.0 * sigma_total

        date_map = {
            "206Pb/238U": "date_68_ma",
            "207Pb/235U": "date_75_ma",
            "207Pb/206Pb": "date_76_ma",
            "Concordia": "concordia_date_ma",
        }
        date_column = date_map[self.geochron_date_type_var.get()]
        lower = self._safe_float_or_none(self.geochron_date_min_var.get())
        upper = self._safe_float_or_none(self.geochron_date_max_var.get())
        if lower is not None:
            points = points.loc[pd.to_numeric(points[date_column], errors="coerce") >= lower]
        if upper is not None:
            points = points.loc[pd.to_numeric(points[date_column], errors="coerce") <= upper]
        points = points.reset_index(drop=True)
        if points.empty:
            raise ValueError("No U-Pb points remain after filtering.")
        self.last_geochron_points_df = points
        return points


    # returns the prepared rows that belong on the current geochronology figure.
    def _geochron_plot_rows(self, points):
        limit = optional_positive_int(self.geochron_max_points_var.get())
        if limit is None or len(points) <= limit:
            return points
        indices = np.linspace(0, len(points) - 1, limit).round().astype(int)
        return points.iloc[np.unique(indices)].copy()


    # assigns stable colors to the selected U-Pb groups.
    def _geochron_point_colors(self, ax, points):
        column = self._geochron_metadata_column(self.geochron_color_var)
        if column == "None" or column not in points.columns:
            return (np.array(["C0"] * len(points), dtype=object), None)
        series = points[column]
        numeric = pd.to_numeric(series, errors="coerce")
        if numeric.notna().sum() >= max(3, int(0.8 * len(points))):
            values = numeric.to_numpy(dtype=float)
            finite = values[np.isfinite(values)]
            if finite.size == 0:
                return (np.array(["C0"] * len(points), dtype=object), None)
            vmin, vmax = float(np.nanmin(finite)), float(np.nanmax(finite))
            try:
                requested_min = str(self.geochron_color_min_var.get()).strip()
                if requested_min:
                    vmin = float(requested_min)
            except (TypeError, ValueError):
                pass
            try:
                requested_max = str(self.geochron_color_max_var.get()).strip()
                if requested_max:
                    vmax = float(requested_max)
            except (TypeError, ValueError):
                pass
            if not np.isfinite(vmin) or not np.isfinite(vmax) or vmax <= vmin:
                vmin, vmax = float(np.nanmin(finite)), float(np.nanmax(finite))
            if vmin == vmax:
                vmax = vmin + 1.0
            norm = mcolors.Normalize(vmin=vmin, vmax=vmax)
            cmap = plt.get_cmap("viridis")
            colors = cmap(norm(np.where(np.isfinite(values), values, vmin)))
            sm = plt.cm.ScalarMappable(norm=norm, cmap=cmap)
            sm.set_array([])
            return colors, (sm, column)
        labels = series.fillna("None").astype(str)
        unique = list(dict.fromkeys(labels.tolist()))
        cmap = plt.get_cmap("tab20")
        mapping = {label: cmap(i % 20) for i, label in enumerate(unique)}
        return np.asarray([mapping[label] for label in labels], dtype=object), mapping


    # redraws whichever geochronology figure is currently selected
    def _geochron_replot_current(self):
        """Rebuild the active Geochron figure from the current settings."""
        if getattr(self, "geochron_last_plot_kind", "concordia") == "dates":
            self.plot_geochron_dates()
        else:
            self.plot_geochron_concordia()


    # responds when the concordia view preset changes
    def _geochron_view_changed(self, event=None):
        """Apply a concordia view preset immediately."""
        if self.geochron_view_var.get() == "Custom":
            return
        self.plot_geochron_concordia()


    # uses the typed axis limits for a custom concordia view.
    def _geochron_apply_custom_view(self):
        values = [
            self._safe_float_or_none(self.geochron_x_min_var.get()),
            self._safe_float_or_none(self.geochron_x_max_var.get()),
            self._safe_float_or_none(self.geochron_y_min_var.get()),
            self._safe_float_or_none(self.geochron_y_max_var.get()),
        ]
        if any(value is None for value in values):
            messagebox.showinfo("Custom axes", "Enter all four axis limits first.")
            return
        x_min, x_max, y_min, y_max = values
        if x_max <= x_min or y_max <= y_min:
            messagebox.showinfo("Custom axes", "Maximum limits must be greater than minimum limits.")
            return
        self.geochron_view_var.set("Custom")
        self.plot_geochron_concordia()


    # draws Wetherill or Terra–Wasserburg concordia with ellipses, dates, and regressions.
    def plot_geochron_concordia(self):
        try:
            self.geochron_last_plot_kind = "concordia"
            all_points = self._geochron_prepare_points()
            points = self._geochron_plot_rows(all_points)
            lambda238, lambda235, u_ratio = self._geochron_constants()
            self.geochron_fig.clear()
            axis = self.geochron_fig.add_subplot(111)
            self.geochron_ax = axis
            plot_type = self.geochron_plot_type_var.get()
            self._geochron_update_fit_choices()

            if plot_type == "Wetherill":
                x = points["upb_r75"].to_numpy(dtype=float)
                y = points["upb_r68"].to_numpy(dtype=float)
                x_all = all_points["upb_r75"].to_numpy(dtype=float)
                y_all = all_points["upb_r68"].to_numpy(dtype=float)
                sx_name, sy_name = "upb_r75_1se_{}", "upb_r68_1se_{}"
                rho_name = "rho_wetherill_{}"
                age_values = pd.concat([all_points["date_68_ma"], all_points["date_75_ma"]])
                axis.set_xlabel("207Pb/235U")
                axis.set_ylabel("206Pb/238U")
            else:
                x = points["upb_r86"].to_numpy(dtype=float)
                y = points["upb_r76"].to_numpy(dtype=float)
                x_all = all_points["upb_r86"].to_numpy(dtype=float)
                y_all = all_points["upb_r76"].to_numpy(dtype=float)
                sx_name, sy_name = "upb_r86_1se_{}", "upb_r76_1se_{}"
                rho_name = "rho_tw_{}"
                age_values = pd.concat([all_points["date_68_ma"], all_points["date_76_ma"]])
                axis.set_xlabel("238U/206Pb")
                axis.set_ylabel("207Pb/206Pb")

            finite_dates = pd.to_numeric(age_values, errors="coerce").dropna().to_numpy(dtype=float)
            requested_low = self._safe_float_or_none(self.geochron_date_min_var.get())
            requested_high = self._safe_float_or_none(self.geochron_date_max_var.get())
            view = str(self.geochron_view_var.get())
            if view == "Full concordia":
                lower_date = 50.0 if plot_type == "Tera-Wasserburg" else 0.0
                upper_date = 4600.0
            elif finite_dates.size:
                natural_lower = float(np.nanpercentile(finite_dates, 2.0))
                natural_upper = float(np.nanpercentile(finite_dates, 98.0))
                center = float(np.nanmedian(finite_dates))
                if view == "Broad":
                    span = max(natural_upper - natural_lower, 500.0, 0.35 * max(center, 100.0))
                    lower_date = max(0.0, natural_lower - 0.65 * span)
                    upper_date = min(4600.0, natural_upper + 0.65 * span)
                else:
                    span = max(natural_upper - natural_lower, 100.0, 0.15 * max(center, 100.0))
                    lower_date = max(0.0, natural_lower - 0.15 * span)
                    upper_date = min(4600.0, natural_upper + 0.15 * span)
            else:
                lower_date, upper_date = 0.0, 4600.0
            if view not in {"Full concordia", "Custom"}:
                if requested_low is not None:
                    lower_date = requested_low
                if requested_high is not None:
                    upper_date = requested_high
            if upper_date <= lower_date:
                upper_date = min(4600.0, lower_date + 100.0)

            curve_start = max(0.1 if plot_type == "Tera-Wasserburg" else 0.0, lower_date)
            line_dates = np.linspace(curve_start, upper_date, 1800)
            curve_x, curve_y = _upb_concordia_xy(
                line_dates, plot_type, lambda238, lambda235, u_ratio
            )
            finite_curve = np.isfinite(curve_x) & np.isfinite(curve_y)
            axis.plot(curve_x[finite_curve], curve_y[finite_curve], linewidth=1.4, label="Concordia")

            tick_dates = _upb_nice_date_ticks(lower_date, upper_date)
            if tick_dates.size:
                tick_x, tick_y = _upb_concordia_xy(
                    tick_dates, plot_type, lambda238, lambda235, u_ratio
                )
                finite_ticks = np.isfinite(tick_x) & np.isfinite(tick_y)
                axis.scatter(
                    tick_x[finite_ticks], tick_y[finite_ticks], s=12,
                    facecolors="white", edgecolors="black", linewidths=0.5, zorder=4,
                )
                for date, px, py in zip(
                    tick_dates[finite_ticks], tick_x[finite_ticks], tick_y[finite_ticks]
                ):
                    axis.annotate(
                        f"{date:g}", (px, py), xytext=(3, 3),
                        textcoords="offset points", fontsize=6,
                    )

            colors, color_info = self._geochron_point_colors(axis, points)
            ellipse_level = "total" if bool(self.geochron_external_ellipses_var.get()) else "internal"
            ellipse_scale = 2.0 if self.geochron_ellipse_level_var.get() == "2 sigma" else 2.44774683068
            sx = pd.to_numeric(points.get(sx_name.format(ellipse_level)), errors="coerce").to_numpy(dtype=float)
            sy = pd.to_numeric(points.get(sy_name.format(ellipse_level)), errors="coerce").to_numpy(dtype=float)
            rho = pd.to_numeric(points.get(rho_name.format(ellipse_level)), errors="coerce").to_numpy(dtype=float)
            if self.geochron_show_ellipses_var.get():
                for px, py, ex, ey, correlation, color in zip(x, y, sx, sy, rho, colors):
                    _upb_ellipse(
                        axis, px, py, ex, ey, correlation, ellipse_scale,
                        facecolor=color, edgecolor=color, alpha=0.20, linewidth=0.8,
                    )
            if isinstance(color_info, tuple):
                axis.scatter(x, y, c=colors, s=18, alpha=0.88, linewidths=0.2)
                self.geochron_fig.colorbar(color_info[0], ax=axis, label=color_info[1])
            elif isinstance(color_info, dict):
                color_column = self._geochron_metadata_column(self.geochron_color_var)
                labels = points[color_column].fillna("None").astype(str)
                for label, color in color_info.items():
                    use = labels.eq(label).to_numpy()
                    axis.scatter(
                        x[use], y[use], c=[color], s=18, alpha=0.88,
                        label=label, linewidths=0.2,
                    )
            else:
                axis.scatter(x, y, c=colors, s=18, alpha=0.88, linewidths=0.2, label="Data")

            summary_rows = []
            fit_choice = str(self.geochron_fit_var.get())
            groups = self._geochron_split_groups(all_points)
            do_concordia = "Concordia date" in fit_choice
            do_regression = (
                "discordia" in fit_choice.casefold() or "common-pb" in fit_choice.casefold()
            )
            external_percent = max(0.0, safe_float(self.geochron_external_var.get(), 0.0))
            use_total_fit = str(self.geochron_fit_uncertainty_var.get()).startswith("Total")
            fixed_common_pb = None
            if plot_type == "Tera-Wasserburg" and do_regression:
                fixed_common_pb = self._geochron_fixed_common_pb_intercept()

            if do_concordia:
                for label, group in groups:
                    propagated_fit = _upb_joint_concordia_date(
                        group["upb_r75"], group["upb_r68"],
                        group["upb_r75_1se_internal"], group["upb_r68_1se_internal"],
                        group["rho_wetherill_internal"], lambda238, lambda235,
                        expand_mswd=False,
                        external_2s_percent=external_percent,
                    )
                    diagnostic_fit = None
                    if use_total_fit:
                        diagnostic_fit = _upb_joint_concordia_date(
                            group["upb_r75"], group["upb_r68"],
                            group["upb_r75_1se_total"], group["upb_r68_1se_total"],
                            group["rho_wetherill_total"], lambda238, lambda235,
                            expand_mswd=False,
                            external_2s_percent=0.0,
                        )
                    if propagated_fit is None and diagnostic_fit is None:
                        continue

                    if propagated_fit is not None:
                        internal = propagated_fit["internal"]
                        propagated = propagated_fit["total"]
                        internal_2se_final = 2.0 * internal["one_sigma_expanded_ma"]
                        internal_2se_unexpanded = 2.0 * internal["one_sigma_ma"]
                        propagated_2se_unexpanded = 2.0 * propagated["one_sigma_ma"]
                        external_component_2se = float(np.sqrt(max(
                            propagated_2se_unexpanded ** 2 - internal_2se_unexpanded ** 2, 0.0
                        )))
                        propagated_2se_final = float(np.sqrt(
                            internal_2se_final ** 2 + external_component_2se ** 2
                        ))
                    else:
                        internal = propagated = None
                        internal_2se_final = propagated_2se_final = np.nan
                    selected = (
                        diagnostic_fit["internal"]
                        if use_total_fit and diagnostic_fit is not None
                        else internal
                    )
                    if selected is None:
                        continue

                    # keeps the reported concordia date and star in one fixed place.
                    # Internal or total changes the uncertainty and fit statistics, not the age coordinate.
                    reported = internal if internal is not None else selected
                    fit_x, fit_y = _upb_concordia_xy(
                        reported["date_ma"], plot_type, lambda238, lambda235, u_ratio
                    )
                    axis.scatter(
                        [fit_x], [fit_y], marker="*", s=80,
                        edgecolors="black", zorder=8, label=f"{label} concordia date",
                    )
                    if internal is not None and propagated is not None:
                        display_2se = (
                            propagated_2se_final if use_total_fit else internal_2se_final
                        )
                    else:
                        display_2se = 2.0 * selected["one_sigma_expanded_ma"]
                    uncertainty_name = "total" if use_total_fit else "internal"
                    annotation = (
                        f"{reported['date_ma']:.1f} ± {display_2se:.1f} Ma "
                        f"(2σ, {uncertainty_name})\n"
                        f"MSWD eq = {selected['mswd_equivalence']:.2f}; "
                        f"conc = {selected['mswd_concordance']:.2f}; "
                        f"combined = {selected['mswd_combined']:.2f}"
                    )
                    axis.annotate(
                        annotation, (fit_x, fit_y), xytext=(6, -24),
                        textcoords="offset points", fontsize=7,
                    )

                    row = {
                        "group": label, "result": "concordia date",
                        "n": (propagated_fit or diagnostic_fit)["n"],
                        "fit_uncertainty": (
                            "total including external" if use_total_fit else "internal only"
                        ),
                        "date_ma": reported["date_ma"],
                        "2se_display_ma": display_2se,
                        "mswd_equivalence": selected["mswd_equivalence"],
                        "mswd_concordance": selected["mswd_concordance"],
                        "mswd_combined": selected["mswd_combined"],
                        "p_equivalence": selected["p_equivalence"],
                        "p_concordance": selected["p_concordance"],
                        "p_combined": selected["p_combined"],
                    }
                    if internal is not None and propagated is not None:
                        row.update({
                            "date_internal_ma": internal["date_ma"],
                            "2se_internal_ma": internal_2se_final,
                            "date_propagated_ma": propagated["date_ma"],
                            "2se_propagated_ma": propagated_2se_final,
                            "mswd_equivalence_internal": internal["mswd_equivalence"],
                            "mswd_concordance_internal": internal["mswd_concordance"],
                            "mswd_combined_internal": internal["mswd_combined"],
                            "p_equivalence_internal": internal["p_equivalence"],
                            "p_concordance_internal": internal["p_concordance"],
                            "p_combined_internal": internal["p_combined"],
                            "mswd_equivalence_propagated": propagated["mswd_equivalence"],
                            "mswd_concordance_propagated": propagated["mswd_concordance"],
                            "mswd_combined_propagated": propagated["mswd_combined"],
                            "p_equivalence_propagated": propagated["p_equivalence"],
                            "p_concordance_propagated": propagated["p_concordance"],
                            "p_combined_propagated": propagated["p_combined"],
                        })
                    if diagnostic_fit is not None:
                        diagnostic = diagnostic_fit["internal"]
                        row.update({
                            "date_total_diagnostic_ma": diagnostic["date_ma"],
                            "2se_total_diagnostic_ma": 2.0 * diagnostic["one_sigma_expanded_ma"],
                            "mswd_equivalence_total_diagnostic": diagnostic["mswd_equivalence"],
                            "mswd_concordance_total_diagnostic": diagnostic["mswd_concordance"],
                            "mswd_combined_total_diagnostic": diagnostic["mswd_combined"],
                        })
                    summary_rows.append(row)

            if do_regression:
                for label, group in groups:
                    level = "total" if use_total_fit else "internal"
                    if plot_type == "Wetherill":
                        group_x = group["upb_r75"].to_numpy(dtype=float)
                        group_y = group["upb_r68"].to_numpy(dtype=float)
                        group_sx = group[f"upb_r75_1se_{level}"].to_numpy(dtype=float)
                        group_sy = group[f"upb_r68_1se_{level}"].to_numpy(dtype=float)
                        group_rho = group[f"rho_wetherill_{level}"].to_numpy(dtype=float)
                    else:
                        group_x = group["upb_r86"].to_numpy(dtype=float)
                        group_y = group["upb_r76"].to_numpy(dtype=float)
                        group_sx = group[f"upb_r86_1se_{level}"].to_numpy(dtype=float)
                        group_sy = group[f"upb_r76_1se_{level}"].to_numpy(dtype=float)
                        group_rho = group[f"rho_tw_{level}"].to_numpy(dtype=float)
                    regression = _upb_york_fit(
                        group_x, group_y, group_sx, group_sy, group_rho,
                        expand_mswd=False,
                        fixed_intercept=(
                            fixed_common_pb if plot_type == "Tera-Wasserburg" else None
                        ),
                    )
                    if regression is None:
                        continue
                    roots = _upb_line_concordia_intercepts(
                        regression, plot_type, lambda238, lambda235, u_ratio
                    )
                    valid_xy = np.isfinite(group_x) & np.isfinite(group_y)
                    if plot_type == "Tera-Wasserburg":
                        data_max = float(np.nanmax(group_x[valid_xy])) if np.any(valid_xy) else 1.0
                        line_x = np.linspace(0.0, max(data_max * 1.08, 0.01), 300)
                    else:
                        endpoints = list(group_x[valid_xy]) if np.any(valid_xy) else []
                        for root in roots:
                            root_x, _ = _upb_concordia_xy(
                                root["date_ma"], plot_type, lambda238, lambda235, u_ratio
                            )
                            if np.isfinite(root_x):
                                endpoints.append(float(root_x))
                        if endpoints:
                            low, high = min(endpoints), max(endpoints)
                            pad = 0.04 * max(high - low, abs(high), 1.0)
                            line_x = np.linspace(max(0.0, low - pad), high + pad, 300)
                        else:
                            line_x = np.linspace(0.0, 1.0, 300)
                    line_y = regression["intercept"] + regression["slope"] * line_x
                    regression_name = (
                        "common-Pb regression" if plot_type == "Tera-Wasserburg" else "discordia"
                    )
                    axis.plot(
                        line_x, line_y, linestyle="--", linewidth=1.2,
                        label=f"{label} {regression_name}",
                    )
                    row = {
                        "group": label, "result": regression_name,
                        "uncertainty_used": (
                            "total including external" if level == "total" else "internal only"
                        ), "n": regression["n"],
                        "slope": regression["slope"],
                        "slope_2se": 2.0 * regression["slope_1se"],
                        "intercept": regression["intercept"],
                        "intercept_2se": 2.0 * regression["intercept_1se"],
                        "intercept_mode": (
                            "fixed" if regression.get("intercept_fixed", False) else "fitted"
                        ),
                        "mswd": regression["mswd"], "df": regression["df"],
                        "p_value": regression["p_value"],
                    }
                    if plot_type == "Wetherill":
                        if roots:
                            row["lower_intercept_ma"] = roots[0]["date_ma"]
                            row["lower_intercept_2se_ma"] = 2.0 * roots[0]["one_sigma_ma"]
                        if len(roots) > 1:
                            row["upper_intercept_ma"] = roots[-1]["date_ma"]
                            row["upper_intercept_2se_ma"] = 2.0 * roots[-1]["one_sigma_ma"]
                        for root in roots[:2]:
                            root_x, root_y = _upb_concordia_xy(
                                root["date_ma"], plot_type, lambda238, lambda235, u_ratio
                            )
                            axis.scatter([root_x], [root_y], marker="D", s=25, zorder=7)
                            root_2se = 2.0 * root["one_sigma_ma"]
                            root_text = f"{root['date_ma']:.1f}"
                            if np.isfinite(root_2se):
                                root_text += f" ± {root_2se:.1f} Ma (2σ)"
                            else:
                                root_text += " Ma"
                            if np.isfinite(regression["mswd"]):
                                root_text += f"\nregression MSWD = {regression['mswd']:.2f}"
                            axis.annotate(
                                root_text, (root_x, root_y),
                                xytext=(5, 5), textcoords="offset points", fontsize=7,
                            )
                    else:
                        row["common_pb_207_206"] = regression["intercept"]
                        row["common_pb_207_206_2se"] = 2.0 * regression["intercept_1se"]
                        row["common_pb_intercept_mode"] = (
                            "fixed" if regression.get("intercept_fixed", False) else "fitted"
                        )
                        axis.scatter([0.0], [regression["intercept"]], marker="s", s=28, zorder=7)
                        intercept_label = (
                            "common Pb (fixed)"
                            if regression.get("intercept_fixed", False) else "common Pb (fitted)"
                        )
                        if regression.get("intercept_fixed", False):
                            intercept_text = (
                                f"{intercept_label} = {regression['intercept']:.4f} (fixed)"
                            )
                        else:
                            intercept_2se = 2.0 * regression["intercept_1se"]
                            intercept_text = (
                                f"{intercept_label} = {regression['intercept']:.4f} "
                                f"± {intercept_2se:.4f} (2σ)"
                            )
                        if np.isfinite(regression["mswd"]):
                            intercept_text += f"\nregression MSWD = {regression['mswd']:.2f}"
                        axis.annotate(
                            intercept_text,
                            (0.0, regression["intercept"]), xytext=(6, 4),
                            textcoords="offset points", fontsize=7,
                        )
                        if roots:
                            row["concordia_intercept_ma"] = roots[0]["date_ma"]
                            row["concordia_intercept_2se_ma"] = 2.0 * roots[0]["one_sigma_ma"]
                            root_x, root_y = _upb_concordia_xy(
                                roots[0]["date_ma"], plot_type, lambda238, lambda235, u_ratio
                            )
                            axis.scatter([root_x], [root_y], marker="D", s=25, zorder=7)
                            root_2se = 2.0 * roots[0]["one_sigma_ma"]
                            root_text = f"{roots[0]['date_ma']:.1f}"
                            if np.isfinite(root_2se):
                                root_text += f" ± {root_2se:.1f} Ma (2σ)"
                            else:
                                root_text += " Ma"
                            if np.isfinite(regression["mswd"]):
                                root_text += f"\nregression MSWD = {regression['mswd']:.2f}"
                            axis.annotate(
                                root_text, (root_x, root_y),
                                xytext=(5, 5), textcoords="offset points", fontsize=7,
                            )
                    summary_rows.append(row)

            finite_x = x_all[np.isfinite(x_all)]
            finite_y = y_all[np.isfinite(y_all)]
            if view == "Custom":
                custom = [
                    self._safe_float_or_none(self.geochron_x_min_var.get()),
                    self._safe_float_or_none(self.geochron_x_max_var.get()),
                    self._safe_float_or_none(self.geochron_y_min_var.get()),
                    self._safe_float_or_none(self.geochron_y_max_var.get()),
                ]
                if any(value is None for value in custom):
                    raise ValueError("Enter all four custom concordia axis limits.")
                axis.set_xlim(custom[0], custom[1])
                axis.set_ylim(custom[2], custom[3])
            elif view == "Full concordia":
                full_start = 50.0 if plot_type == "Tera-Wasserburg" else 0.0
                full_dates = np.linspace(full_start, 4600.0, 2400)
                full_x, full_y = _upb_concordia_xy(
                    full_dates, plot_type, lambda238, lambda235, u_ratio
                )
                axis.set_xlim(*_upb_curve_and_data_limits(full_x, None, padding=0.035, floor_zero=True))
                axis.set_ylim(*_upb_curve_and_data_limits(full_y, None, padding=0.035, floor_zero=True))
            elif view == "Broad":
                axis.set_xlim(*_upb_curve_and_data_limits(
                    curve_x[finite_curve], finite_x, padding=0.08, floor_zero=True
                ))
                axis.set_ylim(*_upb_curve_and_data_limits(
                    curve_y[finite_curve], finite_y, padding=0.08, floor_zero=True
                ))
            else:
                x_errors = pd.to_numeric(
                    all_points.get(sx_name.format(ellipse_level)), errors="coerce"
                ).to_numpy(dtype=float)
                y_errors = pd.to_numeric(
                    all_points.get(sy_name.format(ellipse_level)), errors="coerce"
                ).to_numpy(dtype=float)
                axis.set_xlim(*_upb_plot_limits(x_all, x_errors, padding=0.08))
                axis.set_ylim(*_upb_plot_limits(y_all, y_errors, padding=0.08))

            axis.set_title(f"{plot_type} concordia; n = {len(all_points):,}")
            axis.grid(True, alpha=0.2)
            if self.geochron_show_legend_var.get() and not isinstance(color_info, tuple):
                handles, labels = axis.get_legend_handles_labels()
                if len(labels) <= 35:
                    axis.legend(fontsize=6, loc="best")
            self.last_geochron_summary_df = pd.DataFrame(summary_rows)
            try:
                self.geochron_toolbar.update()
                self.geochron_toolbar.push_current()
            except Exception:
                pass
            self.geochron_canvas.draw_idle()
            if summary_rows:
                self._geochron_write(self.last_geochron_summary_df.to_string(index=False))
            else:
                internal_count = int(np.isfinite(all_points["upb_r68_1se_internal"]).sum())
                total_count = int(np.isfinite(all_points["upb_r68_1se_total"]).sum())
                raw_rows = bool(
                    (all_points.get("point_kind", pd.Series(dtype=str)).astype(str) == "row").all()
                )
                note = (
                    "Raw pixels can be displayed, but the recommended population fit needs "
                    "internal uncertainty and rho. Choose group means, or select Total "
                    "(diagnostic) to explore externally assigned uncertainty."
                    if raw_rows else
                    "No fit was calculated. Check that the points have finite ratio uncertainty and rho."
                )
                self._geochron_write(
                    f"{plot_type} concordia\nPoints: {len(all_points):,}\n"
                    f"Points with internal uncertainty: {internal_count:,}\n"
                    f"Points with total uncertainty: {total_count:,}\n{note}"
                )
        except Exception as exc:
            messagebox.showerror("Concordia", str(exc))


    # maps each requested date type to its age and uncertainty columns.
    def _geochron_date_columns(self):
        mapping = {
            "206Pb/238U": ("date_68_ma", "date_68_1se_internal", "date_68_2se_internal", "date_68_2se_total"),
            "207Pb/235U": ("date_75_ma", "date_75_1se_internal", "date_75_2se_internal", "date_75_2se_total"),
            "207Pb/206Pb": ("date_76_ma", "date_76_1se_internal", "date_76_2se_internal", "date_76_2se_total"),
            "Concordia": ("concordia_date_ma", "concordia_date_1se_internal", "concordia_date_2se_internal", "concordia_date_2se_total"),
        }
        return mapping[self.geochron_date_type_var.get()]


    # splits prepared U-Pb rows into the groups selected for plotting or statistics.
    def _geochron_split_groups(self, points):
        column = self._geochron_metadata_column(self.geochron_summary_group_var)
        if column == "None" or column not in points.columns:
            return [("All data", points)]
        return [(str(label), group.copy()) for label, group in points.groupby(column, dropna=False, sort=False)]


    # calculates the weighted mean, uncertainty, MSWD, and p-value for one age group.
    def _geochron_weighted_mean(self, ages, sigma_1s):
        ages = np.asarray(ages, dtype=float)
        sigma = np.asarray(sigma_1s, dtype=float)
        valid = np.isfinite(ages) & np.isfinite(sigma) & (sigma > 0.0)
        ages, sigma = ages[valid], sigma[valid]
        if ages.size == 0:
            return None
        weights = 1.0 / (sigma * sigma)
        mean = float(np.sum(weights * ages) / np.sum(weights))
        sigma_mean = float(np.sqrt(1.0 / np.sum(weights)))
        if ages.size > 1:
            mswd = float(np.sum(weights * (ages - mean) ** 2) / (ages.size - 1))
            if False and mswd > 1.0:
                sigma_mean *= np.sqrt(mswd)
        else:
            mswd = np.nan
        return mean, sigma_mean, mswd, int(ages.size), valid


    # converts the external-percent setting into a 2-sigma age uncertainty.
    def _geochron_external_date_2s_for_type(self, date_ma, date_type):
        external = max(0.0, float(self.geochron_external_var.get() or 0.0)) / 100.0
        if external <= 0.0 or not np.isfinite(date_ma):
            return 0.0
        lambda238, lambda235, u_ratio = self._geochron_constants()
        years = date_ma * 1.0e6
        if date_type == "206Pb/238U":
            ratio = np.expm1(lambda238 * years)
            return float(_upb_date_sigma_ma(
                ratio, ratio * external, "68", lambda238, lambda235, u_ratio
            ))
        if date_type == "207Pb/235U":
            ratio = np.expm1(lambda235 * years)
            return float(_upb_date_sigma_ma(
                ratio, ratio * external, "75", lambda238, lambda235, u_ratio
            ))
        if date_type == "207Pb/206Pb":
            ratio = float(_upb_ratio76_from_date_ma(date_ma, lambda238, lambda235, u_ratio))
            return float(_upb_date_sigma_ma(
                ratio, ratio * external, "76", lambda238, lambda235, u_ratio
            ))
        r75 = np.expm1(lambda235 * years)
        r68 = np.expm1(lambda238 * years)
        s75 = r75 * external / 2.0
        s68 = r68 * external / 2.0
        _date, sigma, _chi2 = _upb_concordia_date(
            r75, r68, s75, s68, 0.0, lambda238, lambda235
        )
        return 2.0 * sigma if np.isfinite(sigma) else 0.0


    # draws weighted means, KDEs, or age distributions from the selected U-Pb date type.
    def plot_geochron_dates(self):
        try:
            self.geochron_last_plot_kind = "dates"
            points = self._geochron_prepare_points()
            date_column, sigma_column, internal_2se_column, total_2se_column = (
                self._geochron_date_columns()
            )
            self.geochron_fig.clear()
            axis = self.geochron_fig.add_subplot(111)
            self.geochron_ax = axis
            summaries = []
            date_type = self.geochron_date_type_var.get()

            if self.geochron_date_plot_var.get() == "KDE":
                bandwidth_multiplier = float(self.geochron_bandwidth_var.get() or 1.0)
                if bandwidth_multiplier <= 0.0:
                    raise ValueError("KDE bandwidth must be positive.")
                all_dates = pd.to_numeric(
                    points[date_column], errors="coerce"
                ).dropna().to_numpy(dtype=float)
                if all_dates.size == 0:
                    raise ValueError(f"No finite {date_type} dates are available.")
                lower = self._safe_float_or_none(self.geochron_date_min_var.get())
                upper = self._safe_float_or_none(self.geochron_date_max_var.get())
                lower = float(np.nanmin(all_dates)) if lower is None else lower
                upper = float(np.nanmax(all_dates)) if upper is None else upper
                if upper <= lower:
                    upper = lower + 1.0
                padding = 0.03 * (upper - lower)
                grid = np.linspace(max(0.0, lower - padding), upper + padding, 900)
                for label, group in self._geochron_split_groups(points):
                    values = pd.to_numeric(
                        group[date_column], errors="coerce"
                    ).dropna().to_numpy(dtype=float)
                    if values.size >= 3 and np.nanstd(values, ddof=1) > 0.0:
                        density, bandwidth = _grain_kde_on_common_grid(
                            values, grid, bandwidth_multiplier
                        )
                        axis.plot(grid, density, label=f"{label} (n={len(values)})")
                        peaks = _upb_kde_peaks(grid, density, bandwidth, maximum=5)
                        for peak_index, peak in enumerate(peaks):
                            axis.axvline(
                                peak["date_ma"], linestyle="--", linewidth=0.7, alpha=0.45
                            )
                            if peak_index == 0:
                                axis.annotate(
                                    f"{peak['date_ma']:.1f} Ma",
                                    (peak["date_ma"], peak["density"]),
                                    xytext=(4, 4), textcoords="offset points", fontsize=7,
                                )
                        summaries.append({
                            "group": label, "result": "KDE", "n": len(values),
                            "bandwidth_ma": bandwidth,
                            "kde_peak_ma": peaks[0]["date_ma"] if peaks else np.nan,
                            "kde_peaks_ma": "; ".join(
                                f"{peak['date_ma']:.2f}" for peak in peaks
                            ),
                            "mean_ma": float(np.nanmean(values)),
                            "median_ma": float(np.nanmedian(values)),
                        })
                    elif values.size:
                        axis.vlines(
                            values, 0.0, 1.0, alpha=0.6,
                            label=f"{label} (n={len(values)})",
                        )
                        summaries.append({
                            "group": label, "result": "dates", "n": len(values),
                            "bandwidth_ma": np.nan,
                            "kde_peak_ma": values[0] if len(values) == 1 else np.nan,
                            "kde_peaks_ma": "; ".join(f"{value:.2f}" for value in values),
                            "mean_ma": float(np.nanmean(values)),
                            "median_ma": float(np.nanmedian(values)),
                        })
                axis.set_xlabel(f"{date_type} date (Ma)")
                axis.set_ylabel("Density")
                axis.set_title(f"{date_type} date KDE")
            else:
                if sigma_column not in points.columns:
                    raise ValueError("This table does not contain date uncertainties.")
                plot_colors, color_info = self._geochron_point_colors(axis, points)
                points = points.copy()
                points["__plot_color"] = [
                    tuple(color) if not isinstance(color, str) else color
                    for color in plot_colors
                ]
                if isinstance(color_info, tuple):
                    self.geochron_fig.colorbar(color_info[0], ax=axis, label=color_info[1])
                elif isinstance(color_info, dict):
                    for color_label, color in color_info.items():
                        axis.scatter([], [], c=[color], s=20, label=color_label)

                use_total_fit = str(self.geochron_fit_uncertainty_var.get()).startswith("Total")
                x_cursor = 1
                annotation_lines = []
                group_boundaries = []
                for label, group in self._geochron_split_groups(points):
                    dates = pd.to_numeric(group[date_column], errors="coerce").to_numpy(dtype=float)
                    sigma_internal = pd.to_numeric(
                        group[sigma_column], errors="coerce"
                    ).to_numpy(dtype=float)
                    sigma_total = pd.to_numeric(
                        group[total_2se_column], errors="coerce"
                    ).to_numpy(dtype=float) / 2.0
                    internal_result = self._geochron_weighted_mean(dates, sigma_internal)
                    total_result = self._geochron_weighted_mean(dates, sigma_total)
                    selected_result = total_result if use_total_fit else internal_result
                    if selected_result is None:
                        continue
                    selected_mean, selected_sigma, selected_mswd, n, valid = selected_result
                    group_valid = group.loc[valid].reset_index(drop=True)
                    values = dates[valid]
                    internal_errors = pd.to_numeric(
                        group_valid[internal_2se_column], errors="coerce"
                    ).to_numpy(dtype=float)
                    total_errors = pd.to_numeric(
                        group_valid[total_2se_column], errors="coerce"
                    ).to_numpy(dtype=float)
                    total_errors = np.where(
                        np.isfinite(total_errors), total_errors, internal_errors
                    )
                    point_colors = group_valid["__plot_color"].to_numpy(dtype=object)
                    x_values = np.arange(x_cursor, x_cursor + n)
                    for px, date, internal_error, total_error, color in zip(
                        x_values, values, internal_errors, total_errors, point_colors
                    ):
                        if np.isfinite(total_error):
                            axis.errorbar(
                                [px], [date], yerr=[[total_error], [total_error]],
                                fmt="none", ecolor=color, alpha=0.25,
                                linewidth=2.2, capsize=0,
                            )
                        if np.isfinite(internal_error):
                            axis.errorbar(
                                [px], [date], yerr=[[internal_error], [internal_error]],
                                fmt="none", ecolor=color, linewidth=0.9, capsize=2,
                            )
                        axis.scatter([px], [date], c=[color], s=18, zorder=4)

                    internal_mean = internal_result[0] if internal_result else np.nan
                    internal_2se = 2.0 * internal_result[1] if internal_result else np.nan
                    internal_mswd = internal_result[2] if internal_result else np.nan
                    total_diag_mean = total_result[0] if total_result else np.nan
                    total_diag_2se = 2.0 * total_result[1] if total_result else np.nan
                    total_diag_mswd = total_result[2] if total_result else np.nan
                    external_2se = (
                        self._geochron_external_date_2s_for_type(internal_mean, date_type)
                        if np.isfinite(internal_mean) else np.nan
                    )
                    propagated_2se = (
                        float(np.sqrt(internal_2se ** 2 + external_2se ** 2))
                        if np.isfinite(internal_2se) and np.isfinite(external_2se)
                        else internal_2se
                    )
                    group_color = point_colors[0] if len(point_colors) else "C0"
                    x_low = float(x_values[0] - 0.45)
                    x_high = float(x_values[-1] + 0.45)
                    if np.isfinite(propagated_2se) and np.isfinite(internal_mean):
                        axis.fill_between(
                            [x_low, x_high], internal_mean - propagated_2se,
                            internal_mean + propagated_2se, color=group_color, alpha=0.07,
                        )
                    if np.isfinite(internal_2se) and np.isfinite(internal_mean):
                        axis.fill_between(
                            [x_low, x_high], internal_mean - internal_2se,
                            internal_mean + internal_2se, color=group_color, alpha=0.16,
                        )
                    axis.hlines(selected_mean, x_low, x_high, color=group_color, linewidth=1.2)
                    df_value = max(0, n - 1)
                    summaries.append({
                        "group": label, "result": "weighted mean", "n": n,
                        "fit_uncertainty": (
                            "total including external" if use_total_fit else "internal only"
                        ),
                        "weighted_mean_ma": selected_mean,
                        "2se_display_ma": 2.0 * selected_sigma,
                        "mswd": selected_mswd,
                        "weighted_mean_internal_ma": internal_mean,
                        "2se_internal_ma": internal_2se,
                        "2se_propagated_ma": propagated_2se,
                        "mswd_internal": internal_mswd,
                        "weighted_mean_total_diagnostic_ma": total_diag_mean,
                        "2se_total_diagnostic_ma": total_diag_2se,
                        "mswd_total_diagnostic": total_diag_mswd,
                        "df": df_value,
                        "p_value": (
                            _upb_chi2_pvalue(selected_mswd * df_value, df_value)
                            if np.isfinite(selected_mswd) else np.nan
                        ),
                        "p_value_internal": (
                            _upb_chi2_pvalue(internal_mswd * df_value, df_value)
                            if np.isfinite(internal_mswd) else np.nan
                        ),
                        "p_value_total_diagnostic": (
                            _upb_chi2_pvalue(total_diag_mswd * df_value, df_value)
                            if np.isfinite(total_diag_mswd) else np.nan
                        ),
                    })
                    selected_mswd_text = (
                        "n/a" if not np.isfinite(selected_mswd) else f"{selected_mswd:.2f}"
                    )
                    annotation_lines.append(
                        f"{label}: {selected_mean:.2f} ± {2.0 * selected_sigma:.2f} Ma; "
                        f"MSWD {selected_mswd_text}; n={n}"
                    )
                    group_boundaries.append((x_low, x_high, label))
                    x_cursor += n + 1

                if not summaries:
                    raise ValueError(
                        "No dates have finite uncertainties. Use domain, grain, line, or map means."
                    )
                axis.set_xlabel("Analysis number")
                axis.set_ylabel(f"{date_type} date (Ma)")
                axis.set_title(f"{date_type} weighted mean")
                for low, high, label in group_boundaries:
                    axis.text(
                        (low + high) / 2.0, 0.01, str(label),
                        transform=axis.get_xaxis_transform(), ha="center",
                        va="bottom", fontsize=7,
                    )
                axis.text(
                    0.99, 0.99, "\n".join(annotation_lines[:10]),
                    transform=axis.transAxes, ha="right", va="top", fontsize=7,
                    bbox={
                        "boxstyle": "round", "facecolor": "white", "alpha": 0.8,
                        "edgecolor": "0.7",
                    },
                )
                if self.geochron_show_legend_var.get() and isinstance(color_info, dict):
                    axis.legend(fontsize=6, loc="best")

            axis.grid(True, alpha=0.2)
            if (
                self.geochron_date_plot_var.get() == "KDE"
                and self.geochron_show_legend_var.get()
                and len(summaries) <= 30
            ):
                axis.legend(fontsize=6, loc="best")
            self.last_geochron_summary_df = pd.DataFrame(summaries)
            self.geochron_canvas.draw_idle()
            self._geochron_write(self.last_geochron_summary_df.to_string(index=False))
        except Exception as exc:
            messagebox.showerror("Date plot", str(exc))


    # writes a geochronology table while preserving the displayed column order.
    def _geochron_write(self, text):
        if not hasattr(self, "geochron_results"):
            return
        self.geochron_results.configure(state="normal")
        self.geochron_results.delete("1.0", tk.END)
        self.geochron_results.insert("1.0", str(text))
        self.geochron_results.configure(state="disabled")


