    # Save the current maps, selections, grains, tables, and UI state.


    # save file for project files
    def save_project_file(self):
        path = filedialog.asksaveasfilename(
            title="Save map project",
            defaultextension=".pkl",
            filetypes=[("Map project", "*.pkl"), ("All files", "*.*")],
            initialfile="map_project.pkl",
        )
        if not path:
            return
        try:
            state = self.build_project_state()
            with open(path, "wb") as f:
                pickle.dump(state, f, protocol=pickle.HIGHEST_PROTOCOL)
            messagebox.showinfo("Project saved", f"Saved project:\n{path}")
        except Exception as exc:
            messagebox.showerror("Could not save project", str(exc))


    # restore project state helper for project files
    def restore_project_state(self, state):
        result = _apply_project_state(self, state)
        try:
            _sample_rebuild_sample_tabs_from_state(self, state)
            old_geochron_names = {
                "geochron_age_min_var": "geochron_date_min_var",
                "geochron_age_max_var": "geochron_date_max_var",
                "geochron_age_type_var": "geochron_date_type_var",
                "geochron_age_plot_var": "geochron_date_plot_var",
            }
            for attr, value in state.get("geochron_vars", {}).items():
                attr = old_geochron_names.get(attr, attr)
                var = getattr(self, attr, None)
                if hasattr(var, "set"):
                    var.set(value)
            saved_points = state.get("last_geochron_points_df")
            saved_summary = state.get("last_geochron_summary_df")
            if isinstance(saved_points, pd.DataFrame):
                self.last_geochron_points_df = saved_points.copy()
            if isinstance(saved_summary, pd.DataFrame):
                self.last_geochron_summary_df = saved_summary.copy()
            self.refresh_column_alias_controls()
            self.refresh_analysis_columns()
            self.refresh_geochron_controls()
            try:
                self._rebuild_pixel_exclusions()
                self._refresh_pixel_filter_channels()
            except Exception:
                pass
        except Exception as exc:
            try:
                self.status_var.set(f"Project opened; sample tabs were rebuilt: {exc}")
            except Exception:
                pass
        return result


