    # normalize coord group key for shared plane
    def _normalize_coord_group_key_for_shared_plane(self, key):
        s = str(key or "")
        s = os.path.basename(s)
        s = re.sub("\\.[A-Za-z0-9]+$", "", s)
        s = re.sub("\\(\\d+\\)$", "", s).strip()
        s = re.sub("\\s+matrix$", "", s, flags=re.I)
        s = re.sub("\\s+(x|y)\\s*\\[[^\\]]+\\]\\s*$", "", s, flags=re.I)
        s = re.sub(
            "\\s+[A-Z][a-z]?\\d{1,3}(?:[_\\s-]*(?:ppm|cps|wt|oxide|total|norm|normalized))?\\s*$",
            "",
            s,
            flags=re.I,
        )
        s = re.sub("\\s+", " ", s).strip()
        return s


    # group mask and coords helper for mineral analysis
    def mineral_group_mask_and_coords(
        self, mineral_name, rule="finite", threshold=0.0, preferred_column=None
    ):
        if mineral_name not in self.mineral_presence_groups:
            raise ValueError(f"Unknown mineral group: {mineral_name}")
        rec = self.mineral_presence_groups[mineral_name]
        layers = rec.get("layers", [])
        if not layers:
            layer = rec.get("representative_layer")
            layers = [layer] if layer else []
        chosen_layer = None
        if preferred_column:
            for layer in layers:
                clean = str(layer).split(" :: ", 1)[-1]
                if clean == preferred_column or layer == preferred_column:
                    chosen_layer = layer
                    break
        if chosen_layer is None:
            chosen_layer = rec.get("representative_layer") or layers[0]
        extent, x, y, z = self._layer_extent_from_meta(chosen_layer)
        vals = np.asarray(z, dtype=float)
        mask = np.isfinite(vals)
        if rule == ">0":
            mask &= vals > 0
        elif rule == ">custom":
            mask &= vals > threshold
        return (chosen_layer, extent, x, y, mask)


    # draw true coordinate pixels
    def _draw_true_coordinate_pixels(
        self, ax, meta, z, mask, color, label=None, alpha=1.0, zorder=5
    ):
        z = np.asarray(z, dtype=float)
        mask = np.asarray(mask, dtype=bool)
        try:
            from matplotlib.colors import ListedColormap, to_rgba

            x_edges, y_edges = self._layer_xy_edges_from_existing_axes(meta, z.shape)
            if x_edges is not None and y_edges is not None:
                arr = np.where(mask, 1.0, np.nan)
                cmap = ListedColormap([to_rgba(color, alpha=float(alpha))])
                artist = ax.pcolormesh(
                    x_edges,
                    y_edges,
                    arr,
                    cmap=cmap,
                    vmin=1.0,
                    vmax=1.0,
                    shading="flat",
                    edgecolors="face",
                    linewidth=0,
                    antialiased=False,
                    snap=True,
                    rasterized=True,
                    zorder=zorder,
                )
                if label is not None:
                    ax.scatter([], [], s=28, c=[color], marker="s", linewidths=0, label=label)
                return artist
        except Exception:
            pass
        xg, yg = self._layer_pixel_centers(meta, z_shape=z.shape)
        if (
            xg is None
            or yg is None
            or tuple(np.shape(xg)) != tuple(z.shape)
            or (tuple(np.shape(yg)) != tuple(z.shape))
        ):
            yy, xx = np.indices(z.shape)
            xg, yg = (xx.astype(float), yy.astype(float))
        good = mask & np.isfinite(xg) & np.isfinite(yg)
        if not np.any(good):
            return None
        xs = np.asarray(xg[good], dtype=float)
        ys = np.asarray(yg[good], dtype=float)
        marker_size = 7.0
        try:
            dx, dy = self._median_pixel_spacing_from_meta(meta, z_shape=z.shape)
            xspan = max(float(np.nanmax(xs) - np.nanmin(xs)), dx)
            yspan = max(float(np.nanmax(ys) - np.nanmin(ys)), dy)
            bbox = ax.get_window_extent().transformed(ax.figure.dpi_scale_trans.inverted())
            width_pts = max(bbox.width * 72.0, 1.0)
            height_pts = max(bbox.height * 72.0, 1.0)
            sx = width_pts * dx / xspan
            sy = height_pts * dy / yspan
            marker_size = max(3.0, min(25.0, 1.15 * sx * sy))
        except Exception:
            pass
        return ax.scatter(
            xs,
            ys,
            s=marker_size,
            c=color,
            marker="s",
            linewidths=0,
            alpha=float(alpha),
            label=label,
            zorder=zorder,
        )


    # true coord limits from layers
    def _true_coord_limits_from_layers(self, layer_records):
        xs_all = []
        ys_all = []
        for rec in layer_records:
            try:
                meta, z, mask = rec
                xg, yg = self._layer_pixel_centers(meta, z_shape=np.asarray(z).shape)
                good = np.asarray(mask, dtype=bool) & np.isfinite(xg) & np.isfinite(yg)
                if np.any(good):
                    xs_all.extend([float(np.nanmin(xg[good])), float(np.nanmax(xg[good]))])
                    ys_all.extend([float(np.nanmin(yg[good])), float(np.nanmax(yg[good]))])
            except Exception:
                pass
        if not xs_all or not ys_all:
            return None
        return (min(xs_all), max(xs_all), min(ys_all), max(ys_all))


    # export the current correlation matrix
    def export_corr_matrix(self):
        if not isinstance(self.last_corr, pd.DataFrame) or self.last_corr.empty:
            messagebox.showinfo("No correlation matrix", "Run correlation first.")
            return
        table = self.last_corr.copy()
        table.index.name = table.index.name or "variable"
        self.save_df_csv(table.reset_index(), "correlation_matrix.csv", "correlation matrix")


    # numeric matrix and labels used by PCA or correlation tools.
    def get_analysis_matrix(self, cols, min_complete_rows=3):
        df = self.get_active_analysis_table()
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            raise ValueError("No active analysis table.")
        before_all = len(df)
        filtered, info = self._apply_iqr_filter(df, cols)
        data = filtered[[c for c in cols if c in filtered.columns]].copy()
        data = data.apply(pd.to_numeric, errors="coerce").replace([np.inf, -np.inf], np.nan)
        data = data.dropna(axis=0, how="any")
        dropped = int(before_all - len(data))
        if len(data.columns) < 2:
            raise ValueError("Fewer than 2 valid columns.")
        if len(data) < min_complete_rows:
            raise ValueError(
                "Not enough complete rows after removing blanks/NaNs and optional IQR outliers."
            )
        self._last_iqr_filter_info = info
        return (data, dropped)


    # run corr matrix
    def run_corr_matrix(self):
        out = _run_corr_matrix(self)
        self._append_iqr_note(
            getattr(self, "_last_iqr_filter_info", None),
            context="correlation matrix",
        )
        return out



