    # clear imported maps and return to an empty project
    def clear_loaded_maps(self, *args, **kwargs):
        try:
            self.values = {}
            self.metas = {}
            self.layer_mineral_type = {}
            self.mineral_presence_groups = {}
            self.mineral_column_index = {}
        except Exception:
            pass
