    # enter rectangular-domain drawing mode
    def start_area_pick(self):
        if not self._map_loaded_for_tools():
            return
        self.active_mode = "area"
        self.pending_points = []
        try:
            self.status_var.set("Domain mode: click two opposite corners.")
        except Exception:
            pass


    # use two clicks to finish a rectangular domain
    def handle_area_click(self, x, y):
        self.pending_points.append((x, y))
        if len(self.pending_points) == 1:
            self.status_var.set("First corner selected. Click opposite corner.")
            return
        p0, p1 = self.pending_points[:2]
        self.active_mode = None
        self.pending_points = []
        self.make_area_summary(p0, p1)


    # summarize channels inside one rectangular domain
    def make_area_summary(self, p0, p1):
        x0, y0 = p0
        x1, y1 = p1
        row0, col0 = self.data_xy_to_fractional_indices(x0, y0)
        row1, col1 = self.data_xy_to_fractional_indices(x1, y1)
        rmin = int(np.floor(min(row0, row1)))
        rmax = int(np.ceil(max(row0, row1)))
        cmin = int(np.floor(min(col0, col1)))
        cmax = int(np.ceil(max(col0, col1)))
        n_rows, n_cols = self.current_z.shape
        rmin = max(0, rmin)
        rmax = min(n_rows - 1, rmax)
        cmin = max(0, cmin)
        cmax = min(n_cols - 1, cmax)
        area_id = self.next_area_id
        self.next_area_id += 1
        domain_prefix = self.area_domain_var.get().strip()
        if not domain_prefix:
            domain_prefix = "Domain"
        domain = f"{domain_prefix}_{area_id:03d}"
        row = {
            "area_id": area_id,
            "domain": domain,
            "area_shape": "rectangle",
            "x0": x0,
            "y0": y0,
            "x1": x1,
            "y1": y1,
            "row_min": rmin,
            "row_max": rmax,
            "column_min": cmin,
            "column_max": cmax,
            "source_n_rows": n_rows,
            "source_n_cols": n_cols,
        }
        rect_mask = np.ones((rmax - rmin + 1, cmax - cmin + 1), dtype=bool)
        skipped = []
        full_mask = np.zeros_like(self.current_z, dtype=bool)
        full_mask[rmin : rmax + 1, cmin : cmax + 1] = True
        xs_area, ys_area = self._current_grid_xy_for_mask(full_mask)
        for col in self._domain_layers_for_active_map():
            try:
                if self.maps_are_same_shape_as_current(col):
                    z = self.values[col]
                    subset = z[rmin : rmax + 1, cmin : cmax + 1]
                    vals = subset[np.isfinite(subset)]
                else:
                    vals = self._sample_layer_line_or_point(col, xs_area, ys_area, method="nearest")
                    vals = vals[np.isfinite(vals)]
            except Exception:
                skipped.append(col)
                continue
            if vals.size > 0:
                mean_val = float(np.nanmean(vals))
                std_val = float(np.nanstd(vals, ddof=1)) if vals.size > 1 else 0.0
                se_val = float(std_val / np.sqrt(vals.size)) if vals.size > 0 else np.nan
            else:
                mean_val = np.nan
                std_val = np.nan
                se_val = np.nan
            row[col] = mean_val
            row[f"{col}_std"] = std_val
            row[f"{col}_se"] = se_val
            row[f"{col}_n_valid"] = int(vals.size)
        self.area_masks[area_id] = rect_mask
        row["n_pixels"] = int(np.sum(rect_mask))
        output = pd.DataFrame([row])
        if self.area_df is None or self.area_df.empty:
            self.area_df = output
        else:
            self.area_df = pd.concat([self.area_df, output], ignore_index=True)
        left = min(x0, x1)
        right = max(x0, x1)
        bottom = min(y0, y1)
        top = max(y0, y1)
        self.area_segments.append(
            {
                "area_id": area_id,
                "domain": domain,
                "area_shape": "rectangle",
                "left": left,
                "right": right,
                "bottom": bottom,
                "top": top,
                "polygon_x": None,
                "polygon_y": None,
            }
        )
        self.draw_one_area_annotation(area_id, domain, left, right, bottom, top)
        self._redraw_all_extraction_overlays()
        msg = f"Domain {area_id} saved as '{domain}'."
        if skipped:
            msg += f" Skipped {len(skipped)} non-overlapping maps."
        self.status_var.set(msg)
        self._refresh_domain_export_choices()


    # enter lasso-domain drawing mode
    def start_lasso_area(self):
        if not self._map_loaded_for_tools():
            return
        self.active_mode = "lasso_area"
        self.pending_points = []
        try:
            self.status_var.set("Lasso mode: click polygon vertices, then Finish lasso.")
        except Exception:
            pass


    # remove the unfinished lasso outline
    def clear_lasso_preview(self):
        for artist in getattr(self, "lasso_preview_artists", []):
            try:
                artist.remove()
            except Exception:
                pass
        self.lasso_preview_artists = []
        if hasattr(self, "map_canvas"):
            self.map_canvas.draw_idle()


    # add the next vertex to the lasso domain
    def handle_lasso_area_click(self, x, y):
        self.pending_points.append((x, y))
        self.draw_lasso_preview()
        self.status_var.set(
            f"Lasso point {len(self.pending_points)} added. Add more points or click 'Finish lasso'."
        )


    # undo the most recent lasso point
    def undo_lasso_point(self):
        try:
            self._force_displayed_map_into_tool_state()
        except Exception:
            pass
        if self.active_mode != "lasso_area" or not self.pending_points:
            return
        self.pending_points.pop()
        self.draw_lasso_preview()
        self.status_var.set(
            f"Removed last lasso point. Points remaining: {len(self.pending_points)}."
        )


    # finish lasso area
    def finish_lasso_area(self):
        try:
            self._force_displayed_map_into_tool_state()
        except Exception:
            pass
        try:
            self._ensure_active_drawable_map()
        except Exception:
            pass
        try:
            if (
                getattr(self, "current_map_array", None) is None
                and getattr(self, "shared_coordinate_pixel_df", None) is not None
            ):
                self._activate_shared_xy_as_drawable_map()
        except Exception:
            pass
        if self.active_mode != "lasso_area":
            messagebox.showinfo("No active lasso", "Click 'Draw lasso' first.")
            return
        if len(self.pending_points) < 3:
            messagebox.showwarning("Too few points", "A lasso domain needs at least three points.")
            return
        vertices = list(self.pending_points)
        self.pending_points = []
        self.active_mode = None
        self.clear_lasso_preview()
        self.make_lasso_area_summary(vertices)


    # summarize channels inside one lasso domain
    def make_lasso_area_summary(self, vertices):
        frac_vertices = []
        for x, y in vertices:
            row_f, col_f = self.data_xy_to_fractional_indices(x, y)
            frac_vertices.append((col_f, row_f))
        cols = np.array([p[0] for p in frac_vertices], dtype=float)
        rows = np.array([p[1] for p in frac_vertices], dtype=float)
        n_rows, n_cols = self.current_z.shape
        rmin = max(0, int(np.floor(np.nanmin(rows))))
        rmax = min(n_rows - 1, int(np.ceil(np.nanmax(rows))))
        cmin = max(0, int(np.floor(np.nanmin(cols))))
        cmax = min(n_cols - 1, int(np.ceil(np.nanmax(cols))))
        if rmax < rmin or cmax < cmin:
            messagebox.showwarning("Bad lasso", "Selected lasso is outside the map.")
            return
        rr, cc = np.mgrid[rmin : rmax + 1, cmin : cmax + 1]
        test_points = np.column_stack([cc.ravel(), rr.ravel()])
        mask = MplPath(frac_vertices).contains_points(test_points).reshape(rr.shape)
        if not np.any(mask):
            messagebox.showwarning("Empty lasso", "The lasso did not include any pixel centers.")
            return
        area_id = self.next_area_id
        self.next_area_id += 1
        domain_prefix = self.area_domain_var.get().strip() or "Domain"
        domain = f"{domain_prefix}_{area_id:03d}"
        polygon_x = [p[0] for p in vertices]
        polygon_y = [p[1] for p in vertices]
        self.create_area_record_from_mask(
            area_id=area_id,
            domain=domain,
            area_shape="lasso",
            rmin=rmin,
            rmax=rmax,
            cmin=cmin,
            cmax=cmax,
            mask=mask,
            x0=float(np.nanmin(polygon_x)),
            y0=float(np.nanmin(polygon_y)),
            x1=float(np.nanmax(polygon_x)),
            y1=float(np.nanmax(polygon_y)),
            polygon_x=polygon_x,
            polygon_y=polygon_y,
        )


    # create one saved domain from a Boolean pixel mask
    def create_area_record_from_mask(
        self,
        area_id,
        domain,
        area_shape,
        rmin,
        rmax,
        cmin,
        cmax,
        mask,
        x0,
        y0,
        x1,
        y1,
        polygon_x=None,
        polygon_y=None,
    ):
        n_rows, n_cols = self.current_z.shape
        row = {
            "area_id": area_id,
            "domain": domain,
            "area_shape": area_shape,
            "x0": x0,
            "y0": y0,
            "x1": x1,
            "y1": y1,
            "row_min": rmin,
            "row_max": rmax,
            "column_min": cmin,
            "column_max": cmax,
            "source_n_rows": n_rows,
            "source_n_cols": n_cols,
            "polygon_x": "" if polygon_x is None else ";".join(map(str, polygon_x)),
            "polygon_y": "" if polygon_y is None else ";".join(map(str, polygon_y)),
        }
        skipped = []
        full_mask = np.zeros_like(self.current_z, dtype=bool)
        full_mask[rmin : rmax + 1, cmin : cmax + 1] = mask
        xs_area, ys_area = self._current_grid_xy_for_mask(full_mask)
        for col in self._domain_layers_for_active_map():
            try:
                if self.maps_are_same_shape_as_current(col):
                    z = self.values[col]
                    subset = z[rmin : rmax + 1, cmin : cmax + 1]
                    vals = subset[mask & np.isfinite(subset)]
                else:
                    vals = self._sample_layer_line_or_point(col, xs_area, ys_area, method="nearest")
                    vals = vals[np.isfinite(vals)]
            except Exception:
                skipped.append(col)
                continue
            if vals.size > 0:
                mean_val = float(np.nanmean(vals))
                std_val = float(np.nanstd(vals, ddof=1)) if vals.size > 1 else 0.0
                se_val = float(std_val / np.sqrt(vals.size)) if vals.size > 0 else np.nan
            else:
                mean_val = np.nan
                std_val = np.nan
                se_val = np.nan
            row[col] = mean_val
            row[f"{col}_std"] = std_val
            row[f"{col}_se"] = se_val
            row[f"{col}_n_valid"] = int(vals.size)
        row["n_pixels"] = int(np.sum(mask))
        output = pd.DataFrame([row])
        if self.area_df is None or self.area_df.empty:
            self.area_df = output
        else:
            self.area_df = pd.concat([self.area_df, output], ignore_index=True)
        self.area_masks[area_id] = mask.copy()
        self.area_segments.append(
            {
                "area_id": area_id,
                "domain": domain,
                "area_shape": area_shape,
                "left": x0,
                "right": x1,
                "bottom": y0,
                "top": y1,
                "polygon_x": polygon_x,
                "polygon_y": polygon_y,
            }
        )
        self.draw_one_area_annotation(
            area_id,
            domain,
            x0,
            x1,
            y0,
            y1,
            area_shape=area_shape,
            polygon_x=polygon_x,
            polygon_y=polygon_y,
        )
        self._redraw_all_extraction_overlays()
        msg = f"Domain {area_id} saved as '{domain}'."
        if skipped:
            msg += f" Skipped {len(skipped)} non-overlapping maps."
        self.status_var.set(msg)
        self._refresh_domain_export_choices()


    # redraw area annotations
    def redraw_area_annotations(self):
        for artist in self.area_artists:
            try:
                artist.remove()
            except Exception:
                pass
        self.area_artists = []
        for seg in self.area_segments:
            self.draw_one_area_annotation(
                seg["area_id"],
                seg["domain"],
                seg["left"],
                seg["right"],
                seg["bottom"],
                seg["top"],
                area_shape=seg.get("area_shape", "rectangle"),
                polygon_x=seg.get("polygon_x"),
                polygon_y=seg.get("polygon_y"),
            )


    # recalculates domain means from the pixels that are still included now.
    def _current_domain_summary_table(self, area_ids=None):
        pixels = self._build_domain_pixel_table(area_ids=area_ids)
        if pixels is None or pixels.empty:
            raise ValueError("No included pixels remain inside the selected domain.")
        if "area_id" not in pixels.columns and "domain_id" in pixels.columns:
            pixels = pixels.rename(columns={"domain_id": "area_id"})
        if "area_shape" not in pixels.columns and "domain_shape" in pixels.columns:
            pixels = pixels.rename(columns={"domain_shape": "area_shape"})

        group_columns = [
            name
            for name in ["sample_id", "mineral_id", "run_id", "area_id", "domain", "area_shape"]
            if name in pixels.columns
        ]
        if "area_id" not in group_columns:
            raise ValueError("The domain pixel table does not contain domain IDs.")
        value_columns = get_value_columns(pixels)
        rows = []
        grouped = pixels.groupby(group_columns, dropna=False, sort=False)
        for key, part in grouped:
            if not isinstance(key, tuple):
                key = (key,)
            row = dict(zip(group_columns, key))
            row["n_pixels"] = int(len(part))
            for column in value_columns:
                values = pd.to_numeric(part[column], errors="coerce").to_numpy(dtype=float)
                values = values[np.isfinite(values)]
                count = int(values.size)
                row[column] = float(np.nanmean(values)) if count else np.nan
                row[f"{column}_std"] = (
                    float(np.nanstd(values, ddof=1)) if count > 1 else (0.0 if count == 1 else np.nan)
                )
                row[f"{column}_se"] = (
                    float(row[f"{column}_std"] / np.sqrt(count)) if count else np.nan
                )
                row[f"{column}_n_valid"] = count
            rows.append(row)

        summary = pd.DataFrame(rows)
        if isinstance(self.area_df, pd.DataFrame) and not self.area_df.empty:
            geometry_columns = [
                column
                for column in [
                    "area_id", "x0", "y0", "x1", "y1", "row_min", "row_max",
                    "column_min", "column_max", "source_n_rows", "source_n_cols",
                    "polygon_x", "polygon_y",
                ]
                if column in self.area_df.columns
            ]
            if "area_id" in geometry_columns:
                geometry = self.area_df[geometry_columns].drop_duplicates("area_id")
                summary = summary.merge(geometry, on="area_id", how="left")
        return summary


    # export domain summaries as CSV
    def export_area_csv(self):
        if not isinstance(self.area_df, pd.DataFrame) or self.area_df.empty:
            messagebox.showinfo("No domains", "Draw one or more domains first.")
            return
        area_ids = self._selected_domain_ids_for_export()
        try:
            out = self._current_domain_summary_table(area_ids=area_ids)
        except Exception as exc:
            messagebox.showerror("Domain summary", str(exc))
            return
        if len(out) == 1:
            name = self.sanitize_filename_part(out.iloc[0].get("domain", "domain"))
            default_name = f"{name}_summary.csv"
        else:
            default_name = "domain_summary.csv"
        self.save_df_csv(out, default_name, "domain summary", export_kind="domain_summary")


    # export each selected domain as channel matrices
    def export_area_matrices(self):
        if self.area_df is None or self.area_df.empty:
            messagebox.showinfo("No domains", "Draw one or more domains first.")
            return
        folder = filedialog.askdirectory(title="Choose folder for domain matrices")
        if not folder:
            return
        folder = Path(folder)
        area_ids = self._selected_domain_ids_for_export()
        areas = self.area_df.copy()
        if area_ids is not None:
            areas = areas[pd.to_numeric(areas["area_id"], errors="coerce").isin(area_ids)].copy()
        if areas.empty:
            messagebox.showinfo("No domain", "The selected domain was not found.")
            return
        summary_rows = []
        exported_count = 0
        skipped_count = 0
        for _, area in areas.iterrows():
            area_id = int(area["area_id"])
            domain = self.sanitize_filename_part(area.get("domain", f"Domain_{area_id}"))
            rmin = int(area["row_min"])
            rmax = int(area["row_max"])
            cmin = int(area["column_min"])
            cmax = int(area["column_max"])
            source_n_rows = int(
                area.get(
                    "source_n_rows", self.current_z.shape[0] if self.current_z is not None else -1
                )
            )
            source_n_cols = int(
                area.get(
                    "source_n_cols", self.current_z.shape[1] if self.current_z is not None else -1
                )
            )
            for col in self._domain_layers_for_active_map():
                z = self.values[col]
                if z.shape[0] != source_n_rows or z.shape[1] != source_n_cols:
                    skipped_count += 1
                    continue
                subset = z[rmin : rmax + 1, cmin : cmax + 1].copy()
                mask = self.area_masks.get(area_id)
                if mask is not None and mask.shape == subset.shape:
                    subset = np.where(mask, subset, np.nan)
                clean_col = self.sanitize_filename_part(col)
                filename = f"domain_{area_id:03d}_{domain}_{clean_col}.csv"
                out_path = folder / filename
                pd.DataFrame(subset).to_csv(out_path, index=False, header=False)
                exported_count += 1
                vals = subset[np.isfinite(subset)]
                if vals.size > 0:
                    mean_val = float(np.nanmean(vals))
                    std_val = float(np.nanstd(vals, ddof=1)) if vals.size > 1 else 0.0
                    se_val = float(std_val / np.sqrt(vals.size)) if vals.size > 0 else np.nan
                else:
                    mean_val = np.nan
                    std_val = np.nan
                    se_val = np.nan
                summary_rows.append(
                    {
                        "area_id": area_id,
                        "domain": domain,
                        "column": col,
                        "matrix_file": filename,
                        "row_min": rmin,
                        "row_max": rmax,
                        "column_min": cmin,
                        "column_max": cmax,
                        "n_pixels_total": int(subset.size),
                        "n_valid": int(vals.size),
                        "mean": mean_val,
                        "std": std_val,
                        "se": se_val,
                    }
                )
        if summary_rows:
            summary_path = folder / "domain_matrix_summary.csv"
            self._write_csv(pd.DataFrame(summary_rows), summary_path)
        self.status_var.set(
            f"Exported {exported_count} domain matrices to {folder}. Skipped {skipped_count} non-matching maps."
        )
        messagebox.showinfo(
            "Domain matrices exported",
            f"Exported {exported_count} matrix file(s).\nSkipped {skipped_count} non-matching map(s).\n\nFolder:\n{folder}",
        )


    # stop lasso area
    def stop_lasso_area(self):
        try:
            if getattr(self, "active_mode", None) == "lasso_area":
                self.active_mode = None
            self.pending_points = []
            self.clear_lasso_preview()
            self.status_var.set("Stopped lasso drawing. Finished domains were kept.")
        except Exception:
            pass


    # draw lasso preview
    def draw_lasso_preview(self):
        self.clear_lasso_preview()
        if len(getattr(self, "pending_points", [])) == 0:
            return
        ax, canvas = (
            self._visible_map_ax_canvas()
            if hasattr(self, "_visible_map_ax_canvas")
            else (self.map_ax, self.map_canvas)
        )
        xs = [p[0] for p in self.pending_points]
        ys = [p[1] for p in self.pending_points]
        (artist,) = ax.plot(
            xs, ys, marker="o", linewidth=2.2, linestyle="--", color="black", zorder=10000
        )
        self.lasso_preview_artists.append(artist)
        if len(xs) >= 3:
            (close_artist,) = ax.plot(
                [xs[-1], xs[0]],
                [ys[-1], ys[0]],
                linewidth=1.5,
                linestyle=":",
                color="black",
                zorder=10000,
            )
            self.lasso_preview_artists.append(close_artist)
        canvas.draw_idle()


    # draw one area annotation
    def draw_one_area_annotation(
        self,
        area_id,
        domain,
        left,
        right,
        bottom,
        top,
        area_shape="rectangle",
        polygon_x=None,
        polygon_y=None,
    ):
        ax, canvas = (
            self._visible_map_ax_canvas()
            if hasattr(self, "_visible_map_ax_canvas")
            else (self.map_ax, self.map_canvas)
        )
        if ax is None:
            return
        if area_shape == "lasso" and polygon_x is not None and (polygon_y is not None):
            xs = list(polygon_x) + [polygon_x[0]]
            ys = list(polygon_y) + [polygon_y[0]]
            (artist,) = ax.plot(xs, ys, linewidth=2.8, color="black", zorder=10001)
            label_x, label_y = (polygon_x[0], polygon_y[0])
        else:
            xs = [left, right, right, left, left]
            ys = [bottom, bottom, top, top, bottom]
            (artist,) = ax.plot(xs, ys, linewidth=2.8, color="black", zorder=10001)
            label_x, label_y = (left, top)
        text_artist = ax.text(
            label_x,
            label_y,
            f"{area_id}: {domain}",
            fontsize=10,
            fontweight="bold",
            color="black",
            zorder=10002,
            bbox=dict(facecolor="white", alpha=0.88, edgecolor="black", linewidth=0.5, pad=1.5),
        )
        self.area_artists.append(artist)
        self.area_artists.append(text_artist)
        try:
            canvas.draw_idle()
        except Exception:
            pass


    # refresh domains shown in the export selector
    def _refresh_domain_export_choices(self):
        choices = ["All domains"]
        area_df = getattr(self, "area_df", None)
        if isinstance(area_df, pd.DataFrame) and not area_df.empty:
            for _, row in area_df.sort_values("area_id").iterrows():
                area_id = int(row["area_id"])
                domain = str(row.get("domain", f"Domain_{area_id:03d}"))
                choices.append(f"{area_id}: {domain}")
        combo = getattr(self, "domain_export_combo", None)
        if combo is not None:
            combo.configure(values=choices)
        var = getattr(self, "domain_export_var", None)
        current = str(var.get()).strip() if var is not None else "All domains"
        if var is not None and current not in choices:
            var.set("All domains")
        return choices


    # domain IDs currently selected for export
    def _selected_domain_ids_for_export(self):
        self._refresh_domain_export_choices()
        selection = str(self.domain_export_var.get()).strip()
        if not selection or selection == "All domains":
            return None
        try:
            return [int(selection.split(":", 1)[0].strip())]
        except (TypeError, ValueError):
            return None


    # domain layers used for active map
    def _domain_layers_for_active_map(self):
        layers = []
        current_layer = getattr(self, "current_column", None)
        if current_layer not in getattr(self, "values", {}):
            current_layer = getattr(self, "current_layer", None)
        current_meta = getattr(self, "current_meta", {}) or {}
        current_sample = str(current_meta.get("sample_id", getattr(self, "active_sample_id", "")))
        current_mineral = str(current_meta.get("mineral_id", current_meta.get("mineral_type", "")))
        current_run = str(current_meta.get("run_id", ""))
        for layer in self.selected_overlapping_map_columns():
            meta = self.metas.get(layer, {}) or {}
            sample = str(meta.get("sample_id", current_sample))
            mineral = str(meta.get("mineral_id", meta.get("mineral_type", current_mineral)))
            run = str(meta.get("run_id", current_run))
            if current_sample and sample and sample != current_sample:
                continue
            if current_mineral and mineral and mineral != current_mineral:
                continue
            if current_run and run and run != current_run:
                continue
            layers.append(layer)
        if current_layer in getattr(self, "values", {}) and current_layer not in layers:
            layers.insert(0, current_layer)
        return layers


    # build the per-pixel table for saved domains
    def _build_domain_pixel_table(self, area_ids=None):
        self._force_displayed_map_into_tool_state()
        area_df = getattr(self, "area_df", None)
        if not isinstance(area_df, pd.DataFrame) or area_df.empty:
            raise ValueError("Draw one or more domains first.")
        if getattr(self, "current_z", None) is None or getattr(self, "current_meta", None) is None:
            raise ValueError("Display the map used to draw the domains first.")
        selected = area_df.copy()
        if area_ids is not None:
            wanted = {int(value) for value in area_ids}
            selected = selected[pd.to_numeric(selected["area_id"], errors="coerce").isin(wanted)]
        if selected.empty:
            raise ValueError("The selected domain was not found.")

        z_shape = tuple(np.asarray(self.current_z).shape)
        n_rows, n_cols = z_shape
        x_grid, y_grid = self._layer_pixel_centers(self.current_meta, z_shape=z_shape)
        if x_grid is None or y_grid is None or np.shape(x_grid) != z_shape or np.shape(y_grid) != z_shape:
            yy, xx = np.indices(z_shape)
            x_grid = xx.astype(float)
            y_grid = yy.astype(float)
        else:
            x_grid = np.asarray(x_grid, dtype=float)
            y_grid = np.asarray(y_grid, dtype=float)

        layers = self._domain_layers_for_active_map()
        if not layers:
            raise ValueError("No map channels overlap the active map.")
        current_meta = getattr(self, "current_meta", {}) or {}
        sample_id = str(current_meta.get("sample_id", getattr(self, "active_sample_id", "")))
        mineral_id = str(current_meta.get("mineral_id", current_meta.get("mineral_type", "")))
        run_id = str(current_meta.get("run_id", ""))
        rows_out = []

        for _, area in selected.sort_values("area_id").iterrows():
            area_id = int(area["area_id"])
            mask = self.area_masks.get(area_id)
            if mask is None:
                continue
            rmin = int(area["row_min"])
            cmin = int(area["column_min"])
            rr_local, cc_local = np.where(np.asarray(mask, dtype=bool))
            rr = rr_local + rmin
            cc = cc_local + cmin
            inside = (rr >= 0) & (rr < n_rows) & (cc >= 0) & (cc < n_cols)
            rr = rr[inside]
            cc = cc[inside]
            if rr.size == 0:
                continue
            xs = x_grid[rr, cc]
            ys = y_grid[rr, cc]
            domain = str(area.get("domain", f"Domain_{area_id:03d}"))
            part = pd.DataFrame(
                {
                    "sample_id": sample_id,
                    "mineral_id": mineral_id,
                    "run_id": run_id,
                    "area_id": area_id,
                    "domain": domain,
                    "area_shape": str(area.get("area_shape", "area")),
                    "pixel_id": np.arange(1, rr.size + 1, dtype=int),
                    "row_index": rr.astype(int),
                    "column_index": cc.astype(int),
                    "x": xs.astype(float),
                    "y": ys.astype(float),
                }
            )
            for layer in layers:
                meta = self.metas.get(layer, {}) or {}
                try:
                    channel = _sample_layer_identity(meta, layer)[3]
                except Exception:
                    channel = self.canonical_layer_display_name(layer)
                try:
                    arr = np.asarray(self.values[layer], dtype=float)
                    if arr.shape == z_shape:
                        values = arr[rr, cc]
                    else:
                        values = self._sample_layer_line_or_point(layer, xs, ys, method="nearest")
                except Exception:
                    values = np.full(rr.size, np.nan)
                values = np.asarray(values, dtype=float)
                if channel in part.columns:
                    old_values = pd.to_numeric(part[channel], errors="coerce").to_numpy(dtype=float)
                    fill = ~np.isfinite(old_values) & np.isfinite(values)
                    old_values[fill] = values[fill]
                    part[channel] = old_values
                else:
                    part[channel] = values
            rows_out.append(part)

        if not rows_out:
            raise ValueError("No pixels were found inside the selected domain.")
        out = pd.concat(rows_out, ignore_index=True, sort=False)
        return self._prepare_export_dataframe(out, export_kind="domain_pixels")


    # switch the analysis source to area pixels
    def use_area_pixels_for_analysis(self):
        try:
            out = self._build_domain_pixel_table()
        except Exception as exc:
            messagebox.showerror("Domain pixels", str(exc))
            return None
        self.set_analysis_df(out, f"Domain pixels ({out['domain'].nunique()} domain(s))")
        self.status_var.set(f"Sent {len(out):,} domain pixels to the plot tabs.")
        return out


    # export all selected domain pixels as CSV
    def export_domain_pixels_csv(self):
        try:
            area_ids = self._selected_domain_ids_for_export()
            out = self._build_domain_pixel_table(area_ids=area_ids)
        except Exception as exc:
            messagebox.showerror("Domain pixels", str(exc))
            return None
        domains = out["domain"].dropna().astype(str).unique().tolist()
        if len(domains) == 1:
            default_name = f"{self.sanitize_filename_part(domains[0])}_pixels.csv"
        else:
            default_name = "domain_pixels.csv"
        self.save_df_csv(out, default_name, "domain pixels")
        return out


    # neighboring raster bins included in a buffered profile
    def _profile_buffer_bins(self):
        try:
            return max(int(float(self.profile_buffer_bins_var.get())), 2)
        except Exception:
            return 200


    # remove polyline artists for profile plots
    def _remove_profile_polyline_artists(self):
        for artist in getattr(self, "profile_polyline_artists", []):
            try:
                artist.remove()
            except Exception:
                pass
        self.profile_polyline_artists = []
        try:
            self.canvas.draw_idle()
        except Exception:
            pass


    # draw polyline preview for profile plots
    def _draw_profile_polyline_preview(self):
        ax, canvas = self._visible_map_ax_canvas()
        if ax is None:
            return
        self._remove_profile_polyline_artists()
        pts = list(getattr(self, "profile_polyline_points", []))
        if not pts:
            return
        xs = [p[0] for p in pts]
        ys = [p[1] for p in pts]
        if len(pts) == 1:
            (artist,) = ax.plot(xs, ys, marker="o", linestyle="", color="orange", zorder=9000)
            self.profile_polyline_artists.append(artist)
        else:
            (artist,) = ax.plot(xs, ys, marker="o", linewidth=2.5, color="orange", zorder=9000)
            self.profile_polyline_artists.append(artist)
        try:
            canvas.draw_idle()
        except Exception:
            pass


    # add the next vertex to the active multi-segment profile
    def handle_multi_segment_profile_click(self, x, y):
        pts = list(getattr(self, "profile_polyline_points", []))
        pts.append((float(x), float(y)))
        self.profile_polyline_points = pts
        self._draw_profile_polyline_preview()
        try:
            self.status_var.set(
                f"Added profile point {len(pts)}. Add more points or click Finish multi-segment profile."
            )
        except Exception:
            pass


    # route map clicks to whichever drawing tool is active
    def on_map_click(self, event):
        if getattr(self, "active_mode", None) == "multi_segment_profile":
            try:
                self._force_displayed_map_into_tool_state()
            except Exception:
                pass
            if event.inaxes != self.map_ax:
                return
            if event.xdata is None or event.ydata is None:
                return
            self.handle_multi_segment_profile_click(event.xdata, event.ydata)
            return
        return _on_map_click(self, event)


    # sample channels along the currently drawn line
    def make_line_profile(self, p0, p1):
        return _make_line_profile(self, p0, p1)


    # sample channels along a multi-segment profile
    def make_polyline_profile(self, points):
        points = [(float(x), float(y)) for x, y in points]
        if len(points) < 2:
            return
        buffer_px = self.get_profile_buffer_pixels()
        if buffer_px <= 0 and len(points) == 2:
            return _make_line_profile(self, points[0], points[1])
        line_id = self.next_line_id
        self.next_line_id += 1
        if buffer_px <= 0:
            pieces = []
            running_distance = 0.0
            for segment_index in range(len(points) - 1):
                x0, y0 = points[segment_index]
                x1, y1 = points[segment_index + 1]
                row0, col0 = self.data_xy_to_fractional_indices(x0, y0)
                row1, col1 = self.data_xy_to_fractional_indices(x1, y1)
                n_samples = max(int(max(abs(col1 - col0), abs(row1 - row0))) + 1, 2)
                xs = np.linspace(x0, x1, n_samples)
                ys = np.linspace(y0, y1, n_samples)
                rows = np.linspace(row0, row1, n_samples)
                cols = np.linspace(col0, col1, n_samples)
                segment_distance = np.sqrt((xs - xs[0]) ** 2 + (ys - ys[0]) ** 2)
                if segment_index > 0:
                    xs = xs[1:]
                    ys = ys[1:]
                    rows = rows[1:]
                    cols = cols[1:]
                    segment_distance = segment_distance[1:]
                pieces.append(
                    pd.DataFrame(
                        {
                            "x": xs,
                            "y": ys,
                            "row_fractional": rows,
                            "column_fractional": cols,
                            "distance": running_distance + segment_distance,
                        }
                    )
                )
                running_distance += float(segment_distance[-1]) if len(segment_distance) else 0.0
            output = pd.concat(pieces, ignore_index=True) if pieces else pd.DataFrame()
            if output.empty:
                return
            total_length = float(output["distance"].max()) if len(output) else 0.0
            output.insert(0, "line_id", line_id)
            output.insert(1, "point_id", np.arange(1, len(output) + 1))
            output["n_points_in_line"] = len(output)
            output["line_total_length"] = total_length
            output["distance_normalized"] = (
                output["distance"] / total_length if total_length > 0 else 0.0
            )
            output["profile_kind"] = "multi_segment_centerline"
            output["profile_buffer_pixels"] = 0
            output["perpendicular_distance_pixels"] = 0.0
            for col in self._domain_layers_for_active_map():
                try:
                    output[col] = self._sample_layer_line_or_point(
                        col, output["x"].to_numpy(), output["y"].to_numpy(), method="bilinear"
                    )
                except Exception:
                    pass
        else:
            pixel_df = self._current_pixel_center_table()
            if pixel_df is None or pixel_df.empty:
                messagebox.showerror(
                    "No map pixels", "Could not build the pixel table for this map."
                )
                return
            output = _polyline_pixel_distance_table(self, pixel_df, points)
            corridor_radius = float(buffer_px)
            output = output[
                np.isfinite(output["perpendicular_distance_pixels"])
                & (output["perpendicular_distance_pixels"] <= corridor_radius)
            ].copy()
            if output.empty:
                messagebox.showinfo(
                    "No pixels in buffer", "No pixels fall inside the chosen profile buffer."
                )
                return
            output = output.sort_values(
                ["distance", "perpendicular_distance_pixels", "row_index", "column_index"]
            ).reset_index(drop=True)
            output.insert(0, "line_id", line_id)
            output.insert(1, "point_id", np.arange(1, len(output) + 1))
            output["n_points_in_line"] = len(output)
            output["profile_kind"] = "buffered_polyline_pixels"
            output["profile_buffer_pixels"] = int(buffer_px)
            bins = max(int(getattr(self, "_profile_buffer_bins", lambda: 200)()), 2)
            output["distance_bin"] = pd.cut(
                output["distance_normalized"],
                bins=np.linspace(0, 1, bins + 1),
                include_lowest=True,
                labels=False,
            )
            rr = output["row_index"].to_numpy(dtype=int)
            cc = output["column_index"].to_numpy(dtype=int)
            for col in self._domain_layers_for_active_map():
                try:
                    if self.maps_are_same_shape_as_current(col):
                        output[col] = np.asarray(self.values[col], dtype=float)[rr, cc]
                    else:
                        output[col] = self._sample_layer_line_or_point(
                            col, output["x"].to_numpy(), output["y"].to_numpy(), method="nearest"
                        )
                except Exception:
                    pass
        if self.line_profile_df is None or self.line_profile_df.empty:
            self.line_profile_df = output
        else:
            self.line_profile_df = pd.concat([self.line_profile_df, output], ignore_index=True)
        for i in range(len(points) - 1):
            x0, y0 = points[i]
            x1, y1 = points[i + 1]
            self.line_segments.append(
                {
                    "line_id": line_id,
                    "segment_id": i + 1,
                    "x0": x0,
                    "y0": y0,
                    "x1": x1,
                    "y1": y1,
                    "profile_buffer_pixels": int(buffer_px),
                }
            )
            self.draw_one_line_annotation(line_id, x0, y0, x1, y1)
        try:
            self._redraw_all_extraction_overlays()
        except Exception:
            pass
        try:
            self.refresh_profile_list()
        except Exception:
            pass
        try:
            if buffer_px > 0:
                try:
                    max_perp = float(
                        pd.to_numeric(
                            output["perpendicular_distance_pixels"], errors="coerce"
                        ).max()
                    )
                    unique_pixels = (
                        int(output[["row_index", "column_index"]].drop_duplicates().shape[0])
                        if {"row_index", "column_index"}.issubset(output.columns)
                        else len(output)
                    )
                    self.status_var.set(
                        f"Buffered profile {line_id}: {unique_pixels:,} unique pixels within <= {buffer_px} px of the line; max perpendicular distance = {max_perp:.3g} px."
                    )
                except Exception:
                    self.status_var.set(
                        f"Buffered profile {line_id}: {len(output):,} pixels within <= {buffer_px} px of the line."
                    )
            else:
                self.status_var.set(f"Profile {line_id}: {len(output)} samples.")
        except Exception:
            pass


    # buffer width used by radial grain profiles
    def get_radial_profile_buffer_pixels(self):
        var = getattr(self, "radial_profile_buffer_pixels_var", None)
        try:
            value = int(round(float(var.get()))) if hasattr(var, "get") else 0
        except Exception:
            value = 0
        return max(0, min(value, 100))



    # calculated channels
    # Creates new channels and carries them back into compatible map layers.


    # calculated phase points from active table
    def calculated_phase_points_from_active_table(
        self, mineral, value_col, rule="finite", threshold=0.0
    ):
        df = self.get_active_pixel_table()
        if df is None or df.empty:
            return None
        group_col = self.active_table_group_column(df)
        col = self.active_table_column_match(value_col, df)
        if group_col is None or col is None:
            return None
        mineral = str(mineral).strip()
        try:
            if hasattr(self, "_resolve_mineral_group_name"):
                mineral = self._resolve_mineral_group_name(mineral)
        except Exception:
            pass
        groups = df[group_col].astype(str).str.strip()
        mask_group = groups.str.lower() == mineral.lower()
        if not mask_group.any():
            clean_target = re.sub("[^a-z0-9]+", "", mineral.lower())
            mask_group = groups.apply(
                lambda v: re.sub("[^a-z0-9]+", "", str(v).lower()) == clean_target
            )
        if not mask_group.any():
            return None
        sub = df.loc[mask_group].copy()
        vals = pd.to_numeric(sub[col], errors="coerce").to_numpy(dtype=float)
        valid = np.isfinite(vals)
        if rule == ">0":
            valid &= vals > 0
        elif rule == ">custom":
            valid &= vals > float(threshold)
        if not np.any(valid):
            return {
                "mineral": mineral,
                "value_col": col,
                "layer": f"active_table:{col}",
                "coords": np.empty((0, 2)),
                "values": np.asarray([], dtype=float),
                "spacing": 1.0,
                "n_pixels": 0,
            }
        if "x" in sub.columns and "y" in sub.columns:
            x = pd.to_numeric(sub["x"], errors="coerce").to_numpy(dtype=float)
            y = pd.to_numeric(sub["y"], errors="coerce").to_numpy(dtype=float)
        elif "X" in sub.columns and "Y" in sub.columns:
            x = pd.to_numeric(sub["X"], errors="coerce").to_numpy(dtype=float)
            y = pd.to_numeric(sub["Y"], errors="coerce").to_numpy(dtype=float)
        else:
            x = pd.to_numeric(
                sub.get("column_index", pd.Series(np.arange(len(sub)))), errors="coerce"
            ).to_numpy(dtype=float)
            y = pd.to_numeric(
                sub.get("row_index", pd.Series(np.arange(len(sub)))), errors="coerce"
            ).to_numpy(dtype=float)
        coord_ok = np.isfinite(x) & np.isfinite(y) & valid
        coords = np.column_stack([x[coord_ok], y[coord_ok]])
        values = vals[coord_ok]
        try:
            spacing = self._median_xy_spacing(coords[:, 0], coords[:, 1]) if len(coords) else 1.0
        except Exception:
            spacing = 1.0
        if not np.isfinite(spacing) or spacing <= 0:
            spacing = 1.0
        return {
            "mineral": mineral,
            "value_col": col,
            "layer": f"active_table:{col}",
            "coords": coords,
            "values": values.astype(float),
            "spacing": float(spacing),
            "n_pixels": int(values.size),
        }


    # switch the analysis source to all map pixels
    def use_all_pixels_for_analysis(self):
        active = getattr(self, "active_sample_id", None)
        if not active or active == "__EMPTY__":
            messagebox.showinfo("No sample", "Load or select a sample first.")
            return None
        try:
            table = _sample_build_combined_pixel_table(self, [active])
            self.set_analysis_df(table, f"All pixels from sample {active}")
            try:
                self.xy_color_by_var.set("mineral_id")
            except Exception:
                pass
            self.status_var.set(f"Using {len(table):,} pixels from active sample {active}.")
            return table
        except Exception as exc:
            messagebox.showerror("Active sample pixels", str(exc))
            return None


    # switch the analysis source to all pixel mean
    def use_all_pixel_mean_for_analysis(self):
        """Use one map-wide mean point and retain uncertainty companions."""
        active = getattr(self, "active_sample_id", None)
        if not active or active == "__EMPTY__":
            messagebox.showinfo("No sample", "Load or select a sample first.")
            return None
        try:
            pixels = _sample_build_combined_pixel_table(self, [active])
            value_columns = get_value_columns(pixels)
            row = {
                "sample_id": str(active),
                "mineral_id": "All minerals",
                "run_id": "All runs",
                "source_kind": "map_mean",
                "group_label": f"{active} map mean",
                "n_pixels": int(len(pixels)),
                "source_row_count": int(len(pixels)),
            }
            finite_channels = 0
            for column in value_columns:
                values = pd.to_numeric(pixels[column], errors="coerce")
                values = values[np.isfinite(values)]
                if values.empty:
                    continue
                count = int(values.size)
                mean = float(values.mean())
                sd = float(values.std(ddof=1)) if count > 1 else np.nan
                one_se = sd / np.sqrt(count) if count > 1 and np.isfinite(sd) else np.nan
                row[str(column)] = mean
                row[f"{column}_sd"] = sd
                row[f"{column}_1se"] = one_se
                row[f"{column}_2se"] = 2.0 * one_se if np.isfinite(one_se) else np.nan
                row[f"{column}_n"] = count
                finite_channels += 1
            if finite_channels == 0:
                raise ValueError("No numeric map channels contain finite pixel values.")
            table = pd.DataFrame([row])
            self.set_analysis_df(table, f"Mean of all pixels from sample {active}")
            try:
                self.xy_color_by_var.set("sample_id")
            except Exception:
                pass
            self.status_var.set(
                f"Using one map-mean point from {len(pixels):,} pixel rows in sample {active}."
            )
            return table
        except Exception as exc:
            messagebox.showerror("Map mean", str(exc))
            return None


    # refresh all controls that depend on analysis columns
    def refresh_analysis_columns(self):
        # Refresh controls from the unfiltered source table. Plot filters and
        # grouped summaries are applied only when a plot is made; they must not
        # replace the source data.
        df = _raw_analysis_source_table(self)
        if df is None:
            self.all_value_columns = []
            self.value_columns = []
        else:
            self.all_value_columns = get_value_columns(df)
            self.value_columns = [
                col
                for col in self.all_value_columns
                if col not in getattr(self, "excluded_columns", set())
            ]
        for method_name in [
            "refresh_exclude_list",
            "refresh_math_lists",
            "refresh_profile_list",
            "refresh_xy_controls",
            "refresh_ternary_controls",
            "refresh_kde_controls",
            "refresh_comparison_controls",
            "refresh_mineral_stats_controls",
            "refresh_grain_controls",
            "refresh_compare_grain_controls",
            "refresh_corr_list",
            "refresh_pca_list",
            "refresh_geochron_controls",
        ]:
            try:
                if hasattr(self, method_name):
                    getattr(self, method_name)()
            except Exception:
                pass
        try:
            self.refresh_column_alias_controls()
        except Exception:
            pass
        try:
            if df is None:
                self.analysis_info_var.set("No active analysis table.")
            else:
                self.analysis_info_var.set(
                    f"{getattr(self, 'analysis_source_name', 'Active data')}\nRows: {len(df):,}\nAll columns: {len(df.columns)}\nPlot columns: {len(self.value_columns)}\nExcluded: {len(getattr(self, 'excluded_columns', set()))}"
                )
        except Exception:
            pass


    # add a calculated column to the comparison table
    def create_comparison_calculated_column(self, new_col, equation):
        if self.comparison_df is None or self.comparison_df.empty:
            raise ValueError("No comparison data loaded.")
        local_dict = {
            "np": np,
            "log": np.log,
            "log10": np.log10,
            "sqrt": np.sqrt,
            "abs": np.abs,
            "sin": np.sin,
            "cos": np.cos,
            "tan": np.tan,
            "exp": np.exp,
        }
        with np.errstate(divide="ignore", invalid="ignore"):
            result = self.comparison_df.eval(equation, engine="python", local_dict=local_dict)
        result = pd.to_numeric(result, errors="coerce")
        result = result.replace([np.inf, -np.inf], np.nan)
        if len(result) != len(self.comparison_df):
            raise ValueError("Equation result length does not match comparison table length.")
        self.comparison_df[new_col] = result
        self.refresh_comparison_controls()
        try:
            self.refresh_compare_grain_controls()
            self.refresh_mineral_stats_controls()
        except Exception:
            pass
        if hasattr(self, "compare_col_var"):
            self.compare_col_var.set(new_col)
        if hasattr(self, "compare_x_col_var"):
            self.compare_x_col_var.set(new_col)
        self.write_results(
            f"Created comparison calculated column:\n\n{new_col} = {equation}\n\nSummary:\n{self.comparison_df[new_col].describe().to_string()}"
        )
        self.status_var.set(f"Created comparison calculated column: {new_col}")


    # full table used to evaluate calculated-channel equations
    def _get_full_calculation_table(self):
        for attr in ("active_analysis_df", "analysis_df", "comparison_df"):
            df = getattr(self, attr, None)
            if isinstance(df, pd.DataFrame) and not df.empty:
                return df
        return None


    # operand names available to calculated-channel equations
    def _calculation_operand_names(self, definition, df=None):
        upb_operands = [name for name in _upb_definition_operands(definition) if name]
        if upb_operands:
            return upb_operands
        if definition.get("kind") == "simple":
            return [str(definition.get("col_a", "")), str(definition.get("col_b", ""))]
        equation = str(definition.get("equation", ""))
        names = list(dict.fromkeys(re.findall("`([^`]+)`", equation)))
        candidates = []
        if isinstance(df, pd.DataFrame):
            candidates.extend([str(c) for c in df.columns])
        try:
            candidates.extend(self.get_canonical_map_columns())
        except Exception:
            pass
        try:
            candidates.extend(list(getattr(self, "calculated_channel_definitions", {}).keys()))
        except Exception:
            pass
        for name in sorted(set(candidates), key=len, reverse=True):
            if not name or name in names:
                continue
            if re.search(f"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])", equation):
                names.append(name)
        return names


    # evaluate one saved calculated-channel definition on a table
    def _evaluate_definition_on_dataframe(self, df, definition):
        return _calculate_column_values(self, df, definition)


    # tables and map layers that can receive a calculated channel.
    def _calculation_contexts(self):
        contexts = {}
        try:
            idx = self.rebuild_mineral_column_index()
        except Exception:
            idx = {}
        for mineral, colmap in (idx or {}).items():
            clean_map = {
                str(c): layer for c, layer in colmap.items() if layer in getattr(self, "values", {})
            }
            if clean_map:
                mineral_group = str(mineral)
                map_group = ""
                mineral_type = mineral_group
                try:
                    map_group, mineral_type, mineral_group = self._split_mineral_group_label(
                        mineral_group
                    )
                except Exception:
                    if " :: " in mineral_group:
                        map_group, mineral_type = [s.strip() for s in mineral_group.split(" :: ", 1)]
                    else:
                        map_group = ""
                        mineral_type = mineral_group
                contexts[f"mineral::{mineral_group}"] = {
                    "label": str(mineral_group),
                    "map_group": str(map_group),
                    "comparison_dataset": str(map_group),
                    "mineral_type": str(mineral_type),
                    "mineral_group": str(mineral_group),
                    "columns": clean_map,
                }
        if contexts:
            return contexts
        grouped = {}
        for layer, arr in getattr(self, "values", {}).items():
            meta = getattr(self, "metas", {}).get(layer, {}) or {}
            if meta.get("calculated_channel"):
                pass
            mineral = str(meta.get("mineral_type", "")).strip()
            coord = str(
                meta.get("coordinate_group_key", "") or meta.get("import_group_key", "") or "map"
            )
            key = f"map::{mineral}::{coord}"
            canon = self.canonical_layer_display_name(meta.get("canonical_column", layer))
            grouped.setdefault(key, {"label": mineral or coord, "mineral_type": mineral, "columns": {}})
            grouped[key]["columns"].setdefault(canon, layer)
        existing_signatures = {tuple(sorted(rec["columns"].items())) for rec in contexts.values()}
        for key, rec in grouped.items():
            signature = tuple(sorted(rec["columns"].items()))
            if rec["columns"] and signature not in existing_signatures:
                contexts[key] = rec
                existing_signatures.add(signature)
        return contexts


    # write a calculated channel into its target tables and maps.
    def _materialize_calculated_channel(self, definition):
        new_col = str(definition["new_col"])
        contexts = self._calculation_contexts()
        made = []
        made_contexts = set()
        skipped = []
        for context_key, rec in contexts.items():
            colmap = rec["columns"]
            try:
                z, operands = _compute_definition_on_map_context(self, definition, colmap)
            except KeyError as exc:
                skipped.append((rec.get("label", context_key), f"missing {exc}"))
                continue
            except Exception as exc:
                skipped.append((rec.get("label", context_key), str(exc)))
                continue
            base_layer = colmap[operands[0]]
            meta = dict(getattr(self, "metas", {}).get(base_layer, {}) or {})
            meta.update(
                {
                    "kind": "persistent_calculated_channel",
                    "calculated_channel": True,
                    "calculated_channel_name": new_col,
                    "calculation_context_key": str(context_key),
                    "calculation_definition": dict(definition),
                    "calculation_dependencies": list(operands),
                    "canonical_column": new_col,
                    "source_layer_name": new_col,
                    "source_file": "Calculated channel",
                    "map_group": rec.get("map_group", meta.get("map_group", "")),
                    "comparison_dataset": rec.get(
                        "comparison_dataset",
                        rec.get("map_group", meta.get("comparison_dataset", meta.get("map_group", ""))),
                    ),
                    "mineral_type": rec.get("mineral_type", meta.get("mineral_type", "")),
                    "mineral_group": rec.get(
                        "mineral_group", rec.get("label", meta.get("mineral_group", ""))
                    ),
                }
            )
            layer = _find_existing_calculated_layer(self, new_col, context_key)
            if layer is None:
                layer = (
                    self.unique_layer_name(new_col) if hasattr(self, "unique_layer_name") else new_col
                )
            self.values[layer] = z
            self.metas[layer] = meta
            try:
                self.layer_mineral_type[layer] = meta.get("mineral_type", "")
            except Exception:
                pass
            made.append(layer)
            made_contexts.add(str(context_key))
        stale_layers = []
        for layer, meta in list(getattr(self, "metas", {}).items()):
            if not isinstance(meta, dict):
                continue
            if str(meta.get("calculated_channel_name", "")) != new_col:
                continue
            if str(meta.get("calculation_context_key", "")) not in made_contexts:
                stale_layers.append(layer)
        for layer in stale_layers:
            self.values.pop(layer, None)
            self.metas.pop(layer, None)
            try:
                self.layer_mineral_type.pop(layer, None)
            except Exception:
                pass
        self.calculated_channel_definitions = getattr(self, "calculated_channel_definitions", {}) or {}
        if made:
            self.calculated_channel_definitions[new_col] = dict(definition)
            try:
                self.rebuild_mineral_presence_groups_from_metadata()
            except Exception:
                pass
            try:
                self.rebuild_mineral_column_index()
            except Exception:
                pass
            try:
                self.refresh_map_column_combo(preserve=True)
            except Exception:
                pass
            try:
                self.refresh_map_view_mineral_list()
            except Exception:
                pass
        else:
            self.calculated_channel_definitions.pop(new_col, None)
        return (made, skipped)


    # copy a calculated channel into matching sample workspaces
    def _propagate_persistent_channel(self, channel, definition, skip_ids=None):
        attrs = [
            "analysis_df",
            "active_analysis_df",
            "comparison_df",
            "_full_analysis_df_for_plotting",
            "current_analysis_df",
            "last_analysis_df",
            "selected_pixels_df",
            "shared_coordinate_pixel_df",
            "line_profile_df",
            "spot_df",
            "area_df",
            "area_pixel_df",
            "last_grain_pixel_df",
            "last_grain_table_df",
            "last_grain_df",
            "last_grain_radial_profile_pixels_df",
            "last_grain_radial_profile_bins_df",
            "last_grain_radial_pixel_df",
            "last_grain_radial_bin_df",
            "manual_grain_merge_groups",
        ]
        skipped_ids = set(skip_ids or [])
        seen_ids = set()
        changed = 0
        for attr in attrs:
            df = getattr(self, attr, None)
            if (
                not isinstance(df, pd.DataFrame)
                or df.empty
                or id(df) in seen_ids
                or id(df) in skipped_ids
            ):
                continue
            seen_ids.add(id(df))
            try:
                updated = _sample_persistent_channel_to_df(self, df, channel, definition)
                if channel in updated.columns:
                    setattr(self, attr, updated)
                    changed += 1
            except Exception:
                pass
        return changed


    # normalize columns before combining mineral-analysis tables
    def normalize_multimineral_analysis_columns(self, df):
        out = _normalize_multimineral_table(self, df)
        if out is None or not isinstance(out, pd.DataFrame) or out.empty:
            return out
        registry = getattr(self, "calculated_channel_definitions", {}) or {}
        for channel in registry.keys():
            matches = [
                c for c in out.columns if self.canonical_layer_display_name(c) == str(channel)
            ]
            if not matches:
                continue
            if len(matches) == 1 and str(matches[0]) == str(channel):
                continue
            tmp = pd.DataFrame(index=out.index)
            for c in matches:
                tmp[str(c)] = pd.to_numeric(out[c], errors="coerce")
            out[str(channel)] = tmp.bfill(axis=1).iloc[:, 0]
            for c in matches:
                if str(c) != str(channel):
                    out = out.drop(columns=[c], errors="ignore")
        return out


    # create a calculated channel from column A, an operator, and column B.
    def create_simple_calculated_column(self):
        df = self._get_full_calculation_table()
        if df is None:
            messagebox.showinfo("No data", "Load maps and create an analysis table first.")
            return
        try:
            definition = {
                "kind": "simple",
                "new_col": self.clean_new_column_name(self.simple_new_col_var.get()),
                "col_a": str(self.simple_col_a_var.get()),
                "col_b": str(self.simple_col_b_var.get()),
                "op": str(self.simple_op_var.get()),
            }
            result = _calculate_column_values(self, df, definition)
            made, skipped = _finish_persistent_calculation(self, definition, result)
            new_col = definition["new_col"]
            formula = f"{definition['col_a']} {definition['op']} {definition['col_b']}"
            self.write_results(
                f"Created calculated channel:\n\n{new_col} = {formula}\n\nMap layers created/updated: {len(made)}\n\nSummary:\n{result.describe().to_string()}"
            )
            if made:
                messagebox.showinfo(
                    "Calculated channel saved",
                    f"Created '{new_col}' in {len(made)} map layer(s). It is available throughout the project.",
                )
            else:
                messagebox.showwarning(
                    "Calculated table column only",
                    f"Created '{new_col}' in the active table. It cannot be drawn as a map because its source channels are not on one grid.",
                )
            self.status_var.set(
                f"Created persistent calculated channel: {new_col} | {len(made)} map layer(s)"
            )
        except Exception as exc:
            messagebox.showerror("Could not create calculated channel", str(exc))


    # create a calculated channel from the typed equation
    def create_custom_calculated_column(self):
        df = self._get_full_calculation_table()
        if df is None:
            messagebox.showinfo("No data", "Load maps and create an analysis table first.")
            return
        try:
            definition = {
                "kind": "custom",
                "new_col": self.clean_new_column_name(self.custom_new_col_var.get()),
                "equation": self.custom_equation_text.get("1.0", tk.END).strip(),
            }
            if not definition["equation"]:
                raise ValueError("Equation cannot be blank.")
            result = _calculate_column_values(self, df, definition)
            made, skipped = _finish_persistent_calculation(self, definition, result)
            new_col = definition["new_col"]
            self.write_results(
                f"Created calculated channel:\n\n{new_col} = {definition['equation']}\n\nMap layers created/updated: {len(made)}\n\nSummary:\n{result.describe().to_string()}"
            )
            if made:
                messagebox.showinfo(
                    "Calculated channel saved",
                    f"Created '{new_col}' in {len(made)} map layer(s). It is available throughout the project.",
                )
            else:
                messagebox.showwarning(
                    "Calculated table column only",
                    f"Created '{new_col}' in the active table. It cannot be drawn as a map because its source channels are not on one grid.",
                )
            self.status_var.set(
                f"Created persistent calculated channel: {new_col} | {len(made)} map layer(s)"
            )
        except Exception as exc:
            messagebox.showerror(
                "Could not evaluate calculated channel",
                f"{exc}\n\nFor column names with spaces, use backticks, for example:\n`U238_ppm` / `Th232_ppm`",
            )


    # save overlay figure to path for mineral analysis
    def _save_mineral_overlay_figure_to_path(self, path):
        ext = os.path.splitext(path)[1].lower()
        if ext == ".png":
            self.mineral_overlay_fig.savefig(
                path,
                dpi=300,
                bbox_inches="tight",
                transparent=True,
                facecolor="none",
                edgecolor="none",
            )
            return
        if ext == ".pdf":
            import tempfile
            from PIL import Image

            with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as tmp:
                tmp_png = tmp.name
            self.mineral_overlay_fig.savefig(
                tmp_png,
                dpi=600,
                bbox_inches="tight",
                transparent=False,
                facecolor="white",
                edgecolor="none",
            )
            img = Image.open(tmp_png).convert("RGB")
            w_px, h_px = img.size
            dpi = 300.0
            fig_w = w_px / dpi
            fig_h = h_px / dpi
            pdf_fig = plt.Figure(figsize=(fig_w, fig_h), constrained_layout=False)
            pdf_ax = pdf_fig.add_axes([0, 0, 1, 1])
            pdf_ax.imshow(img)
            pdf_ax.axis("off")
            pdf_fig.savefig(path, dpi=dpi, bbox_inches="tight", pad_inches=0)
            try:
                os.remove(tmp_png)
            except Exception:
                pass
            return
        self.mineral_overlay_fig.savefig(path, bbox_inches="tight", dpi=300)


    # boundary buffer pixel width lookup
    def get_boundary_buffer_pixel_width(self):
        try:
            return max(1, int(round(float(self.boundary_buffer_pixels_var.get()))))
        except Exception:
            return 5


    # selected nearest-neighbor or mineral pairs lookup
    def get_selected_nn_or_mineral_pairs(self, respect_pair_dropdown=True):
        selected_pair = ""
        try:
            selected_pair = self.mineral_stats_nn_pair_var.get()
        except Exception:
            selected_pair = ""
        if respect_pair_dropdown and selected_pair and (selected_pair != "All NN/selected pairs"):
            try:
                parsed = self._parse_boundary_pair_label(selected_pair)
                if parsed:
                    return [parsed]
            except Exception:
                pass
        pairs = []
        df = getattr(self, "last_mineral_nn_df", None)
        if (
            df is not None
            and isinstance(df, pd.DataFrame)
            and (not df.empty)
            and {"from_group", "to_group"}.issubset(df.columns)
        ):
            seen = set()
            for _, row in df.iterrows():
                try:
                    a = (
                        self._resolve_mineral_group_name(row["from_group"])
                        if hasattr(self, "_resolve_mineral_group_name")
                        else str(row["from_group"])
                    )
                    b = (
                        self._resolve_mineral_group_name(row["to_group"])
                        if hasattr(self, "_resolve_mineral_group_name")
                        else str(row["to_group"])
                    )
                except Exception:
                    a = str(row.get("from_group", "")).strip()
                    b = str(row.get("to_group", "")).strip()
                if not a or not b or a == b:
                    continue
                key = tuple(sorted([a, b]))
                if key not in seen:
                    seen.add(key)
                    pairs.append((key[0], key[1]))
        if pairs:
            return pairs
        groups = []
        try:
            groups = list(self._selected_mineral_stat_groups())
        except Exception:
            groups = []
        resolved = []
        for g in groups:
            try:
                rg = (
                    self._resolve_mineral_group_name(g)
                    if hasattr(self, "_resolve_mineral_group_name")
                    else str(g).strip()
                )
            except Exception:
                rg = str(g).strip()
            if rg and rg not in resolved:
                resolved.append(rg)
        for i in range(len(resolved)):
            for j in range(i + 1, len(resolved)):
                pairs.append((resolved[i], resolved[j]))
        return pairs


    # refresh nearest-neighbor pair combo for mineral analysis
    def refresh_mineral_nn_pair_combo(self, reset_to_all=True):
        if not hasattr(self, "mineral_stats_nn_pair_combo"):
            return
        pairs = self.get_selected_nn_or_mineral_pairs(respect_pair_dropdown=False)
        options = ["All NN/selected pairs"] + [f"{a} ↔ {b}" for a, b in pairs]
        try:
            old = self.mineral_stats_nn_pair_var.get()
        except Exception:
            old = ""
        try:
            self.mineral_stats_nn_pair_combo.configure(values=options)
            if reset_to_all:
                self.mineral_stats_nn_pair_var.set("All NN/selected pairs")
            elif old in options:
                self.mineral_stats_nn_pair_var.set(old)
            else:
                self.mineral_stats_nn_pair_var.set("All NN/selected pairs")
            try:
                self.mineral_stats_info_var.set(
                    f"Boundary-buffer pair list refreshed: {len(pairs)} pair(s)."
                )
            except Exception:
                pass
        except Exception:
            pass


    # mineral groups currently available for analysis
    def _available_mineral_group_names(self):
        names = set()
        try:
            self.rebuild_mineral_presence_groups_from_metadata()
            names.update(
                (
                    str(k).strip()
                    for k in getattr(self, "mineral_presence_groups", {}).keys()
                    if str(k).strip()
                )
            )
        except Exception:
            pass
        try:
            groups = self.get_mineral_group_layers()
            names.update((str(k).strip() for k in groups.keys() if str(k).strip()))
        except Exception:
            pass
        try:
            idx = (
                self.rebuild_mineral_column_index()
                if hasattr(self, "rebuild_mineral_column_index")
                else getattr(self, "mineral_column_index", {})
            )
            names.update((str(k).strip() for k in idx.keys() if str(k).strip()))
        except Exception:
            pass
        return sorted(names)


    # resolve group name for mineral analysis
    def _resolve_mineral_group_name(self, name):
        if name is None:
            return None
        raw = str(name).strip()
        if not raw:
            return None
        available = self._available_mineral_group_names()
        if raw in available:
            return raw
        raw_key = re.sub("\\s+", " ", raw).strip().lower()
        for g in available:
            g_key = re.sub("\\s+", " ", str(g)).strip().lower()
            if g_key == raw_key:
                return g
        raw_key2 = re.sub("[^a-z0-9]+", "", raw_key)
        for g in available:
            g_key2 = re.sub("[^a-z0-9]+", "", str(g).lower())
            if g_key2 == raw_key2:
                return g
        return raw



    # mineral and boundary summaries
    # Plots and exports mineral fractions, element totals, and boundary chemistry.


    # plot boundary buffer chemistry
    def plot_boundary_buffer_chemistry(self):
        try:
            df = self.build_boundary_buffer_chemistry_table()
        except Exception as exc:
            messagebox.showerror("Boundary-buffer chemistry failed", str(exc))
            return
        self.last_boundary_buffer_chemistry_df = df.copy()
        summary = df[df["zone"] == "near_vs_interior"].copy()
        if summary.empty:
            messagebox.showerror("No summary rows", "No near-vs-interior rows were calculated.")
            return
        value_col = str(summary["value_col"].iloc[0])
        buffer_px = int(summary["buffer_pixels"].iloc[0])
        self.mineral_stats_fig.clear()
        ax = self.mineral_stats_fig.add_subplot(111)
        self.mineral_stats_ax = ax
        labels = []
        near_vals = []
        interior_vals = []
        pct = []
        for _, r in summary.iterrows():
            labels.append(f"{r['phase']}\nnear {r['other_phase']}")
            near_vals.append(r["mean_value"])
            interior_vals.append(r["interior_mean_value"])
            pct.append(r["near_percent_difference_from_interior"])
        x = np.arange(len(labels), dtype=float)
        width = 0.38
        ax.bar(
            x - width / 2,
            near_vals,
            width,
            label=f"within {buffer_px}px of other phase",
            alpha=0.85,
        )
        ax.bar(x + width / 2, interior_vals, width, label="interior of same phase", alpha=0.65)
        ax.set_xticks(x)
        ax.set_xticklabels(labels, rotation=55, ha="right", fontsize=8)
        ax.set_ylabel(f"Mean {value_col}")
        ax.set_title(
            f"Boundary-buffer chemistry for selected NN/contact pair(s)\n{value_col}; buffer = {buffer_px} pixels"
        )
        ax.legend(fontsize=8)
        ymax = np.nanmax(
            [
                np.nanmax(np.asarray(near_vals, dtype=float)),
                np.nanmax(np.asarray(interior_vals, dtype=float)),
            ]
        )
        if not np.isfinite(ymax) or ymax <= 0:
            ymax = 1.0
        for xi, yi, pi in zip(x, near_vals, pct):
            if np.isfinite(yi) and np.isfinite(pi):
                ax.text(
                    xi - width / 2,
                    yi + 0.02 * ymax,
                    f"{pi:+.0f}%",
                    ha="center",
                    va="bottom",
                    fontsize=7,
                    rotation=90,
                )
        self.mineral_stats_fig.tight_layout()
        self.mineral_stats_canvas.draw_idle()
        try:
            skipped = getattr(self, "last_boundary_buffer_skipped", [])
            extra = f" | skipped {len(skipped)}" if skipped else ""
            self.mineral_stats_info_var.set(
                f"Boundary-buffer chemistry: {len(summary)} phase-near-other comparisons{extra}."
            )
        except Exception:
            pass


    # plot boundary buffer ratio bars
    def plot_boundary_buffer_ratio_bars(self):
        try:
            summary, pair_rows = self.build_boundary_buffer_ratio_table()
        except Exception as exc:
            messagebox.showerror("Buffer ratio failed", str(exc))
            return
        if summary is None or summary.empty:
            messagebox.showinfo("No ratios", "No buffer ratio rows were calculated.")
            return
        df = summary.copy()
        df["median_ratio"] = pd.to_numeric(df["median_ratio"], errors="coerce")
        df["n_ratio_pairs"] = pd.to_numeric(df["n_ratio_pairs"], errors="coerce")
        df = df.sort_values(["pair", "ratio_direction"]).reset_index(drop=True)
        labels = df["ratio_direction"].astype(str).tolist()
        vals = df["median_ratio"].to_numpy(dtype=float)
        nvals = df["n_ratio_pairs"].fillna(0).astype(int).to_numpy()
        self.mineral_stats_fig.clear()
        ax = self.mineral_stats_fig.add_subplot(111)
        self.mineral_stats_ax = ax
        x = np.arange(len(labels), dtype=float)
        ax.bar(x, np.nan_to_num(vals, nan=0.0), alpha=0.85)
        ax.axhline(1.0, color="black", linewidth=1, linestyle="--", alpha=0.8)
        ax.set_xticks(x)
        ax.set_xticklabels(labels, rotation=55, ha="right", fontsize=8)
        ax.set_ylabel("Median concentration ratio / Kd")
        value_col = (
            str(df["value_col"].iloc[0]) if "value_col" in df.columns and len(df) else "value"
        )
        buffer_px = (
            int(df["buffer_pixels"].iloc[0])
            if "buffer_pixels" in df.columns and len(df)
            else self.get_boundary_buffer_pixel_width()
        )
        ax.set_title(
            f"Boundary-buffer concentration ratios for NN/contact relationships\n{value_col}; buffer = {buffer_px} px; ratio = numerator phase / nearest denominator phase"
        )
        ymax = np.nanmax(np.nan_to_num(vals, nan=0.0)) if len(vals) else 1.0
        if not np.isfinite(ymax) or ymax <= 0:
            ymax = 1.0
        for xi, yi, ni in zip(x, np.nan_to_num(vals, nan=0.0), nvals):
            ax.text(
                xi, yi + 0.02 * ymax, f"n={ni}", ha="center", va="bottom", fontsize=7, rotation=90
            )
        ax.grid(axis="y", alpha=0.25)
        self.mineral_stats_fig.tight_layout()
        self.mineral_stats_canvas.draw_idle()
        try:
            skipped = getattr(self, "last_boundary_buffer_ratio_skipped", [])
            extra = f" | skipped {len(skipped)}" if skipped else ""
            self.mineral_stats_info_var.set(
                f"Buffer ratios calculated for {len(df)} directional relationships; {len(pair_rows):,} matched pixel ratios{extra}."
            )
        except Exception:
            pass
        try:
            self._apply_manual_color_scale_to_axes(self.mineral_stats_ax)
        except Exception:
            pass
        try:
            _ax_for_log = self.mineral_stats_ax
            if _ax_for_log is not None:
                self._apply_log_axes_to_axes(_ax_for_log)
                try:
                    self._apply_manual_color_scale_to_axes(_ax_for_log)
                except Exception:
                    pass
        except Exception:
            pass


