    # plot boundary buffer delta
    def plot_boundary_buffer_delta(self):
        try:
            df = self.build_boundary_buffer_chemistry_table()
        except Exception as exc:
            messagebox.showerror("Boundary Δ failed", str(exc))
            return
        self.last_boundary_buffer_chemistry_df = df.copy()
        summary = df[df["zone"] == "near_vs_interior"].copy()
        if summary.empty:
            messagebox.showerror("No summary rows", "No near-vs-interior rows were calculated.")
            return
        summary["mean_value"] = pd.to_numeric(summary["mean_value"], errors="coerce")
        summary["interior_mean_value"] = pd.to_numeric(
            summary["interior_mean_value"], errors="coerce"
        )
        summary["delta_near_minus_interior"] = (
            summary["mean_value"] - summary["interior_mean_value"]
        )
        self.last_boundary_buffer_delta_df = summary.copy()
        labels = [f"{r['phase']}\nnear {r['other_phase']}" for _, r in summary.iterrows()]
        vals = summary["delta_near_minus_interior"].to_numpy(dtype=float)
        pct = pd.to_numeric(
            summary.get("near_percent_difference_from_interior", np.nan), errors="coerce"
        ).to_numpy(dtype=float)
        value_col = (
            str(summary["value_col"].iloc[0])
            if "value_col" in summary.columns and len(summary)
            else "value"
        )
        buffer_px = (
            int(summary["buffer_pixels"].iloc[0])
            if "buffer_pixels" in summary.columns and len(summary)
            else self.get_boundary_buffer_pixel_width()
        )
        self.mineral_stats_fig.clear()
        ax = self.mineral_stats_fig.add_subplot(111)
        self.mineral_stats_ax = ax
        x = np.arange(len(labels), dtype=float)
        ax.bar(x, np.nan_to_num(vals, nan=0.0), alpha=0.85)
        ax.axhline(0.0, color="black", linewidth=1)
        ax.set_xticks(x)
        ax.set_xticklabels(labels, rotation=55, ha="right", fontsize=8)
        ax.set_ylabel(f"Δ mean {value_col}\nnear-boundary − interior")
        ax.set_title(
            f"Boundary enrichment/depletion relative to core/interior\n{value_col}; buffer = {buffer_px} px"
        )
        ymax = np.nanmax(np.abs(vals[np.isfinite(vals)])) if np.isfinite(vals).any() else 1.0
        if not np.isfinite(ymax) or ymax == 0:
            ymax = 1.0
        for xi, yi, pi in zip(x, vals, pct):
            if np.isfinite(yi) and np.isfinite(pi):
                ax.text(
                    xi,
                    yi + (0.03 * ymax if yi >= 0 else -0.03 * ymax),
                    f"{pi:+.0f}%",
                    ha="center",
                    va="bottom" if yi >= 0 else "top",
                    fontsize=7,
                    rotation=90,
                )
        ax.grid(axis="y", alpha=0.25)
        self.mineral_stats_fig.tight_layout()
        self.mineral_stats_canvas.draw_idle()
        try:
            self.mineral_stats_info_var.set(
                "Boundary Δ: positive is enriched; negative is depleted."
            )
        except Exception:
            pass


