    # resolve element layer strict for mineral analysis
    def _resolve_mineral_element_layer_strict(self, mineral, value_col):
        if not mineral or not value_col:
            return None
        mineral = str(mineral).strip()
        clean_value = (
            self.canonical_layer_display_name(value_col)
            if hasattr(self, "canonical_layer_display_name")
            else str(value_col).strip()
        )
        try:
            idx = (
                self.rebuild_mineral_column_index()
                if hasattr(self, "rebuild_mineral_column_index")
                else getattr(self, "mineral_column_index", {})
            )
            colmap = idx.get(mineral, {})
            for key, layer in colmap.items():
                key_clean = (
                    self.canonical_layer_display_name(key)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(key)
                )
                if key_clean == clean_value and layer in getattr(self, "values", {}):
                    return layer
        except Exception:
            pass
        try:
            layer = self._layer_for_mineral_value_column(mineral, clean_value)
            if layer in getattr(self, "values", {}):
                return layer
        except Exception:
            pass
        try:
            for layer, meta in getattr(self, "metas", {}).items():
                if layer not in getattr(self, "values", {}):
                    continue
                if not isinstance(meta, dict):
                    continue
                layer_mineral = str(meta.get("mineral_type", meta.get("mineral", ""))).strip()
                if layer_mineral != mineral:
                    continue
                meta_col = meta.get("canonical_column", meta.get("source_layer_name", layer))
                meta_clean = (
                    self.canonical_layer_display_name(meta_col)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(meta_col)
                )
                if meta_clean == clean_value:
                    return layer
        except Exception:
            pass
        try:
            for layer, layer_mineral in getattr(self, "layer_mineral_type", {}).items():
                if layer not in getattr(self, "values", {}):
                    continue
                if str(layer_mineral).strip() != mineral:
                    continue
                layer_clean = (
                    self.canonical_layer_display_name(layer)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(layer)
                )
                if layer_clean == clean_value:
                    return layer
        except Exception:
            pass
        return None


