    # current mineral type for map layers
    def _current_layer_mineral_type(self, layer_name=None):
        if layer_name is None:
            try:
                layer_name = self.grain_mask_var.get()
            except Exception:
                try:
                    layer_name = self.column_var.get()
                except Exception:
                    layer_name = ""
        layer_name = str(layer_name)
        if layer_name in getattr(self, "mineral_presence_groups", {}):
            return layer_name
        try:
            meta = self.metas.get(layer_name, {})
            return self._mineral_group_key_from_meta(layer_name, meta)
        except Exception:
            pass
        return layer_name or "Unknown"


    # add sample, mineral, run, and grain IDs to a result table.
    def add_grain_metadata_to_table(
        self, df, grain_df=None, layer_name=None, source_kind="grain_pixels"
    ):
        if df is None or len(df) == 0:
            return df
        out = df.copy()
        if grain_df is None:
            grain_df = getattr(self, "last_grain_df", None)
        if grain_df is not None and (not grain_df.empty):
            gdf = grain_df.copy()
            if "grain_id" in gdf.columns:
                gdf["grain_id"] = pd.to_numeric(gdf["grain_id"], errors="coerce").astype("Int64")
            if "area" in gdf.columns and "grain_area_pixels" not in gdf.columns:
                gdf = gdf.rename(columns={"area": "grain_area_pixels"})
            if "area_pixels" in gdf.columns and "grain_area_pixels" not in gdf.columns:
                gdf = gdf.rename(columns={"area_pixels": "grain_area_pixels"})
            if "aspect_ratio" in gdf.columns and "grain_aspect_ratio" not in gdf.columns:
                gdf = gdf.rename(columns={"aspect_ratio": "grain_aspect_ratio"})
            if "grain_id" in out.columns and "grain_id" in gdf.columns:
                keep = ["grain_id"]
                for c in [
                    "grain_area_pixels",
                    "grain_area",
                    "grain_area_um2",
                    "grain_area_coordinate_units2",
                    "grain_area_coordinate_units",
                    "pixel_size_x_um",
                    "pixel_size_y_um",
                    "pixel_area_um2",
                    "grain_aspect_ratio",
                    "grain_center_x",
                    "grain_center_y",
                    "centroid_x",
                    "centroid_y",
                    "grain_ellipse_major_axis",
                    "grain_ellipse_minor_axis",
                    "ellipse_boundary_major_axis",
                    "ellipse_boundary_minor_axis",
                ]:
                    if c in gdf.columns and c not in keep:
                        keep.append(c)
                out["grain_id"] = pd.to_numeric(out["grain_id"], errors="coerce").astype("Int64")
                out = out.merge(
                    gdf[keep].drop_duplicates("grain_id"),
                    on="grain_id",
                    how="left",
                    suffixes=("", "_grain"),
                )
        try:
            if grain_df is not None and (not grain_df.empty) and ("grain_id" in grain_df.columns):
                out["grain_count_total"] = int(pd.Series(grain_df["grain_id"]).nunique())
            elif "grain_id" in out.columns:
                out["grain_count_total"] = int(out["grain_id"].nunique())
            else:
                out["grain_count_total"] = 0
        except Exception:
            out["grain_count_total"] = 0
        layer = (
            layer_name
            or getattr(self, "last_grain_layer_name", None)
            or getattr(self, "current_grain_layer", None)
        )
        meta = self.metas.get(layer, {}) if layer in getattr(self, "metas", {}) else {}
        z = self.values.get(layer, None) if layer in getattr(self, "values", {}) else None
        z_shape = np.asarray(z).shape if z is not None else None
        try:
            dx, dy = self._median_pixel_spacing_from_meta(meta, z_shape=z_shape)
            pix_area = float(abs(dx * dy))
        except Exception:
            dx = dy = pix_area = np.nan
        if "grain_area_coordinate_units2" not in out.columns:
            out["grain_area_coordinate_units2"] = pd.Series(np.nan, index=out.index, dtype=float)
        if "grain_area_pixels" in out.columns and np.isfinite(pix_area):
            calculated_area = pd.to_numeric(out["grain_area_pixels"], errors="coerce") * pix_area
            current_area = pd.to_numeric(out["grain_area_coordinate_units2"], errors="coerce")
            out["grain_area_coordinate_units2"] = current_area.where(np.isfinite(current_area), calculated_area)
        out["grain_area_coordinate_units"] = pd.to_numeric(
            out["grain_area_coordinate_units2"], errors="coerce"
        )
        if _metadata_uses_micron_coordinates(meta, z_shape=z_shape):
            physical_area = pd.to_numeric(out["grain_area_coordinate_units2"], errors="coerce")
            if "grain_area_um2" in out.columns:
                existing = pd.to_numeric(out["grain_area_um2"], errors="coerce")
                out["grain_area_um2"] = existing.where(np.isfinite(existing), physical_area)
            else:
                out["grain_area_um2"] = physical_area
            out["grain_area"] = pd.to_numeric(out["grain_area_um2"], errors="coerce")
            out["pixel_size_x_um"] = float(dx) if np.isfinite(dx) else np.nan
            out["pixel_size_y_um"] = float(dy) if np.isfinite(dy) else np.nan
            out["pixel_area_um2"] = float(pix_area) if np.isfinite(pix_area) else np.nan
        else:
            if "grain_area_um2" not in out.columns:
                out["grain_area_um2"] = np.nan
            if "grain_area" not in out.columns:
                out["grain_area"] = np.nan

        if (
            "grain_aspect_ratio" not in out.columns
            or pd.to_numeric(out.get("grain_aspect_ratio", pd.Series(dtype=float)), errors="coerce")
            .isna()
            .all()
        ):
            for major_col, minor_col in [
                ("grain_ellipse_major_axis", "grain_ellipse_minor_axis"),
                ("ellipse_boundary_major_axis", "ellipse_boundary_minor_axis"),
            ]:
                if major_col in out.columns and minor_col in out.columns:
                    major = pd.to_numeric(out[major_col], errors="coerce")
                    minor = pd.to_numeric(out[minor_col], errors="coerce").replace(0, np.nan)
                    out["grain_aspect_ratio"] = major / minor
                    break
        mineral_type = self._current_layer_mineral_type(layer_name)
        if "mineral_type" not in out.columns:
            out["mineral_type"] = mineral_type
        if "map_group" not in out.columns:
            out["map_group"] = mineral_type
        if "source_kind" not in out.columns:
            out["source_kind"] = source_kind
        return out


    # refresh mineral choices for grain analysis
    def refresh_grain_mineral_choices(self):
        try:
            self.refresh_map_view_mineral_list()
        except Exception:
            pass
        choices = ["None"]
        try:
            groups = sorted(list(getattr(self, "mineral_presence_groups", {}).keys()))
            choices.extend(groups)
        except Exception:
            pass
        try:
            for layer in self.values.keys():
                if layer not in choices:
                    choices.append(layer)
        except Exception:
            pass
        try:
            current = self.grain_mask_layer_var.get()
        except Exception:
            current = "None"
        try:
            self.grain_mask_combo.configure(values=choices)
        except Exception:
            pass
        if current in choices:
            try:
                self.grain_mask_layer_var.set(current)
            except Exception:
                pass
        elif len(choices) > 1:
            try:
                self.grain_mask_layer_var.set(choices[1])
            except Exception:
                pass
        else:
            try:
                self.grain_mask_layer_var.set("None")
            except Exception:
                pass
        return choices


    # selected source name for grain analysis
    def _grain_selected_source_name(self):
        for attr in ["grain_mask_layer_var", "grain_mask_var", "grain_layer_var"]:
            if hasattr(self, attr):
                try:
                    val = getattr(self, attr).get()
                    if val not in [None, "", "None"]:
                        return str(val)
                except Exception:
                    pass
        try:
            return str(self.column_var.get())
        except Exception:
            return None


    # mask for grain detection source lookup
    def _get_mask_for_grain_detection_source(self, source_name=None):
        if source_name is None:
            source_name = self._grain_selected_source_name()
        if source_name in [None, "", "None"]:
            try:
                source_name = self.column_var.get()
            except Exception:
                source_name = None
        if source_name in getattr(self, "mineral_presence_groups", {}):
            rule = "finite"
            threshold = 0.0
            try:
                if hasattr(self, "grain_mask_rule_var"):
                    rv = self.grain_mask_rule_var.get()
                    if rv in [">0", ">custom", "finite"]:
                        rule = rv
                if hasattr(self, "grain_threshold_var"):
                    threshold = float(self.grain_threshold_var.get())
            except Exception:
                pass
            layer_used, extent, x, y, mask = self.mineral_group_mask_and_coords(
                source_name, rule=rule, threshold=threshold
            )
            z = np.asarray(self.values[layer_used], dtype=float)
            meta = self.metas.get(layer_used, {})
            return (
                source_name,
                layer_used,
                np.asarray(mask, dtype=bool),
                z,
                meta,
                str(source_name),
            )
        layer = source_name
        if layer not in getattr(self, "values", {}):
            for candidate in getattr(self, "values", {}).keys():
                clean = str(candidate).split(" :: ", 1)[-1]
                if clean == source_name:
                    layer = candidate
                    break
        if layer not in getattr(self, "values", {}):
            raise ValueError(f"Could not find grain source layer/group: {source_name}")
        z = np.asarray(self.values[layer], dtype=float)
        meta = self.metas.get(layer, {})
        rule = "finite"
        threshold = 0.0
        try:
            rule = self.grain_mask_rule_var.get()
        except Exception:
            pass
        try:
            threshold = float(self.grain_threshold_var.get())
        except Exception:
            threshold = 0.0
        mask = np.isfinite(z)
        if rule == ">0":
            mask &= z > 0
        elif rule == ">custom":
            mask &= z > threshold
        mineral_type = self._current_layer_mineral_type(layer)
        return (source_name, layer, mask, z, meta, mineral_type)


    # pixel dataframe from labels
    def _grain_pixel_dataframe_from_labels(self, labels=None, source_layer=None, mineral_type=None):
        if labels is None:
            labels = self._find_any_grain_labels()
        if labels is None:
            raise ValueError("No grain labels are available. Run grain detection first.")
        labels = np.asarray(labels)
        if labels.ndim != 2 or not np.any(labels > 0):
            raise ValueError("No labeled grains are available. Run grain detection first.")
        if source_layer is None:
            source_layer = getattr(self, "last_grain_layer_name", None)
        if mineral_type is None:
            mineral_type = getattr(
                self, "last_grain_mineral_type", None
            ) or self._current_layer_mineral_type(source_layer)
        rows, cols = np.where(labels > 0)
        grain_ids = labels[rows, cols].astype(int)
        meta = (
            self.metas.get(source_layer, {}) if source_layer in getattr(self, "metas", {}) else {}
        )
        xg, yg = self._layer_pixel_centers(meta, z_shape=labels.shape)
        if (
            xg is None
            or yg is None
            or np.shape(xg) != labels.shape
            or (np.shape(yg) != labels.shape)
        ):
            x_vals = cols.astype(float)
            y_vals = rows.astype(float)
        else:
            x_vals = np.asarray(xg)[rows, cols]
            y_vals = np.asarray(yg)[rows, cols]
        df = pd.DataFrame(
            {
                "row": rows.astype(int),
                "col": cols.astype(int),
                "x": x_vals,
                "y": y_vals,
                "grain_id": grain_ids,
                "mineral_type": str(mineral_type),
                "map_group": str(mineral_type),
                "source_layer": str(source_layer),
                "source_kind": "grain_pixels",
            }
        )
        for layer, arr in getattr(self, "values", {}).items():
            arr = np.asarray(arr, dtype=float)
            if arr.shape != labels.shape:
                continue
            col_name = str(layer).split(" :: ", 1)[-1]
            if col_name in df.columns:
                col_name = str(layer)
            df[col_name] = arr[rows, cols]
        grain_df = getattr(self, "last_grain_df", None)
        df = self.add_grain_metadata_to_table(
            df, grain_df=grain_df, layer_name=source_layer, source_kind="grain_pixels"
        )
        return df


    # means dataframe from pixels
    def _grain_means_dataframe_from_pixels(self, pixel_df=None):
        if pixel_df is None:
            pixel_df = self._grain_pixel_dataframe_from_labels()
        if pixel_df is None or pixel_df.empty:
            raise ValueError("No grain pixels are available.")
        meta_first = [
            "mineral_type",
            "map_group",
            "source_layer",
            "grain_count_total",
            "grain_area_pixels",
            "grain_area_coordinate_units",
            "grain_aspect_ratio",
        ]
        numeric_cols = []
        for c in pixel_df.columns:
            if c in ["row", "col", "x", "y", "grain_id"]:
                continue
            try:
                vals = pd.to_numeric(pixel_df[c], errors="coerce")
                if np.isfinite(vals).sum() > 0:
                    numeric_cols.append(c)
            except Exception:
                pass
        rows = []
        for gid, g in pixel_df.groupby("grain_id", dropna=False):
            rec = {"grain_id": gid, "source_kind": "grain_means"}
            for c in meta_first:
                if c in g.columns:
                    vals = g[c].dropna()
                    rec[c] = vals.iloc[0] if len(vals) else np.nan
            if "x" in g.columns:
                rec["grain_center_x"] = pd.to_numeric(g["x"], errors="coerce").mean()
            if "y" in g.columns:
                rec["grain_center_y"] = pd.to_numeric(g["y"], errors="coerce").mean()
            for c in numeric_cols:
                vals = pd.to_numeric(g[c], errors="coerce")
                vals = vals[np.isfinite(vals)]
                if vals.size == 0:
                    continue
                rec[c] = float(np.nanmean(vals))
                rec[f"{c}_std"] = float(np.nanstd(vals, ddof=1)) if vals.size > 1 else np.nan
                rec[f"{c}_n"] = int(vals.size)
            rows.append(rec)
        out = pd.DataFrame(rows)
        out = self.add_grain_metadata_to_table(
            out,
            grain_df=getattr(self, "last_grain_df", None),
            layer_name=getattr(self, "last_grain_layer_name", None),
            source_kind="grain_means",
        )
        return out


    # remember grain labels helper for grain analysis
    def _remember_grain_labels(self, labels, source_layer=None, mineral_type=None):
        if labels is None:
            return None
        labels = np.asarray(labels)
        if labels.ndim != 2:
            return None
        self.last_grain_labels = labels
        self.grain_labels = labels
        self.current_grain_labels = labels
        if source_layer is not None:
            self.last_grain_layer_name = source_layer
            self.current_grain_layer = source_layer
        if mineral_type is not None:
            self.last_grain_mineral_type = mineral_type
        return labels


    # find any grain labels
    def _find_any_grain_labels(self):
        for attr in [
            "last_grain_labels",
            "grain_labels",
            "current_grain_labels",
            "last_labels",
            "labels",
            "grain_label_image",
            "last_grain_label_image",
            "cleaned_grain_labels",
            "final_grain_labels",
        ]:
            try:
                labels = getattr(self, attr, None)
                if labels is not None:
                    labels = np.asarray(labels)
                    if labels.ndim == 2 and np.any(labels > 0):
                        self._remember_grain_labels(
                            labels,
                            source_layer=getattr(self, "last_grain_layer_name", None),
                            mineral_type=getattr(self, "last_grain_mineral_type", None),
                        )
                        return labels
            except Exception:
                pass
        return None


    # label layer and meta helper for grain analysis
    def _grain_label_layer_and_meta(self):
        layer = getattr(self, "last_grain_layer_name", None)
        if layer not in getattr(self, "values", {}):
            try:
                layer = self.grain_mask_layer_var.get()
            except Exception:
                layer = None
        if layer not in getattr(self, "values", {}):
            try:
                layer = self.column_var.get()
            except Exception:
                layer = None
        z = (
            np.asarray(self.values[layer], dtype=float)
            if layer in getattr(self, "values", {})
            else None
        )
        meta = self.metas.get(layer, {}) if layer in getattr(self, "metas", {}) else {}
        return (layer, meta, z)


    # source layer used for display
    def _grain_source_layer_for_display(self):
        layer = getattr(self, "last_grain_layer_name", None)
        if layer in getattr(self, "values", {}):
            return layer
        try:
            layer = self.grain_mask_layer_var.get()
            if layer in getattr(self, "values", {}):
                return layer
        except Exception:
            pass
        try:
            layer = self.column_var.get()
            if layer in getattr(self, "values", {}):
                return layer
            for candidate in self.values.keys():
                if str(candidate).split(" :: ", 1)[-1] == layer:
                    return candidate
        except Exception:
            pass
        return None


    # draw numbers on map axes for grain analysis
    def _draw_grain_numbers_on_map_axes(self, ax, labels, source_layer=None):
        if labels is None:
            return []
        labels = np.asarray(labels)
        if labels.ndim != 2 or not np.any(labels > 0):
            return []
        if source_layer is None:
            source_layer = self._grain_source_layer_for_display()
        artists = []
        for gid in np.unique(labels):
            if gid <= 0:
                continue
            rr, cc = np.where(labels == gid)
            if rr.size == 0:
                continue
            r = float(np.nanmean(rr))
            c = float(np.nanmean(cc))
            try:
                x, y = self._array_rc_to_map_xy([r], [c], source_layer=source_layer)
                x = float(np.asarray(x)[0])
                y = float(np.asarray(y)[0])
                t = ax.text(
                    x,
                    y,
                    str(int(gid)),
                    color="white",
                    fontsize=5,
                    ha="center",
                    va="center",
                    zorder=30,
                )
                artists.append(t)
            except Exception:
                pass
        return artists


    # clear overlay artists from axis for grain analysis
    def _clear_grain_overlay_artists_from_axis(self, ax):
        if ax is None:
            return
        for artist_list_name in ["lines", "patches", "texts"]:
            try:
                for artist in list(getattr(ax, artist_list_name)):
                    try:
                        artist.remove()
                    except Exception:
                        pass
            except Exception:
                pass


    # hide boundary toggles for grain analysis
    def _hide_grain_boundary_toggles(self):
        changed = []
        for attr in [
            "draw_grain_boundaries_var",
            "draw_boundaries_var",
            "grain_draw_boundaries_var",
            "draw_grain_ellipses_var",
            "draw_boundaries_ellipses_var",
        ]:
            if hasattr(self, attr):
                try:
                    var = getattr(self, attr)
                    old = bool(var.get())
                    if old:
                        var.set(False)
                        changed.append((var, old))
                except Exception:
                    pass
        return changed


    # show labels without offset for grain analysis
    def show_grain_labels_without_offset(self):
        try:
            labels = (
                self._find_any_grain_labels()
                if hasattr(self, "_find_any_grain_labels")
                else getattr(self, "last_grain_labels", None)
            )
            if labels is None:
                return
            labels = np.asarray(labels)
            if labels.ndim != 2 or not np.any(labels > 0):
                return
            source_layer = self._grain_source_layer_for_display()
            if source_layer is None:
                return
            changed_toggles = self._hide_grain_boundary_toggles()
            try:
                fig, ax, canvas = self._reset_main_map_figure()
                self._clear_grain_overlay_artists_from_axis(ax)
                mineral_name = getattr(self, "last_grain_mineral_type", None)
                if mineral_name in getattr(self, "mineral_presence_groups", {}):
                    try:
                        layer_used, extent, x, y, mineral_mask = self.mineral_group_mask_and_coords(
                            mineral_name
                        )
                        self._draw_true_coordinate_pixels(
                            ax,
                            self.metas.get(layer_used, {}),
                            np.asarray(self.values[layer_used], dtype=float),
                            np.asarray(mineral_mask, dtype=bool),
                            color="lightgray",
                            label=mineral_name,
                            alpha=0.28,
                            zorder=5,
                        )
                        source_layer = layer_used
                    except Exception:
                        pass
                else:
                    try:
                        z = np.asarray(self.values[source_layer], dtype=float)
                        self._draw_value_layer_same_grid(
                            ax,
                            source_layer,
                            values=z,
                            mask=np.isfinite(z),
                            cmap="Greys",
                            alpha=0.25,
                            zorder=5,
                        )
                    except Exception:
                        pass
                self._draw_label_image_on_map_axes(
                    ax, labels, source_layer=source_layer, alpha=0.95
                )
                try:
                    self._draw_grain_numbers_on_map_axes(ax, labels, source_layer=source_layer)
                except Exception:
                    pass
                try:
                    self._draw_grain_overlays(ax)
                except Exception:
                    pass
                try:
                    self._apply_shared_map_axes(ax, records=[(source_layer, labels > 0)])
                except Exception:
                    pass
                n_grains = int(len(np.unique(labels[labels > 0])))
                ax.set_title(
                    f"{getattr(self, 'last_grain_mineral_type', 'Grains')}: {n_grains} grains | X/Y-correct grain display"
                )
                fig.tight_layout()
                canvas.draw_idle()
                try:
                    self.status_var.set(
                        f"Displayed {n_grains} grains using the map X/Y coordinate grid."
                    )
                except Exception:
                    pass
            finally:
                self._restore_toggles(changed_toggles)
        except Exception:
            pass
        try:
            self.draw_manual_grain_split_lines()
        except Exception:
            pass


    # save overlay exact for mineral analysis
    def save_mineral_overlay_exact(self, path):
        self._save_mineral_overlay_figure_to_path(path)


    # draw manual grain split lines
    def draw_manual_grain_split_lines(self, ax=None, canvas=None):
        return redraw_manual_split_lines(self, ax, canvas)


    # cut the grain mask along the saved manual split lines.
    def apply_manual_grain_split_lines_to_mask(self, mask, x, y):
        lines = get_manual_split_lines(self)
        if not lines:
            return mask
        out = np.asarray(mask, dtype=bool).copy()
        before = int(np.count_nonzero(out))
        try:
            width_pixels = max(
                1.0,
                float(getattr(self, "manual_grain_split_width_var", tk.StringVar(value="2")).get()),
            )
        except Exception:
            width_pixels = 2.0
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        try:
            if x.ndim == 2:
                x_axis = np.nanmedian(x, axis=0)
            else:
                x_axis = x.ravel()
            if y.ndim == 2:
                y_axis = np.nanmedian(y, axis=1)
            else:
                y_axis = y.ravel()
        except Exception:
            x_axis = np.asarray(x).ravel()
            y_axis = np.asarray(y).ravel()
        if x_axis.size < 1 or y_axis.size < 1:
            return out

        # convert helper to index
        def axis_to_index(vals):
            vals = np.asarray(vals, dtype=float)
            n = vals.size
            if n <= 1:
                return lambda q: np.zeros_like(np.asarray(q, dtype=float))
            idx = np.arange(n, dtype=float)
            good = np.isfinite(vals)
            if good.sum() < 2:
                v0 = 0.0
                step = 1.0
                return lambda q: (np.asarray(q, dtype=float) - v0) / step
            vg = vals[good]
            ig = idx[good]
            order = np.argsort(vg)
            vg = vg[order]
            ig = ig[order]
            uniq, first = np.unique(vg, return_index=True)
            ig = ig[first]
            if uniq.size < 2:
                step = 1.0
                v0 = float(uniq[0]) if uniq.size else 0.0
                return lambda q: (np.asarray(q, dtype=float) - v0) / step
            return lambda q: np.interp(
                np.asarray(q, dtype=float), uniq, ig, left=np.nan, right=np.nan
            )

        x_to_col = axis_to_index(x_axis)
        y_to_row = axis_to_index(y_axis)
        rr, cc = np.indices(out.shape)
        radius = width_pixels / 2.0
        for x0, y0, x1, y1 in lines:
            try:
                c0 = float(x_to_col(float(x0)))
                r0 = float(y_to_row(float(y0)))
                c1 = float(x_to_col(float(x1)))
                r1 = float(y_to_row(float(y1)))
                if not np.isfinite([r0, c0, r1, c1]).all():
                    continue
                vc = c1 - c0
                vr = r1 - r0
                denom = vc * vc + vr * vr
                if denom <= 0 or not np.isfinite(denom):
                    continue
                t = ((cc - c0) * vc + (rr - r0) * vr) / denom
                t = np.clip(t, 0.0, 1.0)
                projc = c0 + t * vc
                projr = r0 + t * vr
                dist = np.sqrt((cc - projc) ** 2 + (rr - projr) ** 2)
                out[dist <= radius] = False
            except Exception:
                continue
        after = int(np.count_nonzero(out))
        try:
            self.last_removed_split_pixels = before - after
        except Exception:
            pass
        return out


    # undo the most recent manual grain split line
    def undo_manual_grain_split_line(self):
        lines = get_manual_split_lines(self)
        if lines:
            lines.pop()
        redraw_manual_split_lines(self)
        try:
            self.status_var.set(
                f"Removed last split line. Remaining: {len(self.manual_grain_split_lines)}"
            )
        except Exception:
            pass


    # clear manual grain split lines
    def clear_manual_grain_split_lines(self):
        self.manual_grain_split_lines = []
        self.current_split_line_start = None
        self.manual_grain_split_start = None
        try:
            if getattr(self, "split_line_preview_artist", None) is not None:
                self.split_line_preview_artist.remove()
        except Exception:
            pass
        self.split_line_preview_artist = None
        redraw_manual_split_lines(self)
        try:
            self.status_var.set("Split lines cleared.")
        except Exception:
            pass


    # simplify grain table helper for grain analysis
    def simplify_grain_df(self):
        df = getattr(self, "last_grain_df", None)
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return
        self.last_grain_df_full = df.copy()
        keep = []
        for c in [
            "grain_id",
            "grain_area",
            "grain_area_um2",
            "grain_area_coordinate_units2",
            "grain_area_pixels",
            "pixel_size_x_um",
            "pixel_size_y_um",
            "pixel_area_um2",
            "area_pixels",
            "aspect_ratio_x_over_y",
            "x_y_aspect_ratio",
        ]:
            if c in df.columns and c not in keep:
                keep.append(c)
        out = df[keep].copy() if keep else df.copy()
        if "grain_area_pixels" not in out.columns and "area_pixels" in out.columns:
            out["grain_area_pixels"] = out["area_pixels"]
        if "x_y_aspect_ratio" not in out.columns and "aspect_ratio_x_over_y" in out.columns:
            out["x_y_aspect_ratio"] = out["aspect_ratio_x_over_y"]
        final_cols = [
            c
            for c in [
                "grain_id", "grain_area", "grain_area_um2", "grain_area_coordinate_units2",
                "grain_area_pixels", "pixel_size_x_um", "pixel_size_y_um", "pixel_area_um2",
                "x_y_aspect_ratio",
            ]
            if c in out.columns
        ]
        self.last_grain_df = out[final_cols].copy() if final_cols else out.copy()


    # metric frame helper for grain analysis
    def _grain_metric_frame(self):
        label_mask = self._grain_label_mask_safe()
        ids = self._all_grain_ids_from_label_mask()
        total = int(len(ids))
        try:
            x_axis, y_axis = self._grain_xy_axes_safe(label_mask)
        except Exception:
            x_axis = np.arange(label_mask.shape[1], dtype=float)
            y_axis = np.arange(label_mask.shape[0], dtype=float)
        source_layer = (
            getattr(self, "last_grain_mask_layer", None)
            or getattr(self, "last_grain_layer_name", None)
            or getattr(self, "last_grain_value_layer", None)
        )
        source_meta = self.metas.get(source_layer, {}) if source_layer in getattr(self, "metas", {}) else {}
        base_df = getattr(self, "last_grain_df_full", None)
        if not isinstance(base_df, pd.DataFrame) or base_df.empty:
            base_df = getattr(self, "last_grain_df", pd.DataFrame())
        by_id = {}
        if isinstance(base_df, pd.DataFrame) and (not base_df.empty) and ("grain_id" in base_df.columns):
            for _, old_row in base_df.iterrows():
                try:
                    by_id[int(old_row.get("grain_id"))] = old_row.to_dict()
                except Exception:
                    pass
        mineral = "grain"
        try:
            mineral = self._grain_run_mineral_name()
        except Exception:
            pass
        blank_values = np.full(label_mask.shape, np.nan, dtype=float)
        rows_out = []
        for gid in ids:
            gid = int(gid)
            rr, cc = np.where(label_mask == gid)
            if rr.size == 0:
                continue
            pix = list(zip(rr.astype(int).tolist(), cc.astype(int).tolist()))
            measured = self._grain_metrics_from_component(pix, x_axis, y_axis, blank_values)
            measured = _add_grain_area_unit_aliases(measured, source_meta, z_shape=label_mask.shape)
            row = dict(by_id.get(gid, {}))
            row.update(measured)
            row["grain_id"] = gid
            row["mineral_type"] = row.get("mineral_type", mineral)
            row["map_group"] = row.get("map_group", mineral)
            row["total_grains_identified"] = total
            rows_out.append(row)
        return self.ensure_grain_shape_metrics(pd.DataFrame(rows_out))


