    # current ellipse params for grain analysis
    def _grain_current_ellipse_params(self, grain_row):
        try:
            gid = int(grain_row.get("grain_id", -1))
        except Exception:
            gid = -1
        fit = _center_refit_pixel_trend_ellipse(self, gid, padding=1.08)
        if fit is None and _current_grain_ellipse_params is not None:
            return _current_grain_ellipse_params(self, grain_row)
        if fit is None:
            raise ValueError("Could not fit pixel-trend ellipse")
        cx, cy, major, minor, angle = fit
        used_method = "pixel_trend"
        manual = getattr(self, "manual_grain_centers", {}) or {}
        if gid in manual:
            try:
                manual_cx, manual_cy = manual[gid]
                manual_cx = float(manual_cx)
                manual_cy = float(manual_cy)
                mode = (
                    self._ellipse_refit_mode()
                    if hasattr(self, "_ellipse_refit_mode")
                    else "refit_from_center"
                )
                if mode == "refit_from_center":
                    major, minor, angle, refit_note = (
                        self._refit_ellipse_from_manual_center_and_long_axis(
                            grain_row, manual_cx, manual_cy, major, minor, angle
                        )
                    )
                    cx, cy = (manual_cx, manual_cy)
                    used_method = used_method + "+" + str(refit_note)
                elif mode == "shift_ellipse":
                    cx, cy = (manual_cx, manual_cy)
                    used_method = used_method + "+manual_center_shift_ellipse"
                else:
                    cx, cy = (manual_cx, manual_cy)
                    used_method = used_method + "+manual_center_only_keep_ellipse"
            except Exception:
                pass
        try:
            scale = float(self.grain_ellipse_scale_var.get())
        except Exception:
            scale = 1.0
        if not np.isfinite(scale) or scale <= 0:
            scale = 1.0
        return (
            float(cx),
            float(cy),
            float(major) * scale,
            float(minor) * scale,
            float(angle),
            used_method,
        )


    # draw overlays for grain analysis
    def _draw_grain_overlays(self, ax):
        df = None
        for attr in ["last_grain_df_full", "last_grain_table_full", "last_grain_df"]:
            candidate = getattr(self, attr, None)
            if (
                isinstance(candidate, pd.DataFrame)
                and (not candidate.empty)
                and ("grain_id" in candidate.columns)
            ):
                df = candidate
                break
        if df is None:
            return
        show_ellipses = True
        try:
            show_ellipses = bool(self.grain_show_ellipses_var.get())
        except Exception:
            pass
        boundary_cache = getattr(self, "last_grain_boundary_cache", {}) or {}
        manual_centers = getattr(self, "manual_grain_centers", {}) or {}
        for _, row in df.iterrows():
            try:
                gid = int(row.get("grain_id"))
            except Exception:
                continue
            try:
                bx, by = boundary_cache.get(gid, (np.array([]), np.array([])))
                bx = np.asarray(bx, dtype=float)
                by = np.asarray(by, dtype=float)
                ok = np.isfinite(bx) & np.isfinite(by)
                if np.any(ok):
                    ax.scatter(
                        bx[ok],
                        by[ok],
                        s=4,
                        c="black",
                        marker="s",
                        linewidths=0,
                        alpha=0.9,
                        zorder=12000,
                    )
            except Exception:
                pass
            try:
                if hasattr(self, "_grain_display_ellipse_and_center_params"):
                    ex, ey, cx, cy, major, minor, angle, method = (
                        self._grain_display_ellipse_and_center_params(row)
                    )
                else:
                    ex, ey, major, minor, angle, method = self._grain_current_ellipse_params(row)
                    cx, cy = (ex, ey)
            except Exception:
                continue
            if show_ellipses:
                try:
                    halo = Ellipse(
                        (ex, ey),
                        width=major,
                        height=minor,
                        angle=angle,
                        fill=False,
                        edgecolor="white",
                        linewidth=3.0,
                        alpha=0.98,
                        zorder=12010,
                    )
                    line = Ellipse(
                        (ex, ey),
                        width=major,
                        height=minor,
                        angle=angle,
                        fill=False,
                        edgecolor="black",
                        linewidth=1.25,
                        alpha=0.98,
                        zorder=12011,
                    )
                    ax.add_patch(halo)
                    ax.add_patch(line)
                except Exception:
                    pass
            try:
                moved = gid in manual_centers
                ax.scatter(
                    [cx],
                    [cy],
                    s=75 if moved else 48,
                    marker="+",
                    c="yellow" if moved else "red",
                    linewidths=2.2,
                    zorder=12020,
                )
                ax.text(
                    float(cx),
                    float(cy),
                    str(gid),
                    color="black" if moved else "white",
                    fontsize=7,
                    ha="center",
                    va="center",
                    fontweight="bold",
                    zorder=12021,
                )
                if moved and self._ellipse_refit_mode() == "center_only_keep_ellipse":
                    ax.plot(
                        [ex, cx],
                        [ey, cy],
                        color="yellow",
                        linewidth=0.8,
                        linestyle=":",
                        alpha=0.8,
                        zorder=12019,
                    )
            except Exception:
                pass
        try:
            self.draw_manual_grain_split_lines()
        except Exception:
            pass


    # add profile color-group controls
    def _add_profile_color_group_controls(self):
        if getattr(self, "_profile_color_group_controls_added_radial_color_groups", False):
            return
        parent = _find_xy_controls_parent(self)
        if parent is None:
            return
        self.profile_color_groups_var = getattr(
            self, "profile_color_groups_var", tk.StringVar(value="")
        )
        frame = ttk.LabelFrame(parent, text="Radial profile color groups")
        frame.pack(fill=tk.X, padx=2, pady=6)
        ttk.Label(frame, text="Profiles in the same group share one line color.").pack(anchor="w")
        ttk.Label(frame, text="Example: 1,4,7 | 2,3,6 | 5").pack(anchor="w")
        ttk.Label(frame, text="Named groups also work: Axial:1,4,7 | Oblique:2,3,6").pack(anchor="w")
        ttk.Entry(frame, textvariable=self.profile_color_groups_var, width=42).pack(
            fill=tk.X, pady=(3, 2)
        )
        ttk.Button(
            frame,
            text="Apply profile color groups",
            command=lambda: self.apply_profile_color_groups(show_message=True),
        ).pack(fill=tk.X, pady=2)
        self._profile_color_group_controls_added_radial_color_groups = True


    # apply color groups for profile plots
    def apply_profile_color_groups(self, show_message=True):
        return _apply_xy_custom_groups(self, show_message)


    # value columns used for profiles
    def _grain_value_columns_for_profiles(self, df=None):
        if df is None:
            try:
                df = self.build_grain_radial_pixel_table()
            except Exception:
                df = getattr(self, "last_grain_radial_pixel_df", pd.DataFrame())
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return []
        skip = set(METADATA_COLUMNS) | {
            "row_index",
            "column_index",
            "local_row_index",
            "local_column_index",
            "grain_id",
            "grain_area",
            "grain_area_pixels",
            "grain_aspect_ratio",
            "grain_center_x",
            "grain_center_y",
            "grain_ellipse_major_axis",
            "grain_ellipse_minor_axis",
            "grain_ellipse_angle_deg",
            "grain_ellipse_method",
            "grain_radial_norm",
            "grain_radial_percent",
            "grain_radial_bin",
            "grain_radial_zone",
            "grain_core_rim_label",
            "grain_pixel_in_detected_mask",
            "grain_pixel_in_fitted_ellipse",
            "grain_ellipse_xprime",
            "grain_ellipse_yprime",
            "analysis_level",
            "analysis_type",
        }
        columns = []
        for column in df.columns:
            name = str(column)
            if name in skip or name.startswith("grain_"):
                continue
            try:
                values = pd.to_numeric(df[column], errors="coerce")
                if values.notna().sum() == 0:
                    continue
            except Exception:
                continue
            columns.append(column)
        return columns


    # draw radial profile lines for grain analysis
    def draw_grain_radial_profile_lines(self):
        return _plot_radial_summary(self)


    # show grains on selected element map
    def show_grains_on_selected_element_map(self):
        labels = getattr(self, "last_grain_label_mask", None)
        df = _full_grain_dataframe(self)
        if labels is None or df is None:
            messagebox.showinfo("No grains", "Detect grains first.")
            return
        selected = ""
        try:
            selected = self.column_var.get()
        except Exception:
            pass
        if not selected:
            messagebox.showinfo(
                "No element map", "Choose a map channel at the top of the Map viewer first."
            )
            return
        try:
            self.map_view_render_mode_var.set("single_element")
            if hasattr(self, "map_mode_display_var"):
                self.map_mode_display_var.set("Element map")
        except Exception:
            pass
        self._draw_element_map()
        ax, canvas = _grain_interaction_visible_ax_canvas(self)
        if ax is None or canvas is None:
            return
        try:
            self._draw_grain_overlays(ax)
        except Exception:
            pass
        try:
            self.draw_manual_grain_split_lines()
        except Exception:
            pass
        if getattr(self, "_grain_radial_lines_visible", False):
            try:
                self.draw_grain_radial_profile_lines()
            except Exception:
                pass
        try:
            n_grains = int(
                len(np.unique(np.asarray(labels, dtype=int)[np.asarray(labels, dtype=int) > 0]))
            )
        except Exception:
            n_grains = int(len(df))
        try:
            ax.set_title(f"{selected} with {n_grains} grain outlines")
            canvas.draw_idle()
            self.status_var.set(f"Displayed {selected} with grain boundaries and ellipses.")
        except Exception:
            pass


    # refresh view for grain analysis
    def refresh_grain_view(self):
        mode = str(
            getattr(self, "grain_display_mode_var", tk.StringVar(value="Element map + outlines")).get()
        )
        if mode == "Element map + outlines":
            return self.show_grains_on_selected_element_map()
        if mode == "Colored grain labels":
            try:
                return self.show_grain_labels_without_offset()
            except Exception:
                return None
        return _run_grain_analysis_from_map_view_ui(self)


