    # start manual grain split line
    def start_manual_grain_split_line(self):
        try:
            self.stop_move_grain_center_mode()
        except Exception:
            pass
        stop_split_line_mode(self, disconnect_only=True)
        ax, canvas = _grain_interaction_visible_ax_canvas(self)
        if ax is None or canvas is None:
            messagebox.showinfo("No map", "Detect grains first, then draw split lines.")
            return
        try:
            toolbar = (
                getattr(canvas, "toolbar", None)
                or getattr(self, "toolbar", None)
                or getattr(self, "map_toolbar", None)
            )
            if toolbar is not None and getattr(toolbar, "mode", ""):
                mode = str(toolbar.mode).lower()
                if "pan" in mode:
                    toolbar.pan()
                elif "zoom" in mode:
                    toolbar.zoom()
        except Exception:
            pass
        get_manual_split_lines(self)
        self.split_line_mode_active = True
        self.drawing_split_line = True
        self.manual_grain_split_active = True
        self.current_split_line_start = None
        self.manual_grain_split_start = None
        self.split_line_start_axis = None
        self.split_line_start_canvas = None
        self.split_line_event_ids = []
        self._split_preview_last_draw = 0.0
        self.split_line_event_ids.append(
            (canvas, canvas.mpl_connect("button_press_event", self.manual_split_line_press))
        )
        self.split_line_event_ids.append(
            (canvas, canvas.mpl_connect("motion_notify_event", self.manual_split_line_motion))
        )
        try:
            self.status_var.set("Split mode ON: click the start and end of a split line.")
        except Exception:
            pass


    # leave move grain center mode
    def stop_move_grain_center_mode(self):
        return _stop_move_grain_center_mode(self)


    # enter grain-center move mode
    def start_move_grain_center_mode(self):
        if _full_grain_dataframe(self) is None:
            messagebox.showinfo("No grains", "Detect grains first.")
            return
        try:
            self.stop_grain_split_lines(disconnect_only=True)
        except TypeError:
            try:
                self.stop_grain_split_lines()
            except Exception:
                pass
        except Exception:
            pass
        _stop_move_grain_center_mode(self)
        ax, canvas = _grain_interaction_visible_ax_canvas(self)
        if ax is None or canvas is None:
            messagebox.showerror("No map", "Could not find the visible map canvas.")
            return
        try:
            toolbar = (
                getattr(canvas, "toolbar", None)
                or getattr(self, "toolbar", None)
                or getattr(self, "map_toolbar", None)
            )
            if toolbar is not None and getattr(toolbar, "mode", ""):
                mode = str(toolbar.mode).lower()
                if "pan" in mode:
                    toolbar.pan()
                elif "zoom" in mode:
                    toolbar.zoom()
        except Exception:
            pass
        self._move_grain_center_active = True
        self._dragging_grain_center = False
        self._drag_grain_center_gid = None
        self._last_grain_drag_xy = None
        self._center_preview_last_draw = 0.0
        self._center_refit_last_time = 0.0
        self._grain_center_canvas = canvas
        self._grain_center_axis = ax
        ids = []
        ids.append(
            (canvas, canvas.mpl_connect("button_press_event", self._move_grain_center_press))
        )
        ids.append(
            (canvas, canvas.mpl_connect("motion_notify_event", self._move_grain_center_motion))
        )
        ids.append(
            (canvas, canvas.mpl_connect("button_release_event", self._move_grain_center_release))
        )
        self._grain_center_event_ids = ids
        try:
            self.status_var.set("Move centers ON: drag directly from a grain center, then release.")
        except Exception:
            pass


    # first mouse press while moving a grain center
    def _move_grain_center_press(self, event):
        if not getattr(self, "_move_grain_center_active", False):
            return
        if getattr(event, "button", None) != 1:
            return
        ax = getattr(self, "_grain_center_axis", None)
        if ax is None or event.inaxes is not ax:
            return
        xy = _center_event_data_xy(self, event)
        if xy is None:
            return
        found = self._nearest_grain_to_xy(*xy)
        if found is None:
            return
        gid, cx, cy, _dist_data = found
        try:
            center_px = np.asarray(ax.transData.transform((float(cx), float(cy))), dtype=float)
            click_px = np.asarray([float(event.x), float(event.y)], dtype=float)
            pixel_distance = float(np.hypot(*center_px - click_px))
        except Exception:
            pixel_distance = np.inf
        if not np.isfinite(pixel_distance) or pixel_distance > 16.0:
            try:
                self.status_var.set("Move centers: start the drag on a red/yellow grain center.")
            except Exception:
                pass
            return
        self._dragging_grain_center = True
        self._drag_grain_center_gid = int(gid)
        self._drag_grain_center_start = (float(cx), float(cy))
        self._last_grain_drag_xy = xy
        self._draw_drag_center_preview(*xy)
        try:
            self.status_var.set(f"Dragging grain {gid}. Release at the corrected center.")
        except Exception:
            pass


    # move center motion for grain analysis
    def _move_grain_center_motion(self, event):
        if not getattr(self, "_move_grain_center_active", False) or not getattr(
            self, "_dragging_grain_center", False
        ):
            return
        xy = _center_event_data_xy(self, event)
        if xy is None:
            return
        self._last_grain_drag_xy = xy
        self._draw_drag_center_preview(*xy)
        try:
            live = bool(self.grain_live_refit_center_var.get())
        except Exception:
            live = False
        if live and getattr(self, "_drag_grain_center_gid", None) is not None:
            now = time.monotonic()
            if now - float(getattr(self, "_center_refit_last_time", 0.0)) >= 0.12:
                self._center_refit_last_time = now
                self._set_manual_center_and_refit(
                    self._drag_grain_center_gid, xy[0], xy[1], redraw=False
                )


    # move center release for grain analysis
    def _move_grain_center_release(self, event):
        if not getattr(self, "_dragging_grain_center", False):
            return
        gid = getattr(self, "_drag_grain_center_gid", None)
        xy = _center_event_data_xy(self, event) or getattr(self, "_last_grain_drag_xy", None)
        self._dragging_grain_center = False
        self._drag_grain_center_gid = None
        self._last_grain_drag_xy = None
        if gid is None or xy is None:
            try:
                self._clear_drag_center_preview()
            except Exception:
                pass
            return
        self._set_manual_center_and_refit(int(gid), float(xy[0]), float(xy[1]), redraw=False)
        try:
            self._clear_drag_center_preview()
        except Exception:
            pass
        self.refresh_grain_view()
        try:
            self.status_var.set(
                f"Moved grain {gid} center using mode: {self._ellipse_refit_mode()}."
            )
        except Exception:
            pass


    # clear manual grain centers
    def clear_manual_grain_centers(self):
        _stop_move_grain_center_mode(self)
        moved = len(getattr(self, "manual_grain_centers", {}) or {})
        self.manual_grain_centers = {}
        manual_cols = [
            "manual_center_x",
            "manual_center_y",
            "center_manually_moved",
            "manual_center_refit_mode",
        ]
        for attr in [
            "last_grain_df",
            "last_grain_df_full",
            "last_grain_table_full",
            "last_grain_mean_df",
            "last_grain_means_df",
        ]:
            df = getattr(self, attr, None)
            if isinstance(df, pd.DataFrame):
                try:
                    setattr(self, attr, df.drop(columns=manual_cols, errors="ignore").copy())
                except Exception:
                    pass
        self.last_grain_radial_pixel_df = pd.DataFrame()
        self.last_grain_radial_bin_df = pd.DataFrame()
        try:
            self.refresh_grain_view()
        except Exception:
            pass
        try:
            self.status_var.set(f"Reset {moved} moved grain center(s).")
        except Exception:
            pass


    # redraw grains after center move
    def _redraw_grains_after_center_move(self):
        try:
            return self.refresh_grain_view()
        except Exception:
            return None


    # queue grain display helper for grain analysis
    def queue_grain_display(self):
        mode = str(
            getattr(
                self, "grain_display_mode_var", tk.StringVar(value="Element map + outlines")
            ).get()
        )
        if mode == "Element map + outlines":
            callback = lambda: self.show_grains_on_selected_element_map()
        elif mode == "Colored grain labels":
            callback = lambda: self.show_grain_labels_without_offset()
        else:
            return
        try:
            self.after_idle(callback)
        except Exception:
            try:
                callback()
            except Exception:
                pass


    # make sure shape metrics exists for grain analysis
    def ensure_grain_shape_metrics(self, df):
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return df
        out = df.copy()
        if "grain_area_coordinate_units2" not in out.columns:
            out["grain_area_coordinate_units2"] = _first_numeric_grain_column(
                out, ["grain_area_units2", "area_units2", "grain_area_coordinate_units"]
            )
        if "grain_area_um2" not in out.columns:
            out["grain_area_um2"] = pd.Series(np.nan, index=out.index, dtype=float)
        if "grain_area" not in out.columns:
            out["grain_area"] = _first_numeric_grain_column(
                out, ["grain_area_um2", "grain_area_coordinate_units2", "grain_area_units2", "area_units2"]
            )
        else:
            physical = pd.to_numeric(out["grain_area_um2"], errors="coerce")
            current = pd.to_numeric(out["grain_area"], errors="coerce")
            out["grain_area"] = physical.where(np.isfinite(physical), current)
        if "grain_area_pixels" not in out.columns:
            out["grain_area_pixels"] = _first_numeric_grain_column(out, ["area_pixels"])
        if "grain_length" not in out.columns:
            out["grain_length"] = _first_numeric_grain_column(
                out,
                [
                    "best_ellipse_major_axis",
                    "ellipse_boundary_major_axis",
                    "ellipse_projected_major_axis",
                    "ellipse_major_axis",
                    "grain_ellipse_major_axis",
                ],
            )
            if out["grain_length"].isna().all():
                width_x = _first_numeric_grain_column(out, ["grain_width_x_units", "bbox_width"])
                height_y = _first_numeric_grain_column(out, ["grain_height_y_units", "bbox_height"])
                out["grain_length"] = pd.concat([width_x, height_y], axis=1).max(axis=1)
        if "grain_width" not in out.columns:
            out["grain_width"] = _first_numeric_grain_column(
                out,
                [
                    "best_ellipse_minor_axis",
                    "ellipse_boundary_minor_axis",
                    "ellipse_projected_minor_axis",
                    "ellipse_minor_axis",
                    "grain_ellipse_minor_axis",
                ],
            )
            if out["grain_width"].isna().all():
                width_x = _first_numeric_grain_column(out, ["grain_width_x_units", "bbox_width"])
                height_y = _first_numeric_grain_column(out, ["grain_height_y_units", "bbox_height"])
                out["grain_width"] = pd.concat([width_x, height_y], axis=1).min(axis=1)
        length = pd.to_numeric(out["grain_length"], errors="coerce")
        width = pd.to_numeric(out["grain_width"], errors="coerce")
        out["grain_length"] = pd.concat([length, width], axis=1).max(axis=1)
        out["grain_width"] = pd.concat([length, width], axis=1).min(axis=1)
        if "grain_aspect_ratio" not in out.columns:
            with np.errstate(divide="ignore", invalid="ignore"):
                out["grain_aspect_ratio"] = out["grain_length"] / out["grain_width"]
        else:
            current = pd.to_numeric(out["grain_aspect_ratio"], errors="coerce")
            with np.errstate(divide="ignore", invalid="ignore"):
                calculated = out["grain_length"] / out["grain_width"]
            out["grain_aspect_ratio"] = current.where(np.isfinite(current), calculated)
        if "grain_roundness" not in out.columns:
            roundness = _first_numeric_grain_column(
                out, ["circularity_approx", "roundness", "circularity"]
            )
            if roundness.isna().all():
                perimeter = _first_numeric_grain_column(
                    out, ["grain_perimeter", "perimeter_approx_units", "perimeter"]
                )
                area = pd.to_numeric(out["grain_area"], errors="coerce")
                with np.errstate(divide="ignore", invalid="ignore"):
                    roundness = 4.0 * np.pi * area / perimeter**2
            out["grain_roundness"] = roundness.clip(lower=0.0, upper=1.0)
        return out


    # metrics from component
    def _grain_metrics_from_component(self, pixels, x, y, values):
        rows = np.asarray([p[0] for p in pixels], dtype=int)
        cols = np.asarray([p[1] for p in pixels], dtype=int)
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        values = np.asarray(values, dtype=float)
        xv = x[cols]
        yv = y[rows]

        # Pixel centers are converted to cell edges so non-square and mildly non-uniform
        # pixels are measured correctly. On a regular grid this is exactly N * dx * dy.
        try:
            x_edges = self._centers_to_edges_1d(x)
            y_edges = self._centers_to_edges_1d(y)
            x_widths = np.abs(np.diff(x_edges))
            y_heights = np.abs(np.diff(y_edges))
        except Exception:
            x_widths = np.full(x.size, 1.0, dtype=float)
            y_heights = np.full(y.size, 1.0, dtype=float)
            x_edges = np.arange(x.size + 1, dtype=float) - 0.5
            y_edges = np.arange(y.size + 1, dtype=float) - 0.5
        good_x = x_widths[np.isfinite(x_widths) & (x_widths > 0)]
        good_y = y_heights[np.isfinite(y_heights) & (y_heights > 0)]
        dx = float(np.nanmedian(good_x)) if good_x.size else 1.0
        dy = float(np.nanmedian(good_y)) if good_y.size else 1.0
        area_pixels = int(len(pixels))
        if area_pixels:
            local_areas = x_widths[cols] * y_heights[rows]
            local_areas = local_areas[np.isfinite(local_areas) & (local_areas > 0)]
            area = float(np.sum(local_areas)) if local_areas.size else float(area_pixels * dx * dy)
        else:
            area = 0.0
        center_x = float(np.nanmean(xv))
        center_y = float(np.nanmean(yv))
        if xv.size:
            c0, c1 = int(np.nanmin(cols)), int(np.nanmax(cols))
            r0, r1 = int(np.nanmin(rows)), int(np.nanmax(rows))
            bbox_width = float(abs(x_edges[c1 + 1] - x_edges[c0]))
            bbox_height = float(abs(y_edges[r1 + 1] - y_edges[r0]))
        else:
            bbox_width = np.nan
            bbox_height = np.nan
        if xv.size >= 2:
            centered = np.column_stack([xv - center_x, yv - center_y])
            covariance = np.cov(centered, rowvar=False)
            eigvals, eigvecs = np.linalg.eigh(covariance)
            order = np.argsort(eigvals)[::-1]
            eigvals = eigvals[order]
            eigvecs = eigvecs[:, order]
            moment_major = 4.0 * np.sqrt(max(float(eigvals[0]), 0.0))
            moment_minor = (
                4.0 * np.sqrt(max(float(eigvals[1]), 0.0)) if eigvals.size > 1 else np.nan
            )
            moment_angle = float(np.degrees(np.arctan2(eigvecs[1, 0], eigvecs[0, 0])))
        else:
            moment_major = moment_minor = moment_angle = np.nan
        try:
            projected_cx, projected_cy, projected_major, projected_minor, projected_angle = (
                self._fit_projected_extent_ellipse(xv, yv)
            )
        except Exception:
            projected_cx, projected_cy = (center_x, center_y)
            projected_major = max(bbox_width, bbox_height)
            projected_minor = min(bbox_width, bbox_height)
            projected_angle = 0.0 if bbox_width >= bbox_height else 90.0
        boundary_rows, boundary_cols = self._grain_boundary_pixels(rows, cols)
        boundary_x = x[boundary_cols]
        boundary_y = y[boundary_rows]
        try:
            fit_cx, fit_cy, length, width, angle = self._fit_boundary_ellipse(
                boundary_x, boundary_y
            )
        except Exception:
            fit_cx, fit_cy = (center_x, center_y)
            length = max(bbox_width, bbox_height)
            width = min(bbox_width, bbox_height)
            angle = 0.0 if bbox_width >= bbox_height else 90.0
        if np.isfinite(length) and np.isfinite(width) and (width > length):
            length, width = (width, length)
            angle = float(angle) + 90.0
        aspect = (
            float(length / width)
            if np.isfinite(length) and np.isfinite(width) and (width > 0)
            else np.nan
        )
        pixel_set = set(zip(rows.tolist(), cols.tolist()))
        perimeter = 0.0
        for row, col in pixel_set:
            horizontal_edge = float(x_widths[col]) if np.isfinite(x_widths[col]) else dx
            vertical_edge = float(y_heights[row]) if np.isfinite(y_heights[row]) else dy
            if (row - 1, col) not in pixel_set:
                perimeter += horizontal_edge
            if (row + 1, col) not in pixel_set:
                perimeter += horizontal_edge
            if (row, col - 1) not in pixel_set:
                perimeter += vertical_edge
            if (row, col + 1) not in pixel_set:
                perimeter += vertical_edge
        roundness = 4.0 * np.pi * area / perimeter**2 if perimeter > 0 else np.nan
        if np.isfinite(roundness):
            roundness = float(np.clip(roundness, 0.0, 1.0))
        grain_values = values[rows, cols]
        valid_values = grain_values[np.isfinite(grain_values)]
        element_mean = float(np.nanmean(valid_values)) if valid_values.size else np.nan
        element_sd = float(np.nanstd(valid_values, ddof=1)) if valid_values.size > 1 else np.nan
        element_cv = (
            element_sd / element_mean
            if np.isfinite(element_sd) and np.isfinite(element_mean) and (element_mean != 0)
            else np.nan
        )
        return {
            "area_pixels": area_pixels,
            "grain_area_pixels": area_pixels,
            "area_units2": area,
            "grain_area_coordinate_units2": area,
            "pixel_size_x_coordinate_units": dx,
            "pixel_size_y_coordinate_units": dy,
            "pixel_area_coordinate_units2": float(dx * dy),
            "bbox_width": bbox_width,
            "bbox_height": bbox_height,
            "grain_width_x_units": bbox_width,
            "grain_height_y_units": bbox_height,
            "aspect_ratio_x_over_y": (
                bbox_width / bbox_height
                if np.isfinite(bbox_width) and np.isfinite(bbox_height) and (bbox_height > 0)
                else np.nan
            ),
            "x_y_aspect_ratio": (
                bbox_width / bbox_height
                if np.isfinite(bbox_width) and np.isfinite(bbox_height) and (bbox_height > 0)
                else np.nan
            ),
            "centroid_x": center_x,
            "centroid_y": center_y,
            "ellipse_major_axis": float(moment_major) if np.isfinite(moment_major) else np.nan,
            "ellipse_minor_axis": float(moment_minor) if np.isfinite(moment_minor) else np.nan,
            "orientation_deg": float(moment_angle) if np.isfinite(moment_angle) else np.nan,
            "axial_ratio": (
                float(moment_major) / float(moment_minor)
                if np.isfinite(moment_major) and np.isfinite(moment_minor) and (moment_minor > 0)
                else np.nan
            ),
            "ellipse_projected_center_x": float(projected_cx),
            "ellipse_projected_center_y": float(projected_cy),
            "ellipse_projected_major_axis": float(projected_major),
            "ellipse_projected_minor_axis": float(projected_minor),
            "ellipse_projected_orientation_deg": float(projected_angle),
            "ellipse_projected_axial_ratio": (
                float(projected_major) / float(projected_minor)
                if np.isfinite(projected_major)
                and np.isfinite(projected_minor)
                and (projected_minor > 0)
                else np.nan
            ),
            "ellipse_boundary_center_x": float(fit_cx),
            "ellipse_boundary_center_y": float(fit_cy),
            "ellipse_boundary_major_axis": float(length),
            "ellipse_boundary_minor_axis": float(width),
            "ellipse_boundary_orientation_deg": float(angle),
            "ellipse_boundary_axial_ratio": aspect,
            "best_ellipse_major_axis": float(length),
            "best_ellipse_minor_axis": float(width),
            "best_ellipse_axial_ratio": aspect,
            "best_ellipse_orientation_deg": float(angle),
            "grain_length": float(length),
            "grain_width": float(width),
            "grain_aspect_ratio": aspect,
            "grain_perimeter": float(perimeter),
            "grain_roundness": roundness,
            "element_n": int(valid_values.size),
            "element_mean": element_mean,
            "element_sd": element_sd,
            "element_cv": element_cv,
        }


    # profile candidate pixels helper for radial profiles
    def _radial_profile_candidate_pixels(self, grain_id, grain_row):
        labels = np.asarray(self.last_grain_label_mask, dtype=int)
        x_axis = np.asarray(self.last_grain_x, dtype=float)
        y_axis = np.asarray(self.last_grain_y, dtype=float)
        rr, cc = np.where(labels == int(grain_id))
        if rr.size == 0:
            return pd.DataFrame()
        base = pd.DataFrame(
            {
                "grain_id": int(grain_id),
                "row_index": rr.astype(int),
                "column_index": cc.astype(int),
                "x": x_axis[cc],
                "y": y_axis[rr],
            }
        )
        base["pixel_id"] = [f"grain_{int(grain_id)}_r{int(r)}_c{int(c)}" for r, c in zip(rr, cc)]
        shape_row = self.ensure_grain_shape_metrics(pd.DataFrame([grain_row])).iloc[0]
        for column in [
            "grain_area",
            "grain_area_pixels",
            "grain_length",
            "grain_width",
            "grain_aspect_ratio",
            "grain_roundness",
        ]:
            if column in shape_row.index:
                base[column] = shape_row[column]
        layers = self._compatible_layers_for_grain_mask()
        for layer in layers:
            clean = self._grain_channel_name(layer)
            try:
                arr = np.asarray(self.values[layer], dtype=float)
                if arr.shape == labels.shape:
                    sampled = arr[rr, cc]
                else:
                    sampled = self._sample_layer_at_xy_for_radial(
                        layer, base["x"].to_numpy(dtype=float), base["y"].to_numpy(dtype=float)
                    )
            except Exception:
                continue
            sampled = pd.Series(sampled, index=base.index, dtype=float)
            if clean not in base.columns:
                base[clean] = sampled
            else:
                existing = pd.to_numeric(base[clean], errors="coerce")
                base[clean] = existing.where(existing.notna(), sampled)
        return base


    # export radial profile pixels
    def export_grain_radial_profile_pixels(self):
        try:
            pixels, _ = self.build_grain_radial_distance_profile_table()
        except Exception as exc:
            messagebox.showerror("Radial profiles failed", str(exc))
            return
        self.save_df_csv(pixels, "grain_radial_pixels.csv", "grain radial pixels")


    # simplify grain output columns helper for grain analysis
    def simplify_grain_output_columns(self, df, keep_radial=True):
        return simplify_grain_output_columns_shape_only(self, df, keep_radial)


    # grain source table helper for comparison plots
    def _compare_grain_source_table(self, apply_filters=True):
        df = _combined_grain_comparison_table(self)
        if not isinstance(df, pd.DataFrame):
            return pd.DataFrame()
        df = self.ensure_grain_shape_metrics(df).copy()
        if apply_filters and not df.empty:
            df = _filter_table(self, df)
            df = _apply_plot_filter_to_table(self, df)
        return df


    # update grain group order for comparison plots
    def update_compare_grain_group_order(self, event=None):
        df = self._compare_grain_source_table()
        if df is None:
            return
        group_column = (
            self.compare_grain_group_var.get() if hasattr(self, "compare_grain_group_var") else ""
        )
        if group_column in df.columns:
            groups = [str(value) for value in pd.unique(df[group_column].fillna("NA"))]
        else:
            groups = ["All grains"]
        self._compare_grain_group_order = groups
        if hasattr(self, "compare_grain_group_order_var"):
            self.compare_grain_group_order_var.set("Group order: " + " | ".join(groups))


    # refresh grain controls for comparison plots
    def refresh_compare_grain_controls(self):
        if not hasattr(self, "compare_grain_group_combo"):
            return
        df = self._compare_grain_source_table()
        if df is None:
            self.compare_grain_group_combo.configure(values=[])
            self.compare_grain_metric_combo.configure(values=list(_GRAIN_METRIC_COLUMNS.keys()))
            return
        group_columns = _compare_group_columns(df)
        self.compare_grain_group_combo.configure(values=group_columns)
        self.compare_grain_metric_combo.configure(values=list(_GRAIN_METRIC_COLUMNS.keys()))
        if group_columns and self.compare_grain_group_var.get() not in group_columns:
            self.compare_grain_group_var.set(group_columns[0])
        if self.compare_grain_metric_var.get() == "Area":
            self.compare_grain_metric_var.set("Area (µm²)")
        if self.compare_grain_metric_var.get() not in _GRAIN_METRIC_COLUMNS:
            self.compare_grain_metric_var.set("Area (µm²)")
        self.update_compare_grain_group_order()


    # colors used for grain-comparison groups
    def _compare_grain_colors(self, groups):
        raw = (
            str(self.compare_grain_colors_var.get()).strip()
            if hasattr(self, "compare_grain_colors_var")
            else ""
        )
        requested = [value.strip() for value in raw.split(",") if value.strip()]
        for color in requested:
            if not mcolors.is_color_like(color):
                raise ValueError(f"'{color}' is not a valid Matplotlib color.")
        cmap = plt.get_cmap("tab10")
        colors = []
        for index, _group in enumerate(groups):
            colors.append(requested[index] if index < len(requested) else cmap(index % 10))
        return colors


    # switch the analysis source to radial pixels
    def use_grain_radial_pixels_for_analysis(self):
        try:
            pixels, binned = self.build_grain_radial_distance_profile_table()
        except Exception as exc:
            messagebox.showerror("Radial profiles failed", str(exc))
            return
        try:
            if (
                hasattr(self, "profile_color_groups_var")
                and str(self.profile_color_groups_var.get()).strip()
            ):
                pixels = _apply_selected_profile_groups(self, pixels)
                binned = _apply_selected_profile_groups(self, binned)
        except Exception:
            pass
        self.last_grain_radial_profile_pixels_df = pixels.copy()
        self.last_grain_radial_profile_bins_df = binned.copy()
        self._full_analysis_df_for_plotting = pixels.copy()
        self.activate_analysis_table(pixels, "radial profile pixels", mirror_to_comparison=False)
        n_grains = int(pixels["grain_id"].nunique()) if "grain_id" in pixels.columns else 0
        if "grain_id" in pixels.columns and "profile_number" in pixels.columns:
            profile_groups = pixels.groupby(["grain_id", "profile_number"], dropna=False)
            n_profiles = int(profile_groups.ngroups)
            median_pixels = float(profile_groups.size().median()) if n_profiles else 0.0
        elif "profile_id" in pixels.columns:
            n_profiles = int(pixels["profile_id"].nunique())
            median_pixels = float(pixels.groupby("profile_id").size().median()) if n_profiles else 0.0
        else:
            n_profiles = 0
            median_pixels = 0.0
        buffer_px = self.get_radial_profile_buffer_pixels()
        self.status_var.set(
            f"Radial pixels active: {len(pixels):,} rows, {n_profiles} profiles, {n_grains} grains, median {median_pixels:.0f} pixels/profile, {buffer_px} px buffer."
        )


    # add grain IQR controls for comparison plots
    def add_compare_grain_iqr_controls(self):
        if not hasattr(self, "compare_grain_tab"):
            return
        target = None
        for widget in _walk_widgets(self.compare_grain_tab):
            if _widget_text(widget) == "Colors, same order (optional):":
                target = widget.master
                break
            if _widget_text(widget) == "Group colors, in the order above (optional):":
                target = widget.master
                break
        if target is None:
            return
        if any((_widget_text(w) == "Filter outliers by IQR" for w in _walk_widgets(target))):
            return
        row = ttk.Frame(target)
        row.pack(
            fill=tk.X,
            pady=(2, 5),
            before=next(
                (
                    w
                    for w in target.winfo_children()
                    if _widget_text(w) in {"Plot comparison", "Plot grain comparison"}
                ),
                None,
            ),
        )
        ttk.Checkbutton(row, text="Filter outliers by IQR", variable=self.plot_iqr_enabled_var).pack(
            side=tk.LEFT
        )
        ttk.Entry(row, textvariable=self.plot_iqr_multiplier_var, width=6).pack(side=tk.RIGHT)


    # store current grain analysis run helper
    def store_current_grain_analysis_run(self, refresh=True):
        grain_df = getattr(self, "last_grain_df", None)
        labels = getattr(self, "last_grain_label_mask", None)
        if not isinstance(grain_df, pd.DataFrame) or grain_df.empty or labels is None:
            return None
        try:
            labels_arr = np.asarray(labels)
            if labels_arr.ndim != 2 or not np.any(labels_arr > 0):
                return None
        except Exception:
            return None
        key = _grain_run_current_key(self)
        mineral = getattr(self, "last_grain_mineral_type", None) or key
        runs = getattr(self, "grain_analysis_runs", None)
        if not isinstance(runs, dict):
            runs = {}
            self.grain_analysis_runs = runs
        for attr in [
            "last_grain_df",
            "last_grain_df_full",
            "last_grain_table_df",
            "last_grain_pixel_df",
            "last_grain_summary_df",
            "last_grain_radial_profile_pixels_df",
            "last_grain_radial_profile_bins_df",
            "last_grain_radial_pixel_df",
            "last_grain_radial_bin_df",
            "manual_grain_merge_groups",
        ]:
            value = getattr(self, attr, None)
            if isinstance(value, pd.DataFrame) and (not value.empty):
                try:
                    setattr(self, attr, _add_grain_set_identity(value, key, mineral))
                except Exception:
                    pass
        snapshot = {
            "grain_set": str(key),
            "mineral_type": str(mineral),
            "manual_grain_split_lines": _project_copy(getattr(self, "manual_grain_split_lines", [])),
            "manual_grain_centers": _project_copy(getattr(self, "manual_grain_centers", {})),
            "manual_grain_merge_groups": _project_copy(getattr(self, "manual_grain_merge_groups", [])),
            "grain_mask_value": self._safe_project_var_value("grain_mask_var", ""),
            "grain_value_value": self._safe_project_var_value("grain_value_var", ""),
            "grain_display_mode": self._safe_project_var_value(
                "grain_display_mode_var", "Element map + outlines"
            ),
            "radial_lines_visible": bool(getattr(self, "_grain_radial_lines_visible", False)),
            "attrs": {},
        }
        for attr in _PROJECT_GRAIN_ATTRS:
            if hasattr(self, attr):
                snapshot["attrs"][attr] = _project_copy(getattr(self, attr))
        runs[str(key)] = snapshot
        self.active_grain_analysis_key = str(key)
        if refresh:
            try:
                self.refresh_grain_analysis_set_controls()
            except Exception:
                pass
        return str(key)


    # refresh analysis set controls for grain analysis
    def refresh_grain_analysis_set_controls(self):
        combo = getattr(self, "grain_analysis_set_combo", None)
        var = getattr(self, "grain_analysis_set_var", None)
        if combo is None or var is None:
            return
        keys = list(getattr(self, "grain_analysis_runs", {}).keys())
        combo.configure(values=keys)
        active = getattr(self, "active_grain_analysis_key", None)
        if active in keys:
            var.set(active)
        elif keys and var.get() not in keys:
            var.set(keys[-1])
        elif not keys:
            var.set("")


    # show selected grain analysis set
    def show_selected_grain_analysis_set(self):
        try:
            key = str(self.grain_analysis_set_var.get()).strip()
        except Exception:
            key = ""
        if not key:
            messagebox.showinfo("No grain set", "Detect grains for a mineral first.")
            return
        current = getattr(self, "active_grain_analysis_key", None)
        if current and current != key:
            try:
                self.store_current_grain_analysis_run(refresh=False)
            except Exception:
                pass
        try:
            _apply_grain_analysis_run(self, key, redraw=True)
        except Exception as exc:
            messagebox.showerror("Could not show grain set", str(exc))


    # switch the analysis source to all detected grain pixels
    def use_all_detected_grain_pixels(self):
        table = combined_grain_pixel_table(self)
        if table.empty:
            messagebox.showinfo("No grain pixels", "Detect grains for one or more minerals first.")
            return
        self.activate_analysis_table(table, "all detected grain pixels", mirror_to_comparison=False)
        self.status_var.set(
            f"Using {len(table):,} grain pixels from {table['grain_set'].nunique()} detected grain set(s)."
        )


    # switch the analysis source to all detected grain means
    def use_all_detected_grain_means(self):
        table = combined_grain_mean_table(self)
        if table.empty:
            messagebox.showinfo("No grain means", "Detect grains for one or more minerals first.")
            return
        self.activate_analysis_table(table, "all detected grain means", mirror_to_comparison=False)
        self.status_var.set(
            f"Using {len(table):,} grain means from {table['grain_set'].nunique()} detected grain set(s)."
        )



    # Public button action for running the grain-detection workflow.


    # detect grains main
    def detect_grains_main(self, *args, **kwargs):
        result = _run_and_store_grain_detection(self, *args, **kwargs)
        grain_df = getattr(self, "last_grain_df", None)
        labels = getattr(self, "last_grain_label_mask", None)
        if isinstance(grain_df, pd.DataFrame) and (not grain_df.empty) and (labels is not None):
            if not getattr(self, "active_grain_analysis_key", None):
                self.active_grain_analysis_key = _grain_run_target_key(self)
            try:
                self.store_current_grain_analysis_run(refresh=True)
                self.last_compare_grain_df = combined_grain_shape_table(self)
                self.refresh_compare_grain_controls()
            except Exception:
                pass
        return result


    # refresh grain plot settings for comparison plots
    def _refresh_compare_grain_plot_settings(self, event=None):
        style = (
            self.compare_grain_plot_style_var.get()
            if hasattr(self, "compare_grain_plot_style_var")
            else "Overlaid histograms"
        )
        if hasattr(self, "compare_grain_hist_options"):
            self.compare_grain_hist_options.pack_forget()
        if hasattr(self, "compare_grain_kde_options"):
            self.compare_grain_kde_options.pack_forget()
        if style == "Overlaid histograms" and hasattr(self, "compare_grain_hist_options"):
            self.compare_grain_hist_options.pack(fill=tk.X)
        elif style == "KDE curves" and hasattr(self, "compare_grain_kde_options"):
            self.compare_grain_kde_options.pack(fill=tk.X)


    # plot grain metric for comparison plots
    def plot_compare_grain_metric(self):
        df = self._compare_grain_source_table(apply_filters=True)
        if df is None or df.empty:
            messagebox.showinfo("No grain data", "No grains match the current row filter.")
            return
        metric_label = self.compare_grain_metric_var.get()
        metric_column = _GRAIN_METRIC_COLUMNS.get(metric_label)
        if metric_column not in df.columns:
            messagebox.showerror(
                "Metric unavailable", f"{metric_label} is not available in this grain table."
            )
            return
        group_column = self.compare_grain_group_var.get()
        work = self.ensure_grain_shape_metrics(df).copy()
        work[metric_column] = pd.to_numeric(work[metric_column], errors="coerce")
        work = work[np.isfinite(work[metric_column])].copy()
        if work.empty:
            messagebox.showerror(
                "No valid values", f"No numeric {metric_label.lower()} values were found."
            )
            return
        try:
            filtered, iqr_info = self._apply_iqr_filter(
                work,
                [metric_column],
                group_col=group_column if group_column in work.columns else None,
            )
        except Exception as exc:
            messagebox.showerror("IQR filter", str(exc))
            return
        work = filtered
        if work.empty:
            messagebox.showerror("No valid values", "No grain values remain after filtering.")
            return
        if group_column in work.columns:
            grouped = list(work.groupby(group_column, dropna=False, sort=False))
        else:
            grouped = [("All grains", work)]
        groups = []
        for name, sub in grouped:
            array = pd.to_numeric(sub[metric_column], errors="coerce").to_numpy(dtype=float)
            array = array[np.isfinite(array)]
            if array.size:
                groups.append((str(name), array))
        if not groups:
            messagebox.showerror("No valid values", "No grain values remain to plot.")
            return
        group_names = [name for name, _array in groups]
        try:
            colors = self._compare_grain_colors(group_names)
        except Exception as exc:
            messagebox.showerror("Group colors", str(exc))
            return
        self.compare_grain_fig.clear()
        self.compare_grain_ax = self.compare_grain_fig.add_subplot(111)
        style = self.compare_grain_plot_style_var.get()
        self.last_compare_grain_kde_df = None
        if style == "Box + points":
            arrays = [array for _name, array in groups]
            self.compare_grain_ax.boxplot(arrays, labels=group_names, vert=True, showfliers=False)
            rng = np.random.default_rng(1)
            for index, ((_name, array), color) in enumerate(zip(groups, colors), start=1):
                xj = rng.normal(index, 0.04, size=len(array))
                self.compare_grain_ax.scatter(xj, array, s=9, alpha=0.5, color=color)
            self.compare_grain_ax.set_ylabel(metric_label)
            self.compare_grain_ax.tick_params(axis="x", rotation=45)
        elif style == "KDE curves":
            try:
                bandwidth_multiplier = float(self.compare_grain_kde_bandwidth_var.get())
            except Exception:
                messagebox.showerror(
                    "KDE bandwidth", "Bandwidth multiplier must be a positive number."
                )
                return
            if not np.isfinite(bandwidth_multiplier) or bandwidth_multiplier <= 0:
                messagebox.showerror(
                    "KDE bandwidth", "Bandwidth multiplier must be a positive number."
                )
                return
            all_values = np.concatenate([array for _name, array in groups])
            xmin = float(np.nanmin(all_values))
            xmax = float(np.nanmax(all_values))
            spread = xmax - xmin
            if not np.isfinite(spread) or spread <= 0:
                messagebox.showerror("KDE", "The selected grain metric has no spread.")
                return
            pad = 0.05 * spread
            grid = np.linspace(xmin - pad, xmax + pad, 500)
            output_rows = []
            skipped = []
            for (name, array), color in zip(groups, colors):
                try:
                    density, bandwidth = _grain_kde_on_common_grid(
                        array, grid, bandwidth_multiplier=bandwidth_multiplier
                    )
                except Exception as exc:
                    skipped.append(f"{name}: {exc}")
                    continue
                self.compare_grain_ax.plot(
                    grid, density, linewidth=2.0, color=color, label=f"{name} (n={array.size})"
                )
                output_rows.extend(
                    (
                        {
                            "group": name,
                            "group_column": group_column if group_column in work.columns else "",
                            "metric": metric_label,
                            "metric_column": metric_column,
                            "x": float(x_value),
                            "density": float(y_value),
                            "n_grains": int(array.size),
                            "bandwidth": float(bandwidth),
                            "bandwidth_multiplier": float(bandwidth_multiplier),
                        }
                        for x_value, y_value in zip(grid, density)
                    )
                )
            if not output_rows:
                messagebox.showerror(
                    "KDE", "No group had enough spread and at least 3 grains for a KDE curve."
                )
                return
            self.last_compare_grain_kde_df = pd.DataFrame(output_rows)
            self.compare_grain_ax.set_xlabel(metric_label)
            self.compare_grain_ax.set_ylabel("Density")
            if bool(self.compare_grain_kde_log_y_var.get()):
                self.compare_grain_ax.set_yscale("log")
            self.compare_grain_ax.legend(
                title=group_column if group_column in work.columns else None, frameon=True
            )
            if skipped:
                try:
                    self.status_var.set("KDE plotted. Skipped " + "; ".join(skipped))
                except Exception:
                    pass
        else:
            all_values = np.concatenate([array for _name, array in groups])
            raw_width = str(self.compare_grain_bin_width_var.get()).strip()
            if raw_width:
                try:
                    bin_width = float(raw_width)
                except Exception:
                    messagebox.showerror("Bin width", "Use a positive number or leave it blank.")
                    return
                if not np.isfinite(bin_width) or bin_width <= 0:
                    messagebox.showerror("Bin width", "Use a positive number or leave it blank.")
                    return
                start = np.floor(np.nanmin(all_values) / bin_width) * bin_width
                stop = np.ceil(np.nanmax(all_values) / bin_width) * bin_width
                if np.isclose(start, stop):
                    stop = start + bin_width
                bins = np.arange(start, stop + bin_width * 1.001, bin_width)
            else:
                bins = 30
            for (name, array), color in zip(groups, colors):
                self.compare_grain_ax.hist(
                    array,
                    bins=bins,
                    histtype="step",
                    linewidth=2.0,
                    label=f"{name} (n={array.size})",
                    color=color,
                )
            self.compare_grain_ax.set_xlabel(metric_label)
            self.compare_grain_ax.set_ylabel("Grain count")
            self.compare_grain_ax.legend(
                title=group_column if group_column in work.columns else None, frameon=True
            )
        self.compare_grain_ax.set_title(f"Grain {metric_label.lower()} distributions")
        self.compare_grain_fig.tight_layout()
        self.compare_grain_canvas.draw_idle()
        self.last_compare_grain_df = self.ensure_grain_shape_metrics(df)
        self.last_compare_grain_plot_df = work.copy()
        try:
            self.status_var.set(f"Grain comparison plotted from {len(work):,} filtered grain row(s).")
        except Exception:
            pass
        try:
            self._append_iqr_note(iqr_info, context="grain comparison")
        except Exception:
            pass


    # explicit selected grain minerals helper
    def _explicit_selected_grain_minerals(self):
        try:
            self.rebuild_mineral_presence_groups_from_metadata()
        except Exception:
            pass
        valid = set((str(k) for k in getattr(self, "mineral_presence_groups", {}).keys()))
        lb = getattr(self, "map_tab_mineral_listbox", None)
        if lb is None:
            lb = getattr(self, "map_view_mineral_listbox", None)
        if lb is None:
            return []
        try:
            selected = [str(lb.get(i)).strip() for i in lb.curselection()]
        except Exception:
            return []
        return [name for name in selected if name in valid]


    # value used for selected mineral
    def _grain_value_for_selected_mineral(self, mineral, preferred=""):
        try:
            index = self.rebuild_mineral_column_index()
        except Exception:
            index = getattr(self, "mineral_column_index", {}) or {}
        available = dict(index.get(str(mineral), {}))
        if not available:
            raise ValueError(f"No map channels are available for {mineral}.")

        # canonical
        def canonical(value):
            value = str(value or "").strip()
            if not value:
                return ""
            try:
                return self.canonical_layer_display_name(value)
            except Exception:
                try:
                    return self.canonical_element_column_name(value)
                except Exception:
                    return value.split(" :: ", 1)[-1].strip()

        for choice in [preferred, getattr(self, "column_var", tk.StringVar(value="")).get()]:
            clean = canonical(choice)
            if clean in available:
                return clean
        try:
            representative = self.mineral_presence_groups[str(mineral)].get("representative_layer")
            clean = canonical(
                self.metas.get(representative, {}).get("canonical_column") or representative
            )
            if clean in available:
                return clean
        except Exception:
            pass
        excluded = {"presence", "present", "x", "y", "mineral_type", "comparison_dataset"}
        candidates = [name for name in available.keys() if str(name).lower() not in excluded]
        if candidates:
            return sorted(candidates, key=str.lower)[0]
        return next(iter(available.keys()))


    # detect selected mineral grain sets
    def detect_selected_mineral_grain_sets(self, minerals=None):
        if minerals is None:
            minerals = self._explicit_selected_grain_minerals()
        minerals = list(dict.fromkeys((str(m) for m in minerals if str(m).strip())))
        if not minerals:
            return _run_single_grain_detection(self)
        try:
            self.store_current_grain_analysis_run(refresh=False)
        except Exception:
            pass
        preferred_value = ""
        try:
            preferred_value = str(self.grain_value_var.get()).strip()
        except Exception:
            pass
        completed = []
        skipped = []
        counts = {}
        for mineral in minerals:
            try:
                value_name = self._grain_value_for_selected_mineral(mineral, preferred_value)
                self.grain_mask_var.set(mineral)
                self.grain_value_var.set(value_name)
                self.active_grain_analysis_key = str(mineral)
                self.manual_grain_split_lines = []
                self.manual_grain_centers = {}
                self.manual_grain_merge_groups = []
                self._manual_grain_merge_undo_stack = []
                self._grain_radial_lines_visible = False
                _run_single_grain_detection(self)
                run = getattr(self, "grain_analysis_runs", {}).get(str(mineral))
                table = None
                if isinstance(run, dict):
                    attrs = run.get("attrs", {})
                    table = attrs.get("last_grain_df_full")
                    if not isinstance(table, pd.DataFrame) or table.empty:
                        table = attrs.get("last_grain_df")
                if not isinstance(table, pd.DataFrame) or table.empty:
                    skipped.append(f"{mineral}: no saved grains")
                    continue
                completed.append(str(mineral))
                counts[str(mineral)] = int(len(table))
            except Exception as exc:
                skipped.append(f"{mineral}: {exc}")
        if not completed:
            try:
                self.status_var.set("No selected mineral grain sets were detected.")
            except Exception:
                pass
            return None
        try:
            self.last_compare_grain_df = combined_grain_shape_table(self)
            self.refresh_compare_grain_controls()
            if (
                hasattr(self, "compare_grain_group_var")
                and "grain_set" in self.last_compare_grain_df.columns
            ):
                self.compare_grain_group_var.set("grain_set")
                self.refresh_compare_grain_controls()
        except Exception:
            pass
        try:
            _apply_grain_analysis_run(self, completed[0], redraw=True)
        except Exception:
            pass
        try:
            self.refresh_grain_analysis_set_controls()
        except Exception:
            pass
        summary = ", ".join((f"{name} ({counts[name]} grains)" for name in completed))
        message = f"Detected {sum(counts.values()):,} grains in {len(completed)} mineral set(s): {summary}."
        if skipped:
            message += " Skipped: " + "; ".join(skipped) + "."
        try:
            self.status_var.set(message)
        except Exception:
            pass
        return completed


    # convert helper to layer fractional indices any
    def _xy_to_layer_fractional_indices_any(self, layer, xs, ys):
        arr = np.asarray(self.values[layer], dtype=float)
        nr, nc = arr.shape
        x_axis, y_axis = self._layer_axes_for_any_sampling(layer)
        xs = np.asarray(xs, dtype=float)
        ys = np.asarray(ys, dtype=float)
        if x_axis[0] <= x_axis[-1]:
            cols = np.interp(xs, x_axis, np.arange(nc, dtype=float), left=np.nan, right=np.nan)
        else:
            cols = np.interp(
                xs, x_axis[::-1], np.arange(nc, dtype=float)[::-1], left=np.nan, right=np.nan
            )
        if y_axis[0] <= y_axis[-1]:
            rows = np.interp(ys, y_axis, np.arange(nr, dtype=float), left=np.nan, right=np.nan)
        else:
            rows = np.interp(
                ys, y_axis[::-1], np.arange(nr, dtype=float)[::-1], left=np.nan, right=np.nan
            )
        return (rows, cols)


    # median X-Y point spacing used by line and profile tools.
    def _median_xy_spacing(self, x, y):
        spacings = []
        try:
            x = np.asarray(x, dtype=float)
            x = x[np.isfinite(x)]
            ux = np.unique(x)
            if ux.size > 1:
                dx = np.diff(np.sort(ux))
                dx = dx[np.isfinite(dx) & (dx > 0)]
                if dx.size:
                    spacings.append(float(np.nanmedian(dx)))
        except Exception:
            pass
        try:
            y = np.asarray(y, dtype=float)
            y = y[np.isfinite(y)]
            uy = np.unique(y)
            if uy.size > 1:
                dy = np.diff(np.sort(uy))
                dy = dy[np.isfinite(dy) & (dy > 0)]
                if dy.size:
                    spacings.append(float(np.nanmedian(dy)))
        except Exception:
            pass
        if spacings:
            return float(np.nanmedian(spacings))
        return 1.0


    # X-Y axes used for shared sampling
    def _layer_xy_axes_for_shared_sampling(self, layer):
        arr = np.asarray(self.values[layer], dtype=float)
        nr, nc = arr.shape
        meta = self.metas.get(layer, {})
        x = np.asarray(meta.get("x", []), dtype=float)
        y = np.asarray(meta.get("y", []), dtype=float)
        if x.ndim != 1 or x.size != nc:
            try:
                xm = np.asarray(meta.get("x_matrix", []), dtype=float)
                if xm.shape == arr.shape:
                    x = np.nanmedian(xm, axis=0)
            except Exception:
                pass
        if y.ndim != 1 or y.size != nr:
            try:
                ym = np.asarray(meta.get("y_matrix", []), dtype=float)
                if ym.shape == arr.shape:
                    y = np.nanmedian(ym, axis=1)
            except Exception:
                pass
        if x.ndim != 1 or x.size != nc or (not np.isfinite(x).any()):
            x = np.arange(nc, dtype=float)
        if y.ndim != 1 or y.size != nr or (not np.isfinite(y).any()):
            y = np.arange(nr, dtype=float)
        return (x.astype(float), y.astype(float))


    # activate shared X-Y as drawable map
    def _activate_shared_xy_as_drawable_map(self, shared_df=None):
        try:
            if shared_df is None:
                shared_df = getattr(self, "shared_coordinate_pixel_df", None)
            if shared_df is None or shared_df.empty:
                return False
            if "x" not in shared_df.columns or "y" not in shared_df.columns:
                return False
            x_vals = np.sort(pd.to_numeric(shared_df["x"], errors="coerce").dropna().unique())
            y_vals = np.sort(pd.to_numeric(shared_df["y"], errors="coerce").dropna().unique())
            if x_vals.size < 2 or y_vals.size < 2:
                return False
            metadata_cols = {
                "row_index",
                "column_index",
                "x",
                "y",
                "coordinate_group_key",
                "base_grid_layer",
                "analysis_level",
                "source_kind",
            }
            numeric_cols = []
            for c in shared_df.columns:
                if c in metadata_cols:
                    continue
                s = pd.to_numeric(shared_df[c], errors="coerce")
                if np.isfinite(s).any():
                    numeric_cols.append(c)
            if not numeric_cols:
                return False
            base_col = None
            try:
                current = self.map_col_var.get()
                if current in numeric_cols:
                    base_col = current
                elif (
                    str(current).startswith("SharedXY::")
                    and str(current).split("::", 1)[1] in numeric_cols
                ):
                    base_col = str(current).split("::", 1)[1]
            except Exception:
                pass
            if base_col is None:
                base_col = numeric_cols[0]
            nx = x_vals.size
            ny = y_vals.size
            pivot_indexed = shared_df.copy()
            pivot_indexed["x"] = pd.to_numeric(pivot_indexed["x"], errors="coerce")
            pivot_indexed["y"] = pd.to_numeric(pivot_indexed["y"], errors="coerce")
            value_mats = {}
            for col in numeric_cols:
                try:
                    piv = pivot_indexed.pivot_table(
                        index="y", columns="x", values=col, aggfunc="mean"
                    )
                    piv = piv.reindex(index=y_vals, columns=x_vals)
                    arr = piv.to_numpy(dtype=float)
                    if arr.shape == (ny, nx):
                        value_mats[col] = arr
                except Exception:
                    pass
            if base_col not in value_mats:
                if value_mats:
                    base_col = next(iter(value_mats.keys()))
                else:
                    return False
            if not hasattr(self, "values") or self.values is None:
                self.values = {}
            if not hasattr(self, "metas") or self.metas is None:
                self.metas = {}
            for col, arr in value_mats.items():
                layer_name = f"SharedXY::{col}"
                self.values[layer_name] = arr
                self.metas[layer_name] = {
                    "x": x_vals.copy(),
                    "y": y_vals.copy(),
                    "source_layer_name": col,
                    "canonical_column": col,
                    "mineral_type": "SharedXY",
                    "map_group": "SharedXY",
                    "coordinate_group_key": str(
                        shared_df.get("coordinate_group_key", pd.Series(["shared"])).iloc[0]
                    ),
                    "kind": "shared_xy_resampled_layer",
                    "shape": arr.shape,
                }
            active_layer = f"SharedXY::{base_col}"
            self.current_layer = active_layer
            self.current_map_layer = active_layer
            self.active_map_layer = active_layer
            self.current_map_name = active_layer
            self.current_map_array = self.values[active_layer]
            self.current_x_axis = x_vals.copy()
            self.current_y_axis = y_vals.copy()
            self.x_axis = x_vals.copy()
            self.y_axis = y_vals.copy()
            self.x_coords = x_vals.copy()
            self.y_coords = y_vals.copy()
            self.map_x = x_vals.copy()
            self.map_y = y_vals.copy()
            try:
                if hasattr(self, "map_col_combo"):
                    vals = list(self.map_col_combo["values"])
                    for col in value_mats:
                        lname = f"SharedXY::{col}"
                        if lname not in vals:
                            vals.append(lname)
                    self.map_col_combo["values"] = vals
                if hasattr(self, "map_col_var"):
                    self.map_col_var.set(active_layer)
            except Exception:
                pass
            try:
                if hasattr(self, "status_var"):
                    self.status_var.set(
                        f"Shared X/Y drawing enabled: {len(value_mats)} columns on {ny}×{nx} base grid."
                    )
            except Exception:
                pass
            return True
        except Exception as exc:
            try:
                if hasattr(self, "status_var"):
                    self.status_var.set(f"Could not activate shared X/Y drawing: {exc}")
            except Exception:
                pass
            return False


    # convert plot X-Y coordinates to fractional raster indices
    @staticmethod
    def _xy_to_fractional_indices_on_axes(xs, ys, x_axis, y_axis):
        xs = np.asarray(xs, dtype=float)
        ys = np.asarray(ys, dtype=float)
        x_axis = np.asarray(x_axis, dtype=float)
        y_axis = np.asarray(y_axis, dtype=float)
        if x_axis[0] <= x_axis[-1]:
            cols = np.interp(
                xs, x_axis, np.arange(x_axis.size, dtype=float), left=np.nan, right=np.nan
            )
        else:
            cols = np.interp(
                xs,
                x_axis[::-1],
                np.arange(x_axis.size, dtype=float)[::-1],
                left=np.nan,
                right=np.nan,
            )
        if y_axis[0] <= y_axis[-1]:
            rows = np.interp(
                ys, y_axis, np.arange(y_axis.size, dtype=float), left=np.nan, right=np.nan
            )
        else:
            rows = np.interp(
                ys,
                y_axis[::-1],
                np.arange(y_axis.size, dtype=float)[::-1],
                left=np.nan,
                right=np.nan,
            )
        return (rows, cols)


    # layer X-Y grids helper for the map view
    def _map_layer_xy_grids(self, layer_name):
        if layer_name not in self.values:
            for candidate in self.values.keys():
                clean = str(candidate).split(" :: ", 1)[-1]
                if clean == layer_name:
                    layer_name = candidate
                    break
        if layer_name not in self.values:
            raise ValueError(f"Layer not found: {layer_name}")
        z = np.asarray(self.values[layer_name], dtype=float)
        meta = self.metas.get(layer_name, {})
        xg, yg = self._layer_pixel_centers(meta, z_shape=z.shape)
        if (
            xg is None
            or yg is None
            or tuple(np.shape(xg)) != tuple(z.shape)
            or (tuple(np.shape(yg)) != tuple(z.shape))
        ):
            x = np.asarray(meta.get("x", []), dtype=float)
            y = np.asarray(meta.get("y", []), dtype=float)
            if x.size == z.shape[1] and y.size == z.shape[0]:
                xg, yg = np.meshgrid(x, y)
            else:
                yy, xx = np.indices(z.shape)
                xg, yg = (xx.astype(float), yy.astype(float))
        return (z, meta, np.asarray(xg, dtype=float), np.asarray(yg, dtype=float))


    # convert data X-Y to fractional indices
    def data_xy_to_fractional_indices(self, x, y):
        z = self.current_z
        n_rows, n_cols = z.shape
        left, right, bottom, top = self.current_extent
        col_f = (x - left) / (right - left) * n_cols - 0.5
        kind = self.current_meta.get("kind", "")
        if kind == "matrix_file":
            row_f = (y - top) / (bottom - top) * n_rows - 0.5
        else:
            row_f = (y - bottom) / (top - bottom) * n_rows - 0.5
        return (row_f, col_f)


    # current grid X-Y for mask
    def _current_grid_xy_for_mask(self, mask):
        if self.current_z is None or self.current_meta is None:
            self._force_displayed_map_into_tool_state()
        x_axis = np.asarray(self.current_meta.get("x", []), dtype=float)
        y_axis = np.asarray(self.current_meta.get("y", []), dtype=float)
        nr, nc = np.asarray(self.current_z).shape
        if x_axis.ndim != 1 or x_axis.size != nc:
            x_axis = np.arange(nc, dtype=float)
        if y_axis.ndim != 1 or y_axis.size != nr:
            y_axis = np.arange(nr, dtype=float)
        yy, xx = np.where(mask)
        return (x_axis[xx], y_axis[yy])


    # all active columns for ternary style
    def _all_active_columns_for_ternary_style(self, df):
        if df is None or df.empty:
            return ["None"]
        columns = user_visible_columns(df)
        priority = [
            "None", "sample_id", "mineral_id", "run_id", "domain",
            "grain_id", "line_id", "spot_id", "analysis_level",
            "grain_area_um2", "grain_area_coordinate_units2",
            "grain_aspect_ratio", "total_grains_identified",
        ]
        ordered = [column for column in priority if column == "None" or column in columns]
        ordered.extend(column for column in columns if column not in ordered)
        return ordered


    # style is continuous numeric helper for ternary plots
    def _ternary_style_is_continuous_numeric(self, series):
        try:
            s = pd.to_numeric(series, errors="coerce")
            finite = s[np.isfinite(s)]
            if finite.size < 3:
                return False
            nunique = int(pd.Series(finite).nunique(dropna=True))
            return nunique > 12
        except Exception:
            return False


    # symbol categories helper for ternary plots
    def _ternary_symbol_categories(self, series, max_bins=6):
        try:
            if self._ternary_style_is_continuous_numeric(series):
                s = pd.to_numeric(series, errors="coerce")
                good = s[np.isfinite(s)]
                if good.nunique(dropna=True) <= 1:
                    return pd.Series(["all"] * len(series), index=series.index)
                q = min(max_bins, int(good.nunique(dropna=True)))
                cats = pd.qcut(s.rank(method="first"), q=q, duplicates="drop")
                labels = []
                vals = pd.to_numeric(series, errors="coerce")
                for cat in cats:
                    if pd.isna(cat):
                        labels.append("NA")
                    else:
                        idxs = cats == cat
                        lo = float(np.nanmin(vals[idxs]))
                        hi = float(np.nanmax(vals[idxs]))
                        labels.append(f"{lo:.3g}–{hi:.3g}")
                return pd.Series(labels, index=series.index)
        except Exception:
            pass
        return series.fillna("NA").astype(str)


    # refresh columns for ternary plots
    def refresh_ternary_columns(self):
        try:
            return self.refresh_ternary_controls()
        except Exception:
            pass


    # refresh controls for ternary plots
    def refresh_ternary_controls(self):
        if not hasattr(self, "ternary_a_combo"):
            return
        df = self.get_active_analysis_table()
        numeric_cols = self.get_active_numeric_columns(df)
        for combo in [self.ternary_a_combo, self.ternary_b_combo, self.ternary_c_combo]:
            combo["values"] = numeric_cols
        if numeric_cols:
            if self.ternary_a_col_var.get() not in numeric_cols:
                self.ternary_a_col_var.set(numeric_cols[0])
            if self.ternary_b_col_var.get() not in numeric_cols:
                self.ternary_b_col_var.set(
                    numeric_cols[1] if len(numeric_cols) > 1 else numeric_cols[0]
                )
            if self.ternary_c_col_var.get() not in numeric_cols:
                self.ternary_c_col_var.set(
                    numeric_cols[2] if len(numeric_cols) > 2 else numeric_cols[-1]
                )
        style_cols = self._all_active_columns_for_ternary_style(df)
        try:
            self.ternary_group_combo["values"] = style_cols
            if self.ternary_group_var.get() not in style_cols:
                if "plot_group" in style_cols:
                    self.ternary_group_var.set("plot_group")
                elif "mineral_type" in style_cols:
                    self.ternary_group_var.set("mineral_type")
                else:
                    self.ternary_group_var.set("None")
        except Exception:
            pass
        try:
            self.ternary_symbol_combo["values"] = style_cols
            if self.ternary_symbol_by_var.get() not in style_cols:
                self.ternary_symbol_by_var.set("None")
        except Exception:
            pass


    # refresh columns for KDE plots
    def refresh_kde_columns(self):
        try:
            return self.refresh_kde_controls()
        except Exception:
            pass


    # refresh controls for KDE plots
    def refresh_kde_controls(self):
        if not hasattr(self, "kde_listbox"):
            return
        selected_names = set()
        try:
            selected_names = {
                str(self.kde_listbox.get(index)) for index in self.kde_listbox.curselection()
            }
        except Exception:
            pass
        df = self._kde_source_table(apply_filters=False)
        cols = self.get_active_numeric_columns(df)
        self.kde_listbox.delete(0, tk.END)
        filt = self.kde_filter_var.get().lower().strip() if hasattr(self, "kde_filter_var") else ""
        for column in cols:
            if not filt or filt in str(column).lower():
                self.kde_listbox.insert(tk.END, column)
                if str(column) in selected_names:
                    self.kde_listbox.selection_set(tk.END)


    # whether the REE spider plot should apply the IQR filter.
    def _spider_iqr_enabled(self):
        try:
            return bool(self.spider_iqr_reject_var.get())
        except Exception:
            return False


    # IQR k helper for REE spider plots
    def _spider_iqr_k(self):
        try:
            k = float(self.spider_iqr_multiplier_var.get())
            return k if np.isfinite(k) and k > 0 else 1.5
        except Exception:
            return 1.5


    # calculate active spider stats
    def compute_active_spider_stats(
        self, ree_to_col, norm_values, summary_mode, distance_subsets=None
    ):
        if self.analysis_df is None:
            return {}
        if distance_subsets is not None:
            grouped_items = distance_subsets
        else:
            df = self.analysis_df.copy()
            if summary_mode == "mean_groups":
                group_col = self.get_plot_group_column(df)
                if group_col is None:
                    grouped_items = [("mean_all_active_rows", df)]
                else:
                    grouped_items = [
                        (str(g), sub.copy()) for g, sub in df.groupby(group_col, dropna=False)
                    ]
            elif summary_mode == "mean_all":
                grouped_items = [("mean_all_active_rows", df)]
            else:
                return {}
        stats = {}
        for label, sub in grouped_items:
            means = []
            sds = []
            counts = []
            p16 = []
            p84 = []
            p025 = []
            p975 = []
            for element in REE_ORDER:
                col = ree_to_col.get(element)
                if col is None or col not in sub.columns or element not in norm_values:
                    means.append(np.nan)
                    sds.append(np.nan)
                    counts.append(0)
                    p16.append(np.nan)
                    p84.append(np.nan)
                    p025.append(np.nan)
                    p975.append(np.nan)
                    continue
                vals = self._finite_normalized_values(sub, col, norm_values[element])
                vals = (
                    pd.to_numeric(vals, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                )
                vals = vals[vals > 0]
                n = int(vals.count())
                counts.append(n)
                if n == 0:
                    means.append(np.nan)
                    sds.append(np.nan)
                    p16.append(np.nan)
                    p84.append(np.nan)
                    p025.append(np.nan)
                    p975.append(np.nan)
                else:
                    arr = vals.to_numpy(dtype=float)
                    means.append(float(np.nanmean(arr)))
                    sds.append(float(np.nanstd(arr, ddof=1)) if n > 1 else 0.0)
                    p16.append(float(np.nanpercentile(arr, 16)))
                    p84.append(float(np.nanpercentile(arr, 84)))
                    p025.append(float(np.nanpercentile(arr, 2.5)))
                    p975.append(float(np.nanpercentile(arr, 97.5)))
            stats[str(label)] = {
                "mean": np.asarray(means, dtype=float),
                "sd": np.asarray(sds, dtype=float),
                "n": np.asarray(counts, dtype=int),
                "lower1": np.asarray(p16, dtype=float),
                "upper1": np.asarray(p84, dtype=float),
                "lower2": np.asarray(p025, dtype=float),
                "upper2": np.asarray(p975, dtype=float),
            }
        return stats


    # draw sd envelope for REE spider plots
    def draw_spider_sd_envelope(
        self, ax, x_positions, y_values, sd_values, factor, color, alpha=0.18
    ):
        if factor <= 0 or sd_values is None:
            return
        x = np.asarray(x_positions)
        y = np.asarray(y_values, dtype=float)
        try:
            log_axis = bool(self.spider_logy_var.get())
        except Exception:
            log_axis = ax.get_yscale() == "log"
        mode = (
            self._ree_envelope_mode_code()
            if hasattr(self, "_ree_envelope_mode_code")
            else "sd2" if factor >= 1.5 else "sd1"
        )
        if isinstance(sd_values, dict):
            mean = np.asarray(sd_values.get("mean", y), dtype=float)
            sd = np.asarray(sd_values.get("sd", np.full_like(y, np.nan)), dtype=float)
            if mode == "p16_84":
                lower = np.asarray(sd_values.get("lower1", np.full_like(y, np.nan)), dtype=float)
                upper = np.asarray(sd_values.get("upper1", np.full_like(y, np.nan)), dtype=float)
            elif mode == "p025_975":
                lower = np.asarray(sd_values.get("lower2", np.full_like(y, np.nan)), dtype=float)
                upper = np.asarray(sd_values.get("upper2", np.full_like(y, np.nan)), dtype=float)
            elif mode in ["logsd1", "logsd2"]:
                k = 1.0 if mode == "logsd1" else 2.0
                rel = np.where(
                    np.isfinite(mean) & (mean > 0) & np.isfinite(sd), np.abs(sd) / mean, np.nan
                )
                log_width = np.log1p(rel)
                lower = mean * np.exp(-k * log_width)
                upper = mean * np.exp(k * log_width)
            else:
                k = 1.0 if mode == "sd1" else 2.0
                lower = mean - k * sd
                upper = mean + k * sd
        else:
            sd = np.asarray(sd_values, dtype=float)
            if mode in ["logsd1", "logsd2"]:
                k = 1.0 if mode == "logsd1" else 2.0
                rel = np.where(np.isfinite(y) & (y > 0) & np.isfinite(sd), np.abs(sd) / y, np.nan)
                log_width = np.log1p(rel)
                lower = y * np.exp(-k * log_width)
                upper = y * np.exp(k * log_width)
            else:
                k = 1.0 if factor < 1.5 else 2.0
                lower = y - k * sd
                upper = y + k * sd
        lower = np.asarray(lower, dtype=float)
        upper = np.asarray(upper, dtype=float)
        bad = ~np.isfinite(lower) | ~np.isfinite(upper) | ~np.isfinite(y)
        if log_axis:
            bad |= (lower <= 0) | (upper <= 0) | (y <= 0)
        lower[bad] = np.nan
        upper[bad] = np.nan
        valid = np.isfinite(lower) & np.isfinite(upper)
        if log_axis:
            valid &= (lower > 0) & (upper > 0)
        if not np.any(valid):
            return
        idx = np.where(valid)[0]
        for seg in np.split(idx, np.where(np.diff(idx) != 1)[0] + 1):
            if len(seg) >= 2:
                ax.fill_between(
                    x[seg], lower[seg], upper[seg], color=color, alpha=alpha, linewidth=0
                )



    # general plots and multivariate tools
    # REE spider plots, X-Y, KDE, ternary, correlations, PCA, and plot exports.


    # plot spider
    def plot_spider(self):
        envelope_label_for_title = (
            self._ree_envelope_mode_label()
            if hasattr(self, "_ree_envelope_mode_label")
            else "envelope"
        )
        df_active = self.get_active_analysis_table()
        if df_active is None or df_active.empty:
            messagebox.showinfo(
                "No data",
                "Send map or selection data to the plot tabs first.",
            )
            return
        self.analysis_df = df_active.copy()
        self.value_columns = self.get_active_numeric_columns(self.analysis_df)
        ree_to_col = self.find_ree_columns()
        if len(ree_to_col) < 3:
            messagebox.showerror(
                "Not enough REE columns", "Could not find at least 3 REE-like columns."
            )
            return
        norm_name = self.spider_norm_var.get() if hasattr(self, "spider_norm_var") else "CI"
        norm_values = REE_NORMALIZATION_VALUES.get(norm_name, CI_VALUES)
        mode = self.spider_mode_var.get() if hasattr(self, "spider_mode_var") else "Distance zones"
        cmap = plt.get_cmap(self.spider_cmap_var.get())
        variation_choice = (
            self.spider_variation_var.get() if hasattr(self, "spider_variation_var") else "none"
        )
        variation_factor = self._sd_factor_from_choice(variation_choice)
        df = self.analysis_df.copy()
        self.spider_ax.clear()
        try:
            _ree_fill_between = self.spider_ax.fill_between

            # safe fill between for REE plots
            def _ree_safe_fill_between(x, y1, y2=0, *args, **kwargs):
                y1_arr = np.asarray(y1, dtype=float)
                y2_arr = np.asarray(y2, dtype=float)
                log_axis = False
                try:
                    log_axis = bool(self.spider_logy_var.get())
                except Exception:
                    try:
                        log_axis = self.spider_ax.get_yscale() == "log"
                    except Exception:
                        log_axis = True
                if log_axis:
                    valid = np.isfinite(y1_arr) & np.isfinite(y2_arr) & (y1_arr > 0) & (y2_arr > 0)
                    x_arr = np.asarray(x)
                    if (
                        y1_arr.shape == y2_arr.shape
                        and y1_arr.shape == x_arr.shape
                        and np.any(valid)
                    ):
                        idx = np.where(valid)[0]
                        segments = np.split(idx, np.where(np.diff(idx) != 1)[0] + 1)
                        artists = []
                        first = True
                        for seg in segments:
                            if len(seg) < 2:
                                continue
                            local_kwargs = dict(kwargs)
                            if not first and "label" in local_kwargs:
                                local_kwargs["label"] = None
                            artists.append(
                                _ree_fill_between(
                                    x_arr[seg], y1_arr[seg], y2_arr[seg], *args, **local_kwargs
                                )
                            )
                            first = False
                        return artists[0] if artists else None
                    y1_arr = np.where(np.isfinite(y1_arr) & (y1_arr > 0), y1_arr, np.nan)
                    y2_arr = np.where(np.isfinite(y2_arr) & (y2_arr > 0), y2_arr, np.nan)
                return _ree_fill_between(x, y1_arr, y2_arr, *args, **kwargs)

            self.spider_ax.fill_between = _ree_safe_fill_between
        except Exception:
            pass
        x_positions = np.arange(len(REE_ORDER))

        # clean y for REE spider plots
        def _clean_spider_y(vals):
            arr = np.asarray(vals, dtype=float)
            arr[~np.isfinite(arr) | (arr <= 0)] = np.nan
            arr[arr < 1e-12] = np.nan
            return arr.tolist()

        output_rows = []
        if mode == "All rows":
            summary_mode = (
                self.spider_summary_var.get() if hasattr(self, "spider_summary_var") else "mean_all"
            )
            plot_df = self.get_plot_dataframe(summary_mode)
            if plot_df is None or plot_df.empty:
                messagebox.showerror(
                    "No data", "No active rows were available for the spider plot."
                )
                return
            if summary_mode == "raw_rows":
                max_raw = (
                    max(safe_int(self.spider_max_raw_rows_var.get(), 500), 1)
                    if hasattr(self, "spider_max_raw_rows_var")
                    else 500
                )
                if len(plot_df) > max_raw:
                    plot_df_to_draw = plot_df.sample(n=max_raw, random_state=1).copy()
                    sampled_note = f"; randomly plotted {max_raw} of {len(plot_df)} rows"
                else:
                    plot_df_to_draw = plot_df.copy()
                    sampled_note = ""
            else:
                plot_df_to_draw = plot_df.copy()
                sampled_note = ""
            n_lines = len(plot_df_to_draw)
            active_spider_stats = (
                self.compute_active_spider_stats(ree_to_col, norm_values, summary_mode)
                if variation_factor > 0 and summary_mode != "raw_rows"
                else {}
            )
            for i, (_, row_df) in enumerate(plot_df_to_draw.iterrows()):
                y_values = []
                for element in REE_ORDER:
                    col = ree_to_col.get(element)
                    if col is None:
                        y_values.append(np.nan)
                        continue
                    val = pd.to_numeric(pd.Series([row_df.get(col, np.nan)]), errors="coerce").iloc[
                        0
                    ]
                    y_values.append(np.nan if pd.isna(val) else val / norm_values[element])
                color = cmap(i / max(n_lines - 1, 1)) if n_lines > 1 else cmap(0.5)
                label = str(row_df.get("plot_group", f"row_{i + 1}"))
                if summary_mode == "raw_rows" and n_lines > 25:
                    label = None
                if variation_factor > 0 and summary_mode != "raw_rows":
                    stat = active_spider_stats.get(str(row_df.get("plot_group", f"row_{i + 1}")))
                    if stat is not None:
                        self.draw_spider_sd_envelope(
                            self.spider_ax, x_positions, y_values, stat, variation_factor, color
                        )
                y_values = _clean_spider_y(y_values)
                if np.isfinite(np.asarray(y_values, dtype=float)).sum() < 2:
                    continue
                self.spider_ax.plot(
                    x_positions,
                    y_values,
                    marker="o",
                    linewidth=1.5,
                    alpha=0.65 if summary_mode == "raw_rows" else 1.0,
                    color=color,
                    label=label,
                )
                out_row = {
                    "spider_mode": summary_mode,
                    "normalization": norm_name,
                    "plot_group": row_df.get("plot_group", f"row_{i + 1}"),
                    "source_row_count": row_df.get("source_row_count", 1),
                }
                for element, value in zip(REE_ORDER, y_values):
                    out_row[element + f"_{norm_name}_normalized"] = value
                if variation_factor > 0 and summary_mode != "raw_rows":
                    stat = active_spider_stats.get(str(row_df.get("plot_group", f"row_{i + 1}")))
                    if stat is not None:
                        for element, sd_val, n_val in zip(REE_ORDER, stat["sd"], stat["n"]):
                            out_row[element + f"_{norm_name}_normalized_sd"] = sd_val
                            out_row[element + "_n"] = n_val
                        out_row["variation_envelope"] = variation_choice
                output_rows.append(out_row)
            legend_title = "Group"
            if summary_mode == "mean_all":
                title = f"REE spider normalized to {norm_name}: mean of all active rows"
            elif summary_mode == "mean_groups":
                title = f"REE spider normalized to {norm_name}: mean per domain/spot/line"
            else:
                title = f"REE spider normalized to {norm_name}: every row/pixel{sampled_note}"
        else:
            if "distance_normalized" not in df.columns:
                messagebox.showerror(
                    "Missing normalized distance",
                    "Distance zones need normalized distance. Use All rows for other data.",
                )
                return
            bins = safe_int(self.spider_bins_var.get(), 5)
            bins = max(bins, 2)
            dmin = safe_float(self.spider_min_dist_var.get(), 0)
            dmax = safe_float(self.spider_max_dist_var.get(), 1)
            if dmax <= dmin:
                messagebox.showerror(
                    "Bad distance range", "Max distance must be greater than min distance."
                )
                return
            df["distance_normalized"] = pd.to_numeric(df["distance_normalized"], errors="coerce")
            df = df[
                (df["distance_normalized"] >= dmin) & (df["distance_normalized"] <= dmax)
            ].copy()
            edges = np.linspace(dmin, dmax, bins + 1)
            centers = 0.5 * (edges[:-1] + edges[1:])
            df["distance_zone"] = pd.cut(
                df["distance_normalized"], bins=edges, include_lowest=True, labels=False
            )
            for bin_index in range(bins):
                sub = df[df["distance_zone"] == bin_index]
                if sub.empty:
                    continue
                y_values = []
                for element in REE_ORDER:
                    col = ree_to_col.get(element)
                    if col is None:
                        y_values.append(np.nan)
                        continue
                    vals = (
                        pd.to_numeric(sub[col], errors="coerce")
                        .replace([np.inf, -np.inf], np.nan)
                        .dropna()
                    )
                    y_values.append(np.nan if vals.empty else vals.mean() / norm_values[element])
                color = cmap(bin_index / max(bins - 1, 1))
                label = f"{edges[bin_index]:.2f}-{edges[bin_index + 1]:.2f}"
                if variation_factor > 0:
                    sd_values = []
                    n_values = []
                    for element in REE_ORDER:
                        col = ree_to_col.get(element)
                        if col is None or element not in norm_values:
                            sd_values.append(np.nan)
                            n_values.append(0)
                        else:
                            vals = self._finite_normalized_values(sub, col, norm_values[element])
                            sd_values.append(
                                float(vals.std(ddof=1))
                                if vals.count() > 1
                                else 0.0 if vals.count() == 1 else np.nan
                            )
                            n_values.append(int(vals.count()))
                    self.draw_spider_sd_envelope(
                        self.spider_ax,
                        x_positions,
                        y_values,
                        np.asarray(sd_values),
                        variation_factor,
                        color,
                    )
                else:
                    sd_values = [np.nan] * len(REE_ORDER)
                    n_values = [0] * len(REE_ORDER)
                y_values = _clean_spider_y(y_values)
                if np.isfinite(np.asarray(y_values, dtype=float)).sum() < 2:
                    continue
                y_values = _clean_spider_y(y_values)
                if np.isfinite(np.asarray(y_values, dtype=float)).sum() < 2:
                    continue
                self.spider_ax.plot(
                    x_positions, y_values, marker="o", linewidth=2, color=color, label=label
                )
                row = {
                    "spider_mode": "distance_zones",
                    "normalization": norm_name,
                    "distance_zone": bin_index,
                    "distance_center": centers[bin_index],
                    "distance_min": edges[bin_index],
                    "distance_max": edges[bin_index + 1],
                    "n_rows": len(sub),
                    "variation_envelope": variation_choice,
                }
                for element, value, sd_val, n_val in zip(REE_ORDER, y_values, sd_values, n_values):
                    row[element + f"_{norm_name}_normalized"] = value
                    row[element + f"_{norm_name}_normalized_sd"] = sd_val
                    row[element + "_n"] = n_val
                output_rows.append(row)
            legend_title = "Distance zone"
            title = f"REE spider normalized to {norm_name}: distance zones"
        self.last_spider_df = pd.DataFrame(output_rows)
        self.spider_ax.set_xticks(x_positions)
        self.spider_ax.set_xticklabels(REE_ORDER)
        self.spider_ax.set_xlabel("REE")
        self.spider_ax.set_ylabel(f"{norm_name}-normalized value")
        if variation_factor > 0:
            title = title + f" with {envelope_label_for_title}"
        self.spider_ax.set_title(title)
        self.spider_ax.set_yscale("log" if self.spider_logy_var.get() else "linear")
        self.spider_ax.legend(
            title=legend_title, loc="center left", bbox_to_anchor=(1.02, 0.5), fontsize=8
        )
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", UserWarning)
            self.spider_fig.tight_layout()
        self.apply_axis_bounds("spider") if hasattr(self, "apply_axis_bounds") else None
        try:
            if self.spider_logy_var.get():
                ymin, ymax = self.spider_ax.get_ylim()
                if not np.isfinite(ymin) or ymin <= 0:
                    positive_vals = []
                    for line in self.spider_ax.lines:
                        ydata = np.asarray(line.get_ydata(), dtype=float)
                        ydata = ydata[np.isfinite(ydata) & (ydata > 0)]
                        if ydata.size:
                            positive_vals.append(np.nanmin(ydata))
                    if positive_vals:
                        self.spider_ax.set_ylim(bottom=max(min(positive_vals) * 0.3, 1e-12))
        except Exception:
            pass
        try:
            for line in list(self.spider_ax.lines):
                y = np.asarray(line.get_ydata(), dtype=float)
                y[~np.isfinite(y) | (y <= 0) | (y < 1e-12)] = np.nan
                line.set_ydata(y)
                if np.isfinite(y).sum() < 2:
                    line.remove()
        except Exception:
            pass
        try:
            title = self.spider_ax.get_title()
            title = re.sub(
                "with (\\{envelope_label_for_title\\}|±\\d+ SD envelope|[+]/-\\d+ SD envelope|P[0-9.]+.*band).*$",
                f"with {envelope_label_for_title}",
                title,
            )
            if "envelope" in title or "band" in title or "SD" in title:
                self.spider_ax.set_title(title)
        except Exception:
            pass
        try:
            if "percentile" in envelope_label_for_title:
                self.spider_ax.text(
                    0.01,
                    0.01,
                    "Percentile band: mean is not expected to be centered.",
                    transform=self.spider_ax.transAxes,
                    fontsize=8,
                    va="bottom",
                    ha="left",
                    alpha=0.75,
                )
            elif "log-space" in envelope_label_for_title:
                self.spider_ax.text(
                    0.01,
                    0.01,
                    "Log-SD band: centered in log space, not linear space.",
                    transform=self.spider_ax.transAxes,
                    fontsize=8,
                    va="bottom",
                    ha="left",
                    alpha=0.75,
                )
        except Exception:
            pass
        self.spider_canvas.draw_idle()
        self.status_var.set("REE spider plot complete.")


    # export CSV
    def export_spider_csv(self):
        self.save_df_csv(self.last_spider_df, "ree_spider.csv", "REE spider data")


    # 2d numpy helper for KDE plots
    def kde_2d_numpy(self, x, y, grid_points=150, bandwidth_mult=1.0):
        x = np.asarray(x, dtype=float)
        y = np.asarray(y, dtype=float)
        mask = np.isfinite(x) & np.isfinite(y)
        x = x[mask]
        y = y[mask]
        if len(x) < 5:
            raise ValueError("Need at least 5 valid X-Y pairs for 2D KDE.")
        n = len(x)
        sx = np.std(x, ddof=1)
        sy = np.std(y, ddof=1)
        if sx <= 0 or sy <= 0:
            raise ValueError("X or Y has zero standard deviation.")
        hx = sx * n ** (-1 / 6) * bandwidth_mult
        hy = sy * n ** (-1 / 6) * bandwidth_mult
        xmin, xmax = np.nanpercentile(x, [0.5, 99.5])
        ymin, ymax = np.nanpercentile(y, [0.5, 99.5])
        xpad = 0.1 * (xmax - xmin) if xmax > xmin else sx
        ypad = 0.1 * (ymax - ymin) if ymax > ymin else sy
        xgrid = np.linspace(xmin - xpad, xmax + xpad, grid_points)
        ygrid = np.linspace(ymin - ypad, ymax + ypad, grid_points)
        Xg, Yg = np.meshgrid(xgrid, ygrid)
        density = np.zeros_like(Xg, dtype=float)
        chunk = 500
        norm = 1.0 / (2 * np.pi * hx * hy * n)
        for start in range(0, n, chunk):
            xs = x[start : start + chunk]
            ys = y[start : start + chunk]
            ux = (Xg[:, :, None] - xs[None, None, :]) / hx
            uy = (Yg[:, :, None] - ys[None, None, :]) / hy
            density += np.exp(-0.5 * (ux**2 + uy**2)).sum(axis=2)
        density *= norm
        return (xgrid, ygrid, density, hx, hy)


    # reset axes for X-Y plots
    def reset_xy_axes(self):
        self.xy_fig.clear()
        self.xy_colorbar = None
        self.xy_ax = self.xy_fig.add_axes([0.12, 0.13, 0.8, 0.75])
        self.xy_canvas.draw_idle()


    # add colorbar for X-Y plots
    def add_xy_colorbar(self, mappable, label):
        cax = self.xy_fig.add_axes([0.9, 0.13, 0.025, 0.75])
        self.xy_colorbar = self.xy_fig.colorbar(mappable, cax=cax)
        self.xy_colorbar.set_label(label)
        self.xy_ax.set_position([0.12, 0.13, 0.74, 0.75])


    # finish plot for X-Y plots
    def finish_xy_plot(self):
        if self.xy_colorbar is None:
            self.xy_ax.set_position([0.12, 0.13, 0.8, 0.75])
        else:
            self.xy_ax.set_position([0.12, 0.13, 0.74, 0.75])
        self.apply_axis_bounds("xy") if hasattr(self, "apply_axis_bounds") else None
        self.xy_canvas.draw_idle()


    # plot distance bins for X-Y plots
    def plot_xy_distance_bins(self, x_col, y_col):
        df = self.analysis_df.copy()
        if "distance_normalized" not in df.columns:
            messagebox.showerror(
                "Missing distance_normalized",
                "Distance bins need normalized distance. Use All rows for other data.",
            )
            return
        bins = max(safe_int(self.xy_bins_var.get(), 25), 2)
        dmin = safe_float(self.xy_min_dist_var.get(), 0)
        dmax = safe_float(self.xy_max_dist_var.get(), 1)
        if dmax <= dmin:
            messagebox.showerror(
                "Bad distance range", "Max distance must be greater than min distance."
            )
            return
        df["distance_normalized"] = pd.to_numeric(df["distance_normalized"], errors="coerce")
        df["_xy_x"] = pd.to_numeric(df[x_col], errors="coerce")
        df["_xy_y"] = pd.to_numeric(df[y_col], errors="coerce")
        df = df.replace([np.inf, -np.inf], np.nan)
        df = df[(df["distance_normalized"] >= dmin) & (df["distance_normalized"] <= dmax)].copy()
        edges = np.linspace(dmin, dmax, bins + 1)
        centers = 0.5 * (edges[:-1] + edges[1:])
        df["distance_bin"] = pd.cut(
            df["distance_normalized"], bins=edges, include_lowest=True, labels=False
        )
        rows = []
        for i in range(bins):
            sub = df[df["distance_bin"] == i]
            xv = pd.to_numeric(sub["_xy_x"], errors="coerce")
            yv = pd.to_numeric(sub["_xy_y"], errors="coerce")
            valid = xv.notna() & yv.notna()
            if valid.sum() == 0:
                continue
            xv = xv[valid]
            yv = yv[valid]
            rows.append(
                {
                    "plot_mode": "distance_normalized_binned_means",
                    "distance_bin": i,
                    "distance_center": centers[i],
                    "distance_min": edges[i],
                    "distance_max": edges[i + 1],
                    "n": int(valid.sum()),
                    f"{x_col}_mean": xv.mean(),
                    f"{x_col}_std": xv.std(ddof=1),
                    f"{y_col}_mean": yv.mean(),
                    f"{y_col}_std": yv.std(ddof=1),
                }
            )
        plot_df = pd.DataFrame(rows)
        if plot_df.empty:
            messagebox.showerror("No valid bins", "No valid binned X-Y data could be made.")
            return
        xm, ym, xs, ys = (f"{x_col}_mean", f"{y_col}_mean", f"{x_col}_std", f"{y_col}_std")
        sc = self.xy_ax.scatter(plot_df[xm], plot_df[ym], c=plot_df["distance_center"], s=45)
        self.xy_ax.plot(plot_df[xm], plot_df[ym], linewidth=1, alpha=0.7)
        self.xy_ax.errorbar(
            plot_df[xm], plot_df[ym], xerr=plot_df[xs], yerr=plot_df[ys], fmt="none", alpha=0.4
        )
        self.add_xy_colorbar(sc, "Distance normalized bin center")
        self.last_xy_plot_df = plot_df
        self.xy_ax.set_xlabel(x_col)
        self.xy_ax.set_ylabel(y_col)
        self.xy_ax.set_title(f"{y_col} vs {x_col}\nBinned profile means")
        if self.xy_logx_var.get():
            self.xy_ax.set_xscale("log")
        if self.xy_logy_var.get():
            self.xy_ax.set_yscale("log")
        self.finish_xy_plot()
        self.status_var.set("Binned X-Y plot complete.")


    # export plot CSV
    def export_xy_plot_csv(self):
        self.save_df_csv(self.last_xy_plot_df, "xy_data.csv", "X-Y data")


    # export KDE CSV
    def export_xy_kde_csv(self):
        self.save_df_csv(self.last_xy_kde_df, "xy_kde.csv", "X-Y KDE data")


    # source table helper for KDE plots
    def _kde_source_table(self, apply_filters=True):
        use_comparison = False
        try:
            use_comparison = bool(self.comparison_mode_var.get())
        except Exception:
            pass
        if use_comparison:
            table = getattr(self, "comparison_df", None)
            if not isinstance(table, pd.DataFrame) or table.empty:
                try:
                    self.build_comparison_df_from_loaded_mineral_maps_if_needed()
                    table = getattr(self, "comparison_df", None)
                except Exception:
                    table = None
            if isinstance(table, pd.DataFrame) and not table.empty:
                table = table.copy(deep=False)
                if apply_filters:
                    table = _filter_table(self, table)
                    table = _apply_plot_filter_to_table(self, table)
                return table
            return pd.DataFrame()
        if apply_filters:
            table = self.get_active_analysis_table()
        else:
            table = _raw_analysis_source_table(self)
        return table.copy(deep=False) if isinstance(table, pd.DataFrame) else pd.DataFrame()


    # curve column helper for KDE plots
    def _kde_curve_column(self, table):
        choice = str(self.kde_group_var.get() if hasattr(self, "kde_group_var") else "Automatic")
        mapped = {
            "Sample": "sample_id", "Mineral": "mineral_id", "Run": "run_id",
            "Domain": "domain", "Grain": "grain_id", "Line": "line_id",
            "Spot": "spot_id", "Comparison dataset": "comparison_dataset",
            "None": None,
        }.get(choice, choice)
        if mapped not in {None, "Automatic"} and mapped in table.columns:
            return mapped
        if choice == "None":
            return None
        for candidate in [
            "comparison_dataset", "sample_id", "run_id", "mineral_id",
            "map_group", "source_layer", "mineral_type",
        ]:
            if candidate in table.columns and table[candidate].nunique(dropna=True) > 1:
                return candidate
        return None


    # mean unit column helper for KDE plots
    def _kde_mean_unit_column(self, table, curve_column=None):
        choice = str(
            self.kde_mean_unit_var.get() if hasattr(self, "kde_mean_unit_var") else "Automatic"
        )
        mapped = {
            "Domain": "domain", "Grain": "grain_id", "Line": "line_id",
            "Spot": "spot_id", "Run": "run_id", "Mineral": "mineral_id",
            "Sample": "sample_id",
        }.get(choice, choice)
        if mapped != "Automatic" and mapped in table.columns:
            return mapped
        for candidate in ["domain", "grain_id", "line_id", "spot_id", "run_id", "mineral_id", "sample_id"]:
            if candidate == curve_column:
                continue
            if candidate in table.columns and table[candidate].nunique(dropna=True) > 1:
                return candidate
        return None


    # unit group columns helper for KDE plots
    def _kde_unit_group_columns(self, table, unit_column):
        columns = [
            column for column in ["sample_id", "mineral_id", "run_id"]
            if column in table.columns
        ]
        if unit_column and unit_column in table.columns and unit_column not in columns:
            columns.append(unit_column)
        return columns


    # prepared curves helper for KDE plots
    def _kde_prepared_curves(self, table, value_column):
        if not isinstance(table, pd.DataFrame) or table.empty:
            raise ValueError("No data are available for the KDE tab.")
        if value_column not in table.columns:
            raise ValueError("Choose a valid numeric channel.")
        work = table.copy(deep=False)
        work = work.copy()
        work[value_column] = pd.to_numeric(work[value_column], errors="coerce")
        work = work[np.isfinite(work[value_column])].copy()
        if bool(self.kde_positive_only_var.get()):
            work = work[work[value_column] > 0].copy()
        if work.empty:
            raise ValueError(f"No valid values are available for {value_column}.")

        curve_column = self._kde_curve_column(work)
        summary = str(self.kde_summary_var.get())
        mean_unit = None
        if summary == "mean_groups":
            mean_unit = self._kde_mean_unit_column(work, curve_column)
            group_columns = self._kde_unit_group_columns(work, mean_unit)
            if curve_column and curve_column not in group_columns:
                group_columns.insert(0, curve_column)
            if not group_columns:
                work = pd.DataFrame({value_column: [float(work[value_column].mean())]})
            else:
                work = work.groupby(
                    group_columns, dropna=False, sort=False, observed=True
                )[value_column].mean().reset_index()
        elif summary == "mean_all":
            if curve_column and curve_column in work.columns:
                work = work.groupby(
                    curve_column, dropna=False, sort=False, observed=True
                )[value_column].mean().reset_index()
            else:
                work = pd.DataFrame({value_column: [float(work[value_column].mean())]})

        if curve_column and curve_column in work.columns:
            grouped = list(work.groupby(curve_column, dropna=False, sort=False, observed=True))
        else:
            grouped = [("All data", work)]

        max_values = optional_positive_int(self.kde_max_points_var.get())
        curves = {}
        for label, group in grouped:
            values = pd.to_numeric(group[value_column], errors="coerce").to_numpy(dtype=float)
            values = values[np.isfinite(values)]
            if max_values is not None and values.size > max_values:
                rng = np.random.default_rng(0)
                values = rng.choice(values, size=max_values, replace=False)
            if bool(self.kde_log_data_var.get()):
                values = values[values > 0.0]
                values = np.log10(values)
            if values.size:
                curves[str(label)] = values
        if not curves:
            raise ValueError("No curves contain valid values after the current settings.")
        return curves, curve_column, mean_unit, summary


    # selected column for KDE plots
    def _selected_kde_column(self):
        selected = self.get_selected_from_listbox(
            self.kde_listbox, min_count=1, warning="Select one channel for KDE."
        )
        return selected[0] if selected else None


    # plot KDE
    def plot_kde(self):
        try:
            table = self._kde_source_table(apply_filters=True)
            column = self._selected_kde_column()
            if not column:
                return
            curves, curve_column, mean_unit, summary = self._kde_prepared_curves(table, column)
            all_values = np.concatenate(list(curves.values()))
            if all_values.size == 0:
                raise ValueError("No values remain for KDE.")

            xmin_text = str(self.kde_xmin_var.get()).strip()
            xmax_text = str(self.kde_xmax_var.get()).strip()
            xmin = float(xmin_text) if xmin_text else float(np.nanpercentile(all_values, 1.0))
            xmax = float(xmax_text) if xmax_text else float(np.nanpercentile(all_values, 99.0))
            if not np.isfinite(xmin) or not np.isfinite(xmax) or xmax <= xmin:
                xmin, xmax = float(np.nanmin(all_values)), float(np.nanmax(all_values))
            if xmax <= xmin:
                xmin -= 0.5
                xmax += 0.5
            grid_count = max(80, safe_int(self.kde_grid_points_var.get(), 300))
            grid = np.linspace(xmin, xmax, grid_count)
            bandwidth_multiplier = safe_float(self.kde_bandwidth_var.get(), 1.0)
            if not np.isfinite(bandwidth_multiplier) or bandwidth_multiplier <= 0.0:
                raise ValueError("Bandwidth multiplier must be positive.")

            self.kde_ax.clear()
            rows = []
            plotted = 0
            for label, values in curves.items():
                values = np.asarray(values, dtype=float)
                values = values[np.isfinite(values)]
                if values.size >= 3 and np.nanstd(values, ddof=1) > 0.0:
                    if _ks_2samp is None:
                        # scipy is optional; the local Gaussian implementation remains available.
                        density, bandwidth = _grain_kde_on_common_grid(
                            values, grid, bandwidth_multiplier
                        )
                    else:
                        from scipy.stats import gaussian_kde
                        estimator = gaussian_kde(values)
                        estimator.set_bandwidth(estimator.factor * bandwidth_multiplier)
                        density = estimator(grid)
                        bandwidth = float(estimator.factor * np.nanstd(values, ddof=1))
                    line, = self.kde_ax.plot(
                        grid, density, linewidth=1.8, label=f"{label} (n={values.size})"
                    )
                    if bool(self.kde_fill_var.get()):
                        self.kde_ax.fill_between(
                            grid, 0.0, density, color=line.get_color(), alpha=0.14
                        )
                    rows.append(pd.DataFrame({
                        "curve": label,
                        "x": grid,
                        "density": density,
                        "n": values.size,
                        "channel": column,
                        "curve_by": curve_column or "None",
                        "summary": summary,
                        "mean_unit": mean_unit or "None",
                        "bandwidth": bandwidth,
                    }))
                else:
                    mean_value = float(np.nanmean(values))
                    self.kde_ax.axvline(
                        mean_value, linewidth=1.8, label=f"{label} mean (n={values.size})"
                    )
                    rows.append(pd.DataFrame([{
                        "curve": label, "x": mean_value, "density": np.nan,
                        "n": values.size, "channel": column,
                        "curve_by": curve_column or "None", "summary": summary,
                        "mean_unit": mean_unit or "None", "bandwidth": np.nan,
                    }]))
                plotted += 1

            self._last_kde_curves = {key: value.copy() for key, value in curves.items()}
            self._last_kde_settings = {
                "column": column, "curve_by": curve_column or "None",
                "summary": summary, "mean_unit": mean_unit or "None",
            }
            self.last_kde_df = pd.concat(rows, ignore_index=True) if rows else pd.DataFrame()
            x_label = f"log10({column})" if bool(self.kde_log_data_var.get()) else str(column)
            self.kde_ax.set_xlabel(x_label)
            self.kde_ax.set_ylabel("Density")
            summary_label = {
                "raw_rows": "rows / pixels", "mean_groups": "means by unit",
                "mean_all": "one mean per curve",
            }.get(summary, summary)
            self.kde_ax.set_title(f"KDE of {column} — {summary_label}")
            if plotted <= 35:
                self.kde_ax.legend(loc="center left", bbox_to_anchor=(1.02, 0.5), fontsize=8)
            self.kde_ax.grid(True, alpha=0.18)
            self.kde_fig.tight_layout()
            self.kde_canvas.draw_idle()
            self.kde_status_var.set(
                f"{plotted} curve(s); {summary_label}; curve by {curve_column or 'none'}."
            )
            self.status_var.set("KDE plot complete.")
        except Exception as exc:
            messagebox.showerror("KDE", str(exc))


    # run ks comparison for KDE plots
    def run_kde_ks_comparison(self):
        try:
            if _ks_2samp is None:
                raise ValueError("K-S comparison requires scipy.")
            table = self._kde_source_table(apply_filters=True)
            column = self._selected_kde_column()
            if not column:
                return
            curves, curve_column, mean_unit, summary = self._kde_prepared_curves(table, column)
            labels = list(curves)
            if len(labels) < 2:
                raise ValueError("Choose a curve grouping that produces at least two groups.")
            rows = []
            for first_index, first_label in enumerate(labels[:-1]):
                first = np.asarray(curves[first_label], dtype=float)
                for second_label in labels[first_index + 1:]:
                    second = np.asarray(curves[second_label], dtype=float)
                    if first.size < 2 or second.size < 2:
                        continue
                    result = _ks_2samp(first, second, alternative="two-sided", method="auto")
                    rows.append({
                        "curve_1": first_label, "curve_2": second_label,
                        "n_1": int(first.size), "n_2": int(second.size),
                        "ks_statistic": float(result.statistic),
                        "p_value": float(result.pvalue),
                        "channel": column, "curve_by": curve_column or "None",
                        "summary": summary, "mean_unit": mean_unit or "None",
                    })
            if not rows:
                raise ValueError(
                    "Each K-S curve needs at least two values. Use rows/pixels or a mean unit with more groups."
                )
            self.last_kde_ks_df = pd.DataFrame(rows)
            self.write_results("K-S comparisons\n\n" + self.last_kde_ks_df.to_string(index=False))
            try:
                self.notebook.select(self.results_tab)
            except Exception:
                pass
            self.kde_status_var.set(f"Calculated {len(rows)} pairwise K-S comparison(s).")
            self.status_var.set("K-S comparison complete.")
        except Exception as exc:
            messagebox.showerror("K-S comparison", str(exc))


