    # convert ternary fractions to Cartesian X-Y coordinates
    def ternary_to_xy(self, a_frac, b_frac, c_frac):
        x = b_frac + 0.5 * c_frac
        y = np.sqrt(3.0) / 2.0 * c_frac
        return (x, y)


    # prepare the table used by ternary plots
    def prepare_ternary_dataframe(self, df, a_col, b_col, c_col, group_col=None):
        if df is None or df.empty:
            return pd.DataFrame()
        keep_cols = [a_col, b_col, c_col]
        extra_candidates = []
        if group_col is not None and group_col != "None":
            extra_candidates.append(group_col)
        try:
            sym = self.ternary_symbol_by_var.get()
            if sym and sym != "None":
                extra_candidates.append(sym)
        except Exception:
            pass
        common_extras = [
            "plot_group",
            "plot_summary_mode",
            "source_row_count",
            "comparison_dataset",
            "mineral_type",
            "map_group",
            "domain",
            "area_id",
            "spot_id",
            "line_id",
            "grain_id",
            "analysis_level",
            "source_kind",
            "grain_area_um2",
            "grain_area_coordinate_units2",
            "grain_aspect_ratio",
            "total_grains_identified",
        ]
        for extra in common_extras + extra_candidates:
            if extra in df.columns and extra not in keep_cols:
                keep_cols.append(extra)
        for extra in extra_candidates:
            if extra in df.columns and extra not in keep_cols:
                keep_cols.append(extra)
        out = df[keep_cols].copy()
        for col in [a_col, b_col, c_col]:
            out[col] = pd.to_numeric(out[col], errors="coerce")
        out = out.replace([np.inf, -np.inf], np.nan).dropna(subset=[a_col, b_col, c_col])
        out = out[(out[a_col] >= 0) & (out[b_col] >= 0) & (out[c_col] >= 0)].copy()
        total = out[a_col] + out[b_col] + out[c_col]
        out = out[total > 0].copy()
        total = out[a_col] + out[b_col] + out[c_col]
        out[f"{a_col}_fraction"] = out[a_col] / total
        out[f"{b_col}_fraction"] = out[b_col] / total
        out[f"{c_col}_fraction"] = out[c_col] / total
        out["ternary_total"] = total
        out["ternary_x"], out["ternary_y"] = self.ternary_to_xy(
            out[f"{a_col}_fraction"].to_numpy(dtype=float),
            out[f"{b_col}_fraction"].to_numpy(dtype=float),
            out[f"{c_col}_fraction"].to_numpy(dtype=float),
        )
        return out


    # setup ternary axes helper for ternary plots
    def setup_ternary_axes(self, ax, a_label, b_label, c_label, title):
        ax.clear()
        h = np.sqrt(3.0) / 2.0
        ax.plot([0, 1, 0.5, 0], [0, 0, h, 0], color="black", linewidth=1.2)
        for t in np.linspace(0.2, 0.8, 4):
            b1, c1 = (0, 1 - t)
            b2, c2 = (1 - t, 0)
            x1, y1 = self.ternary_to_xy(t, b1, c1)
            x2, y2 = self.ternary_to_xy(t, b2, c2)
            ax.plot([x1, x2], [y1, y2], color="0.85", linewidth=0.8)
            a1, c1 = (0, 1 - t)
            a2, c2 = (1 - t, 0)
            x1, y1 = self.ternary_to_xy(a1, t, c1)
            x2, y2 = self.ternary_to_xy(a2, t, c2)
            ax.plot([x1, x2], [y1, y2], color="0.85", linewidth=0.8)
            a1, b1 = (0, 1 - t)
            a2, b2 = (1 - t, 0)
            x1, y1 = self.ternary_to_xy(a1, b1, t)
            x2, y2 = self.ternary_to_xy(a2, b2, t)
            ax.plot([x1, x2], [y1, y2], color="0.85", linewidth=0.8)
        ax.text(-0.04, -0.055, a_label, ha="right", va="top", fontsize=10, fontweight="bold")
        ax.text(1.04, -0.055, b_label, ha="left", va="top", fontsize=10, fontweight="bold")
        ax.text(0.5, h + 0.055, c_label, ha="center", va="bottom", fontsize=10, fontweight="bold")
        ax.set_xlim(-0.1, 1.1)
        ax.set_ylim(-0.1, h + 0.12)
        ax.set_aspect("equal", adjustable="box")
        ax.axis("off")
        ax.set_title(title)


    # draw points for ternary plots
    def draw_ternary_points(self, ax, plot_df, group_col=None, max_points=10000):
        markers = ["o", "s", "^", "D", "v", "P", "X", "<", ">", "h", "*"]
        if plot_df is None or plot_df.empty:
            return pd.DataFrame()
        if len(plot_df) > max_points:
            plot_df = plot_df.sample(n=max_points, random_state=1).copy()
        else:
            plot_df = plot_df.copy()
        if group_col in [None, "", "None"] or group_col not in plot_df.columns:
            group_col = None
        try:
            symbol_col = self.ternary_symbol_by_var.get()
        except Exception:
            symbol_col = "None"
        if symbol_col in [None, "", "None"] or symbol_col not in plot_df.columns:
            symbol_col = None
        try:
            if getattr(self, "ternary_colorbar", None) is not None:
                self.ternary_colorbar.remove()
                self.ternary_colorbar = None
        except Exception:
            self.ternary_colorbar = None
        color_is_continuous = False
        color_values = None
        if group_col is not None and self._ternary_style_is_continuous_numeric(plot_df[group_col]):
            color_is_continuous = True
            color_values = pd.to_numeric(plot_df[group_col], errors="coerce")
        if symbol_col is None:
            symbol_labels = pd.Series(["all"] * len(plot_df), index=plot_df.index)
        else:
            symbol_labels = self._ternary_symbol_categories(plot_df[symbol_col], max_bins=6)
        symbol_groups = list(pd.unique(symbol_labels.fillna("NA").astype(str)))
        marker_map = {g: markers[i % len(markers)] for i, g in enumerate(symbol_groups)}
        plotted = []
        if color_is_continuous:
            finite = color_values[np.isfinite(color_values)]
            vmin, vmax = self._color_limits_for_data(finite)
            scatters = []
            for sg in symbol_groups:
                sub = plot_df[symbol_labels.fillna("NA").astype(str) == sg]
                if sub.empty:
                    continue
                cvals = pd.to_numeric(sub[group_col], errors="coerce")
                cvals = self._log_transform_color_array_if_needed(cvals)
                sc = ax.scatter(
                    sub["ternary_x"],
                    sub["ternary_y"],
                    s=24,
                    alpha=0.78,
                    marker=marker_map[sg],
                    c=cvals,
                    cmap="viridis",
                    vmin=vmin,
                    vmax=vmax,
                    edgecolors="none",
                )
                scatters.append(sc)
                plotted.append(sub)
            self._apply_manual_color_scale_to_axes(ax, finite)
            try:
                if scatters:
                    self.ternary_colorbar = self.ternary_fig.colorbar(
                        scatters[0], ax=ax, fraction=0.046, pad=0.04
                    )
                    self.ternary_colorbar.set_label(str(group_col))
            except Exception:
                pass
            try:
                from matplotlib.lines import Line2D

                handles = []
                if symbol_col is not None:
                    for g in symbol_groups[:12]:
                        handles.append(
                            Line2D(
                                [0],
                                [0],
                                marker=marker_map[g],
                                linestyle="",
                                color="black",
                                label=f"{symbol_col}: {g}",
                            )
                        )
                if handles:
                    ax.legend(
                        handles=handles, loc="center left", bbox_to_anchor=(1.15, 0.5), fontsize=8
                    )
            except Exception:
                pass
        else:
            if group_col is None:
                color_groups = ["all"]
                color_labels = pd.Series(["all"] * len(plot_df), index=plot_df.index)
            else:
                color_labels = plot_df[group_col].fillna("NA").astype(str)
                color_groups = list(pd.unique(color_labels))
            cmap = plt.get_cmap("tab20")
            color_map = {g: cmap(i % 20) for i, g in enumerate(color_groups)}
            for cg in color_groups:
                for sg in symbol_groups:
                    sub = plot_df[
                        (color_labels == cg) & (symbol_labels.fillna("NA").astype(str) == sg)
                    ]
                    if sub.empty:
                        continue
                    ax.scatter(
                        sub["ternary_x"],
                        sub["ternary_y"],
                        s=24,
                        alpha=0.75,
                        marker=marker_map[sg],
                        color=color_map[cg],
                        edgecolors="none",
                    )
                    plotted.append(sub)
            try:
                from matplotlib.lines import Line2D

                handles = []
                if group_col is not None:
                    for g in color_groups[:12]:
                        handles.append(
                            Line2D(
                                [0],
                                [0],
                                marker="o",
                                linestyle="",
                                color=color_map[g],
                                label=f"Color {group_col}: {g}",
                            )
                        )
                if symbol_col is not None:
                    for g in symbol_groups[:12]:
                        handles.append(
                            Line2D(
                                [0],
                                [0],
                                marker=marker_map[g],
                                linestyle="",
                                color="black",
                                label=f"Symbol {symbol_col}: {g}",
                            )
                        )
                if handles:
                    ax.legend(
                        handles=handles, loc="center left", bbox_to_anchor=(1.02, 0.5), fontsize=8
                    )
            except Exception:
                pass
        plotted_df = (
            pd.concat(plotted, ignore_index=True, sort=False) if plotted else pd.DataFrame()
        )
        return plotted_df


