    # prepare pair for X-Y plots
    def prepare_xy_pair(self, x_col, y_col, df=None):
        if df is None:
            df = self.get_active_analysis_table()
        if df is None:
            return pd.DataFrame()
        keep_cols = []
        for col in [x_col, y_col]:
            if col in df.columns and col not in keep_cols:
                keep_cols.append(col)
        for extra in [
            "plot_group",
            "plot_group_id",
            "plot_summary_mode",
            "source_row_count",
            "line_id",
            "profile_id",
            "grain_id",
            "area_id",
            "domain",
            "spot_id",
            "distance",
            "distance_normalized",
            "point_id",
            "distance_bin",
        ]:
            if extra in df.columns and extra not in keep_cols:
                keep_cols.append(extra)
        for var_name in ["xy_color_by_var", "xy_symbol_by_var"]:
            try:
                col = getattr(self, var_name).get()
                if col and col != "None" and (col in df.columns) and (col not in keep_cols):
                    keep_cols.append(col)
            except Exception:
                pass
        pair = df[keep_cols].copy()
        pair[x_col] = pd.to_numeric(pair[x_col], errors="coerce")
        pair[y_col] = pd.to_numeric(pair[y_col], errors="coerce")
        pair = pair.replace([np.inf, -np.inf], np.nan).dropna(subset=[x_col, y_col])
        try:
            use_log = bool(self.xy_log_data_for_kde_var.get())
        except Exception:
            use_log = False
        if use_log:
            pair = pair[(pair[x_col] > 0) & (pair[y_col] > 0)].copy()
            pair[x_col] = np.log10(pair[x_col])
            pair[y_col] = np.log10(pair[y_col])
        return pair


