    # refresh custom color group source options
    def _refresh_custom_color_group_source_options(self):
        combo = getattr(self, "custom_color_group_source_combo", None)
        var = getattr(self, "custom_color_group_source_var", None)
        if combo is None or var is None:
            return
        choices = _candidate_custom_group_sources(self)
        try:
            combo.configure(values=choices)
        except Exception:
            pass
        current = str(var.get()).strip()
        if not current:
            if "profile_number" in choices:
                var.set("profile_number")
            elif choices:
                var.set(choices[0])


    # apply custom color groups to table
    def _apply_custom_color_groups_to_df(self, df, source_col=None, raw_text=None):
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return df
        if source_col is None:
            try:
                source_col = str(self.custom_color_group_source_var.get()).strip()
            except Exception:
                source_col = "profile_number"
        if raw_text is None:
            try:
                raw_text = self.custom_color_groups_var.get()
            except Exception:
                try:
                    raw_text = self.profile_color_groups_var.get()
                except Exception:
                    raw_text = ""
        if not source_col or source_col not in df.columns:
            return df.copy()
        mapping = _parse_custom_color_groups(raw_text)
        out = df.copy()
        labels = []
        for value in out[source_col]:
            key = _normalize_custom_group_value(value)
            if key is None:
                labels.append("Unassigned")
            else:
                labels.append(mapping.get(key, _display_custom_group_value(value)))
        out["custom_color_group"] = labels
        out["custom_color_group_source"] = str(source_col)
        if str(source_col) == "profile_number":
            out["profile_color_group"] = out["custom_color_group"].astype(str)
        return out


