    # plot ternary
    def plot_ternary(self):
        cols = []
        for attr in ("ternary_a_col_var", "ternary_b_col_var", "ternary_c_col_var"):
            try:
                cols.append(str(getattr(self, attr).get()))
            except Exception:
                pass
        raw = _raw_analysis_source_table(self)
        filtered, info = self._apply_iqr_filter(raw, cols)
        _set_iqr_override(self, filtered)
        try:
            out = _plot_ternary(self)
        finally:
            _clear_iqr_override(self)
        self._append_iqr_note(info, context="ternary")
        return out


    # plot all rows for X-Y plots
    def plot_xy_all_rows(self, x_col, y_col):
        plot_type = self.xy_plot_type_var.get()
        kde_max_points = optional_positive_int(self.xy_kde_max_points_var.get())
        grid_points = max(safe_int(self.xy_kde_grid_points_var.get(), 150), 40)
        bandwidth = max(safe_float(self.xy_kde_bandwidth_var.get(), 1.0), 0.05)
        pair = self.prepare_xy_pair(x_col, y_col, self.get_active_analysis_table())
        if pair.empty:
            messagebox.showerror(
                "No valid data", "No valid X-Y pairs remain after the current filters."
            )
            return
        need_kde = plot_type in ["KDE", "Scatter + KDE"]
        need_scatter = plot_type in ["Scatter", "Scatter + KDE", "Scatter + line"]
        need_line = plot_type in ["Line", "Scatter + line"]
        scatter_data = pair.copy()
        if need_kde and kde_max_points is not None and (len(pair) > kde_max_points):
            kde_data = pair.sample(n=kde_max_points, random_state=1).copy()
            kde_note = f"; KDE used {len(kde_data):,} of {len(pair):,} valid rows"
        else:
            kde_data = pair.copy()
            kde_note = f"; KDE used {len(kde_data):,} valid rows" if need_kde else ""
        if need_kde:
            try:
                xgrid, ygrid, density, hx, hy = self.kde_2d_numpy(
                    kde_data[x_col].to_numpy(dtype=float),
                    kde_data[y_col].to_numpy(dtype=float),
                    grid_points=grid_points,
                    bandwidth_mult=bandwidth,
                )
                artist = (
                    self.xy_ax.contourf(xgrid, ygrid, density, levels=20)
                    if plot_type == "KDE"
                    else self.xy_ax.contour(xgrid, ygrid, density, levels=12)
                )
                _add_xy_colorbar(self, artist, "KDE density")
                rows = []
                for row_index, yy in enumerate(ygrid):
                    for column_index, xx in enumerate(xgrid):
                        rows.append(
                            {
                                "x_column": x_col,
                                "y_column": y_col,
                                "x": xx,
                                "y": yy,
                                "density": density[row_index, column_index],
                                "n_used": len(kde_data),
                                "bandwidth_x": hx,
                                "bandwidth_y": hy,
                            }
                        )
                self.last_xy_kde_df = pd.DataFrame(rows)
            except Exception as exc:
                messagebox.showerror("2D KDE error", str(exc))
                return
        if need_scatter:
            _draw_xy_scatter(self, scatter_data, x_col, y_col)
        if need_line:
            _plot_xy_lines(self, pair, x_col, y_col, include_points=False)
        self.last_xy_regression_df = _add_xy_regression_lines(self, pair, x_col, y_col)
        _xy_apply_legend_visibility(self)
        self.last_xy_plot_df = pair.copy()
        self.last_xy_plot_df["plot_mode"] = "filtered_active_data"
        self.last_xy_plot_df["plot_type"] = plot_type
        self.last_xy_plot_df["log10_transformed"] = bool(self.xy_log_data_for_kde_var.get())
        self.last_xy_drawn_df = scatter_data.copy() if need_scatter else pd.DataFrame()
        xlabel = f"log10({x_col})" if self.xy_log_data_for_kde_var.get() else x_col
        ylabel = f"log10({y_col})" if self.xy_log_data_for_kde_var.get() else y_col
        self.xy_ax.set_xlabel(xlabel)
        self.xy_ax.set_ylabel(ylabel)
        if need_scatter:
            count_note = f"n valid={len(pair):,}; points drawn={len(scatter_data):,}"
        elif need_line:
            count_note = f"n valid={len(pair):,}; line rows={len(pair):,}"
        else:
            count_note = f"n valid={len(pair):,}"
        self.xy_ax.set_title(f"{ylabel} vs {xlabel}\n{plot_type}; {count_note}")
        if self.xy_logx_var.get() and (not self.xy_log_data_for_kde_var.get()):
            self.xy_ax.set_xscale("log")
        if self.xy_logy_var.get() and (not self.xy_log_data_for_kde_var.get()):
            self.xy_ax.set_yscale("log")
        self.finish_xy_plot()
        try:
            base_count = len(self.get_active_analysis_table())
            msg = (
                f"X-Y {plot_type} complete. Active rows: {base_count:,}; valid X-Y rows: {len(pair):,}"
            )
            if need_scatter:
                msg += f"; scatter points drawn: {len(scatter_data):,}"
            if kde_note:
                msg += kde_note
            self.status_var.set(msg + ".")
        except Exception:
            pass


