    # X-Y edges from existing axes
    def _layer_xy_edges_from_existing_axes(self, meta, z_shape):
        try:
            xg = np.asarray(meta.get("x_grid"), dtype=float)
            yg = np.asarray(meta.get("y_grid"), dtype=float)
            if xg.shape == yg.shape == tuple(z_shape):
                x_centers = _axis_from_sparse_coordinate_grid(xg, "x")
                y_centers = _axis_from_sparse_coordinate_grid(yg, "y")
                return (self._centers_to_edges_1d(x_centers), self._centers_to_edges_1d(y_centers))
        except Exception:
            pass
        try:
            x = np.asarray(meta.get("x", []), dtype=float)
            y = np.asarray(meta.get("y", []), dtype=float)
            if x.size == int(z_shape[1]) and y.size == int(z_shape[0]):
                return (self._centers_to_edges_1d(x), self._centers_to_edges_1d(y))
        except Exception:
            pass
        return (None, None)


