    # IQR filter series helper
    def _iqr_filter_series(self, vals):
        vals = (
            pd.to_numeric(pd.Series(vals), errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
        )
        vals = vals[vals > 0]
        if vals.count() < 4:
            return vals
        q1 = float(vals.quantile(0.25))
        q3 = float(vals.quantile(0.75))
        iqr = q3 - q1
        if not np.isfinite(iqr) or iqr <= 0:
            return vals
        k = self._spider_iqr_k()
        return vals[(vals >= q1 - k * iqr) & (vals <= q3 + k * iqr)]


