    # add log axis controls
    def _add_log_axis_controls(self, parent, label="Axis scale"):
        try:
            self._ensure_log_axis_vars()
            if getattr(parent, "_has_log_axis_controls", False):
                return False
            lf = ttk.LabelFrame(parent, text=label)
            lf.pack(fill=tk.X, padx=2, pady=6)
            parent._has_log_axis_controls = True
            ttk.Checkbutton(lf, text="Log X axis", variable=self.global_log_x_var).pack(
                anchor="w", padx=4, pady=1
            )
            ttk.Checkbutton(lf, text="Log Y axis", variable=self.global_log_y_var).pack(
                anchor="w", padx=4, pady=1
            )
            ttk.Checkbutton(lf, text="Log color values", variable=self.global_log_color_var).pack(
                anchor="w", padx=4, pady=1
            )
            ttk.Button(
                lf, text="Apply axis/color scale", command=self.apply_axis_scale_to_current_figure
            ).pack(fill=tk.X, padx=4, pady=2)
            return True
        except Exception:
            return False


    # positive axis limits derived from the current view
    def _positive_axis_limits_from_current(self, ax, which="x"):
        vals = []
        try:
            for line in ax.lines:
                data = line.get_xdata() if which == "x" else line.get_ydata()
                vals.extend(np.asarray(data, dtype=float).ravel())
        except Exception:
            pass
        try:
            for coll in ax.collections:
                off = coll.get_offsets()
                if off is not None and len(off):
                    vals.extend(
                        np.asarray(off[:, 0] if which == "x" else off[:, 1], dtype=float).ravel()
                    )
        except Exception:
            pass
        vals = np.asarray(vals, dtype=float)
        vals = vals[np.isfinite(vals) & (vals > 0)]
        if vals.size:
            return (float(np.nanmin(vals)), float(np.nanmax(vals)))
        return None


    # apply log axes to axes
    def _apply_log_axes_to_axes(self, ax=None):
        try:
            self._ensure_log_axis_vars()
            if ax is None:
                return
            if bool(self.global_log_x_var.get()):
                lim = self._positive_axis_limits_from_current(ax, "x")
                if lim is not None and lim[0] < lim[1]:
                    ax.set_xscale("log")
                    ax.set_xlim(lim[0], lim[1])
            if bool(self.global_log_y_var.get()):
                lim = self._positive_axis_limits_from_current(ax, "y")
                if lim is not None and lim[0] < lim[1]:
                    ax.set_yscale("log")
                    ax.set_ylim(lim[0], lim[1])
        except Exception:
            pass


    # apply log scaling to numeric color values when requested
    def _log_transform_color_array_if_needed(self, values):
        try:
            self._ensure_log_axis_vars()
            arr = np.asarray(values, dtype=float)
            if bool(self.global_log_color_var.get()):
                out = np.full(arr.shape, np.nan, dtype=float)
                ok = np.isfinite(arr) & (arr > 0)
                out[ok] = np.log10(arr[ok])
                return out
            return arr
        except Exception:
            return values


    # apply axis scale to current figure
    def apply_axis_scale_to_current_figure(self):
        axes = [
            getattr(self, "ax", None),
            getattr(self, "map_ax", None),
            getattr(self, "xy_ax", None),
            getattr(self, "ternary_ax", None),
            getattr(self, "kde_ax", None),
            getattr(self, "mineral_stats_ax", None),
            getattr(self, "compare_ax", None),
            getattr(self, "pca_ax", None),
            getattr(self, "corr_ax", None),
        ]
        for ax in axes:
            if ax is not None:
                self._apply_log_axes_to_axes(ax)
                try:
                    self._apply_manual_color_scale_to_axes(ax)
                except Exception:
                    pass
        for canvas in [
            getattr(self, "canvas", None),
            getattr(self, "map_canvas", None),
            getattr(self, "xy_canvas", None),
            getattr(self, "ternary_canvas", None),
            getattr(self, "kde_canvas", None),
            getattr(self, "mineral_stats_canvas", None),
            getattr(self, "compare_canvas", None),
            getattr(self, "pca_canvas", None),
            getattr(self, "corr_canvas", None),
        ]:
            try:
                if canvas is not None:
                    canvas.draw_idle()
            except Exception:
                pass


    # create scrollable left panel
    def make_scrollable_left_panel(self, parent, *, width=360):
        outer = ttk.Frame(parent)
        canvas = tk.Canvas(outer, borderwidth=0, highlightthickness=0, width=width)
        vbar = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vbar.set)
        inner = ttk.Frame(canvas)
        window_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        vbar.pack(side=tk.RIGHT, fill=tk.Y)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # configure
        def _configure(event=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
                canvas.itemconfigure(window_id, width=max(canvas.winfo_width() - 2, 50))
            except Exception:
                pass

        inner.bind("<Configure>", _configure)
        canvas.bind("<Configure>", _configure)

        # local wheel helper
        def _wheel(event):
            try:
                if event.num == 4:
                    canvas.yview_scroll(-1, "units")
                elif event.num == 5:
                    canvas.yview_scroll(1, "units")
                else:
                    canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            except Exception:
                pass

        # bind
        def _bind(event=None):
            canvas.bind_all("<MouseWheel>", _wheel)
            canvas.bind_all("<Button-4>", _wheel)
            canvas.bind_all("<Button-5>", _wheel)

        # local unbind helper
        def _unbind(event=None):
            canvas.unbind_all("<MouseWheel>")
            canvas.unbind_all("<Button-4>")
            canvas.unbind_all("<Button-5>")

        canvas.bind("<Enter>", _bind)
        canvas.bind("<Leave>", _unbind)
        inner.bind("<Enter>", _bind)
        inner.bind("<Leave>", _unbind)
        return (outer, inner, canvas)


    # force displayed map into tool state helper
    def _force_displayed_map_into_tool_state(self):
        return _sample_force_displayed_map_into_tool_state(self)



    # shared data, channel names, and import cleanup
    # Keeps tables and channel aliases consistent between maps and plotting tabs.


    # loaded used for tools
    def _map_loaded_for_tools(self):
        try:
            return bool(self._force_displayed_map_into_tool_state())
        except Exception:
            return False


    # active map axes and canvas used by drawing tools
    def _active_map_axes_canvas(self):
        ax = getattr(self, "map_ax", None)
        canvas = getattr(self, "map_canvas", None)
        if ax is None:
            ax = getattr(self, "ax", None)
        if canvas is None:
            canvas = getattr(self, "canvas", None)
        try:
            self.map_ax = ax
            self.map_canvas = canvas
            self.ax = ax
            self.canvas = canvas
        except Exception:
            pass
        return (ax, canvas)


    # visible map axes and canvas for the current sample tab.
    def _visible_map_ax_canvas(self):
        ax = getattr(self, "map_ax", None)
        canvas = getattr(self, "map_canvas", None)
        if ax is None:
            ax = getattr(self, "ax", None)
        if canvas is None:
            canvas = getattr(self, "canvas", None)
        if ax is not None:
            try:
                self.map_ax = ax
                self.ax = ax
            except Exception:
                pass
        if canvas is not None:
            try:
                self.map_canvas = canvas
                self.canvas = canvas
            except Exception:
                pass
        return (ax, canvas)


    # current visible axis limits
    def _current_visible_axis_limits(self):
        ax, _canvas = self._visible_map_ax_canvas()
        if ax is None:
            return None
        try:
            return (ax.get_xlim(), ax.get_ylim())
        except Exception:
            return None


    # put the map axes back after a temporary redraw
    def _restore_visible_axis_limits(self, lims):
        if lims is None:
            return
        ax, _canvas = self._visible_map_ax_canvas()
        if ax is None:
            return
        try:
            ax.set_xlim(lims[0])
            ax.set_ylim(lims[1])
        except Exception:
            pass


    # draw extraction overlays on visible map
    def _draw_extraction_overlays_on_visible_map(self):
        ax, canvas = self._visible_map_ax_canvas()
        if ax is None:
            return
        old_artists = []
        for name in ["line_artists", "spot_artists", "area_artists", "lasso_preview_artists"]:
            old_artists.extend(list(getattr(self, name, [])))
            try:
                setattr(self, name, [])
            except Exception:
                pass
        for artist in old_artists:
            try:
                artist.remove()
            except Exception:
                pass
        for seg in list(getattr(self, "line_segments", [])):
            try:
                line_id = seg.get("line_id", "")
                x0, y0, x1, y1 = (
                    float(seg["x0"]),
                    float(seg["y0"]),
                    float(seg["x1"]),
                    float(seg["y1"]),
                )
                buffer_pixels = self.get_profile_buffer_pixels() if hasattr(self, "get_profile_buffer_pixels") else 0
                if buffer_pixels > 0:
                    (halo,) = ax.plot(
                        [x0, x1], [y0, y1], linewidth=max(5.0, 4.0 * buffer_pixels + 2.0),
                        alpha=0.22, solid_capstyle="round", zorder=4999,
                    )
                    self.line_artists.append(halo)
                (artist,) = ax.plot([x0, x1], [y0, y1], linewidth=2.5, marker="o", zorder=5000)
                txt = ax.text(
                    x0,
                    y0,
                    str(line_id),
                    fontsize=10,
                    fontweight="bold",
                    color="black",
                    zorder=5001,
                    bbox=dict(
                        facecolor="white", alpha=0.85, edgecolor="black", linewidth=0.5, pad=1.5
                    ),
                )
                self.line_artists.extend([artist, txt])
            except Exception:
                pass
        df_spots = getattr(self, "spot_df", None)
        if df_spots is not None and (not df_spots.empty):
            for _, row in df_spots.iterrows():
                try:
                    sid = int(row.get("spot_id", row.get("point_id", 0)))
                    x = float(row["x"])
                    y = float(row["y"])
                    (artist,) = ax.plot(
                        [x], [y], marker="o", markersize=9, linestyle="None", zorder=5002
                    )
                    txt = ax.text(
                        x,
                        y,
                        str(sid),
                        fontsize=10,
                        fontweight="bold",
                        color="black",
                        zorder=5003,
                        bbox=dict(
                            facecolor="white", alpha=0.85, edgecolor="black", linewidth=0.5, pad=1.5
                        ),
                    )
                    self.spot_artists.extend([artist, txt])
                except Exception:
                    pass
        for seg in list(getattr(self, "area_segments", [])):
            try:
                aid = seg.get("area_id", "")
                domain = seg.get("domain", "")
                shape = seg.get("area_shape", "rectangle")
                if (
                    shape == "lasso"
                    and seg.get("polygon_x") is not None
                    and (seg.get("polygon_y") is not None)
                ):
                    xs = list(seg["polygon_x"]) + [seg["polygon_x"][0]]
                    ys = list(seg["polygon_y"]) + [seg["polygon_y"][0]]
                    (artist,) = ax.plot(xs, ys, linewidth=2.5, zorder=5004)
                    lx, ly = (xs[0], ys[0])
                else:
                    left, right = (float(seg["left"]), float(seg["right"]))
                    bottom, top = (float(seg["bottom"]), float(seg["top"]))
                    xs = [left, right, right, left, left]
                    ys = [bottom, bottom, top, top, bottom]
                    (artist,) = ax.plot(xs, ys, linewidth=2.5, zorder=5004)
                    lx, ly = (left, top)
                txt = ax.text(
                    lx,
                    ly,
                    f"{aid}: {domain}",
                    fontsize=10,
                    fontweight="bold",
                    color="black",
                    zorder=5005,
                    bbox=dict(
                        facecolor="white", alpha=0.85, edgecolor="black", linewidth=0.5, pad=1.5
                    ),
                )
                self.area_artists.extend([artist, txt])
            except Exception:
                pass
        if canvas is not None:
            try:
                canvas.draw_idle()
            except Exception:
                pass


    # redraw all extraction overlays
    def _redraw_all_extraction_overlays(self):
        lims = self._current_visible_axis_limits()
        self._draw_extraction_overlays_on_visible_map()
        self._restore_visible_axis_limits(lims)


    # axes used for any sampling
    def _layer_axes_for_any_sampling(self, layer):
        arr = np.asarray(self.values[layer], dtype=float)
        nr, nc = arr.shape
        meta = self.metas.get(layer, {}) if hasattr(self, "metas") else {}
        x = np.asarray(meta.get("x", []), dtype=float)
        y = np.asarray(meta.get("y", []), dtype=float)
        if x.ndim != 1 or x.size != nc:
            x = np.arange(nc, dtype=float)
        if y.ndim != 1 or y.size != nr:
            y = np.arange(nr, dtype=float)
        return (x, y)


    # check whether a map layer overlaps the current X-Y extent.
    def _layer_overlaps_current_xy(self, layer):
        try:
            if self.current_z is None or self.current_meta is None:
                self._force_displayed_map_into_tool_state()
            cur_x = np.asarray(self.current_meta.get("x", []), dtype=float)
            cur_y = np.asarray(self.current_meta.get("y", []), dtype=float)
            lx, ly = self._layer_axes_for_any_sampling(layer)
            if cur_x.size < 2 or cur_y.size < 2 or lx.size < 2 or (ly.size < 2):
                return np.asarray(self.values[layer]).shape == np.asarray(self.current_z).shape
            cx0, cx1 = sorted([float(np.nanmin(cur_x)), float(np.nanmax(cur_x))])
            cy0, cy1 = sorted([float(np.nanmin(cur_y)), float(np.nanmax(cur_y))])
            lx0, lx1 = sorted([float(np.nanmin(lx)), float(np.nanmax(lx))])
            ly0, ly1 = sorted([float(np.nanmin(ly)), float(np.nanmax(ly))])
            return min(cx1, lx1) > max(cx0, lx0) and min(cy1, ly1) > max(cy0, ly0)
        except Exception:
            return False


    # selected overlapping map columns
    def selected_overlapping_map_columns(self):
        cols = []
        for layer in list(getattr(self, "values", {}).keys()):
            try:
                if self.maps_are_same_shape_as_current(layer) or self._layer_overlaps_current_xy(
                    layer
                ):
                    cols.append(layer)
            except Exception:
                pass
        return cols


    # layer line or point helper for sample workspaces
    def _sample_layer_line_or_point(self, layer, xs, ys, method="bilinear"):
        rows, cols = self._xy_to_layer_fractional_indices_any(layer, xs, ys)
        arr = np.asarray(self.values[layer], dtype=float)
        if method == "nearest":
            out = []
            for r, c in zip(np.asarray(rows).ravel(), np.asarray(cols).ravel()):
                out.append(nearest_sample(arr, r, c))
            return np.asarray(out, dtype=float)
        return bilinear_sample(arr, rows, cols)


    # parse boundary pair label
    def _parse_boundary_pair_label(self, label):
        if not label:
            return None
        s = str(label).strip()
        if not s or s == "All NN/selected pairs":
            return None
        for sep in ["↔", "→", "->", "—", "–"]:
            if sep in s:
                parts = [p.strip() for p in s.split(sep, 1)]
                if len(parts) == 2:
                    a = self._resolve_mineral_group_name(parts[0])
                    b = self._resolve_mineral_group_name(parts[1])
                    if a and b and (a != b):
                        return (a, b)
        return None


    # matching column name in the active analysis table
    def active_table_column_match(self, name, df=None):
        if df is None:
            df = self.get_active_pixel_table()
        if df is None or df.empty or (not name):
            return None
        name = str(name).strip()
        if name in df.columns:
            return name

        # clean
        def clean(v):
            s = str(v).strip()
            s = re.sub("\\s+\\(\\d+\\)$", "", s)
            if " :: " in s:
                s = s.split(" :: ", 1)[-1].strip()
            try:
                if hasattr(self, "canonical_layer_display_name"):
                    s = self.canonical_layer_display_name(s)
            except Exception:
                pass
            return s

        target = clean(name)
        for c in df.columns:
            if clean(c) == target:
                return c
        return None


    # numeric columns in the active analysis table
    def active_table_numeric_columns(self):
        df = self.get_active_pixel_table()
        if df is None or df.empty:
            return []
        skip = {"row_index", "column_index"}
        columns = []
        for column in df.columns:
            if str(column) in skip:
                continue
            try:
                series = df[column]
                is_numeric = pd.api.types.is_numeric_dtype(series)
                if not is_numeric and not isinstance(series.dtype, pd.CategoricalDtype):
                    sample = series.dropna().iloc[:1000]
                    is_numeric = (
                        not sample.empty
                        and pd.to_numeric(sample, errors="coerce").notna().mean() > 0.95
                    )
                if is_numeric:
                    columns.append(str(column))
            except Exception:
                continue
        return columns


    # value points used for boundary
    def _phase_value_points_for_boundary(self, mineral, value_col, rule="finite", threshold=0.0):
        active_points = self.calculated_phase_points_from_active_table(
            mineral, value_col, rule=rule, threshold=threshold
        )
        if active_points is not None and active_points.get("n_pixels", 0) > 0:
            return active_points
        mineral = (
            self._resolve_mineral_group_name(mineral)
            if hasattr(self, "_resolve_mineral_group_name")
            else str(mineral)
        )
        value_col = (
            self.canonical_layer_display_name(value_col)
            if hasattr(self, "canonical_layer_display_name")
            else str(value_col)
        )
        _, extent, x, y, phase_mask = self.mineral_group_mask_and_coords(
            mineral, rule=rule, threshold=threshold
        )
        phase_mask = np.asarray(phase_mask, dtype=bool)
        layer_value = None
        if hasattr(self, "_resolve_mineral_element_layer_strict"):
            layer_value = self._resolve_mineral_element_layer_strict(mineral, value_col)
        if layer_value is None and hasattr(self, "_layer_for_mineral_value_column"):
            try:
                layer_value = self._layer_for_mineral_value_column(mineral, value_col)
            except Exception:
                layer_value = None
        if layer_value not in getattr(self, "values", {}):
            raise ValueError(f"{mineral}: no {value_col} layer or active-table column")
        vals = np.asarray(self.values[layer_value], dtype=float)
        try:
            _, vx, vy, vz = self._layer_extent_from_meta(layer_value)
            vals = np.asarray(vz, dtype=float)
            if vals.shape == phase_mask.shape:
                x_use, y_use = (np.asarray(vx, dtype=float), np.asarray(vy, dtype=float))
            else:
                x_use, y_use = (np.asarray(x, dtype=float), np.asarray(y, dtype=float))
        except Exception:
            x_use, y_use = (np.asarray(x, dtype=float), np.asarray(y, dtype=float))
        if vals.shape != phase_mask.shape:
            raise ValueError(
                f"{mineral}: {value_col} value grid shape {vals.shape} does not match its own phase mask shape {phase_mask.shape}"
            )
        finite = np.isfinite(vals)
        valid = phase_mask & finite
        if rule == ">0":
            valid &= vals > 0
        elif rule == ">custom":
            valid &= vals > threshold
        if not np.any(valid):
            raise ValueError(f"{mineral}: no valid {value_col} pixels after mask rule")
        xx, yy = np.meshgrid(x_use, y_use)
        coords = np.column_stack([xx[valid].ravel(), yy[valid].ravel()])
        values = vals[valid].astype(float).ravel()
        spacing = self._median_xy_spacing(x_use, y_use)
        return {
            "mineral": mineral,
            "value_col": value_col,
            "layer": layer_value,
            "coords": coords,
            "values": values,
            "spacing": spacing,
            "n_pixels": int(values.size),
        }


    # boundary stats from values
    def _boundary_stats_from_values(self, values):
        values = np.asarray(values, dtype=float)
        values = values[np.isfinite(values)]
        n = int(values.size)
        if n == 0:
            return {
                "n_pixels": 0,
                "mean": np.nan,
                "median": np.nan,
                "sd": np.nan,
                "se": np.nan,
                "cv_percent": np.nan,
                "sum": np.nan,
                "p05": np.nan,
                "p25": np.nan,
                "p75": np.nan,
                "p95": np.nan,
            }
        mean = float(np.nanmean(values))
        sd = float(np.nanstd(values, ddof=1)) if n > 1 else np.nan
        return {
            "n_pixels": n,
            "mean": mean,
            "median": float(np.nanmedian(values)),
            "sd": sd,
            "se": float(sd / np.sqrt(n)) if n > 1 and np.isfinite(sd) else np.nan,
            "cv_percent": (
                float(100.0 * sd / mean) if n > 1 and mean != 0 and np.isfinite(sd) else np.nan
            ),
            "sum": float(np.nansum(values)),
            "p05": float(np.nanpercentile(values, 5)),
            "p25": float(np.nanpercentile(values, 25)),
            "p75": float(np.nanpercentile(values, 75)),
            "p95": float(np.nanpercentile(values, 95)),
        }


    # spacing used for shared sampling
    def _axis_spacing_for_shared_sampling(self, axis):
        try:
            axis = np.asarray(axis, dtype=float)
            d = np.diff(axis)
            d = d[np.isfinite(d) & (np.abs(d) > 0)]
            if d.size:
                return float(np.nanmedian(np.abs(d)))
        except Exception:
            pass
        return 1.0


    # convert layer to reference grid
    def _sample_layer_to_reference_grid(self, layer, base_x, base_y, max_distance=None):
        arr = np.asarray(self.values[layer], dtype=float)
        x, y = self._layer_xy_axes_for_shared_sampling(layer)
        base_x = np.asarray(base_x, dtype=float)
        base_y = np.asarray(base_y, dtype=float)
        if arr.shape == (base_y.size, base_x.size):
            try:
                if np.allclose(x, base_x, equal_nan=True) and np.allclose(
                    y, base_y, equal_nan=True
                ):
                    return arr.ravel()
            except Exception:
                pass
        try:
            from scipy.spatial import cKDTree
        except Exception:
            if arr.shape == (base_y.size, base_x.size):
                return arr.ravel()
            return np.full(base_x.size * base_y.size, np.nan, dtype=float)
        sx_grid, sy_grid = np.meshgrid(x, y)
        src_coords = np.column_stack([sx_grid.ravel(), sy_grid.ravel()])
        src_vals = arr.ravel()
        ok_src = np.isfinite(src_coords).all(axis=1) & np.isfinite(src_vals)
        if not np.any(ok_src):
            return np.full(base_x.size * base_y.size, np.nan, dtype=float)
        src_coords = src_coords[ok_src]
        src_vals = src_vals[ok_src]
        bx_grid, by_grid = np.meshgrid(base_x, base_y)
        base_coords = np.column_stack([bx_grid.ravel(), by_grid.ravel()])
        tree = cKDTree(src_coords)
        dists, idx = tree.query(base_coords, k=1)
        if max_distance is None:
            sx = self._axis_spacing_for_shared_sampling(x)
            sy = self._axis_spacing_for_shared_sampling(y)
            bx = self._axis_spacing_for_shared_sampling(base_x)
            by = self._axis_spacing_for_shared_sampling(base_y)
            max_distance = 0.75 * max(sx, sy, bx, by)
        out = np.full(base_coords.shape[0], np.nan, dtype=float)
        good = np.isfinite(dists) & (dists <= float(max_distance))
        out[good] = src_vals[idx[good]]
        return out


    # split group suffix
    def _split_group_suffix(self, layer_name):
        text = str(layer_name)
        if " :: " in text:
            return text.split(" :: ", 1)
        return (text, text)


    # canonical element-channel name used for matching
    def canonical_element_column_name(self, name):
        raw = (
            self.raw_canonical_element_column_name(name)
            if hasattr(self, "raw_canonical_element_column_name")
            else str(name).strip()
        )
        aliases = getattr(self, "column_alias_definitions", {}) or {}
        if not aliases:
            return raw
        seen = set()
        current = raw
        for _ in range(20):
            if current in seen:
                break
            seen.add(current)
            if current in aliases:
                nxt = str(aliases[current]).strip()
            else:
                lower_map = {str(k).strip().lower(): str(v).strip() for k, v in aliases.items()}
                nxt = lower_map.get(str(current).strip().lower(), current)
            if not nxt or nxt == current:
                break
            current = nxt
        return current


    # unfiltered canonical element column name
    def raw_canonical_element_column_name(self, name):
        s = str(name).strip()
        if " :: " in s:
            s = s.split(" :: ")[-1].strip()
        s = re.sub("\\s+\\(\\d+\\)$", "", s).strip()
        return s


    # all alias candidate columns
    def _all_alias_candidate_columns(self):
        cols = []

        # add column names to the list without duplicates
        def add_many(items):
            for c in items or []:
                s = str(c).strip()
                if s and s not in cols:
                    cols.append(s)

        try:
            add_many(list(getattr(self, "values", {}).keys()))
        except Exception:
            pass
        for attr in [
            "analysis_df",
            "active_analysis_df",
            "comparison_df",
            "line_profile_df",
            "spot_df",
            "area_df",
            "area_pixel_df",
            "shared_coordinate_pixel_df",
            "last_grain_df",
            "last_grain_table_df",
            "last_grain_pixel_df",
            "last_grain_summary_df",
            "last_compare_grain_df",
            "last_grain_radial_pixel_df",
            "last_grain_radial_profile_pixels_df",
            "last_grain_radial_profile_bins_df",
            "last_grain_radial_bin_df",
            "last_compare_grain_kde_df",
        ]:
            df = getattr(self, attr, None)
            if isinstance(df, pd.DataFrame):
                add_many(list(df.columns))
        extra = []
        for c in cols:
            try:
                raw = self.raw_canonical_element_column_name(c)
            except Exception:
                raw = str(c)
            try:
                can = self.canonical_element_column_name(c)
            except Exception:
                can = raw
            extra.extend([raw, can])
        add_many(extra)
        metadata_cols = set(METADATA_COLUMNS) | {
            "map_group",
            "mineral_type",
            "mineral_group",
            "comparison_dataset",
            "plot_group",
            "grain_set",
            "grain_uid",
            "profile_id",
            "profile_number",
        }
        out = []
        for c in cols:
            if str(c) in metadata_cols:
                continue
            if str(c).strip() and str(c).strip() not in out:
                out.append(str(c).strip())
        return sorted(out, key=lambda x: x.lower())


    # available sources for a calculated-channel operand
    def _column_source_choices(self):
        mapping = {}
        used_labels = set()
        for layer in (getattr(self, "values", {}) or {}).keys():
            meta = (getattr(self, "metas", {}) or {}).get(layer, {}) or {}
            run_name = str(meta.get("map_group") or meta.get("comparison_dataset") or "Map").strip()
            current = str(
                meta.get("canonical_column") or self.raw_canonical_element_column_name(layer)
            ).strip()
            label = f"{run_name} :: {current}"
            if label in used_labels:
                label = f"{label}  [stored layer: {layer}]"
            used_labels.add(label)
            mapping[label] = ("layer", layer)
        represented = {str(v[1]) for v in mapping.values() if v[0] == "layer"}
        for attr in [
            "analysis_df",
            "active_analysis_df",
            "comparison_df",
            "line_profile_df",
            "spot_df",
            "area_df",
            "area_pixel_df",
            "last_grain_df",
            "last_grain_df_full",
            "last_grain_table_df",
            "last_grain_pixel_df",
            "last_compare_grain_df",
        ]:
            df = getattr(self, attr, None)
            if not isinstance(df, pd.DataFrame):
                continue
            for col in df.columns:
                name = str(col).strip()
                if not name or name in METADATA_COLUMNS or name in represented:
                    continue
                label = f"Table column :: {name}"
                if label not in mapping:
                    mapping[label] = ("table", name)
        return mapping


    # add column alias controls
    def add_column_alias_controls(self, parent=None):
        try:
            if parent is None:
                parent = self.math_tab
            if getattr(self, "column_alias_frame", None) is not None and bool(
                self.column_alias_frame.winfo_exists()
            ):
                return
        except Exception:
            pass
        frame = ttk.LabelFrame(parent, text="Rename channel")
        frame.pack(side=tk.BOTTOM, fill=tk.X, padx=6, pady=(2, 6))
        self.column_alias_frame = frame
        self.alias_source_col_var = getattr(self, "alias_source_col_var", tk.StringVar())
        self.alias_target_col_var = getattr(self, "alias_target_col_var", tk.StringVar())
        self.alias_rule_var = getattr(
            self, "alias_rule_var", tk.StringVar(value="Target then source")
        )
        self.alias_remove_originals_var = getattr(
            self, "alias_remove_originals_var", tk.BooleanVar(value=True)
        )
        ttk.Label(
            frame,
            text="Choose a channel and enter the shared name.",
            wraplength=950,
            justify=tk.LEFT,
        ).pack(anchor="w", padx=6, pady=(5, 3))
        row = ttk.Frame(frame)
        row.pack(fill=tk.X, padx=6, pady=(1, 4))
        ttk.Label(row, text="Channel:").pack(side=tk.LEFT)
        self.alias_source_combo = ttk.Combobox(
            row, textvariable=self.alias_source_col_var, state="readonly", width=52
        )
        self.alias_source_combo.pack(side=tk.LEFT, padx=(4, 10))
        ttk.Label(row, text="New name:").pack(side=tk.LEFT)
        self.alias_target_combo = ttk.Combobox(
            row, textvariable=self.alias_target_col_var, width=34
        )
        self.alias_target_combo.pack(side=tk.LEFT, padx=4)
        self.alias_source_combo.bind("<<ComboboxSelected>>", self._suggest_column_target)
        ttk.Button(
            frame, text="Rename channel", command=self.create_column_alias_from_ui
        ).pack(fill=tk.X, padx=6, pady=(1, 5))
        ttk.Label(
            frame,
            text="Matching channels plot together; runs stay separate.",
            wraplength=950,
            justify=tk.LEFT,
        ).pack(anchor="w", padx=6, pady=(0, 5))
        self.refresh_column_alias_controls()


    # canonical target name choices
    def _canonical_target_name_choices(self):
        names = []
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            value = str(
                (meta or {}).get("canonical_column")
                or self.raw_canonical_element_column_name(layer)
            ).strip()
            if value and value not in names:
                names.append(value)
        for candidate in self._all_alias_candidate_columns():
            clean = self.raw_canonical_element_column_name(candidate)
            if clean and clean not in names:
                names.append(clean)
        return sorted(names, key=str.lower)


    # best standard-name match for the selected column
    def _suggest_column_target(self, event=None):
        try:
            display = str(self.alias_source_col_var.get()).strip()
            kind, source = (getattr(self, "_channel_source_map", {}) or {}).get(
                display, ("table", display)
            )
            if kind == "layer" and source in getattr(self, "metas", {}):
                meta = self.metas.get(source, {}) or {}
                suggested = str(
                    meta.get("canonical_column") or self.raw_canonical_element_column_name(source)
                ).strip()
            else:
                suggested = self.raw_canonical_element_column_name(source)
            self.alias_target_col_var.set(suggested)
        except Exception:
            pass


    # refresh column-alias choices after a rename or import
    def refresh_column_alias_controls(self):
        combo = getattr(self, "simple_rename_source_combo", None)
        target_combo = getattr(self, "simple_rename_target_combo", None)
        if combo is None:
            try:
                return _refresh_alias_controls(self)
            except Exception:
                return
        mapping = {}
        labels = []
        canonical_names = []
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if layer not in (getattr(self, "values", {}) or {}):
                continue
            sample, mineral, run, channel = _sample_layer_identity(meta, layer)
            label = f"{sample} | {mineral} | {run} | {channel}"
            if label in mapping:
                label = f"{label} | stored {layer}"
            mapping[label] = layer
            labels.append(label)
            if channel not in canonical_names:
                canonical_names.append(channel)
        self._channel_rename_sources = mapping
        combo.configure(values=labels)
        target_combo.configure(values=sorted(canonical_names, key=str.lower))
        if labels and self.simple_rename_source_var.get() not in labels:
            self.simple_rename_source_var.set(labels[0])
            _sample_suggest_rename_target(self)


    # columns that can be renamed through the alias controls
    def _alias_column_candidates_in_df(self, df, source_raw):
        candidates = []
        if not isinstance(df, pd.DataFrame):
            return candidates
        for c in df.columns:
            try:
                raw = self.raw_canonical_element_column_name(c)
            except Exception:
                raw = str(c)
            if raw == source_raw or str(c) == source_raw:
                candidates.append(c)
        return candidates


    # combined alias source series
    def _combined_alias_source_series(self, df, candidates, rule="Target then source"):
        if not candidates:
            return None
        series_list = [pd.to_numeric(df[c], errors="coerce") for c in candidates if c in df.columns]
        if not series_list:
            return None
        out = series_list[0].copy()
        if len(series_list) == 1:
            return out
        if rule == "Mean where both exist":
            return pd.concat(series_list, axis=1).mean(axis=1, skipna=True)
        for s in series_list[1:]:
            if rule == "Source replaces target" or rule == "Source then target":
                out = out.combine_first(s)
            else:
                out = out.combine_first(s)
        return out


    # apply column alias to dataframe
    def _apply_column_alias_to_dataframe(
        self, df, source_raw, target, rule="Target then source", remove_originals=False
    ):
        if not isinstance(df, pd.DataFrame) or df.empty:
            return False
        candidates = self._alias_column_candidates_in_df(df, source_raw)
        for c in list(df.columns):
            try:
                if (
                    self.canonical_element_column_name(c) == target
                    and c not in candidates
                    and (str(c) != target)
                ):
                    candidates.append(c)
            except Exception:
                pass
        candidates = [
            c for c in dict.fromkeys(candidates) if c in df.columns and str(c) != str(target)
        ]
        if not candidates:
            return False
        source_series = self._combined_alias_source_series(df, candidates, rule=rule)
        if source_series is None:
            return False
        if target in df.columns:
            current = pd.to_numeric(df[target], errors="coerce")
            if rule == "Source replaces target":
                new_values = source_series
            elif rule == "Source then target":
                new_values = source_series.combine_first(current)
            elif rule == "Mean where both exist":
                new_values = pd.concat([current, source_series], axis=1).mean(axis=1, skipna=True)
            else:
                new_values = current.combine_first(source_series)
        else:
            new_values = source_series
        df[target] = new_values
        if remove_originals:
            drop_cols = [c for c in candidates if c in df.columns and str(c) != str(target)]
            if drop_cols:
                try:
                    df.drop(columns=drop_cols, inplace=True)
                except Exception:
                    for c in drop_cols:
                        try:
                            del df[c]
                        except Exception:
                            pass
        return True


    # find existing alias layer
    def _find_existing_alias_layer(self, source_layer, target):
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if not isinstance(meta, dict):
                continue
            if (
                meta.get("column_alias_generated")
                and meta.get("alias_source_layer") == source_layer
                and (meta.get("canonical_column") == target)
            ):
                return layer
        return None


    # unused map-layer name for a new alias
    def _unique_alias_layer_name(self, target):
        if target not in getattr(self, "values", {}):
            return target
        i = 2
        while f"{target} ({i})" in self.values:
            i += 1
        return f"{target} ({i})"


    # merge numeric arrays for alias
    def _merge_numeric_arrays_for_alias(self, current, source, rule="Target then source"):
        cur = np.asarray(current, dtype=float)
        src = np.asarray(source, dtype=float)
        if cur.shape != src.shape:
            return (
                src.copy()
                if rule in {"Source replaces target", "Source then target"}
                else cur.copy()
            )
        if rule == "Source replaces target":
            return src.copy()
        if rule == "Source then target":
            out = cur.copy()
            mask = np.isfinite(src)
            out[mask] = src[mask]
            return out
        if rule == "Mean where both exist":
            stacked = np.stack([cur, src], axis=0)
            with np.errstate(all="ignore"):
                return np.nanmean(stacked, axis=0)
        out = cur.copy()
        mask = ~np.isfinite(out) & np.isfinite(src)
        out[mask] = src[mask]
        return out


    # group key used for alias
    def _layer_group_key_for_alias(self, layer, meta=None):
        try:
            meta = (
                meta
                if isinstance(meta, dict)
                else (getattr(self, "metas", {}) or {}).get(layer, {}) or {}
            )
            if hasattr(self, "_mineral_group_key_from_meta"):
                return self._mineral_group_key_from_meta(layer, meta)
            return (
                meta.get("mineral_group") or meta.get("mineral_type") or meta.get("map_group") or ""
            )
        except Exception:
            return ""


    # replace a layer name in maps, tables, and saved state.
    def _replace_layer_name_everywhere(self, old_layer, new_layer):
        for group, info in list((getattr(self, "mineral_presence_groups", {}) or {}).items()):
            if not isinstance(info, dict):
                continue
            layers = list(info.get("layers", []) or [])
            changed = False
            new_layers = []
            for lyr in layers:
                if lyr == old_layer:
                    if new_layer not in new_layers:
                        new_layers.append(new_layer)
                    changed = True
                elif lyr not in new_layers:
                    new_layers.append(lyr)
            if changed:
                info["layers"] = new_layers


    # remove name everywhere for map layers
    def _remove_layer_name_everywhere(self, old_layer):
        for group, info in list((getattr(self, "mineral_presence_groups", {}) or {}).items()):
            if not isinstance(info, dict):
                continue
            layers = list(info.get("layers", []) or [])
            if old_layer in layers:
                info["layers"] = [lyr for lyr in layers if lyr != old_layer]


    # find target layer in same group
    def _find_target_layer_in_same_group(self, source_layer, target, source_meta=None):
        source_group = self._layer_group_key_for_alias(source_layer, source_meta)
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if layer == source_layer:
                continue
            raw = self.raw_canonical_element_column_name(
                (meta or {}).get("canonical_column") or layer
            )
            if raw != target and str(layer) != target:
                continue
            if self._layer_group_key_for_alias(layer, meta) == source_group:
                return layer
        return None


    # apply column alias to maps
    def _apply_column_alias_to_maps(
        self, source_raw, target, rule="Target then source", remove_originals=False
    ):
        made = []
        for layer, z in list((getattr(self, "values", {}) or {}).items()):
            if layer not in getattr(self, "values", {}):
                continue
            meta = dict((getattr(self, "metas", {}) or {}).get(layer, {}) or {})
            raw = self.raw_canonical_element_column_name(
                meta.get("raw_column_before_alias") or meta.get("canonical_column") or layer
            )
            if raw != source_raw and str(layer) != source_raw:
                continue
            if remove_originals:
                target_layer = self._find_target_layer_in_same_group(layer, target, meta)
                if target_layer is not None and target_layer in self.values:
                    self.values[target_layer] = self._merge_numeric_arrays_for_alias(
                        self.values[target_layer], z, rule=rule
                    )
                    self.metas.setdefault(target_layer, {}).setdefault(
                        "raw_column_before_alias", target
                    )
                    self.metas[target_layer]["canonical_column"] = target
                    self.metas[target_layer]["source_layer_name"] = target
                    self.metas[target_layer].setdefault("column_renamed_from", raw)
                    try:
                        del self.values[layer]
                    except Exception:
                        pass
                    try:
                        del self.metas[layer]
                    except Exception:
                        pass
                    self._remove_layer_name_everywhere(layer)
                    made.append(target_layer)
                    continue
                if layer == target:
                    new_layer = layer
                elif target not in self.values:
                    new_layer = target
                else:
                    new_layer = self._unique_alias_layer_name(target)
                arr = np.asarray(z, dtype=float).copy()
                new_meta = dict(meta)
                new_meta.update(
                    {
                        "canonical_column": target,
                        "source_layer_name": target,
                        "raw_column_before_alias": raw,
                        "column_renamed_from": raw,
                        "column_alias_generated": False,
                    }
                )
                if new_layer != layer:
                    try:
                        del self.values[layer]
                    except Exception:
                        pass
                    try:
                        del self.metas[layer]
                    except Exception:
                        pass
                self.values[new_layer] = arr
                self.metas[new_layer] = new_meta
                self._replace_layer_name_everywhere(layer, new_layer)
                made.append(new_layer)
                continue
            try:
                self.metas.setdefault(layer, {}).setdefault("raw_column_before_alias", raw)
                self.metas[layer]["canonical_column"] = target
            except Exception:
                pass
            existing = self._find_existing_alias_layer(layer, target)
            alias_layer = existing or self._unique_alias_layer_name(target)
            self.values[alias_layer] = np.asarray(z, dtype=float).copy()
            alias_meta = dict(meta)
            alias_meta.update(
                {
                    "canonical_column": target,
                    "source_layer_name": target,
                    "column_alias_generated": True,
                    "alias_source_layer": layer,
                    "alias_source_column": source_raw,
                    "raw_column_before_alias": raw,
                }
            )
            self.metas[alias_layer] = alias_meta
            try:
                group_key = (
                    self._mineral_group_key_from_meta(layer, meta)
                    if hasattr(self, "_mineral_group_key_from_meta")
                    else meta.get("mineral_type")
                )
                if group_key in getattr(self, "mineral_presence_groups", {}):
                    layers = self.mineral_presence_groups[group_key].setdefault("layers", [])
                    if alias_layer not in layers:
                        layers.append(alias_layer)
            except Exception:
                pass
            made.append(alias_layer)
        if made:
            try:
                self.rebuild_mineral_column_index()
            except Exception:
                pass
        return made


    # register column alias
    def register_column_alias(
        self, source, target, rule="Target then source", apply_now=True, remove_originals=True
    ):
        source_raw = self.raw_canonical_element_column_name(source)
        target = self.raw_canonical_element_column_name(target)
        if not source_raw or not target:
            raise ValueError("Choose both the source column and the canonical name.")
        self.column_alias_definitions = dict(getattr(self, "column_alias_definitions", {}) or {})
        self.column_alias_definitions[source_raw] = target
        changed_tables = 0
        made_layers = []
        if apply_now:
            made_layers = self._apply_column_alias_to_maps(
                source_raw, target, rule=rule, remove_originals=remove_originals
            )
            for attr in [
                "analysis_df",
                "active_analysis_df",
                "comparison_df",
                "line_profile_df",
                "spot_df",
                "area_df",
                "area_pixel_df",
                "shared_coordinate_pixel_df",
                "last_grain_df",
                "last_grain_table_df",
                "last_grain_pixel_df",
                "last_grain_summary_df",
                "last_compare_grain_df",
                "last_grain_radial_pixel_df",
                "last_grain_radial_profile_pixels_df",
                "last_grain_radial_profile_bins_df",
                "last_grain_radial_bin_df",
                "last_compare_grain_kde_df",
            ]:
                df = getattr(self, attr, None)
                if isinstance(df, pd.DataFrame):
                    try:
                        if self._apply_column_alias_to_dataframe(
                            df, source_raw, target, rule=rule, remove_originals=remove_originals
                        ):
                            setattr(self, attr, df)
                            changed_tables += 1
                    except Exception:
                        pass
            try:
                self.refresh_analysis_controls_after_channel_change()
            except Exception:
                pass
            try:
                self.refresh_analysis_columns()
            except Exception:
                pass
        return {
            "source": source_raw,
            "target": target,
            "tables": changed_tables,
            "layers": made_layers,
        }


    # apply column aliases to loaded data
    def apply_column_aliases_to_loaded_data(self, refresh=True):
        aliases = dict(getattr(self, "column_alias_definitions", {}) or {})
        results = []
        for source, target in aliases.items():
            results.append(
                self.register_column_alias(
                    source,
                    target,
                    apply_now=True,
                    remove_originals=getattr(self, "column_alias_remove_originals", True),
                )
            )
        if refresh:
            try:
                self.refresh_analysis_controls_after_channel_change()
                self.refresh_analysis_columns()
            except Exception:
                pass
        return results


    # rename exact dataframe column
    def _rename_exact_dataframe_column(self, df, source, target):
        if not isinstance(df, pd.DataFrame) or df.empty:
            return False
        source = str(source).strip()
        target = str(target).strip()
        if not source or not target or source == target:
            return False
        source_columns = [c for c in df.columns if str(c) == source]
        if not source_columns:
            try:
                source_raw = self.raw_canonical_element_column_name(source)
                target_raw = self.raw_canonical_element_column_name(target)
            except Exception:
                source_raw, target_raw = (source, target)
            if source_raw != target_raw:
                for c in df.columns:
                    try:
                        if (
                            self.raw_canonical_element_column_name(c) == source_raw
                            and str(c) != target
                        ):
                            source_columns.append(c)
                    except Exception:
                        pass
        source_columns = list(
            dict.fromkeys((c for c in source_columns if c in df.columns and str(c) != target))
        )
        if not source_columns:
            return False
        if target in df.columns:
            combined = df[target].copy()
            for c in source_columns:
                combined = combined.combine_first(df[c])
            df[target] = combined
        else:
            first = source_columns.pop(0)
            df.rename(columns={first: target}, inplace=True)
            combined = df[target].copy()
            for c in source_columns:
                combined = combined.combine_first(df[c])
            df[target] = combined
        drop_columns = [c for c in source_columns if c in df.columns and str(c) != target]
        if drop_columns:
            df.drop(columns=drop_columns, inplace=True)
        return True


    # rename column everywhere
    def rename_column_everywhere(self, source, target):
        source_display = str(source).strip()
        target = self.raw_canonical_element_column_name(str(target).strip())
        if not source_display or not target:
            raise ValueError("Choose the run/channel and enter the shared name.")
        kind, source_key = (getattr(self, "_channel_source_map", {}) or {}).get(
            source_display, ("table", source_display)
        )
        old_names = []
        changed_layers = []
        if kind == "layer" and source_key in getattr(self, "values", {}):
            selected_meta = (getattr(self, "metas", {}) or {}).get(source_key, {}) or {}
            old_canonical = str(
                selected_meta.get("canonical_column")
                or self.raw_canonical_element_column_name(source_key)
            ).strip()
            old_names.extend(
                [old_canonical, str(source_key), self.raw_canonical_element_column_name(source_key)]
            )
            for layer in list((getattr(self, "values", {}) or {}).keys()):
                meta = (getattr(self, "metas", {}) or {}).setdefault(layer, {})
                current = str(
                    meta.get("canonical_column") or self.raw_canonical_element_column_name(layer)
                ).strip()
                raw_layer = self.raw_canonical_element_column_name(layer)
                if layer == source_key or current == old_canonical or raw_layer == old_canonical:
                    meta.setdefault("original_canonical_column", current)
                    meta["canonical_column"] = target
                    meta["column_renamed_from"] = current
                    changed_layers.append(layer)
        else:
            old_canonical = self.raw_canonical_element_column_name(source_key)
            old_names.extend([str(source_key), old_canonical])
        old_names = [
            n for n in dict.fromkeys((str(v).strip() for v in old_names)) if n and n != target
        ]
        table_attrs = [
            "analysis_df",
            "active_analysis_df",
            "comparison_df",
            "line_profile_df",
            "spot_df",
            "area_df",
            "area_pixel_df",
            "shared_coordinate_pixel_df",
            "last_grain_df",
            "last_grain_df_full",
            "last_grain_table_df",
            "last_grain_pixel_df",
            "last_grain_summary_df",
            "last_compare_grain_df",
            "last_grain_radial_pixel_df",
            "last_grain_radial_profile_pixels_df",
            "last_grain_radial_profile_bins_df",
            "last_grain_radial_bin_df",
            "last_compare_grain_kde_df",
        ]
        changed_tables = 0
        for attr in table_attrs:
            df = getattr(self, attr, None)
            if not isinstance(df, pd.DataFrame):
                continue
            changed = False
            for old in old_names:
                if self._rename_exact_dataframe_column(df, old, target):
                    changed = True
            if changed:
                setattr(self, attr, df)
                changed_tables += 1
        for run in (getattr(self, "grain_analysis_runs", {}) or {}).values():
            attrs = run.get("attrs", {}) if isinstance(run, dict) else {}
            for key, value in list(attrs.items()):
                if isinstance(value, pd.DataFrame):
                    changed = False
                    for old in old_names:
                        if self._rename_exact_dataframe_column(value, old, target):
                            changed = True
                    if changed:
                        attrs[key] = value
                        changed_tables += 1
        self.column_alias_definitions = dict(getattr(self, "column_alias_definitions", {}) or {})
        if old_canonical and old_canonical != target:
            self.column_alias_definitions[old_canonical] = target
        self.column_alias_remove_originals = True
        self.rebuild_mineral_presence_groups_from_metadata()
        self.rebuild_mineral_column_index()
        self.refresh_map_column_combo(preserve=True)
        self.refresh_analysis_controls_after_channel_change()
        try:
            self.refresh_analysis_columns()
        except Exception:
            pass
        self.refresh_column_alias_controls()
        try:
            self.update_map()
        except Exception:
            pass
        return {
            "source": source_display,
            "target": target,
            "layers": list(dict.fromkeys(changed_layers)),
            "tables": int(changed_tables),
            "already_matched": bool(old_canonical == target),
        }


    # create column alias from UI
    def create_column_alias_from_ui(self):
        try:
            source = self.alias_source_col_var.get().strip()
            target = self.alias_target_col_var.get().strip()
            result = self.rename_column_everywhere(source, target)
            if result.get("already_matched"):
                text = f"{result['source']} already uses the shared name {result['target']}.\n\nAny duplicate table heading was collapsed into that name."
            else:
                text = f"Renamed {result['source']} to {result['target']}.\n\nMap layers matched: {len(result['layers'])}\nTables updated: {result['tables']}\n\nThe runs remain separate for comparison."
            messagebox.showinfo("Channel renamed", text)
            try:
                self.status_var.set(
                    f"Matched channel name: {result['source']} → {result['target']}"
                )
            except Exception:
                pass
        except Exception as exc:
            messagebox.showerror("Could not rename channel", str(exc))


    # refresh analysis controls after channel change
    def refresh_analysis_controls_after_channel_change(self):
        for method_name in [
            "refresh_mineral_stats_controls",
            "refresh_comparison_controls",
            "refresh_compare_ree_controls",
            "refresh_grain_controls",
            "refresh_compare_grain_controls",
            "refresh_xy_controls",
            "refresh_ree_controls",
            "refresh_ternary_controls",
            "refresh_kde_controls",
            "refresh_correlation_controls",
            "refresh_pca_controls",
        ]:
            try:
                if hasattr(self, method_name):
                    getattr(self, method_name)()
            except Exception:
                pass


    # records from active table used for column
    def _phase_records_from_active_table_for_column(self, value_col):
        df = self.get_active_pixel_table()
        if df is None or df.empty:
            return []
        group_col = self.active_table_group_column(df)
        if group_col is None:
            return []
        value_col = str(value_col).strip()
        if value_col not in df.columns:
            target = (
                self.canonical_layer_display_name(value_col)
                if hasattr(self, "canonical_layer_display_name")
                else value_col
            )
            match = None
            for c in df.columns:
                clean = (
                    self.canonical_layer_display_name(c)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(c)
                )
                if clean == target:
                    match = c
                    break
            if match is None:
                return []
            value_col = match
        selected_groups = (
            self._selected_mineral_stat_groups()
            if hasattr(self, "_selected_mineral_stat_groups")
            else []
        )
        selected_groups = [str(g) for g in selected_groups]
        try:
            rule = self.mineral_stats_rule_var.get()
        except Exception:
            rule = "finite"
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        records = []
        for group, sub in df.groupby(group_col, dropna=False):
            group = str(group)
            if selected_groups and group not in selected_groups:
                continue
            vals = pd.to_numeric(sub[value_col], errors="coerce").to_numpy(dtype=float)
            mask = np.isfinite(vals)
            if rule == ">0":
                mask &= vals > 0
            elif rule == ">custom":
                mask &= vals > threshold
            selected_vals = vals[mask]
            selected_vals = selected_vals[np.isfinite(selected_vals)]
            n = int(selected_vals.size)
            if n == 0:
                continue
            coords = np.empty((0, 2))
            if "x" in sub.columns and "y" in sub.columns:
                try:
                    coords_df = (
                        sub.loc[mask, ["x", "y"]].apply(pd.to_numeric, errors="coerce").dropna()
                    )
                    coords = coords_df.to_numpy(dtype=float)
                except Exception:
                    coords = np.empty((0, 2))
            mean_v = float(np.nanmean(selected_vals))
            median_v = float(np.nanmedian(selected_vals))
            sd_v = float(np.nanstd(selected_vals, ddof=1)) if n > 1 else np.nan
            iqr_v = (
                float(np.nanpercentile(selected_vals, 75) - np.nanpercentile(selected_vals, 25))
                if n > 1
                else np.nan
            )
            cv = float(sd_v / mean_v) if np.isfinite(sd_v) and mean_v != 0 else np.nan
            robust_cv = float(iqr_v / median_v) if np.isfinite(iqr_v) and median_v != 0 else np.nan
            records.append(
                {
                    "group": group,
                    "mineral_type": group,
                    "suffix": value_col,
                    "value_col": value_col,
                    "layer": f"active_table:{value_col}",
                    "n_pixels": n,
                    "sum_value": float(np.nansum(selected_vals)),
                    "mean_value": mean_v,
                    "median_value": median_v,
                    "sd_value": sd_v,
                    "se_value": float(sd_v / np.sqrt(n)) if n > 1 and np.isfinite(sd_v) else np.nan,
                    "cv_value": cv,
                    "cv_percent": float(100.0 * cv) if np.isfinite(cv) else np.nan,
                    "iqr_value": iqr_v,
                    "robust_cv_value": robust_cv,
                    "robust_cv_percent": (
                        float(100.0 * robust_cv) if np.isfinite(robust_cv) else np.nan
                    ),
                    "min_value": float(np.nanmin(selected_vals)),
                    "max_value": float(np.nanmax(selected_vals)),
                    "p05_value": float(np.nanpercentile(selected_vals, 5)),
                    "p25_value": float(np.nanpercentile(selected_vals, 25)),
                    "p75_value": float(np.nanpercentile(selected_vals, 75)),
                    "p95_value": float(np.nanpercentile(selected_vals, 95)),
                    "coords": coords,
                    "values": selected_vals,
                }
            )
        return records


    # mask values used for layer
    def _mask_values_for_layer(self, layer_name, rule, threshold):
        extent, x, y, z = self._layer_extent_from_meta(layer_name)
        vals = np.asarray(z, dtype=float)
        mask = np.isfinite(vals)
        if rule == ">0":
            mask &= vals > 0
        elif rule == ">custom":
            mask &= vals > threshold
        return (extent, x, y, vals, mask)


    # selected presence records for mineral analysis
    def _selected_mineral_presence_records(self):
        """Count the pixels that define each selected mineral, independent of chemistry channels."""
        self.rebuild_mineral_presence_groups_from_metadata()
        groups = getattr(self, "mineral_presence_groups", {}) or {}
        selected = self._selected_mineral_stat_groups()
        if not selected:
            selected = list(groups.keys())
        try:
            rule = self.mineral_stats_rule_var.get()
        except Exception:
            rule = "finite"
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        rows = []
        for group_key in selected:
            record = groups.get(str(group_key), {})
            layer = record.get("representative_layer")
            if layer not in getattr(self, "values", {}):
                continue
            try:
                _extent, x, y, values = self._layer_extent_from_meta(layer)
                values = np.asarray(values, dtype=float)
            except Exception:
                continue
            mask = np.isfinite(values)
            if rule == ">0":
                mask &= values > 0
            elif rule == ">custom":
                mask &= values > threshold
            count = int(np.count_nonzero(mask))
            if count <= 0:
                continue
            xx, yy = np.meshgrid(np.asarray(x, dtype=float), np.asarray(y, dtype=float))
            rows.append(
                {
                    "group": str(group_key),
                    "mineral_group": str(group_key),
                    "mineral_type": str(record.get("mineral_type") or group_key),
                    "map_group": str(record.get("map_group") or "Map"),
                    "value_col": "present",
                    "suffix": "present",
                    "layer": layer,
                    "n_pixels": count,
                    "sum_value": float(count),
                    "mean_value": 1.0,
                    "sd_value": 0.0,
                    "se_value": 0.0,
                    "coords": np.column_stack([xx[mask].ravel(), yy[mask].ravel()]),
                    "values": np.ones(count, dtype=float),
                }
            )
        if not rows:
            raise ValueError(
                "No present pixels were found for the selected minerals. Check that the selected mineral maps contain finite pixels."
            )
        return rows


    # selected grain count records for mineral analysis
    def _selected_mineral_grain_count_records(self):
        """Count unique detected grains for the selected mineral groups."""
        table = combined_grain_shape_table(self)
        if not isinstance(table, pd.DataFrame) or table.empty:
            raise ValueError("No saved grain detections are available. Detect grains for the selected minerals first.")
        selected = set(self._selected_mineral_stat_groups())
        if selected:
            group_column = next(
                (column for column in ["mineral_group", "grain_set"] if column in table.columns),
                None,
            )
            if group_column is not None:
                table = table[table[group_column].astype(str).isin(selected)].copy()
        if table.empty:
            raise ValueError("None of the selected mineral groups has a saved grain detection.")
        if "grain_uid" in table.columns:
            table = table.drop_duplicates("grain_uid")
        else:
            unique_columns = [
                column
                for column in ["sample_id", "mineral_group", "grain_set", "grain_id"]
                if column in table.columns
            ]
            if unique_columns:
                table = table.drop_duplicates(unique_columns)
        group_to_type = {
            str(group_key): str(record.get("mineral_type") or group_key)
            for group_key, record in (getattr(self, "mineral_presence_groups", {}) or {}).items()
        }
        if "mineral_group" in table.columns:
            mapped = table["mineral_group"].astype(str).map(group_to_type)
        elif "grain_set" in table.columns:
            mapped = table["grain_set"].astype(str).map(group_to_type)
        else:
            mapped = pd.Series(np.nan, index=table.index)
        if "mineral_type" not in table.columns:
            table["mineral_type"] = mapped
        else:
            table["mineral_type"] = mapped.combine_first(table["mineral_type"].astype(str))
        table["mineral_type"] = table["mineral_type"].astype(str).str.replace(
            r"\s*\[[^\]]*\]\s*$", "", regex=True
        )
        rows = []
        for mineral_type, sub in table.groupby("mineral_type", dropna=False):
            count = int(len(sub))
            if count <= 0:
                continue
            rows.append(
                {
                    "group": str(mineral_type),
                    "mineral_type": str(mineral_type),
                    "value_col": "number_of_grains",
                    "suffix": "number_of_grains",
                    "layer": "saved_grain_sets",
                    "n_pixels": np.nan,
                    "n_grains": count,
                    "sum_value": float(count),
                    "mean_value": float(count),
                    "sd_value": np.nan,
                    "se_value": np.nan,
                    "coords": np.empty((0, 2)),
                    "values": np.ones(count, dtype=float),
                }
            )
        if not rows:
            raise ValueError("No unique grains were found for the selected minerals.")
        return rows


    # combine mineral records by type helper for mineral analysis
    def _combine_mineral_records_by_type(self, records, mode):
        """Combine repeated runs of the same mineral into one mineral-type value."""
        combined = []
        for mineral_type in dict.fromkeys(str(r.get("mineral_type") or r.get("group")) for r in records):
            subset = [r for r in records if str(r.get("mineral_type") or r.get("group")) == mineral_type]
            if not subset:
                continue
            pixel_count = float(np.nansum([r.get("n_pixels", 0) for r in subset]))
            grain_count = float(np.nansum([r.get("n_grains", 0) for r in subset]))
            total_sum = float(np.nansum([r.get("sum_value", 0) for r in subset]))
            if mode == "mean_value":
                weights = np.asarray([r.get("n_pixels", np.nan) for r in subset], dtype=float)
                means = np.asarray([r.get("mean_value", np.nan) for r in subset], dtype=float)
                good = np.isfinite(weights) & (weights > 0) & np.isfinite(means)
                value = float(np.average(means[good], weights=weights[good])) if np.any(good) else np.nan
            elif mode == "grain_count":
                value = grain_count
            elif mode == "pixel_area":
                value = pixel_count
            else:
                value = total_sum
            combined.append(
                {
                    "group": mineral_type,
                    "mineral_type": mineral_type,
                    "value_col": subset[0].get("value_col", ""),
                    "n_pixels": pixel_count,
                    "n_grains": grain_count,
                    "sum_value": total_sum,
                    "mean_value": value if mode == "mean_value" else np.nan,
                    "plot_value": value,
                    "source_groups": "; ".join(str(r.get("group")) for r in subset),
                }
            )
        return combined


    # records from comparison table
    def _phase_records_from_comparison_table(self):
        self.build_comparison_df_from_loaded_mineral_maps_if_needed()
        if self.comparison_df is None or self.comparison_df.empty:
            if getattr(self, "mineral_presence_groups", None):
                self.comparison_df = self.mineral_comparison_dataframe_from_loaded_maps()
            else:
                raise ValueError("No comparison table loaded or built from mineral maps.")
        suffix = self.mineral_stats_value_var.get()
        suffix = (
            self.canonical_layer_display_name(suffix)
            if hasattr(self, "canonical_layer_display_name")
            else str(suffix)
        )
        if suffix == "present" and suffix not in self.comparison_df.columns:
            self.comparison_df = self.comparison_df.copy()
            self.comparison_df["present"] = 1
        if not suffix or suffix not in self.comparison_df.columns:
            match = None
            for column in self.comparison_df.columns:
                clean = (
                    self.canonical_layer_display_name(column)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(column)
                )
                if clean == suffix:
                    match = column
                    break
            if match is None:
                raise ValueError("Choose a value column that exists in the comparison table.")
            suffix = match
        group_col = next(
            (
                column
                for column in ["mineral_group", "mineral_type", "comparison_dataset"]
                if column in self.comparison_df.columns
            ),
            None,
        )
        if group_col is None:
            raise ValueError("No mineral grouping column was found in the comparison table.")
        selected_groups = set(self._selected_mineral_stat_groups())
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        try:
            rule = self.mineral_stats_rule_var.get()
        except Exception:
            rule = "finite"
        records = []
        for group, sub in self.comparison_df.groupby(group_col, dropna=False):
            group = str(group)
            if selected_groups and group not in selected_groups:
                continue
            values = pd.to_numeric(sub[suffix], errors="coerce").to_numpy(dtype=float)
            mask = np.isfinite(values)
            if rule == ">0":
                mask &= values > 0
            elif rule == ">custom":
                mask &= values > threshold
            selected_values = values[mask]
            selected_values = selected_values[np.isfinite(selected_values)]
            count = int(selected_values.size)
            if count == 0:
                continue
            coordinates = np.empty((0, 2))
            if "x" in sub.columns and "y" in sub.columns:
                xy = sub.loc[mask, ["x", "y"]].apply(pd.to_numeric, errors="coerce").dropna()
                coordinates = xy.to_numpy(dtype=float)
            mineral_type = (
                str(sub["mineral_type"].dropna().iloc[0])
                if "mineral_type" in sub.columns and not sub["mineral_type"].dropna().empty
                else group
            )
            mean_value = float(np.nanmean(selected_values))
            sd_value = float(np.nanstd(selected_values, ddof=1)) if count > 1 else np.nan
            records.append(
                {
                    "group": group,
                    "mineral_group": group,
                    "mineral_type": mineral_type,
                    "suffix": suffix,
                    "value_col": (
                        self.canonical_layer_display_name(suffix)
                        if hasattr(self, "canonical_layer_display_name")
                        else str(suffix)
                    ),
                    "layer": f"{group_col}={group}",
                    "n_pixels": count,
                    "sum_value": float(np.nansum(selected_values)),
                    "mean_value": mean_value,
                    "median_value": float(np.nanmedian(selected_values)),
                    "sd_value": sd_value,
                    "se_value": float(sd_value / np.sqrt(count)) if count > 1 and np.isfinite(sd_value) else np.nan,
                    "coords": coordinates,
                    "values": selected_values,
                }
            )
        return records


    # mineral-phase records that contain the selected channel
    def _phase_records_for_selected_column(self):
        try:
            _chosen = (
                self.mineral_stats_value_var.get()
                if hasattr(self, "mineral_stats_value_var")
                else ""
            )
            _df = self.get_active_pixel_table()
            _match = self.active_table_column_match(_chosen, _df)
            if _match is not None:
                _records = self._phase_records_from_active_table_for_column(_match)
                if _records:
                    return _records
        except Exception:
            pass
        try:
            _chosen_value = (
                self.mineral_stats_value_var.get()
                if hasattr(self, "mineral_stats_value_var")
                else ""
            )
            _active_df = self.get_active_pixel_table()
            if (
                isinstance(_active_df, pd.DataFrame)
                and (not _active_df.empty)
                and (_chosen_value in _active_df.columns)
            ):
                _active_records = self._phase_records_from_active_table_for_column(_chosen_value)
                if _active_records:
                    return _active_records
        except Exception:
            pass
        "\n    Build one record per selected mineral/domain for the chosen element.\n\n    This is the shared data engine for:\n    - pie fractions\n    - variability / zoning proxy\n    - nearest-neighbor tests\n    "
        if (
            hasattr(self, "mineral_stats_source_var")
            and self.mineral_stats_source_var.get() == "comparison_table"
        ):
            records = self._phase_records_from_comparison_table()
            if not records:
                raise ValueError(
                    "No selected comparison groups have valid values for the chosen column/rule."
                )
            return records
        groups = self.get_mineral_group_layers()
        selected_groups = self._selected_mineral_stat_groups()
        suffix = self.mineral_stats_value_var.get()
        suffix = (
            self.canonical_layer_display_name(suffix)
            if hasattr(self, "canonical_layer_display_name")
            else str(suffix)
        )
        if not suffix:
            raise ValueError("Choose a shared value/element column first.")
        try:
            threshold = float(self.mineral_stats_threshold_var.get())
        except Exception:
            threshold = 0.0
        rule = self.mineral_stats_rule_var.get()
        records = []
        for group in selected_groups:
            layer = None
            if hasattr(self, "_resolve_mineral_element_layer_strict"):
                layer = self._resolve_mineral_element_layer_strict(group, suffix)
            if layer is None and group in groups:
                layer = groups.get(group, {}).get(suffix)
            if layer is None:
                for k, lyr in groups.get(group, {}).items():
                    clean = (
                        self.canonical_layer_display_name(k)
                        if hasattr(self, "canonical_layer_display_name")
                        else str(k)
                    )
                    if clean == suffix:
                        layer = lyr
                        break
            if layer is None or layer not in getattr(self, "values", {}):
                continue
            extent, x, y, vals, mask = self._mask_values_for_layer(layer, rule, threshold)
            selected_vals = vals[mask]
            selected_vals = selected_vals[np.isfinite(selected_vals)]
            n = int(selected_vals.size)
            if n == 0:
                continue
            xx, yy = np.meshgrid(x, y)
            coords = np.column_stack([xx[mask].ravel(), yy[mask].ravel()])
            mean_v = float(np.nanmean(selected_vals))
            sd_v = float(np.nanstd(selected_vals, ddof=1)) if n > 1 else np.nan
            median_v = float(np.nanmedian(selected_vals))
            iqr_v = (
                float(np.nanpercentile(selected_vals, 75) - np.nanpercentile(selected_vals, 25))
                if n > 1
                else np.nan
            )
            robust_cv = float(iqr_v / median_v) if np.isfinite(iqr_v) and median_v != 0 else np.nan
            cv = float(sd_v / mean_v) if np.isfinite(sd_v) and mean_v != 0 else np.nan
            records.append(
                {
                    "group": group,
                    "mineral_type": group,
                    "suffix": suffix,
                    "value_col": suffix,
                    "layer": layer,
                    "n_pixels": n,
                    "sum_value": float(np.nansum(selected_vals)),
                    "mean_value": mean_v,
                    "median_value": median_v,
                    "sd_value": sd_v,
                    "se_value": float(sd_v / np.sqrt(n)) if n > 1 and np.isfinite(sd_v) else np.nan,
                    "cv_value": cv,
                    "cv_percent": float(100.0 * cv) if np.isfinite(cv) else np.nan,
                    "iqr_value": iqr_v,
                    "robust_cv_value": robust_cv,
                    "robust_cv_percent": (
                        float(100.0 * robust_cv) if np.isfinite(robust_cv) else np.nan
                    ),
                    "min_value": float(np.nanmin(selected_vals)),
                    "max_value": float(np.nanmax(selected_vals)),
                    "p05_value": float(np.nanpercentile(selected_vals, 5)),
                    "p25_value": float(np.nanpercentile(selected_vals, 25)),
                    "p75_value": float(np.nanpercentile(selected_vals, 75)),
                    "p95_value": float(np.nanpercentile(selected_vals, 95)),
                    "coords": coords,
                    "values": selected_vals,
                }
            )
        if not records:
            raise ValueError(
                f"No selected groups contain valid pixels for '{suffix}'. Check the selected minerals, value column, and mask rule."
            )
        return records


    # records used for one fraction variable
    def _records_for_one_fraction_variable(self, value_col):
        old = None
        try:
            old = self.mineral_stats_value_var.get()
            self.mineral_stats_value_var.set(value_col)
            return self._phase_records_for_selected_column()
        finally:
            try:
                if old is not None:
                    self.mineral_stats_value_var.set(old)
            except Exception:
                pass


    # remember the map-axis direction before a redraw
    def _capture_current_map_axis_orientation(self):
        state = {"xlim": None, "ylim": None, "x_inverted": False, "y_inverted": False}
        ax = None
        for name in ("grain_ax", "ax", "map_ax"):
            cand = getattr(self, name, None)
            if cand is not None:
                ax = cand
                break
        if ax is not None:
            try:
                state["xlim"] = tuple(ax.get_xlim())
                state["ylim"] = tuple(ax.get_ylim())
                state["x_inverted"] = bool(ax.xaxis_inverted())
                state["y_inverted"] = bool(ax.yaxis_inverted())
                return state
            except Exception:
                pass
        try:
            state["x_inverted"] = bool(
                getattr(self, "map_invert_x_var", tk.BooleanVar(value=False)).get()
            )
        except Exception:
            pass
        try:
            state["y_inverted"] = bool(
                getattr(self, "map_invert_y_var", tk.BooleanVar(value=False)).get()
            )
        except Exception:
            pass
        return state


    # apply axis orientation for the map view
    def _apply_map_axis_orientation(self, ax=None, state=None, preserve_limits=False):
        if ax is None:
            ax = (
                getattr(self, "grain_ax", None)
                or getattr(self, "ax", None)
                or getattr(self, "map_ax", None)
            )
        if ax is None:
            return
        if state is None:
            state = self._capture_current_map_axis_orientation()
        try:
            if preserve_limits and state.get("xlim") is not None:
                ax.set_xlim(state["xlim"])
            else:
                lo, hi = ax.get_xlim()
                if bool(state.get("x_inverted", False)):
                    ax.set_xlim(max(lo, hi), min(lo, hi))
                else:
                    ax.set_xlim(min(lo, hi), max(lo, hi))
        except Exception:
            pass
        try:
            if preserve_limits and state.get("ylim") is not None:
                ax.set_ylim(state["ylim"])
            else:
                lo, hi = ax.get_ylim()
                if bool(state.get("y_inverted", False)):
                    ax.set_ylim(max(lo, hi), min(lo, hi))
                else:
                    ax.set_ylim(min(lo, hi), max(lo, hi))
        except Exception:
            pass
        try:
            ax.set_aspect("equal", adjustable="box")
        except Exception:
            pass


    # ellipse-refit rule selected in the grain controls
    def _ellipse_refit_mode(self):
        try:
            raw = str(self.grain_manual_center_mode_var.get()).strip()
        except Exception:
            return "center_only_keep_ellipse"
        low = raw.lower().replace("_", " ")
        if raw == "refit_from_center" or low.startswith("refit"):
            return "refit_from_center"
        if raw == "shift_ellipse" or low.startswith("move whole") or "without resizing" in low:
            return "shift_ellipse"
        if (
            raw == "center_only"
            or raw == "center_only_keep_ellipse"
            or "keep ellipse" in low
            or low.startswith("move center only")
        ):
            return "center_only_keep_ellipse"
        return "center_only_keep_ellipse"


    # refit ellipse from manual center and long axis
    def _refit_ellipse_from_manual_center_and_long_axis(
        self, grain_row, cx, cy, major0, minor0, angle0
    ):
        gid = int(grain_row.get("grain_id", -1))
        xs, ys = self._points_for_grain_id(gid)
        if xs.size < 3:
            return (major0, minor0, angle0, "manual_center_no_refit_points")
        angle = float(angle0) if np.isfinite(angle0) else 0.0
        if not np.isfinite(angle0):
            try:
                pts = np.column_stack([xs - np.nanmean(xs), ys - np.nanmean(ys)])
                cov = np.cov(pts.T)
                eigvals, eigvecs = np.linalg.eigh(cov)
                vec = eigvecs[:, int(np.argmax(eigvals))]
                angle = float(np.degrees(np.arctan2(vec[1], vec[0])))
            except Exception:
                angle = 0.0
        theta = np.deg2rad(angle)
        ct, st = (np.cos(theta), np.sin(theta))
        dx = xs - float(cx)
        dy = ys - float(cy)
        xp = dx * ct + dy * st
        yp = -dx * st + dy * ct
        max_major_half = float(np.nanmax(np.abs(xp))) if xp.size else np.nan
        max_minor_half = float(np.nanmax(np.abs(yp))) if yp.size else np.nan
        old_a = float(major0) / 2.0 if np.isfinite(major0) and major0 > 0 else np.nan
        old_b = float(minor0) / 2.0 if np.isfinite(minor0) and minor0 > 0 else np.nan
        if not np.isfinite(max_major_half) or max_major_half <= 0:
            max_major_half = old_a
        if not np.isfinite(max_minor_half) or max_minor_half <= 0:
            max_minor_half = old_b
        if np.isfinite(old_b) and np.isfinite(max_minor_half):
            max_minor_half = max(max_minor_half, old_b)
        if np.isfinite(old_a) and np.isfinite(max_major_half):
            max_major_half = max(max_major_half, old_a)
        major = 2.0 * max_major_half if np.isfinite(max_major_half) else major0
        minor = 2.0 * max_minor_half if np.isfinite(max_minor_half) else minor0
        if np.isfinite(major) and np.isfinite(minor) and (minor > major):
            major, minor = (minor, major)
            angle += 90.0
        return (float(major), float(minor), float(angle), "manual_center_refit_long_axis")


    # set manual center and refit
    def _set_manual_center_and_refit(self, gid, xnew, ynew, redraw=False):
        if not hasattr(self, "manual_grain_centers") or self.manual_grain_centers is None:
            self.manual_grain_centers = {}
        gid = int(gid)
        xnew = float(xnew)
        ynew = float(ynew)
        self.manual_grain_centers[gid] = (xnew, ynew)
        try:
            idx = self.last_grain_df["grain_id"].astype(int) == gid
            self.last_grain_df.loc[idx, "manual_center_x"] = xnew
            self.last_grain_df.loc[idx, "manual_center_y"] = ynew
            self.last_grain_df.loc[idx, "center_manually_moved"] = True
            self.last_grain_df.loc[idx, "manual_center_refit_mode"] = (
                self._ellipse_refit_mode()
                if hasattr(self, "_ellipse_refit_mode")
                else "center_only_keep_ellipse"
            )
            for _ii in self.last_grain_df.index[idx]:
                _cx, _cy, _maj, _min, _ang, _meth = self._grain_current_ellipse_params(
                    self.last_grain_df.loc[_ii]
                )
                self.last_grain_df.loc[_ii, "grain_center_x"] = _cx
                self.last_grain_df.loc[_ii, "grain_center_y"] = _cy
                self.last_grain_df.loc[_ii, "grain_ellipse_major_axis"] = _maj
                self.last_grain_df.loc[_ii, "grain_ellipse_minor_axis"] = _min
                self.last_grain_df.loc[_ii, "grain_ellipse_angle_deg"] = _ang
                self.last_grain_df.loc[_ii, "grain_ellipse_method"] = _meth
        except Exception:
            pass
        try:
            self.last_grain_radial_pixel_df = pd.DataFrame()
            self.last_grain_radial_bin_df = pd.DataFrame()
        except Exception:
            pass
        if redraw:
            self._redraw_grains_after_center_move()


    # remove the temporary ellipse shown while dragging a center
    def _clear_drag_center_preview(self):
        try:
            artist = getattr(self, "_drag_center_preview_artist", None)
            if artist is not None:
                artist.remove()
            self._drag_center_preview_artist = None
        except Exception:
            self._drag_center_preview_artist = None


    # remove repeated column names while keeping the first copy
    def _dedupe_cols_keep_first(self, df):
        if df is None:
            return None
        return df.loc[:, ~pd.Index(df.columns).duplicated(keep="first")].copy()


    # actual table column behind a displayed menu label
    def _table_column_name(self, layer, used):
        name = str(layer).split(" :: ", 1)[-1]
        base = name
        i = 2
        while name in used:
            name = f"{base}_{i}"
            i += 1
        used.add(name)
        return name


    # merge export columns
    def _merge_export_columns(self, df):
        """Coalesce duplicate column names without discarding conflicting values."""
        merged = pd.DataFrame(index=df.index)
        for position, raw_name in enumerate(df.columns):
            name = str(raw_name).strip() or f"column_{position + 1}"
            series = df.iloc[:, position].copy()
            if name not in merged.columns:
                merged[name] = series
                continue

            current = merged[name]
            both = current.notna() & series.notna()
            conflict = False
            if both.any():
                left = current.loc[both]
                right = series.loc[both]
                left_num = pd.to_numeric(left, errors="coerce")
                right_num = pd.to_numeric(right, errors="coerce")
                numeric = left_num.notna() & right_num.notna()
                equal = pd.Series(False, index=left.index)
                if numeric.any():
                    equal.loc[numeric] = np.isclose(
                        left_num.loc[numeric].to_numpy(dtype=float),
                        right_num.loc[numeric].to_numpy(dtype=float),
                        rtol=1e-12,
                        atol=0.0,
                        equal_nan=True,
                    )
                if (~numeric).any():
                    equal.loc[~numeric] = (
                        left.loc[~numeric].astype(str).to_numpy()
                        == right.loc[~numeric].astype(str).to_numpy()
                    )
                conflict = not bool(equal.all())

            if not conflict:
                combined = current.copy()
                missing = combined.isna()
                if missing.any():
                    combined.loc[missing] = series.loc[missing]
                merged[name] = combined
                continue

            suffix = 2
            new_name = f"{name}_{suffix}"
            while new_name in merged.columns:
                suffix += 1
                new_name = f"{name}_{suffix}"
            merged[new_name] = series
        return merged



    # export formatting
    # Removes internal-only fields and orders the columns written to CSV.


    # prepare export dataframe
    def _prepare_export_dataframe(self, df, export_kind="general"):
        """Return a clean table while preserving all non-duplicate data."""
        if not isinstance(df, pd.DataFrame):
            return pd.DataFrame()
        out = df.copy()
        try:
            out = self._filter_excluded_pixel_rows(out)
        except Exception:
            pass
        try:
            out = self.normalize_multimineral_analysis_columns(out)
        except (AttributeError, KeyError, TypeError, ValueError):
            try:
                out = _sample_canonicalize_dataframe_columns(self, out)
            except (AttributeError, KeyError, TypeError, ValueError):
                pass

        out = self._merge_export_columns(out)
        out = out.dropna(axis=1, how="all")
        private = [col for col in out.columns if str(col).startswith("__")]
        if private:
            out = out.drop(columns=private, errors="ignore")

        # Remove aliases only when they contain the same information.
        for alias, direct in [
            ("comparison_dataset", "sample_id"),
            ("map_group", "sample_id"),
            ("dataset_id", "sample_id"),
            ("sample_name", "sample_id"),
            ("mineral_name", "mineral_id"),
            ("mineral_type", "mineral_id"),
            ("run_name", "run_id"),
            ("source_row_count", "n_pixels"),
            ("plot_group_id", "plot_group"),
        ]:
            if alias in out.columns and direct in out.columns:
                left = out[alias].fillna("").astype(str)
                right = out[direct].fillna("").astype(str)
                if left.equals(right):
                    out = out.drop(columns=[alias])
        out = out.drop(
            columns=["plot_summary_mode", "coordinate_group_key", "base_grid_layer"],
            errors="ignore",
        )
        clear_group_columns = {
            "sample_id", "mineral_id", "run_id", "domain",
            "grain_id", "line_id", "spot_id",
        }
        if clear_group_columns.intersection(out.columns):
            out = out.drop(columns=["plot_group", "plot_group_id"], errors="ignore")

        if "grain_uid" in out.columns and "grain_id" in out.columns:
            identity = [column for column in ["sample_id", "mineral_id", "run_id"] if column in out.columns]
            if len(identity) == 3 or out["grain_uid"].nunique(dropna=True) == out["grain_id"].nunique(dropna=True):
                out = out.drop(columns=["grain_uid"])

        export_names = {
            "area_id": "domain_id",
            "area_shape": "domain_shape",
            "source_kind": "data_type",
        }
        rename = {old: new for old, new in export_names.items() if old in out.columns and new not in out.columns}
        if rename:
            out = out.rename(columns=rename)

        if export_kind == "geochron":
            helper_columns = [
                column for column in out.columns
                if str(column).startswith("_upb_") or str(column).startswith("_cov")
            ]
            if helper_columns:
                out = out.drop(columns=helper_columns, errors="ignore")

            geochron_names = {
                "upb_r68": "206Pb_238U",
                "upb_r75": "207Pb_235U",
                "upb_r76": "207Pb_206Pb",
                "upb_r86": "238U_206Pb",
                "upb_r87": "238U_207Pb",
                "date_68_ma": "Date_206Pb_238U_Ma",
                "date_75_ma": "Date_207Pb_235U_Ma",
                "date_76_ma": "Date_207Pb_206Pb_Ma",
                "concordia_date_ma": "Concordia_date_Ma",
                "rho_wetherill_internal": "rho_Wetherill_internal",
                "rho_wetherill_total": "rho_Wetherill_total",
                "rho_tw_internal": "rho_Tera_Wasserburg_internal",
                "rho_tw_total": "rho_Tera_Wasserburg_total",
                "group_label": "group",
            }
            suffixes = [
                "sd", "1se_internal", "2se_internal", "1se_total", "2se_total"
            ]
            for old, label in [
                ("upb_r68", "206Pb_238U"),
                ("upb_r75", "207Pb_235U"),
                ("upb_r76", "207Pb_206Pb"),
                ("upb_r86", "238U_206Pb"),
                ("upb_r87", "238U_207Pb"),
                ("date_68", "Date_206Pb_238U"),
                ("date_75", "Date_207Pb_235U"),
                ("date_76", "Date_207Pb_206Pb"),
                ("concordia_date", "Concordia_date"),
            ]:
                for suffix in suffixes:
                    geochron_names[f"{old}_{suffix}"] = f"{label}_{suffix}"
            rename = {
                old: new for old, new in geochron_names.items()
                if old in out.columns and new not in out.columns
            }
            if rename:
                out = out.rename(columns=rename)

        if export_kind == "domain_summary":
            rename = {}
            drop = []
            for col in list(out.columns):
                name = str(col)
                if name.endswith("_mean"):
                    base = name[:-5]
                    if base in out.columns:
                        drop.append(col)
                    else:
                        rename[col] = base
                elif name.endswith("_std"):
                    rename[col] = name[:-4] + "_sd"
                elif name.endswith("_n_valid"):
                    rename[col] = name[:-8] + "_n"
            if drop:
                out = out.drop(columns=drop, errors="ignore")
            if rename:
                out = out.rename(columns=rename)
            out = self._merge_export_columns(out)

        preferred = [
            "sample_id", "mineral_id", "run_id", "domain_id", "domain", "domain_shape",
            "line_id", "point_id", "spot_id", "grain_id", "pixel_id",
            "row_index", "column_index", "x", "y", "distance", "distance_normalized",
            "n_pixels", "source_row_count", "analysis_level",
        ]
        ordered = [col for col in preferred if col in out.columns]
        remaining = [col for col in out.columns if col not in ordered]
        if export_kind == "domain_summary":
            statistic_order = {"": 0, "_sd": 1, "_se": 2, "_n": 3}
            base_rank = {}
            parsed = []
            for position, col in enumerate(remaining):
                name = str(col)
                suffix = ""
                base = name
                for candidate in ("_sd", "_se", "_n"):
                    if name.endswith(candidate):
                        suffix = candidate
                        base = name[: -len(candidate)]
                        break
                base_rank.setdefault(base, position)
                parsed.append((col, base, suffix))
            remaining = [
                item[0]
                for item in sorted(
                    parsed,
                    key=lambda item: (base_rank[item[1]], statistic_order[item[2]]),
                )
            ]
        ordered.extend(remaining)
        return out.loc[:, ordered].reset_index(drop=True)


    # write CSV
    def _write_csv(self, df, path, export_kind="general"):
        clean = self._prepare_export_dataframe(df, export_kind=export_kind)
        if clean.empty:
            raise ValueError("There is no data to export.")
        clean.to_csv(path, index=False, na_rep="", lineterminator="\n")
        return clean


    # save table CSV
    def save_df_csv(self, df, default_name, title, export_kind="general"):
        if not isinstance(df, pd.DataFrame) or df.empty:
            messagebox.showinfo("No data", "There is no data to export.")
            return None
        path = filedialog.asksaveasfilename(
            title=f"Save {title}",
            defaultextension=".csv",
            initialfile=default_name,
            filetypes=[("CSV files", "*.csv"), ("All files", "*.*")],
        )
        if not path:
            return None
        try:
            clean = self._write_csv(df, path, export_kind=export_kind)
        except (OSError, TypeError, ValueError) as exc:
            messagebox.showerror("Export failed", str(exc))
            return None
        self.status_var.set(
            f"Saved {len(clean):,} rows and {len(clean.columns):,} columns: {os.path.basename(path)}"
        )
        return Path(path)


    # save related csvs
    def save_related_csvs(self, primary_df, default_name, title, related=None,
                          export_kind="general"):
        if not isinstance(primary_df, pd.DataFrame) or primary_df.empty:
            messagebox.showinfo("No data", "There is no data to export.")
            return []
        path = filedialog.asksaveasfilename(
            title=f"Save {title}",
            defaultextension=".csv",
            initialfile=default_name,
            filetypes=[("CSV files", "*.csv"), ("All files", "*.*")],
        )
        if not path:
            return []
        base = Path(path)
        saved = []
        try:
            self._write_csv(primary_df, base, export_kind=export_kind)
            saved.append(base)
            for suffix, table, kind in related or []:
                if not isinstance(table, pd.DataFrame) or table.empty:
                    continue
                extra = base.with_name(base.stem + suffix + ".csv")
                self._write_csv(table, extra, export_kind=kind)
                saved.append(extra)
        except (OSError, TypeError, ValueError) as exc:
            messagebox.showerror("Export failed", str(exc))
            return []
        names = ", ".join(item.name for item in saved)
        self.status_var.set(f"Saved {len(saved)} CSV file(s): {names}")
        return saved


    # remember the last folder used for CSV exports
    def save_csv_folder(self, tables, title="CSV files"):
        folder = filedialog.askdirectory(title=f"Choose folder for {title}")
        if not folder:
            return []
        folder = Path(folder)
        saved = []
        try:
            for filename, table, kind in tables:
                if not isinstance(table, pd.DataFrame) or table.empty:
                    continue
                path = folder / filename
                self._write_csv(table, path, export_kind=kind)
                saved.append(path)
        except (OSError, TypeError, ValueError) as exc:
            messagebox.showerror("Export failed", str(exc))
            return []
        self.status_var.set(f"Saved {len(saved)} CSV file(s) to {folder}")
        return saved


    # selected values from a Tkinter listbox
    def get_selected_from_listbox(
        self, listbox, min_count=1, warning="Select at least one column."
    ):
        selected = [listbox.get(i) for i in listbox.curselection()]
        if len(selected) < min_count:
            messagebox.showwarning("Selection needed", warning)
            return None
        return selected


    # unused internal name for a new map layer
    def unique_layer_name(self, requested_name):
        return _next_available_layer_name(self, requested_name)



    # Add more maps to the project without clearing the maps already loaded.


    # add files for the map view
    def add_map_files(self, *args, **kwargs):
        paths = _sample_choose_import_files(self, "Choose files for a new sample, mineral, or run")
        if not paths:
            return
        assignment = _sample_prompt_import_assignment(self, paths, force_new=False)
        if not assignment:
            return
        return _sample_import_paths(self, paths, **assignment)


    # color-scale limits typed in the map controls
    def get_vmin_vmax(self, z):
        vmin_text = self.vmin_var.get().strip()
        vmax_text = self.vmax_var.get().strip()
        vmin = None
        vmax = None
        if vmin_text:
            try:
                vmin = float(vmin_text)
            except Exception:
                messagebox.showwarning("Bad min", "Min value is not a number.")
                self.vmin_var.set("")
        if vmax_text:
            try:
                vmax = float(vmax_text)
            except Exception:
                messagebox.showwarning("Bad max", "Max value is not a number.")
                self.vmax_var.set("")
        return (vmin, vmax)


    # reset main map figure
    def _reset_main_map_figure(self):
        fig = getattr(self, "fig", None) or getattr(self, "map_fig", None)
        canvas = getattr(self, "canvas", None) or getattr(self, "map_canvas", None)
        if fig is None:
            raise RuntimeError("No main map figure exists.")
        fig.clear()
        ax = fig.add_subplot(111)
        self.fig = fig
        self.ax = ax
        if hasattr(self, "map_fig"):
            self.map_fig = fig
        if hasattr(self, "map_ax"):
            self.map_ax = ax
        if canvas is not None:
            self.canvas = canvas
            if hasattr(self, "map_canvas"):
                self.map_canvas = canvas
        return (fig, ax, canvas)


    # canonical display name for map layers
    def canonical_layer_display_name(self, name):
        original = str(name).strip()
        try:
            meta = (getattr(self, "metas", {}) or {}).get(original, {})
            if isinstance(meta, dict):
                stored = str(meta.get("canonical_column") or "").strip()
                if stored:
                    name = stored
        except Exception:
            pass
        if hasattr(self, "canonical_element_column_name"):
            return self.canonical_element_column_name(name)
        s = str(name).strip()
        if " :: " in s:
            s = s.split(" :: ")[-1].strip()
        s = re.sub("\\s+\\(\\d+\\)$", "", s).strip()
        return s


    # standard map columns available across loaded layers
    def get_canonical_map_columns(self):
        active = getattr(self, "active_sample_id", None)
        cols = []
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if layer not in (getattr(self, "values", {}) or {}):
                continue
            sample, _mineral, _run, channel = _sample_layer_identity(meta, layer)
            if active and active != "__EMPTY__" and (sample != active):
                continue
            if channel and channel != "presence" and (channel not in cols):
                cols.append(channel)
        return sorted(cols, key=str.lower)


    # refresh column combo for the map view
    def refresh_map_column_combo(self, preserve=True):
        if not hasattr(self, "column_combo") or not hasattr(self, "column_var"):
            return
        old = self.canonical_layer_display_name(self.column_var.get()) if preserve else ""
        cols = self.get_canonical_map_columns()
        self.column_combo["values"] = cols
        if old in cols:
            self.column_var.set(old)
        elif cols:
            self.column_var.set(cols[0])
        else:
            self.column_var.set("")
        try:
            self._refresh_pixel_filter_channels()
            if getattr(self, "pixel_exclusion_rules", []):
                self._rebuild_pixel_exclusions()
        except Exception:
            pass


    # resolve display column to layer
    def resolve_display_column_to_layer(self, display_col, mineral=None):
        clean = self.canonical_layer_display_name(display_col)
        active = getattr(self, "active_sample_id", None)
        candidates = []
        for layer, meta in (getattr(self, "metas", {}) or {}).items():
            if layer not in (getattr(self, "values", {}) or {}):
                continue
            sample, min_id, _run, channel = _sample_layer_identity(meta, layer)
            if channel != clean:
                continue
            score = 0
            if active and active != "__EMPTY__" and (sample == active):
                score += 100
            if mineral not in (None, "", "None"):
                mineral_text = str(mineral)
                if mineral_text in {min_id, f"{sample} :: {min_id}"}:
                    score += 50
                else:
                    continue
            candidates.append((score, layer))
        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            return candidates[0][1]
        return _resolve_display_layer(self, display_col, mineral=mineral)


    # internal layer currently represented by the map controls
    def _map_pixel_scale_current_layer(self):
        for attr in ("current_layer", "current_map_layer", "current_column"):
            layer = getattr(self, attr, None)
            if layer in getattr(self, "values", {}):
                return layer
        try:
            selected = str(self.column_var.get()).strip()
            layer = self.resolve_display_column_to_layer(selected)
            if layer in getattr(self, "values", {}):
                return layer
        except Exception:
            pass
        return None


    # layers affected by a manual scale change
    def _map_pixel_scale_target_layers(self):
        layer = self._map_pixel_scale_current_layer()
        if layer is None:
            return []
        scope = str(self.map_pixel_scale_scope_var.get()).strip()
        meta = self.metas.get(layer, {}) or {}
        sample, mineral, run, _channel = _sample_layer_identity(meta, layer)
        if scope == "Current layer":
            return [layer]
        targets = []
        for candidate, candidate_meta in (getattr(self, "metas", {}) or {}).items():
            if candidate not in getattr(self, "values", {}):
                continue
            cs, cm, cr, _cc = _sample_layer_identity(candidate_meta, candidate)
            if scope == "Current sample":
                match = cs == sample
            else:
                match = (cs, cm, cr) == (sample, mineral, run)
            if match:
                targets.append(candidate)
        return targets or [layer]


    # current pixel spacing, origin, and unit status for the active layer
    def _map_pixel_scale_info(self, layer=None):
        layer = layer or self._map_pixel_scale_current_layer()
        if layer is None or layer not in getattr(self, "values", {}):
            return None
        z = np.asarray(self.values[layer])
        meta = self.metas.get(layer, {}) or {}
        dx, dy = self._median_pixel_spacing_from_meta(meta, z_shape=z.shape)
        x = np.asarray(meta.get("x", []), dtype=float)
        y = np.asarray(meta.get("y", []), dtype=float)
        x0 = float(x[0]) if x.ndim == 1 and x.size == z.shape[1] and np.isfinite(x[0]) else 0.0
        y0 = float(y[0]) if y.ndim == 1 and y.size == z.shape[0] and np.isfinite(y[0]) else 0.0
        is_um = _metadata_uses_micron_coordinates(meta, z_shape=z.shape)
        mode = str(meta.get("coordinate_import_mode", ""))
        if mode == "manual_pixel_scale":
            source = "manual"
        elif is_um:
            source = "imported X/Y"
        else:
            source = "pixel indices / uncalibrated"
        return {
            "layer": layer,
            "shape": tuple(z.shape),
            "dx": float(dx),
            "dy": float(dy),
            "x0": x0,
            "y0": y0,
            "is_um": bool(is_um),
            "source": source,
        }


    # fill the map-scale fields from the displayed layer
    def refresh_map_pixel_scale_controls(self, fill_entries=True):
        info = self._map_pixel_scale_info()
        if info is None:
            self.map_pixel_scale_status_var.set("No map layer is selected.")
            return
        if fill_entries:
            self.map_pixel_size_x_var.set(f"{info['dx']:.9g}")
            self.map_pixel_size_y_var.set(f"{info['dy']:.9g}")
            self.map_pixel_origin_x_var.set(f"{info['x0']:.12g}")
            self.map_pixel_origin_y_var.set(f"{info['y0']:.12g}")
        rows, cols = info["shape"]
        pixel_area = info["dx"] * info["dy"]
        if info["is_um"]:
            status = (
                f"{info['source']}: {info['dx']:.6g} × {info['dy']:.6g} µm/pixel "
                f"= {pixel_area:.6g} µm²/pixel; grid {cols} × {rows}."
            )
        else:
            status = (
                f"{info['source']}: grid {cols} × {rows}. No physical µm calibration is attached; "
                "grain area stays separate from raw pixel count until X/Y coordinates or a manual scale are supplied."
            )
        self.map_pixel_scale_status_var.set(status)


    # apply one regular physical pixel grid while preserving the chosen origin
    def _apply_manual_pixel_scale_to_meta(self, meta, z_shape, dx, dy, x0, y0):
        new_meta = dict(meta or {})
        if "_manual_pixel_scale_backup" not in new_meta:
            new_meta["_manual_pixel_scale_backup"] = copy.deepcopy(
                {k: v for k, v in new_meta.items() if k != "_manual_pixel_scale_backup"}
            )
        n_rows, n_cols = map(int, z_shape)
        old_x = np.asarray(new_meta.get("x", []), dtype=float)
        old_y = np.asarray(new_meta.get("y", []), dtype=float)
        x_sign = -1.0 if old_x.size > 1 and np.nanmedian(np.diff(old_x)) < 0 else 1.0
        y_sign = -1.0 if old_y.size > 1 and np.nanmedian(np.diff(old_y)) < 0 else 1.0
        x = float(x0) + x_sign * np.arange(n_cols, dtype=float) * float(dx)
        y = float(y0) + y_sign * np.arange(n_rows, dtype=float) * float(dy)
        x_grid, y_grid = np.meshgrid(x, y)
        new_meta["x"] = x
        new_meta["y"] = y
        new_meta["x_grid"] = x_grid
        new_meta["y_grid"] = y_grid
        new_meta.pop("registered_x_axis", None)
        new_meta.pop("registered_y_axis", None)
        new_meta["x_name"] = "X (µm)"
        new_meta["y_name"] = "Y (µm)"
        old_kind = str(new_meta.get("kind", "matrix_file"))
        if old_kind == "matrix_file":
            new_meta["kind"] = "matrix_file_with_manual_xy"
        new_meta["physical_coordinate_units"] = "µm"
        new_meta["coordinate_import_mode"] = "manual_pixel_scale"
        new_meta["manual_pixel_size_x_um"] = float(dx)
        new_meta["manual_pixel_size_y_um"] = float(dy)
        new_meta["manual_pixel_origin_x_um"] = float(x0)
        new_meta["manual_pixel_origin_y_um"] = float(y0)
        new_meta["coordinate_grid_preserved"] = True
        return new_meta


    # button action for manual map calibration
    def apply_map_pixel_size_override(self):
        try:
            dx = float(self.map_pixel_size_x_var.get())
            dy = float(self.map_pixel_size_y_var.get())
            x0 = float(self.map_pixel_origin_x_var.get())
            y0 = float(self.map_pixel_origin_y_var.get())
        except Exception:
            messagebox.showerror("Map scale", "Enter numeric X size, Y size, first X center, and first Y center.")
            return
        if not np.isfinite([dx, dy, x0, y0]).all() or dx <= 0 or dy <= 0:
            messagebox.showerror("Map scale", "X and Y pixel sizes must be positive finite numbers.")
            return
        targets = self._map_pixel_scale_target_layers()
        if not targets:
            messagebox.showinfo("Map scale", "Display a map layer first.")
            return
        changed = []
        for layer in targets:
            try:
                shape = np.asarray(self.values[layer]).shape
                if len(shape) != 2:
                    continue
                self.metas[layer] = self._apply_manual_pixel_scale_to_meta(
                    self.metas.get(layer, {}), shape, dx, dy, x0, y0
                )
                changed.append(layer)
            except Exception:
                continue
        if not changed:
            messagebox.showerror("Map scale", "The scale could not be applied to the selected layer(s).")
            return
        current = self._map_pixel_scale_current_layer()
        if current in changed:
            _sample_set_current_map_state_from_layer(self, current)
        grain_source = (
            getattr(self, "last_grain_mask_layer", None)
            or getattr(self, "last_grain_layer_name", None)
            or getattr(self, "last_grain_value_layer", None)
        )
        if grain_source in changed and getattr(self, "last_grain_label_mask", None) is not None:
            try:
                self.rebuild_current_grain_tables_from_label_mask()
                self.store_current_grain_analysis_run(refresh=True)
            except Exception:
                pass
        self.update_map()
        self.refresh_map_pixel_scale_controls(fill_entries=True)
        self.status_var.set(
            f"Applied {dx:g} × {dy:g} µm pixels to {len(changed)} layer(s). Grain area now uses calibrated pixel area, not raw pixel count."
        )


    # restore imported/original coordinates after a manual scale override
    def revert_map_pixel_size_override(self):
        targets = self._map_pixel_scale_target_layers()
        restored = []
        for layer in targets:
            meta = self.metas.get(layer, {}) or {}
            backup = meta.get("_manual_pixel_scale_backup")
            if isinstance(backup, dict):
                self.metas[layer] = copy.deepcopy(backup)
                restored.append(layer)
        if not restored:
            messagebox.showinfo("Map scale", "No manual scale is stored for the selected layer(s).")
            return
        current = self._map_pixel_scale_current_layer()
        if current in restored:
            _sample_set_current_map_state_from_layer(self, current)
        grain_source = (
            getattr(self, "last_grain_mask_layer", None)
            or getattr(self, "last_grain_layer_name", None)
            or getattr(self, "last_grain_value_layer", None)
        )
        if grain_source in restored and getattr(self, "last_grain_label_mask", None) is not None:
            try:
                self.rebuild_current_grain_tables_from_label_mask()
                self.store_current_grain_analysis_run(refresh=True)
            except Exception:
                pass
        self.update_map()
        self.refresh_map_pixel_scale_controls(fill_entries=True)
        self.status_var.set(f"Restored the original/imported map coordinates for {len(restored)} layer(s).")


    # median pixel spacing from meta
    def _median_pixel_spacing_from_meta(self, meta, z_shape=None):
        xg, yg = self._layer_pixel_centers(meta, z_shape=z_shape)
        dx = np.nan
        dy = np.nan
        try:
            if xg is not None and np.ndim(xg) == 2 and (xg.shape[1] > 1):
                dd = np.abs(np.diff(xg, axis=1))
                dd = dd[np.isfinite(dd) & (dd > 0)]
                if dd.size:
                    dx = float(np.nanmedian(dd))
        except Exception:
            pass
        try:
            if yg is not None and np.ndim(yg) == 2 and (yg.shape[0] > 1):
                dd = np.abs(np.diff(yg, axis=0))
                dd = dd[np.isfinite(dd) & (dd > 0)]
                if dd.size:
                    dy = float(np.nanmedian(dd))
        except Exception:
            pass
        if not np.isfinite(dx) or dx <= 0:
            try:
                x = np.asarray(meta.get("x", []), dtype=float)
                dd = np.abs(np.diff(x))
                dd = dd[np.isfinite(dd) & (dd > 0)]
                if dd.size:
                    dx = float(np.nanmedian(dd))
            except Exception:
                pass
        if not np.isfinite(dy) or dy <= 0:
            try:
                y = np.asarray(meta.get("y", []), dtype=float)
                dd = np.abs(np.diff(y))
                dd = dd[np.isfinite(dd) & (dd > 0)]
                if dd.size:
                    dy = float(np.nanmedian(dd))
            except Exception:
                pass
        if not np.isfinite(dx) or dx <= 0:
            dx = 1.0
        if not np.isfinite(dy) or dy <= 0:
            dy = dx
        return (dx, dy)


    # convert centers to edges 1d
    def _centers_to_edges_1d(self, centers):
        centers = np.asarray(centers, dtype=float)
        if centers.size == 0:
            return centers
        if centers.size == 1:
            return np.array([centers[0] - 0.5, centers[0] + 0.5], dtype=float)
        idx = np.arange(centers.size)
        good = np.isfinite(centers)
        if good.sum() < 2:
            return np.arange(centers.size + 1, dtype=float) - 0.5
        centers = np.interp(idx, idx[good], centers[good])
        mids = 0.5 * (centers[:-1] + centers[1:])
        first = centers[0] - (mids[0] - centers[0])
        last = centers[-1] + (centers[-1] - mids[-1])
        return np.concatenate([[first], mids, [last]]).astype(float)


    # default grouping column for the active analysis table
    def _default_group_column_for_active_table(self, df=None):
        if df is None:
            df = self.get_active_analysis_table()
        if df is None or df.empty:
            return None
        for col in [
            "mineral_type",
            "map_group",
            "source_layer",
            "source_kind",
            "grain_id",
            "profile_id",
            "line_id",
        ]:
            if col in df.columns and pd.Series(df[col]).nunique(dropna=True) > 1:
                return col
        return None


    # convert array rc to map X-Y
    def _array_rc_to_map_xy(self, rows, cols, source_layer=None):
        rows = np.asarray(rows, dtype=float)
        cols = np.asarray(cols, dtype=float)
        if source_layer is None:
            source_layer = getattr(self, "last_grain_layer_name", None)
        z = None
        meta = {}
        if source_layer in getattr(self, "values", {}):
            z = np.asarray(self.values[source_layer], dtype=float)
            meta = self.metas.get(source_layer, {})
        else:
            source_layer, meta, z = self._grain_label_layer_and_meta()
        if z is None:
            return (cols, rows)
        xg, yg = self._layer_pixel_centers(meta, z_shape=z.shape)
        try:
            x_axis = np.asarray(meta.get("x", []), dtype=float)
            y_axis = np.asarray(meta.get("y", []), dtype=float)
            if x_axis.size == z.shape[1] and y_axis.size == z.shape[0]:
                col_idx = np.arange(z.shape[1], dtype=float)
                row_idx = np.arange(z.shape[0], dtype=float)
                x = np.interp(cols, col_idx, x_axis)
                y = np.interp(rows, row_idx, y_axis)
                return (x, y)
        except Exception:
            pass
        try:
            if xg is not None and yg is not None and (tuple(np.shape(xg)) == tuple(z.shape)):
                r0 = np.clip(np.floor(rows).astype(int), 0, z.shape[0] - 1)
                c0 = np.clip(np.floor(cols).astype(int), 0, z.shape[1] - 1)
                return (np.asarray(xg)[r0, c0], np.asarray(yg)[r0, c0])
        except Exception:
            pass
        return (cols, rows)


    # shared map limits from records
    def _shared_map_limits_from_records(self, records):
        xs = []
        ys = []
        for layer_name, mask in records:
            try:
                z, meta, xg, yg = self._map_layer_xy_grids(layer_name)
                mask = np.asarray(mask, dtype=bool)
                good = mask & np.isfinite(xg) & np.isfinite(yg)
                if np.any(good):
                    dx, dy = self._median_pixel_spacing_from_meta(meta, z_shape=z.shape)
                    xs.extend(
                        [float(np.nanmin(xg[good]) - dx / 2), float(np.nanmax(xg[good]) + dx / 2)]
                    )
                    ys.extend(
                        [float(np.nanmin(yg[good]) - dy / 2), float(np.nanmax(yg[good]) + dy / 2)]
                    )
            except Exception:
                pass
        if not xs or not ys:
            return None
        xmin, xmax = (min(xs), max(xs))
        ymin, ymax = (min(ys), max(ys))
        pad_x = 0.01 * max(abs(xmax - xmin), 1.0)
        pad_y = 0.01 * max(abs(ymax - ymin), 1.0)
        return (xmin - pad_x, xmax + pad_x, ymin - pad_y, ymax + pad_y)


    # apply shared map axes
    def _apply_shared_map_axes(self, ax, records=None):
        try:
            if records:
                lims = self._shared_map_limits_from_records(records)
                if lims is not None:
                    xmin, xmax, ymin, ymax = lims
                    ax.set_xlim(xmin, xmax)
                    ax.set_ylim(ymin, ymax)
        except Exception:
            pass
        ax.set_aspect("equal", adjustable="box")
        ax.set_xlabel("X")
        ax.set_ylabel("Y")
        try:
            if hasattr(self, "map_invert_x_var") and self.map_invert_x_var.get():
                if not ax.xaxis_inverted():
                    ax.invert_xaxis()
            if hasattr(self, "map_invert_y_var") and self.map_invert_y_var.get():
                if not ax.yaxis_inverted():
                    ax.invert_yaxis()
        except Exception:
            pass


    # draw value layer same grid
    def _draw_value_layer_same_grid(
        self,
        ax,
        layer_name,
        values=None,
        mask=None,
        cmap="viridis",
        vmin=None,
        vmax=None,
        label=None,
        alpha=1.0,
        zorder=5,
    ):
        z, meta, xg, yg = self._map_layer_xy_grids(layer_name)
        if values is None:
            values = z
        values = np.asarray(values, dtype=float)
        if mask is None:
            mask = np.isfinite(values)
        mask = np.asarray(mask, dtype=bool) & np.isfinite(values)
        arr = np.where(mask, values, np.nan)
        try:
            x_edges, y_edges = self._layer_xy_edges_from_existing_axes(meta, z.shape)
            if x_edges is not None and y_edges is not None:
                im = ax.pcolormesh(
                    x_edges,
                    y_edges,
                    arr,
                    cmap=cmap,
                    vmin=vmin,
                    vmax=vmax,
                    shading="flat",
                    edgecolors="face",
                    linewidth=0,
                    antialiased=False,
                    snap=True,
                    rasterized=True,
                    alpha=alpha,
                    zorder=zorder,
                )
                return (im, mask)
        except Exception:
            pass
        good = mask & np.isfinite(xg) & np.isfinite(yg)
        sc = ax.scatter(
            xg[good],
            yg[good],
            c=arr[good],
            cmap=cmap,
            vmin=vmin,
            vmax=vmax,
            marker="s",
            s=6,
            linewidths=0,
            alpha=alpha,
            label=label,
            zorder=zorder,
        )
        return (sc, mask)


    # draw label image on map axes
    def _draw_label_image_on_map_axes(self, ax, labels, source_layer=None, alpha=0.95):
        if labels is None:
            return None
        labels = np.asarray(labels)
        if labels.ndim != 2 or not np.any(labels > 0):
            return None
        if source_layer is None:
            source_layer = self._grain_source_layer_for_display()
        if source_layer not in getattr(self, "values", {}):
            return None
        z = np.asarray(self.values[source_layer], dtype=float)
        meta = self.metas.get(source_layer, {})
        if labels.shape != z.shape:
            return None
        try:
            x_edges, y_edges = self._layer_xy_edges_from_existing_axes(meta, z.shape)
        except Exception:
            x_edges, y_edges = (None, None)
        try:
            import matplotlib.pyplot as plt
            from matplotlib.colors import ListedColormap

            unique = np.unique(labels[labels > 0])
            if unique.size == 0:
                return None
            base = plt.get_cmap("tab20")
            colors = []
            for i in range(int(labels.max()) + 1):
                if i == 0:
                    colors.append((1, 1, 1, 0))
                else:
                    c = base((i - 1) % 20)
                    colors.append((c[0], c[1], c[2], alpha))
            cmap = ListedColormap(colors)
            label_arr = np.where(labels > 0, labels, np.nan)
            if x_edges is not None and y_edges is not None:
                artist = ax.pcolormesh(
                    x_edges,
                    y_edges,
                    label_arr,
                    cmap=cmap,
                    shading="flat",
                    edgecolors="none",
                    linewidth=0,
                    antialiased=False,
                    snap=True,
                    rasterized=True,
                    zorder=15,
                )
                return artist
            z0, meta0, xg, yg = self._map_layer_xy_grids(source_layer)
            good = labels > 0
            artist = ax.scatter(
                xg[good],
                yg[good],
                c=labels[good],
                cmap=cmap,
                marker="s",
                s=7,
                linewidths=0,
                alpha=alpha,
                zorder=15,
            )
            return artist
        except Exception:
            return None


    # restore on/off controls after a project is opened
    def _restore_toggles(self, changed):
        for var, old in changed:
            try:
                var.set(old)
            except Exception:
                pass


    # reset the map color limits from the visible data
    def auto_scale(self):
        self.vmin_var.set("")
        self.vmax_var.set("")
        self.update_map()


    # bind ctrl cmd multiselect
    def bind_ctrl_cmd_multiselect(self, listbox):
        try:
            mode = str(listbox.cget("selectmode"))
        except Exception:
            mode = ""
        if mode not in (tk.MULTIPLE, tk.EXTENDED, "multiple", "extended"):
            return
        listbox.bind(
            "<Control-Button-1>",
            lambda event, lb=listbox: self.toggle_listbox_item(event, lb),
            add="+",
        )
        listbox.bind(
            "<Command-Button-1>",
            lambda event, lb=listbox: self.toggle_listbox_item(event, lb),
            add="+",
        )
        listbox.bind("<Control-ButtonRelease-1>", lambda event: "break", add="+")
        listbox.bind("<Command-ButtonRelease-1>", lambda event: "break", add="+")


    # toggle listbox item
    def toggle_listbox_item(self, event, listbox):
        index = listbox.nearest(event.y)
        if index < 0 or index >= listbox.size():
            return "break"
        if index in listbox.curselection():
            listbox.selection_clear(index)
        else:
            listbox.selection_set(index)
        listbox.activate(index)
        listbox.focus_set()
        return "break"


    # bind Command/Ctrl selection behavior to every listbox
    def bind_all_multiselect_listboxes(self):

        # walk the widget tree and bind every listbox
        def visit(widget):
            if isinstance(widget, tk.Listbox):
                self.bind_ctrl_cmd_multiselect(widget)
            for child in widget.winfo_children():
                visit(child)

        visit(self)


    # create the four Tkinter variables used by manual plot bounds.
    def init_bounds_vars(self, prefix):
        for suffix in ["xmin", "xmax", "ymin", "ymax"]:
            name = f"{prefix}_{suffix}_var"
            if not hasattr(self, name):
                setattr(self, name, tk.StringVar(value=""))


    # add manual X/Y limit entries beside a plot
    def add_inline_bounds_controls(self, parent, prefix, title="Axis bounds"):
        self.init_bounds_vars(prefix)
        frame = ttk.LabelFrame(parent, text=title)
        frame.pack(fill=tk.X, pady=(6, 4))
        row1 = ttk.Frame(frame)
        row1.pack(fill=tk.X, padx=4, pady=2)
        row2 = ttk.Frame(frame)
        row2.pack(fill=tk.X, padx=4, pady=2)
        ttk.Label(row1, text="X min").pack(side=tk.LEFT)
        ttk.Entry(row1, textvariable=getattr(self, f"{prefix}_xmin_var"), width=8).pack(
            side=tk.LEFT, padx=(2, 6)
        )
        ttk.Label(row1, text="X max").pack(side=tk.LEFT)
        ttk.Entry(row1, textvariable=getattr(self, f"{prefix}_xmax_var"), width=8).pack(
            side=tk.LEFT, padx=(2, 6)
        )
        ttk.Label(row2, text="Y min").pack(side=tk.LEFT)
        ttk.Entry(row2, textvariable=getattr(self, f"{prefix}_ymin_var"), width=8).pack(
            side=tk.LEFT, padx=(2, 6)
        )
        ttk.Label(row2, text="Y max").pack(side=tk.LEFT)
        ttk.Entry(row2, textvariable=getattr(self, f"{prefix}_ymax_var"), width=8).pack(
            side=tk.LEFT, padx=(2, 6)
        )
        buttons = ttk.Frame(frame)
        buttons.pack(fill=tk.X, padx=4, pady=(2, 4))
        ttk.Button(buttons, text="Apply", command=lambda p=prefix: self.apply_axis_bounds(p)).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 2)
        )
        ttk.Button(buttons, text="Reset bounds", command=lambda p=prefix: self.clear_axis_bounds(p)).pack(
            side=tk.LEFT, fill=tk.X, expand=True, padx=(2, 0)
        )


    # add the button that opens manual axis limits
    def add_bounds_button(self, parent, prefix, label="Set graph bounds"):
        self.init_bounds_vars(prefix)
        ttk.Button(parent, text=label, command=lambda p=prefix: self.open_bounds_window(p)).pack(
            fill=tk.X, pady=2
        )


    # open bounds window
    def open_bounds_window(self, prefix):
        self.init_bounds_vars(prefix)
        win = tk.Toplevel(self)
        win.title(f"Set {prefix} graph bounds")
        win.resizable(False, False)
        ttk.Label(win, text="Leave blank for automatic bounds.").grid(
            row=0, column=0, columnspan=4, sticky="w", padx=8, pady=(8, 4)
        )
        labels = ["X min", "X max", "Y min", "Y max"]
        suffixes = ["xmin", "xmax", "ymin", "ymax"]
        for i, (label, suffix) in enumerate(zip(labels, suffixes)):
            ttk.Label(win, text=label).grid(row=1, column=i, sticky="w", padx=8)
            ttk.Entry(win, textvariable=getattr(self, f"{prefix}_{suffix}_var"), width=12).grid(
                row=2, column=i, padx=8, pady=(0, 8)
            )
        ttk.Button(
            win, text="Apply bounds", command=lambda p=prefix: self.apply_axis_bounds(p)
        ).grid(row=3, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 8))
        ttk.Button(
            win, text="Clear bounds", command=lambda p=prefix: self.clear_axis_bounds(p)
        ).grid(row=3, column=2, columnspan=2, sticky="ew", padx=8, pady=(0, 8))


    # parse bound
    def _parse_bound(self, text):
        text = str(text).strip()
        if text == "":
            return None
        return float(text)


    # axes associated with one set of manual-bound controls
    def get_axis_for_prefix(self, prefix):
        ax = getattr(self, f"{prefix}_ax", None)
        canvas = getattr(self, f"{prefix}_canvas", None)
        return (ax, canvas)


    # apply typed X/Y limits to a plot
    def apply_axis_bounds(self, prefix):
        self.init_bounds_vars(prefix)
        ax, canvas = self.get_axis_for_prefix(prefix)
        if ax is None:
            return
        try:
            xmin = self._parse_bound(getattr(self, f"{prefix}_xmin_var").get())
            xmax = self._parse_bound(getattr(self, f"{prefix}_xmax_var").get())
            ymin = self._parse_bound(getattr(self, f"{prefix}_ymin_var").get())
            ymax = self._parse_bound(getattr(self, f"{prefix}_ymax_var").get())
        except Exception:
            messagebox.showerror("Bad bounds", "Bounds must be numbers or blank.")
            return
        cur_xmin, cur_xmax = ax.get_xlim()
        cur_ymin, cur_ymax = ax.get_ylim()
        if xmin is not None or xmax is not None:
            ax.set_xlim(cur_xmin if xmin is None else xmin, cur_xmax if xmax is None else xmax)
        if ymin is not None or ymax is not None:
            ax.set_ylim(cur_ymin if ymin is None else ymin, cur_ymax if ymax is None else ymax)
        if canvas is not None:
            canvas.draw_idle()


    # clear typed limits and return to automatic scaling
    def clear_axis_bounds(self, prefix):
        self.init_bounds_vars(prefix)
        for suffix in ["xmin", "xmax", "ymin", "ymax"]:
            getattr(self, f"{prefix}_{suffix}_var").set("")
        self.apply_axis_bounds(prefix)



