    # remove characters that are unsafe in exported file names
    def sanitize_filename_part(self, text):
        text = str(text).strip()
        if not text:
            text = "unnamed"
        text = re.sub("[^A-Za-z0-9_.-]+", "_", text)
        text = text.strip("._")
        return text or "unnamed"


    # switch the analysis source to areas
    def use_areas_for_analysis(self):
        if self.area_df is None or self.area_df.empty:
            messagebox.showinfo("No domains", "Draw one or more domains first.")
            return
        try:
            summary = self._current_domain_summary_table()
        except Exception as exc:
            messagebox.showerror("Domain means", str(exc))
            return
        self.set_analysis_df(summary, "Domain means")


    # grouping column selected for the active plot
    def get_plot_group_column(self, df=None):
        if df is None:
            df = self.get_active_analysis_table()
        if df is None:
            return None
        for col in [
            "mineral_type",
            "grain_category",
            "comparison_dataset",
            "domain",
            "area_id",
            "spot_id",
            "line_id",
            "mask_selection",
        ]:
            if col in df.columns:
                return col
        return None


    # numeric columns available in the active analysis table
    def get_active_numeric_columns(self, df=None):
        if df is None:
            df = self.get_active_analysis_table()
        if df is None or df.empty:
            return []

        out = []
        seen = set()
        for column in df.columns:
            try:
                series = df[column]
                is_numeric = pd.api.types.is_numeric_dtype(series)
                if not is_numeric and not isinstance(series.dtype, pd.CategoricalDtype):
                    sample = series.dropna().iloc[:1000]
                    if not sample.empty:
                        is_numeric = pd.to_numeric(sample, errors="coerce").notna().mean() > 0.95
                if not is_numeric:
                    continue
                clean = (
                    self.canonical_layer_display_name(column)
                    if hasattr(self, "canonical_layer_display_name")
                    else str(column)
                )
                if any(
                    token in str(column)
                    for token in [
                        "grain_", "area_", "ellipse", "aspect", "__sd", "__se",
                        "__cv", "__sum", "__n", "distance", "row_index",
                        "column_index", "x", "y",
                    ]
                ):
                    clean = str(column)
                if clean not in seen:
                    seen.add(clean)
                    out.append(clean if clean in df.columns else column)
            except Exception:
                continue
        return out


    # activate analysis table
    def activate_analysis_table(self, df, source_name="analysis table", mirror_to_comparison=True):
        return self._set_active_everywhere(df, source_name)


    # set active everywhere
    def _set_active_everywhere(self, df, source_name="active analysis table"):
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            messagebox.showerror("No analysis data", "No rows were generated for analysis.")
            return None
        try:
            needs_normalizing = any(
                " :: " in str(column) or re.search(r"\s+\(\d+\)$", str(column))
                for column in df.columns
            )
            if needs_normalizing and hasattr(self, "normalize_multimineral_analysis_columns"):
                df = self.normalize_multimineral_analysis_columns(df)
        except Exception:
            pass

        self.analysis_df = df
        self.active_analysis_df = df
        self._full_analysis_df_for_plotting = df
        self._full_analysis_source_name = str(source_name)
        self.comparison_df = df.copy(deep=False)
        self.analysis_source_name = source_name
        self.current_analysis_label = source_name
        self.active_analysis_name = source_name
        self.current_analysis_source = source_name
        self.excluded_columns = getattr(self, "excluded_columns", set())
        self.all_value_columns = get_value_columns(df)
        self.value_columns = [c for c in self.all_value_columns if c not in self.excluded_columns]

        try:
            self.refresh_analysis_columns()
        except Exception:
            pass
        try:
            if hasattr(self, "analysis_info_var"):
                self.analysis_info_var.set(
                    f"{source_name}\nRows: {len(df):,}\nColumns: {len(df.columns)}\n"
                    f"Columns: {len(self.value_columns)}"
                )
        except Exception:
            pass
        try:
            self.status_var.set(
                f"Active analysis table: {source_name} | {len(df):,} rows | "
                f"{len(self.value_columns)} numeric columns"
            )
        except Exception:
            pass
        return df



    # active data tables and plot filters
    # Loads standalone tables and updates the profile, correlation, and PCA lists.


    # load analysis CSV
    def load_analysis_csv(self):
        path = filedialog.askopenfilename(
            title="Choose CSV table", filetypes=[("CSV files", "*.csv"), ("All files", "*.*")]
        )
        if not path:
            return
        try:
            df = pd.read_csv(path)
        except Exception as exc:
            messagebox.showerror("Could not read CSV", str(exc))
            return
        for col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="ignore")
        self.set_analysis_df(df, f"CSV: {os.path.basename(path)}")


    # load multiple profile csvs
    def load_multiple_profile_csvs(self):
        paths = filedialog.askopenfilenames(
            title="Choose multiple single-element profile CSVs",
            filetypes=[("CSV files", "*.csv"), ("All files", "*.*")],
        )
        if not paths:
            return
        try:
            merged, info = load_and_merge_profile_csvs(paths)
        except Exception as exc:
            messagebox.showerror("Could not merge CSVs", str(exc))
            return
        self.set_analysis_df(merged, f"Merged {len(paths)} profile CSVs")


    # refresh the column-exclusion list
    def refresh_exclude_list(self):
        if not hasattr(self, "exclude_listbox"):
            return
        self.exclude_listbox.delete(0, tk.END)
        for col in self.all_value_columns:
            self.exclude_listbox.insert(tk.END, col)
        for i, col in enumerate(self.all_value_columns):
            if col in self.excluded_columns:
                self.exclude_listbox.selection_set(i)


    # refresh columns shown by the calculated-channel tab
    def refresh_math_lists(self):
        if not hasattr(self, "math_listbox"):
            return
        df = self.get_active_analysis_table()
        numeric = self.get_active_numeric_columns(df)
        self.math_listbox.delete(0, tk.END)
        for col in numeric:
            self.math_listbox.insert(tk.END, col)
        if hasattr(self, "simple_col_a_combo"):
            self.simple_col_a_combo["values"] = numeric
            self.simple_col_b_combo["values"] = numeric
            if numeric and self.simple_col_a_var.get() not in numeric:
                self.simple_col_a_var.set(numeric[0])
            if numeric and self.simple_col_b_var.get() not in numeric:
                self.simple_col_b_var.set(numeric[1] if len(numeric) > 1 else numeric[0])


    # refresh saved profiles and available profile channels
    def refresh_profile_list(self):
        if not hasattr(self, "profile_listbox"):
            return
        self.profile_listbox.delete(0, tk.END)
        df = self.get_active_analysis_table()
        for col in self.get_active_numeric_columns(df):
            self.profile_listbox.insert(tk.END, col)


    # refresh controls that use the comparison table
    def refresh_comparison_controls(self):
        if not hasattr(self, "compare_col_combo"):
            return
        if self.comparison_df is None or self.comparison_df.empty:
            self.compare_col_combo["values"] = []
            if hasattr(self, "compare_col_b_combo"):
                self.compare_col_b_combo["values"] = ["None"]
                self.compare_col_b_var.set("None")
            if hasattr(self, "compare_x_col_combo"):
                self.compare_x_col_combo["values"] = []
                self.compare_y_col_combo["values"] = []
            self.compare_group_combo["values"] = ["comparison_dataset"]
            if hasattr(self, "compare_spider_group_combo"):
                self.compare_spider_group_combo["values"] = ["comparison_dataset"]
                self.compare_spider_group_var.set("comparison_dataset")
            if hasattr(self, "compare_ternary_a_combo"):
                for combo in [
                    self.compare_ternary_a_combo,
                    self.compare_ternary_b_combo,
                    self.compare_ternary_c_combo,
                ]:
                    combo["values"] = []
                self.compare_ternary_group_combo["values"] = ["comparison_dataset"]
                self.compare_ternary_group_var.set("comparison_dataset")
                self.compare_ternary_info_var.set("No comparison data loaded.")
            self.comparison_info_var.set("No comparison data loaded.")
            if hasattr(self, "compare_spider_info_var"):
                self.compare_spider_info_var.set("No comparison data loaded.")
            return
        numeric_cols = get_value_columns(self.comparison_df)
        group_cols = [
            c
            for c in [
                "mineral_type",
                "comparison_dataset",
                "domain",
                "area_id",
                "spot_id",
                "line_id",
                "plot_group",
            ]
            if c in self.comparison_df.columns
        ]
        if not group_cols:
            group_cols = ["comparison_dataset"]
        self.compare_col_combo["values"] = numeric_cols
        if hasattr(self, "compare_col_b_combo"):
            self.compare_col_b_combo["values"] = ["None"] + list(numeric_cols)
            if self.compare_col_b_var.get() not in ["None"] + list(numeric_cols):
                self.compare_col_b_var.set("None")
        if hasattr(self, "compare_x_col_combo"):
            self.compare_x_col_combo["values"] = numeric_cols
            self.compare_y_col_combo["values"] = numeric_cols
        if hasattr(self, "compare_ternary_a_combo"):
            for combo in [
                self.compare_ternary_a_combo,
                self.compare_ternary_b_combo,
                self.compare_ternary_c_combo,
            ]:
                combo["values"] = numeric_cols
            self.compare_ternary_group_combo["values"] = group_cols
        self.compare_group_combo["values"] = group_cols
        if hasattr(self, "compare_spider_group_combo"):
            self.compare_spider_group_combo["values"] = group_cols
            if self.compare_spider_group_var.get() not in group_cols:
                self.compare_spider_group_var.set(group_cols[0])
        if numeric_cols and self.compare_col_var.get() not in numeric_cols:
            self.compare_col_var.set(numeric_cols[0])
        if (
            numeric_cols
            and hasattr(self, "compare_x_col_var")
            and (self.compare_x_col_var.get() not in numeric_cols)
        ):
            self.compare_x_col_var.set(numeric_cols[0])
        if (
            numeric_cols
            and hasattr(self, "compare_y_col_var")
            and (self.compare_y_col_var.get() not in numeric_cols)
        ):
            if len(numeric_cols) > 1:
                self.compare_y_col_var.set(numeric_cols[1])
            else:
                self.compare_y_col_var.set(numeric_cols[0])
        if hasattr(self, "compare_ternary_a_col_var") and numeric_cols:
            if self.compare_ternary_a_col_var.get() not in numeric_cols:
                self.compare_ternary_a_col_var.set(numeric_cols[0])
            if self.compare_ternary_b_col_var.get() not in numeric_cols:
                self.compare_ternary_b_col_var.set(
                    numeric_cols[1] if len(numeric_cols) > 1 else numeric_cols[0]
                )
            if self.compare_ternary_c_col_var.get() not in numeric_cols:
                self.compare_ternary_c_col_var.set(
                    numeric_cols[2] if len(numeric_cols) > 2 else numeric_cols[-1]
                )
            if self.compare_ternary_group_var.get() not in group_cols:
                self.compare_ternary_group_var.set(group_cols[0])
        if self.compare_group_var.get() not in group_cols:
            self.compare_group_var.set(group_cols[0])
        n_groups = (
            self.comparison_df[self.compare_group_var.get()].nunique(dropna=False)
            if self.compare_group_var.get() in self.comparison_df.columns
            else 0
        )
        n_sets = (
            self.comparison_df["comparison_dataset"].nunique(dropna=False)
            if "comparison_dataset" in self.comparison_df.columns
            else 0
        )
        self.comparison_info_var.set(
            f"Rows: {len(self.comparison_df)}\nDatasets/images: {n_sets}\nGroups in selected grouping: {n_groups}\nNumeric columns: {len(numeric_cols)}"
        )


