    # remove selected columns from general plotting menus
    def apply_column_exclusions(self):
        if self.analysis_df is None:
            messagebox.showinfo("No data", "Load or create an analysis table first.")
            return
        selected_indices = self.exclude_listbox.curselection()
        self.excluded_columns = {self.exclude_listbox.get(i) for i in selected_indices}
        self.refresh_analysis_columns()
        self.status_var.set(f"Applied exclusions: {len(self.excluded_columns)} columns excluded.")


    # restore all columns to the plotting menus
    def clear_column_exclusions(self):
        self.excluded_columns = set()
        self.refresh_analysis_columns()
        self.status_var.set("Cleared column exclusions.")


    # keep only REE channels in the current exclusion selection
    def keep_ree_only(self):
        if self.analysis_df is None:
            messagebox.showinfo("No data", "Load or create an analysis table first.")
            return
        keep = set()
        for col in self.all_value_columns:
            element = clean_element_name(col)
            if element in REE_ORDER:
                keep.add(col)
        self.excluded_columns = {col for col in self.all_value_columns if col not in keep}
        self.refresh_analysis_columns()
        self.status_var.set(
            f"Kept {len(keep)} REE columns; excluded {len(self.excluded_columns)} others."
        )


    # hide common U-Pb columns from the general plotting menus
    def exclude_common_upb_columns(self):
        if self.analysis_df is None:
            messagebox.showinfo("No data", "Load or create an analysis table first.")
            return
        patterns = ["Pb", "U", "Th", "age", "Age", "206", "207", "208", "232", "235", "238"]
        new_exclusions = set(self.excluded_columns)
        for col in self.all_value_columns:
            name = str(col)
            if any((p in name for p in patterns)):
                new_exclusions.add(col)
        self.excluded_columns = new_exclusions
        self.refresh_analysis_columns()
        self.status_var.set(
            f"Excluded common U-Pb/Pb/U/Th columns. {len(self.excluded_columns)} total excluded."
        )


