    # undo the most recently drawn domain
    def undo_last_area(self):
        try:
            if not getattr(self, "area_segments", []):
                self.status_var.set("No finished domain to undo.")
                return
            last = self.area_segments.pop()
            area_id = int(last.get("area_id"))
            if hasattr(self, "area_masks"):
                self.area_masks.pop(area_id, None)
            if getattr(self, "area_df", None) is not None and (not self.area_df.empty):
                self.area_df = self.area_df[
                    pd.to_numeric(self.area_df["area_id"], errors="coerce") != area_id
                ].reset_index(drop=True)
            self.redraw_area_annotations()
            try:
                self._redraw_all_extraction_overlays()
            except Exception:
                pass
            self.status_var.set(f"Removed area/domain {area_id}.")
        except Exception as exc:
            messagebox.showerror("Could not undo domain", str(exc))


