        df = _add_shared_channels(df)
        result = self._set_active_everywhere(df, source_name)
        active = getattr(self, "active_analysis_df", None)
        if isinstance(active, pd.DataFrame):
            self._full_analysis_df_for_plotting = active
            self._full_analysis_source_name = str(source_name)
        return result


