    # apply the shared row and group filters
    def apply_plot_filter(self):
        try:
            tab_text = self.notebook.tab(self.notebook.select(), "text")
        except Exception:
            tab_text = ""
        try:
            if "X-Y" in tab_text:
                self.plot_xy()
                return
            if "Ternary" in tab_text:
                self.plot_ternary()
                return
            if "KDE" in tab_text:
                self.plot_kde()
                return
            if "REE" in tab_text:
                self.plot_spider()
                return
            if "PCA" in tab_text:
                self.run_pca()
                return
            if "Correlation" in tab_text:
                self.run_corr_matrix()
                return
            if "Profiles" in tab_text:
                self.plot_profiles()
                return
            if "Grain comparison" in tab_text:
                try:
                    self.refresh_compare_grain_controls()
                except Exception:
                    pass
                self.plot_compare_grain_metric()
                return
        except Exception as exc:
            messagebox.showerror("Could not apply plot filter", str(exc))
            return
        try:
            self.status_var.set("Plot filter is set. Click the plot button for this tab.")
        except Exception:
            pass


